function finishTextInput(value = null) {
  const request = state.textInputRequest;
  if (!request) return;
  state.textInputRequest = null;
  if (elements.textInputDialog.open) elements.textInputDialog.close();
  request.resolve(value);
}

function requestTextInput({ title, message, label = "内容", value = "", placeholder = "" } = {}) {
  if (state.textInputRequest) finishTextInput(null);
  const request = {};
  const promise = new Promise((resolve) => {
    request.resolve = resolve;
  });
  state.textInputRequest = request;
  elements.textInputDialogTitle.textContent = title || "输入内容";
  elements.textInputDialogMessage.textContent = message || "";
  elements.textInputDialogMessage.hidden = !message;
  elements.textInputDialogLabel.textContent = label;
  elements.textInputDialogInput.value = value == null ? "" : String(value);
  elements.textInputDialogInput.placeholder = placeholder;
  elements.textInputDialog.showModal();
  requestAnimationFrame(() => {
    if (state.textInputRequest !== request || !elements.textInputDialog.open) return;
    elements.textInputDialogInput.focus();
    elements.textInputDialogInput.select();
  });
  return promise;
}

