function renderClaudePluginList() {
  const plugins = state.claudeExtensions.plugins;
  elements.claudePluginList.replaceChildren();
  elements.claudePluginError.textContent = "";
  if (!plugins.length) {
    elements.claudePluginList.innerHTML = '<div class="list-empty">尚未安装 Claude Plugin</div>';
    return;
  }
  for (const plugin of plugins) {
    const row = document.createElement("div");
    row.className = "claude-plugin-row";
    row.innerHTML = '<span class="claude-extension-icon"><i data-lucide="blocks"></i></span><span class="claude-plugin-identity"><strong></strong><small></small></span><label class="toggle-line claude-plugin-toggle"><input type="checkbox" /><span class="toggle-control"></span><span>启用</span></label><span class="claude-plugin-row-actions"><button class="icon-button" data-action="details" type="button" title="查看详情与 Token 预计" aria-label="查看插件详情"><i data-lucide="info"></i></button><button class="icon-button" data-action="update" type="button" title="更新插件" aria-label="更新插件"><i data-lucide="refresh-cw"></i></button><button class="icon-button danger-button" data-action="remove" type="button" title="卸载插件" aria-label="卸载插件"><i data-lucide="trash-2"></i></button></span>';
    row.querySelector("strong").textContent = plugin.identifier;
    row.querySelector("small").textContent = [plugin.version ? `v${plugin.version}` : null, plugin.scope].filter(Boolean).join(" · ");
    const toggle = row.querySelector('input[type="checkbox"]');
    const details = row.querySelector('[data-action="details"]');
    const update = row.querySelector('[data-action="update"]');
    const remove = row.querySelector('[data-action="remove"]');
    toggle.checked = plugin.enabled !== false;
    toggle.disabled = plugin.editable === false;
    update.hidden = plugin.editable === false;
    remove.hidden = plugin.editable === false;
    toggle.addEventListener("change", () => setClaudePluginEnabled(plugin.identifier, toggle.checked, toggle));
    details.addEventListener("click", () => showClaudePluginDetails(plugin.identifier));
    update.addEventListener("click", () => updateClaudePlugin(plugin.identifier));
    remove.addEventListener("click", () => deleteClaudePlugin(plugin.identifier));
    elements.claudePluginList.append(row);
  }
}

function renderClaudePluginMarket() {
  const market = state.claudeExtensions.pluginMarket || {};
  const marketplaces = Array.isArray(market.marketplaces) ? market.marketplaces : [];
  const available = Array.isArray(market.available) ? market.available : [];
  const query = state.claudePluginMarketQuery.trim().toLowerCase();
  const filtered = available.filter((plugin) => {
    if (!query) return true;
    return [plugin.identifier, plugin.name, plugin.marketplace, plugin.description]
      .filter(Boolean)
      .some((value) => String(value).toLowerCase().includes(query));
  });
  elements.claudePluginMarketStatus.textContent = marketplaces.length
    ? `${marketplaces.length} 个市场 · ${filtered.length}/${available.length} 个可用插件`
    : "未配置 Claude 插件市场；可用手动安装已配置来源的插件";
  elements.claudePluginMarketList.replaceChildren();
  elements.claudePluginMarketplaceList.replaceChildren();
  for (const marketplace of marketplaces) {
    const row = document.createElement("div");
    row.className = "claude-plugin-marketplace-row";
    row.innerHTML = '<span><strong></strong><small></small></span><span class="claude-plugin-marketplace-actions"><button class="icon-button" type="button" title="更新市场" aria-label="更新插件市场"><i data-lucide="refresh-cw"></i></button><button class="icon-button danger-button" type="button" title="移除市场" aria-label="移除插件市场"><i data-lucide="trash-2"></i></button></span>';
    row.querySelector("strong").textContent = marketplace.name;
    row.querySelector("small").textContent = [marketplace.sourceType, marketplace.source, marketplace.trusted ? "可信来源" : null].filter(Boolean).join(" · ");
    row.querySelector("button[title='更新市场']").addEventListener("click", () => updateClaudePluginMarketplace(marketplace.name));
    row.querySelector("button[title='移除市场']").addEventListener("click", () => removeClaudePluginMarketplace(marketplace.name));
    elements.claudePluginMarketplaceList.append(row);
  }
  if (!filtered.length) {
    elements.claudePluginMarketList.innerHTML = '<div class="list-empty">没有匹配的可用插件</div>';
    return;
  }
  for (const plugin of filtered) {
    const row = document.createElement("article");
    row.className = "claude-plugin-market-row";
    row.innerHTML = `
      <div class="claude-plugin-market-identity">
        <strong></strong>
        <small></small>
      </div>
      <p class="claude-plugin-market-description"></p>
      <div class="claude-plugin-market-permissions"></div>
      <button class="secondary-button" type="button"><i data-lucide="download"></i><span></span></button>
    `;
    row.querySelector("strong").textContent = plugin.name || plugin.identifier;
    row.querySelector("small").textContent = [
      plugin.marketplace,
      plugin.version ? `v${plugin.version}` : null,
      plugin.installed ? `已安装${plugin.installedVersion ? ` · ${plugin.installedVersion}` : ""}` : null,
    ].filter(Boolean).join(" · ");
    row.querySelector(".claude-plugin-market-description").textContent = plugin.description || "此插件未提供描述";
    const permissions = Array.isArray(plugin.permissions) ? plugin.permissions : [];
    const permissionBox = row.querySelector(".claude-plugin-market-permissions");
    if (permissions.length) {
      permissionBox.textContent = `权限：${permissions.join("、")}`;
    } else {
      permissionBox.textContent = "未声明额外权限";
    }
    const action = row.querySelector("button");
    const needsUpdate = plugin.installed && plugin.installedVersion && plugin.version
      && plugin.installedVersion !== plugin.version;
    action.querySelector("span").textContent = needsUpdate ? "更新" : plugin.installed ? "已安装" : "安装";
    action.disabled = plugin.installed && !needsUpdate;
    action.addEventListener("click", () => installClaudePlugin(plugin.identifier, plugin));
    elements.claudePluginMarketList.append(row);
  }
}

async function addClaudePluginMarketplace() {
  const source = elements.claudePluginMarketplaceSourceInput.value.trim();
  if (!source) return elements.claudePluginMarketplaceSourceInput.focus();
  if (!window.confirm(`添加插件市场“${source}”？\n\n市场内容会由服务器上的 Claude CLI 下载和校验。`)) return;
  await mutateClaudePluginMarketplace(
    "/api/claude/plugin-marketplaces",
    { method: "POST", body: { source } },
    "插件市场已添加",
  );
  elements.claudePluginMarketplaceSourceInput.value = "";
}

async function updateClaudePluginMarketplace(name) {
  if (!window.confirm(`更新插件市场“${name}”？`)) return;
  await mutateClaudePluginMarketplace(
    `/api/claude/plugin-marketplaces/${encodeURIComponent(name)}/update`,
    { method: "POST" },
    "插件市场已更新",
  );
}

async function removeClaudePluginMarketplace(name) {
  if (!window.confirm(`移除插件市场“${name}”？已安装的插件不会自动卸载。`)) return;
  await mutateClaudePluginMarketplace(
    `/api/claude/plugin-marketplaces/${encodeURIComponent(name)}`,
    { method: "DELETE" },
    "插件市场已移除",
  );
}

async function mutateClaudePluginMarketplace(url, { method, body = null }, successMessage) {
  elements.claudePluginError.textContent = "";
  try {
    const response = await fetchWithTimeout(url, {
      method,
      headers: {
        ...(body ? { "Content-Type": "application/json" } : {}),
        "X-Codex-Desktop-Action": method === "DELETE"
          ? "claude-plugin-marketplace-remove"
          : body ? "claude-plugin-marketplace-add" : "claude-plugin-marketplace-update",
      },
      ...(body ? { body: JSON.stringify(body) } : {}),
    }, 100_000);
    const data = await response.json().catch(() => ({}));
    if (!response.ok) throw new Error(data.error || "Claude 插件市场操作失败");
    await loadClaudeExtensions();
    toast(successMessage);
  } catch (error) {
    elements.claudePluginError.textContent = error.message;
  }
}

async function installClaudePlugin(identifierOverride = null, catalogEntry = null) {
  const identifier = String(identifierOverride || elements.claudePluginIdentifierInput.value || "").trim();
  if (!identifier) return elements.claudePluginIdentifierInput.focus();
  if (catalogEntry?.permissions?.length) {
    const allowed = window.confirm(
      `安装 ${identifier}？\n\n该插件声明的权限：\n${catalogEntry.permissions.join("\n")}`,
    );
    if (!allowed) return;
  }
  const submit = elements.claudePluginForm.querySelector('button[type="submit"]');
  if (!identifierOverride) submit.disabled = true;
  elements.claudePluginError.textContent = "";
  try {
    const response = await fetchWithTimeout("/api/claude/plugins", {
      method: "POST",
      headers: { "Content-Type": "application/json", "X-Codex-Desktop-Action": "claude-plugin-install" },
      body: JSON.stringify({ identifier }),
    }, 70_000);
    const data = await response.json().catch(() => ({}));
    if (!response.ok) throw new Error(data.error || "Claude Plugin 安装失败");
    if (!identifierOverride) elements.claudePluginIdentifierInput.value = "";
    await loadClaudeExtensions();
    toast(`Plugin “${identifier}”已安装`);
  } catch (error) {
    elements.claudePluginError.textContent = error.message;
  } finally {
    if (!identifierOverride) submit.disabled = false;
  }
}

async function setClaudePluginEnabled(identifier, enabled, input) {
  input.disabled = true;
  elements.claudePluginError.textContent = "";
  try {
    const response = await fetchWithTimeout(`/api/claude/plugins/${encodeURIComponent(identifier)}/enabled`, {
      method: "PUT",
      headers: { "Content-Type": "application/json", "X-Codex-Desktop-Action": "claude-plugin-enabled" },
      body: JSON.stringify({ enabled }),
    }, 70_000);
    const data = await response.json().catch(() => ({}));
    if (!response.ok) throw new Error(data.error || "Claude Plugin 状态更新失败");
    await loadClaudeExtensions();
    toast(`Plugin “${identifier}”已${enabled ? "启用" : "停用"}`);
  } catch (error) {
    input.checked = !enabled;
    input.disabled = false;
    elements.claudePluginError.textContent = error.message;
  }
}

async function deleteClaudePlugin(identifier) {
  if (!confirm(`卸载 Plugin “${identifier}”？`)) return;
  elements.claudePluginError.textContent = "";
  try {
    const response = await fetchWithTimeout(`/api/claude/plugins/${encodeURIComponent(identifier)}`, {
      method: "DELETE",
      headers: { "X-Codex-Desktop-Action": "claude-plugin-delete" },
    }, 70_000);
    if (!response.ok) {
      const data = await response.json().catch(() => ({}));
      throw new Error(data.error || "Claude Plugin 卸载失败");
    }
    await loadClaudeExtensions();
    toast(`Plugin “${identifier}”已卸载`);
  } catch (error) {
    elements.claudePluginError.textContent = error.message;
  }
}

async function showClaudePluginDetails(identifier) {
  elements.claudePluginError.textContent = "";
  elements.claudePluginLifecycleOutput.hidden = false;
  elements.claudePluginLifecycleOutput.textContent = "正在读取插件详情…";
  try {
    const response = await fetchWithTimeout(
      `/api/claude/plugins/${encodeURIComponent(identifier)}/details`,
      { cache: "no-store" },
      35_000,
    );
    const data = await response.json().catch(() => ({}));
    if (!response.ok) throw new Error(data.error || "Claude 插件详情读取失败");
    elements.claudePluginLifecycleOutput.textContent = data.details || "插件未返回组件或 Token 预计信息";
  } catch (error) {
    elements.claudePluginLifecycleOutput.hidden = true;
    elements.claudePluginError.textContent = error.message;
  }
}

async function updateClaudePlugin(identifier) {
  if (!confirm(`将 Plugin “${identifier}”更新到市场中的最新版本？更新会在下一个 Claude 进程生效。`)) return;
  await mutateClaudePluginLifecycle(
    `/api/claude/plugins/${encodeURIComponent(identifier)}/update`,
    {
      method: "POST",
      headers: { "X-Codex-Desktop-Action": "claude-plugin-update" },
    },
    `Plugin “${identifier}”已更新`,
    { reload: true },
  );
}

async function validateClaudePlugin() {
  const requestedPath = elements.claudePluginValidatePathInput.value.trim();
  if (!state.currentProject) {
    elements.claudePluginError.textContent = "请先选择一个工程";
    return;
  }
  if (!requestedPath) return elements.claudePluginValidatePathInput.focus();
  await mutateClaudePluginLifecycle(
    "/api/claude/plugins/validate",
    {
      method: "POST",
      headers: {
        "Content-Type": "application/json",
        "X-Codex-Desktop-Action": "claude-plugin-validate",
      },
      body: JSON.stringify({
        cwd: state.currentProject.path,
        path: requestedPath,
        strict: true,
      }),
    },
    null,
    { outputField: "diagnostics", validField: "valid" },
  );
}

async function pruneClaudePlugins(dryRun) {
  if (!dryRun && !confirm("清理当前账号不再使用的自动安装依赖？建议先执行“预览依赖清理”。")) return;
  await mutateClaudePluginLifecycle(
    "/api/claude/plugins/prune",
    {
      method: "POST",
      headers: {
        "Content-Type": "application/json",
        "X-Codex-Desktop-Action": "claude-plugin-prune",
      },
      body: JSON.stringify({
        dryRun,
        ...(dryRun ? {} : { confirmation: "清理未使用插件" }),
      }),
    },
    dryRun ? "插件依赖清理预览已生成" : "未使用的插件依赖已清理",
    { outputField: "diagnostics", reload: !dryRun },
  );
}

async function mutateClaudePluginLifecycle(
  url,
  options,
  successMessage,
  { outputField = null, validField = null, reload = false } = {},
) {
  const buttons = [
    elements.claudePluginValidateButton,
    elements.claudePluginPrunePreviewButton,
    elements.claudePluginPruneButton,
  ];
  buttons.forEach((button) => { button.disabled = true; });
  elements.claudePluginError.textContent = "";
  try {
    const response = await fetchWithTimeout(url, options, 70_000);
    const data = await response.json().catch(() => ({}));
    if (!response.ok) throw new Error(data.error || "Claude 插件操作失败");
    if (outputField) {
      elements.claudePluginLifecycleOutput.hidden = false;
      elements.claudePluginLifecycleOutput.textContent = data[outputField]
        || (validField && data[validField] === true ? "校验通过" : "没有返回诊断详情");
    }
    if (validField && data[validField] !== true) {
      elements.claudePluginError.textContent = "Claude 插件严格校验未通过，请根据诊断修复";
    } else if (successMessage) {
      toast(successMessage);
    }
    if (reload) await loadClaudeExtensions();
  } catch (error) {
    elements.claudePluginError.textContent = error.message;
  } finally {
    buttons.forEach((button) => { button.disabled = false; });
  }
}

function setClaudePluginAdminBusy(busy) {
  [
    elements.claudePluginInitButton,
    elements.claudePluginEvalButton,
    elements.claudePluginTagPreviewButton,
    elements.claudePluginTagCreateButton,
  ].forEach((button) => { button.disabled = busy; });
}

async function initializeClaudePlugin() {
  const name = elements.claudePluginInitNameInput.value.trim();
  if (!name) return elements.claudePluginInitNameInput.focus();
  const components = [...elements.claudePluginInitComponents.querySelectorAll('input[type="checkbox"]:checked')]
    .map((input) => input.value);
  if (!window.confirm(`在当前账号的 Claude Skills 目录创建插件“${name}”？不会覆盖已有插件。`)) return;
  setClaudePluginAdminBusy(true);
  elements.claudePluginError.textContent = "";
  try {
    const response = await fetchWithTimeout("/api/claude/plugins/init", {
      method: "POST",
      headers: {
        "Content-Type": "application/json",
        "X-Codex-Desktop-Action": "claude-plugin-init",
      },
      body: JSON.stringify({
        name,
        description: elements.claudePluginInitDescriptionInput.value.trim() || null,
        components,
      }),
    }, 70_000);
    const data = await response.json().catch(() => ({}));
    if (!response.ok) throw new Error(data.error || "Claude 插件脚手架创建失败");
    elements.claudePluginAdminOutput.hidden = false;
    elements.claudePluginAdminOutput.textContent = data.diagnostics || `插件 ${name} 已创建`;
    await loadClaudeExtensions();
    toast(`Claude 插件“${name}”脚手架已创建`);
  } catch (error) {
    elements.claudePluginError.textContent = error.message;
  } finally {
    setClaudePluginAdminBusy(false);
  }
}

async function evaluateClaudePlugin() {
  const cwd = state.currentProject?.path;
  const target = elements.claudePluginEvalTargetInput.value.trim();
  const maxCostUsd = Number(elements.claudePluginEvalCostInput.value);
  const runs = Number(elements.claudePluginEvalRunsInput.value);
  const threshold = Number(elements.claudePluginEvalThresholdInput.value);
  if (!cwd) {
    elements.claudePluginError.textContent = "请先选择一个工程";
    return;
  }
  if (!target) return elements.claudePluginEvalTargetInput.focus();
  if (!window.confirm(
    `运行插件 Eval“${target}”？\n\n最多使用 $${maxCostUsd.toFixed(2)}，每个用例运行 ${runs} 次。服务器固定禁用 scaffold 和公开报告。`,
  )) return;
  setClaudePluginAdminBusy(true);
  elements.claudePluginError.textContent = "";
  elements.claudePluginAdminOutput.hidden = false;
  elements.claudePluginAdminOutput.textContent = "Claude 插件 Eval 正在运行…";
  try {
    const response = await fetchWithTimeout("/api/claude/plugins/eval", {
      method: "POST",
      headers: {
        "Content-Type": "application/json",
        "X-Codex-Desktop-Action": "claude-plugin-eval",
      },
      body: JSON.stringify({ cwd, target, maxCostUsd, runs, threshold }),
    }, 31 * 60_000);
    const data = await response.json().catch(() => ({}));
    if (!response.ok) throw new Error(data.error || "Claude 插件 Eval 执行失败");
    elements.claudePluginAdminOutput.textContent = data.diagnostics || "Claude 插件 Eval 未返回报告";
    if (data.partial) elements.claudePluginError.textContent = "Eval 达到成本上限，已返回部分结果";
    else if (!data.thresholdPassed) elements.claudePluginError.textContent = "Eval 已完成，但未达到通过阈值";
    else toast("Claude 插件 Eval 已通过");
  } catch (error) {
    elements.claudePluginAdminOutput.hidden = true;
    elements.claudePluginError.textContent = error.message;
  } finally {
    setClaudePluginAdminBusy(false);
  }
}

