function renderClaudeAutoMode() {
  const snapshot = state.claudeAutoMode;
  elements.claudeProjectPurgeSection.hidden = !canUseClaudeProjectPurge();
  elements.claudeUltraReviewSection.hidden = !canUseClaudeUltraReview();
  elements.claudeAutoModeSummary.replaceChildren();
  elements.claudeAutoModeEffectiveList.replaceChildren();
  elements.claudeAutoModeDefaultList.replaceChildren();
  if (!snapshot) {
    elements.claudeAutoModeStatus.textContent = state.claudeAutoModeLoading ? "正在读取" : "等待读取";
    return;
  }
  elements.claudeAutoModeStatus.textContent = snapshot.hasCustomRules ? "存在自定义规则" : "使用官方默认";
  for (const group of Array.isArray(snapshot.groups) ? snapshot.groups : []) {
    const item = document.createElement("div");
    item.dataset.customized = group.customized === true ? "true" : "false";
    item.innerHTML = "<strong></strong><span></span>";
    item.querySelector("strong").textContent = claudeAutoModeGroupLabel(group.name);
    item.querySelector("span").textContent = group.customized
      ? `${group.effectiveCount} 条 · 已自定义`
      : `${group.effectiveCount} 条 · 默认`;
    elements.claudeAutoModeSummary.append(item);
  }
  const effective = Array.isArray(snapshot.effective) ? snapshot.effective : [];
  const defaults = Array.isArray(snapshot.defaults) ? snapshot.defaults : [];
  renderClaudeAutoModeRules(elements.claudeAutoModeEffectiveList, effective, "当前分组没有生效规则");
  renderClaudeAutoModeRules(elements.claudeAutoModeDefaultList, defaults, "当前分组没有默认规则");
}

function renderClaudeAutoModeRules(container, rules, emptyLabel) {
  if (!rules.length) {
    const empty = document.createElement("li");
    empty.className = "list-empty";
    empty.textContent = emptyLabel;
    container.append(empty);
    return;
  }
  rules.forEach((rule, index) => {
    const item = document.createElement("li");
    const title = String(rule).split(":", 1)[0].trim();
    item.innerHTML = "<strong></strong><p></p>";
    item.querySelector("strong").textContent = title && title.length <= 120 ? title : `规则 ${index + 1}`;
    item.querySelector("p").textContent = rule;
    container.append(item);
  });
}

function claudeAutoModeGroupLabel(group) {
  return ({
    allow: "Allow",
    soft_deny: "Soft deny",
    hard_deny: "Hard deny",
    environment: "Environment",
  })[group] || group;
}

