async function loadClaudeUltraReviews({ quiet = false } = {}) {
  const cwd = state.currentProject?.path;
  if (!cwd || !canUseClaudeUltraReview() || state.claudeUltraReviewLoading) return state.claudeUltraReviews;
  state.claudeUltraReviewLoading = true;
  if (!quiet) elements.claudeUltraReviewError.textContent = "";
  try {
    const response = await fetchWithTimeout(
      `/api/claude/ultrareview?cwd=${encodeURIComponent(cwd)}`,
      { cache: "no-store" },
      30_000,
    );
    const data = await response.json().catch(() => ({}));
    if (!response.ok) throw new Error(data.error || "Claude Ultra Review 状态读取失败");
    if (state.currentProject?.path !== cwd) return state.claudeUltraReviews;
    state.claudeUltraReviews = Array.isArray(data.reviews) ? data.reviews : [];
    renderClaudeUltraReviews();
    return state.claudeUltraReviews;
  } catch (error) {
    if (!quiet) elements.claudeUltraReviewError.textContent = error.message;
    return state.claudeUltraReviews;
  } finally {
    state.claudeUltraReviewLoading = false;
  }
}

function renderClaudeUltraReviews() {
  elements.claudeUltraReviewList.replaceChildren();
  const reviews = Array.isArray(state.claudeUltraReviews) ? state.claudeUltraReviews : [];
  if (!reviews.length) {
    elements.claudeUltraReviewList.innerHTML = '<div class="list-empty">当前工程还没有 Ultra Review 记录</div>';
    return;
  }
  for (const review of reviews) {
    const row = document.createElement("article");
    row.className = "claude-ultrareview-row";
    row.dataset.status = review.status || "unknown";
    row.innerHTML = `
      <header>
        <span><strong></strong><small></small></span>
        <span class="claude-ultrareview-badge"></span>
      </header>
      <p class="claude-ultrareview-meta"></p>
      <pre hidden></pre>
      <footer><button class="secondary-button danger-button" type="button" hidden><i data-lucide="square"></i><span>取消审查</span></button></footer>
    `;
    row.querySelector("strong").textContent = review.target ? `目标：${review.target}` : "当前分支";
    row.querySelector("small").textContent = `最长 ${review.timeoutMinutes || 30} 分钟`;
    row.querySelector(".claude-ultrareview-badge").textContent = claudeUltraReviewStatusLabel(review.status);
    const elapsedEnd = review.finishedAt || Date.now();
    row.querySelector(".claude-ultrareview-meta").textContent = [
      review.startedAt ? `耗时 ${formatElapsedTime(Math.max(0, elapsedEnd - review.startedAt))}` : null,
      review.error || null,
    ].filter(Boolean).join(" · ");
    const output = row.querySelector("pre");
    if (review.output) {
      output.hidden = false;
      output.textContent = review.output;
    }
    const cancel = row.querySelector("button");
    cancel.hidden = !["running", "cancelling"].includes(review.status);
    cancel.disabled = review.status === "cancelling";
    cancel.addEventListener("click", () => cancelClaudeUltraReview(review.id));
    elements.claudeUltraReviewList.append(row);
  }
  refreshIcons();
}

function claudeUltraReviewStatusLabel(status) {
  return ({
    running: "审查中",
    cancelling: "正在取消",
    completed: "已完成",
    failed: "失败",
    cancelled: "已取消",
    interrupted: "已中断",
  })[status] || "未知";
}

async function startClaudeUltraReview() {
  const cwd = state.currentProject?.path;
  if (!cwd) {
    elements.claudeUltraReviewError.textContent = "请先选择一个工程";
    return;
  }
  const target = elements.claudeUltraReviewTargetInput.value.trim();
  const timeoutMinutes = Number(elements.claudeUltraReviewTimeoutInput.value);
  const label = target || "当前分支";
  if (!window.confirm(
    `启动 Ultra Review 审查“${label}”？\n\n此操作会调用 Claude 云端多 Agent，并产生官方账号用量；最长等待 ${timeoutMinutes} 分钟。`,
  )) return;
  elements.claudeUltraReviewStartButton.disabled = true;
  elements.claudeUltraReviewError.textContent = "";
  try {
    const response = await fetchWithTimeout("/api/claude/ultrareview", {
      method: "POST",
      headers: {
        "Content-Type": "application/json",
        "X-Codex-Desktop-Action": "claude-ultrareview-start",
      },
      body: JSON.stringify({ cwd, target: target || null, timeoutMinutes }),
    }, 45_000);
    const data = await response.json().catch(() => ({}));
    if (!response.ok) throw new Error(data.error || "Claude Ultra Review 启动失败");
    state.claudeUltraReviews = [
      data.review,
      ...state.claudeUltraReviews.filter((review) => review.id !== data.review?.id),
    ].filter(Boolean);
    renderClaudeUltraReviews();
    startClaudeUltraReviewPolling();
    toast("Claude Ultra Review 已在服务器启动");
  } catch (error) {
    elements.claudeUltraReviewError.textContent = error.message;
  } finally {
    elements.claudeUltraReviewStartButton.disabled = false;
  }
}

async function cancelClaudeUltraReview(id) {
  if (!window.confirm("取消正在运行的 Ultra Review？已产生的官方账号用量无法撤销。")) return;
  elements.claudeUltraReviewError.textContent = "";
  try {
    const response = await fetchWithTimeout(`/api/claude/ultrareview/${encodeURIComponent(id)}/cancel`, {
      method: "POST",
      headers: { "X-Codex-Desktop-Action": "claude-ultrareview-cancel" },
    }, 30_000);
    const data = await response.json().catch(() => ({}));
    if (!response.ok) throw new Error(data.error || "Claude Ultra Review 取消失败");
    state.claudeUltraReviews = state.claudeUltraReviews.map((review) =>
      review.id === id ? data.review : review);
    renderClaudeUltraReviews();
  } catch (error) {
    elements.claudeUltraReviewError.textContent = error.message;
  }
}

function startClaudeUltraReviewPolling() {
  if (state.claudeUltraReviewTimer || !canUseClaudeUltraReview()) return;
  state.claudeUltraReviewTimer = setInterval(() => {
    if (
      !elements.claudeDialog.open
      || state.claudeSettingsTab !== "extensions"
      || state.claudeExtensionTab !== "autoMode"
    ) {
      stopClaudeUltraReviewPolling();
      return;
    }
    renderClaudeUltraReviews();
    if (state.claudeUltraReviews.some((review) => ["running", "cancelling"].includes(review.status))) {
      void loadClaudeUltraReviews({ quiet: true });
    }
  }, 5_000);
}

function stopClaudeUltraReviewPolling() {
  clearInterval(state.claudeUltraReviewTimer);
  state.claudeUltraReviewTimer = null;
}

function parseClaudeToolRules(value) {
  const rules = [];
  let current = "";
  let depth = 0;
  for (const character of String(value || "")) {
    if (character === "(") depth += 1;
    else if (character === ")" && depth > 0) depth -= 1;
    if (depth === 0 && (character === "," || /\s/.test(character))) {
      if (current.trim() && !rules.includes(current.trim())) rules.push(current.trim());
      current = "";
    } else current += character;
  }
  if (current.trim() && !rules.includes(current.trim())) rules.push(current.trim());
  return rules.slice(0, 64);
}

