async function saveClaudeProvider() {
  const id = elements.claudeProviderIdInput.value;
  const body = {
    name: elements.claudeProviderNameInput.value.trim(),
    baseUrl: elements.claudeProviderBaseUrlInput.value.trim(),
    model: elements.claudeProviderModelInput.value.trim(),
  };
  if (elements.claudeProviderApiKeyInput.value) body.apiKey = elements.claudeProviderApiKeyInput.value;
  const endpoint = id ? `/api/claude/providers/${encodeURIComponent(id)}` : "/api/claude/providers";
  try {
    const response = await fetchWithTimeout(endpoint, {
      method: id ? "PUT" : "POST",
      headers: { "Content-Type": "application/json", "X-Codex-Desktop-Action": id ? "claude-provider-update" : "claude-provider-create" },
      body: JSON.stringify(body),
    }, 12_000);
    const data = await response.json().catch(() => ({}));
    if (!response.ok) throw new Error(data.error || "Claude 供应商保存失败");
    const profile = data.profile;
    await fetchWithTimeout(`/api/claude/providers/${encodeURIComponent(profile.id)}/activate`, {
      method: "POST",
      headers: { "X-Codex-Desktop-Action": "claude-provider-activate" },
    }, 12_000);
    await loadClaudeConfig();
    toast("Claude API 供应商已保存并启用");
  } catch (error) {
    elements.claudeProviderError.textContent = error.message;
  }
}

async function probeClaudeProviderConnection() {
  const id = elements.claudeProviderIdInput.value;
  const body = {
    id: id || undefined,
    baseUrl: elements.claudeProviderBaseUrlInput.value.trim(),
  };
  if (elements.claudeProviderApiKeyInput.value) body.apiKey = elements.claudeProviderApiKeyInput.value;
  elements.claudeProviderProbeButton.disabled = true;
  elements.claudeProviderError.textContent = "";
  elements.claudeProviderProbeResult.hidden = false;
  elements.claudeProviderProbeResult.dataset.status = "checking";
  elements.claudeProviderProbeResult.textContent = "正在从服务器测试连接…";
  try {
    const response = await fetchWithTimeout("/api/claude/providers/probe", {
      method: "POST",
      headers: {
        "Content-Type": "application/json",
        "X-Codex-Desktop-Action": "claude-provider-probe",
      },
      body: JSON.stringify(body),
    }, 15_000);
    const data = await response.json().catch(() => ({}));
    if (!response.ok) throw new Error(data.error || "Claude 供应商连接测试失败");
    const catalogKey = id || "__draft";
    state.claudeProviderModelCatalogs[catalogKey] = Array.isArray(data.models) ? data.models : [];
    elements.claudeProviderModelOptions.replaceChildren(
      ...state.claudeProviderModelCatalogs[catalogKey].map((model) => new Option(model, model)),
    );
    elements.claudeProviderProbeResult.dataset.status = data.ok ? "ready" : "failed";
    elements.claudeProviderProbeResult.textContent = data.message || (data.ok ? "连接成功" : "连接失败");
  } catch (error) {
    elements.claudeProviderProbeResult.dataset.status = "failed";
    elements.claudeProviderProbeResult.textContent = error.message;
  } finally {
    elements.claudeProviderProbeButton.disabled = false;
  }
}

