    if (!response.ok) throw new Error(data.error || "无法添加 Claude 官方账号");
    state.selectedClaudeOfficialAccountId = data.accounts?.find((account) => !before.has(account.id))?.id
      || data.activeId
      || null;
    await loadClaudeConfig();
