async function deleteClaudeOfficialAccount(account) {
  elements.claudeOfficialError.textContent = "";
  try {
    const previewResponse = await fetchWithTimeout(
      `/api/claude/official/accounts/${encodeURIComponent(account.id)}/delete-preview`,
      { cache: "no-store" },
      12_000,
    );
    const preview = await previewResponse.json();
    if (!previewResponse.ok) throw new Error(preview.error || "无法检查 Claude 官方账号绑定");
    if (!preview.deletable) {
      const names = (preview.sessions || []).slice(0, 3).map((session) => session.name).join("、");
      throw new Error([preview.reason, names ? `绑定会话：${names}` : null].filter(Boolean).join("；"));
    }
    const phrase = `删除 ${account.label || "Claude 账号"}`;
    if (prompt(`此操作会永久删除服务器中的账号凭据与代理配置。\n请输入“${phrase}”确认。`, "") !== phrase) {
      return;
    }
    const response = await fetchWithTimeout(
      `/api/claude/official/accounts/${encodeURIComponent(account.id)}`,
      {
        method: "DELETE",
        headers: {
          "Content-Type": "application/json",
          "X-Codex-Desktop-Action": "claude-official-account-delete",
        },
        body: JSON.stringify({ confirmation: "彻底删除 Claude 官方账号" }),
      },
      20_000,
    );
    const data = await response.json();
    if (!response.ok) throw new Error(data.error || "无法删除 Claude 官方账号");
    state.selectedClaudeOfficialAccountId = data.activeId || data.accounts?.[0]?.id || null;
    await loadClaudeConfig();
    toast("Claude 官方账号槽已彻底删除");
  } catch (error) {
    elements.claudeOfficialError.textContent = error.message;
  }
}

