function claudeOfficialProxyDraft() {
  const host = elements.claudeOfficialProxyHost.value.trim();
  const port = Number(elements.claudeOfficialProxyPort.value);
  if (!host || !Number.isInteger(port)) throw new Error("请填写代理主机和端口");
  return {
    protocol: elements.claudeOfficialProxyProtocol.value,
    host,
    port,
    username: elements.claudeOfficialProxyUsername.value.trim(),
    password: elements.claudeOfficialProxyPassword.value,
  };
}

async function mutateClaudeOfficialProxy(action) {
  const account = selectedClaudeOfficialAccount();
  if (!account) throw new Error("请先选择 Claude 官方账号");
  const draft = action === "clear" ? null : claudeOfficialProxyDraft();
  const path = action === "test"
    ? `/api/claude/official/accounts/${encodeURIComponent(account.id)}/proxy/test`
    : `/api/claude/official/accounts/${encodeURIComponent(account.id)}/proxy`;
  const response = await fetchWithTimeout(path, {
    method: action === "test" ? "POST" : "PUT",
    headers: {
      "Content-Type": "application/json",
      "X-Codex-Desktop-Action": action === "test"
        ? "claude-official-proxy-test"
        : "claude-official-proxy-save",
    },
    body: JSON.stringify({
      proxy: draft,
      preserveAuthentication: account.proxy?.hasAuthentication === true
        && !draft?.username
        && !draft?.password,
    }),
  }, 30_000);
  const data = await response.json().catch(() => ({}));
  if (!response.ok) throw new Error(data.error || "Claude 账号代理操作失败");
  if (action === "test") {
    const health = data.proxy?.health;
    elements.claudeOfficialProxyStatus.textContent = health?.status === "ready"
      ? `测试通过 · ${health.exitIp || `${data.proxy.host}:${data.proxy.port}`}`
      : "代理测试失败";
    toast("Claude 账号代理测试通过");
  } else {
    await loadClaudeConfig();
    toast(action === "clear" ? "Claude 账号代理已清除" : "Claude 账号代理已保存");
  }
}

async function handleClaudeOfficialProxy(action) {
  const buttons = [
    elements.claudeOfficialProxyClearButton,
    elements.claudeOfficialProxyTestButton,
    elements.claudeOfficialProxySaveButton,
  ];
  buttons.forEach((button) => { button.disabled = true; });
  try {
    elements.claudeOfficialError.textContent = "";
    await mutateClaudeOfficialProxy(action);
  } catch (error) {
    elements.claudeOfficialError.textContent = error.message;
  } finally {
    buttons.forEach((button) => { button.disabled = false; });
    elements.claudeOfficialProxyPassword.value = "";
  }
}

