function cancelClaudeOfficialLoginConfirmation() {
  const confirmation = state.claudeOfficialLoginConfirmation;
  if (!confirmation) return;
  confirmation.controller.abort();
  state.claudeOfficialLoginConfirmation = null;
}

function showClaudeOfficialLoginFailure(message) {
  const detail = String(message || "Claude 官方登录未完成");
  elements.claudeOfficialError.textContent = detail;
  if (state.officialBrowserRuntime === "claude") {
    elements.officialBrowserStatus.textContent = detail;
  }
}

async function closeClaudeOfficialBrowserSession() {
  const response = await fetch("/api/claude/official/login/browser/close", {
    method: "POST",
    headers: { "X-Codex-Desktop-Action": "claude-official-login-browser-close" },
  });
  if (!response.ok) await readApiJson(response, "无法关闭 Claude 服务器登录窗口");
}

async function confirmClaudeOfficialLogin({ timeoutMs = 30_000 } = {}) {
  if (state.claudeOfficialLoginConfirmation) {
    return state.claudeOfficialLoginConfirmation.promise;
  }
  const controller = new AbortController();
  const confirmation = { controller, promise: null };
  confirmation.promise = (async () => {
    const deadline = Date.now() + timeoutMs;
    let stoppedAt = null;
    while (!controller.signal.aborted && Date.now() < deadline) {
      try {
        const config = await loadClaudeConfig();
        const loginAccountId = config.runtime?.officialLogin?.accountId
          || state.selectedClaudeOfficialAccountId;
        const account = config.official?.accounts?.find((entry) => entry.id === loginAccountId);
        if (account?.credentialStatus === "valid" || (!loginAccountId && config.official?.loggedIn === true)) {
          elements.claudeOfficialError.textContent = "";
          if (state.officialBrowserRuntime === "claude") closeOfficialBrowserDialog();
          await closeClaudeOfficialBrowserSession().catch(() => {});
          toast("Claude 官方登录成功");
          return true;
        }
        const login = config.runtime?.officialLogin || null;
        const running = login?.running === true || config.runtime?.officialLoginRunning === true;
        if (running) {
          stoppedAt = null;
        } else {
          stoppedAt ||= Date.now();
          if (Date.now() - stoppedAt >= 3_000) {
            showClaudeOfficialLoginFailure("授权码未写入服务器，请重新开始 Claude 官方登录");
            return false;
          }
        }
      } catch (error) {
        if (!controller.signal.aborted) showClaudeOfficialLoginFailure(error.message);
      }
      await new Promise((resolve) => setTimeout(resolve, 1_000));
    }
    if (!controller.signal.aborted) {
      showClaudeOfficialLoginFailure("确认服务器登录超时，请检查授权页面后重试");
    }
    return false;
  })().finally(() => {
    if (state.claudeOfficialLoginConfirmation === confirmation) {
      state.claudeOfficialLoginConfirmation = null;
    }
  });
  state.claudeOfficialLoginConfirmation = confirmation;
  return confirmation.promise;
}

async function submitClaudeOfficialCodeFromBrowser() {
  if (state.officialBrowserRuntime !== "claude") return;
  elements.officialBrowserClaudeCodeButton.disabled = true;
  try {
    const response = await fetch("/api/claude/official/login/browser/clipboard", {
      method: "POST",
      headers: { "X-Codex-Desktop-Action": "claude-official-login-browser-clipboard" },
    });
    const data = await readApiJson(response, "无法读取服务器授权码");
    const code = String(data.text || "").trim();
    if (!code || code.length < 12 || code.length > 4_096 || /[\r\n]/.test(code)) {
      await reopenClaudeOfficialAuthorizationPage({ silent: true }).catch(() => {});
      throw new Error("剪贴板内容不是 Claude 授权码，已重新打开授权页");
    }
    elements.claudeOfficialCodeInput.value = code;
    await submitClaudeOfficialCode();
  } catch (error) {
    elements.officialBrowserStatus.textContent = error.message;
    toast(error.message, "error");
  } finally {
    elements.officialBrowserClaudeCodeButton.disabled = false;
  }
}

