function promptClaudeInstall({ once = false } = {}) {
  if (!canUseClaudePermission("claudeRuntime") || claudeComponentReady()) return;
  if (!isAccountAdmin()) {
    toast("服务器尚未安装 Claude Code，请联系管理员在版本中心安装", "error");
    return;
  }
  const goToVersionCenter = window.confirm(
    "服务器尚未安装 Claude Code，Claude 工作页面暂不可用。\n\n是否前往版本中心下载并安装？",
  );
  if (goToVersionCenter) openVersionDialog();
  else if (!once) elements.runtimeSwitcherButton.focus();
}

