async function openAccountDialog() {
  elements.accountError.textContent = "";
  elements.accountDialog.showModal();
  elements.accountForm.querySelector(".settings-body").scrollTop = 0;
  renderAccountDrawer();
  startAccountCountdown();
  await refreshAccountDrawer();
}

async function refreshAccountDrawer({ announce = false } = {}) {
  elements.refreshAccountButton.disabled = true;
  state.accountOfficialQuotaError = null;
  try {
    const [data] = await Promise.all([
      loadAccount(),
      loadAccountOfficialQuota({ refresh: true }),
    ]);
    if (!data) throw new Error("无法读取账号信息");
    renderAccountDrawer();
    if (announce) {
      toast(state.accountOfficialQuota?.refreshDeferred
        ? "任务执行中，已显示最近同步的官方额度"
        : "账户用量已刷新");
    }
  } catch (error) {
    elements.accountError.textContent = error.message;
  } finally {
    elements.refreshAccountButton.disabled = false;
  }
}

