function openCodexFeedbackDialog() {
  if (state.runtime !== "codex" || !canUseCodexFeedback()) {
    toast("当前账号没有 Codex 诊断反馈权限", "error");
    return;
  }
  resetCodexFeedbackDialog();
  elements.codexFeedbackDialog.showModal();
  elements.codexFeedbackReasonInput.focus();
}

function closeCodexFeedbackDialog() {
  if (elements.codexFeedbackDialog.open) elements.codexFeedbackDialog.close();
  else resetCodexFeedbackDialog();
}

function resetCodexFeedbackDialog() {
  state.codexFeedbackRevision += 1;
  state.codexFeedbackPreview = null;
  state.codexFeedbackLoading = false;
  elements.codexFeedbackForm.reset();
  elements.codexFeedbackPreview.hidden = true;
  elements.codexFeedbackPreviewText.textContent = "";
  elements.codexFeedbackPreviewExpiry.textContent = "10 分钟内有效";
  elements.codexFeedbackError.textContent = "";
  elements.codexFeedbackResult.textContent = "";
  setCodexFeedbackInputsDisabled(false);
  renderCodexFeedbackSubmitState();
}

function invalidateCodexFeedbackPreview() {
  state.codexFeedbackRevision += 1;
  state.codexFeedbackPreview = null;
  elements.codexFeedbackPreview.hidden = true;
  elements.codexFeedbackPreviewText.textContent = "";
  elements.codexFeedbackConfirmInput.checked = false;
  elements.codexFeedbackError.textContent = "";
  elements.codexFeedbackResult.textContent = "";
  renderCodexFeedbackSubmitState();
}

function codexFeedbackDraft() {
  return {
    classification: elements.codexFeedbackClassificationInput.value,
    errorCode: elements.codexFeedbackErrorCodeInput.value.trim(),
    reason: elements.codexFeedbackReasonInput.value.trim(),
    includeDiagnostics: elements.codexFeedbackDiagnosticsInput.checked,
  };
}

async function requestCodexFeedbackPreview() {
  if (state.codexFeedbackLoading || state.runtime !== "codex" || !canUseCodexFeedback()) return;
  const draft = codexFeedbackDraft();
  if (!draft.reason) {
    elements.codexFeedbackError.textContent = "请先填写问题说明";
    elements.codexFeedbackReasonInput.focus();
    return;
  }
  invalidateCodexFeedbackPreview();
  const revision = state.codexFeedbackRevision;
  state.codexFeedbackLoading = true;
  elements.codexFeedbackError.textContent = "";
  elements.codexFeedbackResult.textContent = "正在服务器生成脱敏预览…";
  setCodexFeedbackInputsDisabled(true);
  renderCodexFeedbackSubmitState();
  try {
    const response = await fetchWithTimeout("/api/codex/feedback/preview", {
      method: "POST",
      headers: {
        "Content-Type": "application/json",
        "X-Codex-Desktop-Action": "codex-feedback-preview",
      },
      body: JSON.stringify(draft),
    }, 20_000);
    const data = await readApiJson(response, "无法生成反馈预览");
    if (revision !== state.codexFeedbackRevision || !elements.codexFeedbackDialog.open) return;
    state.codexFeedbackPreview = {
      previewId: data.previewId,
      expiresAt: Number(data.expiresAt),
      copyText: String(data.copyText || ""),
      digest: String(data.digest || ""),
      consumed: false,
    };
    elements.codexFeedbackPreviewText.textContent = state.codexFeedbackPreview.copyText;
    elements.codexFeedbackPreviewExpiry.textContent = Number.isFinite(state.codexFeedbackPreview.expiresAt)
      ? `${formatMessageTime(state.codexFeedbackPreview.expiresAt)} 前有效`
      : "10 分钟内有效";
    elements.codexFeedbackPreview.hidden = false;
    elements.codexFeedbackResult.textContent = "请检查以上内容；勾选确认前不会上传。";
  } catch (error) {
    if (revision === state.codexFeedbackRevision) {
      elements.codexFeedbackError.textContent = error.message;
      elements.codexFeedbackResult.textContent = "";
    }
  } finally {
    if (revision === state.codexFeedbackRevision) {
      state.codexFeedbackLoading = false;
      setCodexFeedbackInputsDisabled(false);
      renderCodexFeedbackSubmitState();
    }
  }
}

function setCodexFeedbackInputsDisabled(disabled) {
  for (const input of [
    elements.codexFeedbackClassificationInput,
    elements.codexFeedbackErrorCodeInput,
    elements.codexFeedbackReasonInput,
    elements.codexFeedbackDiagnosticsInput,
    elements.codexFeedbackPreviewButton,
  ]) input.disabled = disabled;
}

function renderCodexFeedbackSubmitState() {
  const preview = state.codexFeedbackPreview;
  const available = Boolean(preview && !preview.consumed);
  elements.codexFeedbackCopyButton.disabled = !preview?.copyText;
  elements.codexFeedbackConfirmInput.disabled = !available || state.codexFeedbackLoading;
  elements.codexFeedbackSubmitButton.disabled = !available
    || !elements.codexFeedbackConfirmInput.checked
    || state.codexFeedbackLoading;
}

async function copyCodexFeedbackPreview() {
  const copyText = state.codexFeedbackPreview?.copyText;
  if (!copyText) return;
  await copyTextToClipboard(copyText, "脱敏诊断摘要已复制", "无法复制脱敏诊断摘要");
}

async function submitCodexFeedback(event) {
  event.preventDefault();
  const preview = state.codexFeedbackPreview;
  if (
    state.codexFeedbackLoading
    || !preview
    || preview.consumed
    || !elements.codexFeedbackConfirmInput.checked
  ) return;
  state.codexFeedbackLoading = true;
  preview.consumed = true;
  elements.codexFeedbackError.textContent = "";
  elements.codexFeedbackResult.textContent = "正在上传已预览的脱敏内容…";
  setCodexFeedbackInputsDisabled(true);
  renderCodexFeedbackSubmitState();
  try {
    const response = await fetchWithTimeout("/api/codex/feedback/upload", {
      method: "POST",
      headers: {
        "Content-Type": "application/json",
        "X-Codex-Desktop-Action": "codex-feedback-upload",
      },
      body: JSON.stringify({
        previewId: preview.previewId,
        confirmation: "submit-safe-feedback",
      }),
    }, 70_000);
    await readApiJson(response, "Codex 未完成反馈上传");
    toast("脱敏诊断反馈已上传");
    closeCodexFeedbackDialog();
  } catch (error) {
    elements.codexFeedbackError.textContent = error.message;
    elements.codexFeedbackResult.textContent = "上传未完成，脱敏摘要仍可复制；如需重试，请重新生成预览。";
    elements.codexFeedbackPreviewExpiry.textContent = "本次预览已使用";
    elements.codexFeedbackConfirmInput.checked = false;
  } finally {
    if (elements.codexFeedbackDialog.open) {
      state.codexFeedbackLoading = false;
      setCodexFeedbackInputsDisabled(false);
      renderCodexFeedbackSubmitState();
    }
  }
}

async function loadAccountOfficialQuota({ refresh = false } = {}) {
  try {
    const query = new URLSearchParams({ _: String(Date.now()) });
    if (refresh) query.set("refresh", "1");
    const response = await fetchWithTimeout(
      `/api/account/official-quota?${query}`,
      { cache: "no-store" },
      10_000,
    );
    const data = await response.json();
    if (!response.ok) throw new Error(data.error || "无法读取官方账户额度");
    state.accountOfficialQuota = data;
    state.accountOfficialQuotaError = null;
    if (elements.accountDialog.open) renderAccountOfficialQuota();
    return data;
  } catch (error) {
    state.accountOfficialQuotaError = error.message;
    if (elements.accountDialog.open) renderAccountOfficialQuota();
    return null;
  }
}

function renderAccountOfficialQuota() {
  const data = state.accountOfficialQuota;
  const account = data?.account;
  const loggedIn = account?.type === "chatgpt";
  const taskActive = data?.taskActive === true || (state.runtime === "codex" && conversationBusy());
  elements.accountOfficialQuotaSection.hidden = !loggedIn;
  if (!loggedIn) return;

  elements.accountOfficialPlan.textContent = officialPlanLabel(account.planType);
  elements.accountOfficialLifetimeTokens.textContent = formatOptionalInteger(data.usage?.lifetimeTokens);
  elements.accountOfficialQuotaStatus.textContent = account.email
    ? `官方账号 · ${account.email}`
    : "Codex 官方账号";
  elements.accountOfficialSyncState.textContent = taskActive
    ? "任务中 · 缓存"
    : data.refreshing
      ? "同步中"
      : data.updatedAt
        ? formatAccountQuotaSyncTime(data.updatedAt)
        : "等待同步";
  elements.accountOfficialUsageSummary.textContent = state.accountOfficialQuotaError
    ? state.accountOfficialQuotaError
    : data.usage
      ? `官方统计：连续 ${formatOptionalInteger(data.usage.currentStreakDays)} 天 · 峰值 ${formatOptionalInteger(data.usage.peakDailyTokens)} Token`
      : data.queryErrors?.length
        ? "官方用量暂不可用，当前仍可查看最近同步的速率额度。"
        : "官方账号暂未返回累计用量。";
  renderOfficialRateLimitList(
    elements.accountOfficialLimitList,
    data.rateLimits?.buckets || [],
    "官方账户暂未返回速率额度",
  );
}

function formatAccountQuotaSyncTime(value) {
  const timestamp = Number(value);
  if (!Number.isFinite(timestamp)) return "等待同步";
  const age = Math.max(0, Date.now() - timestamp);
  if (age < 60_000) return "刚刚同步";
  if (age < 60 * 60_000) return `${Math.floor(age / 60_000)} 分钟前`;
  return new Date(timestamp).toLocaleTimeString(interfaceLocale(), { hour: "2-digit", minute: "2-digit" });
}

function renderTokenBudget(prefix, usage, limit) {
  const available = usage?.available === true && Number.isSafeInteger(usage.totalTokens);
  const used = available ? usage.totalTokens : null;
  const limited = Number.isSafeInteger(limit);
  const percent = available && limited ? Math.min(100, used / limit * 100) : 0;
  elements[`account${prefix}Usage`].textContent = available
    ? formatTokenCount(used)
    : usage?.reportingStatus === "idle" ? "0" : "未上报";
  elements[`account${prefix}Limit`].textContent = limited ? ` / ${formatTokenCount(limit)}` : " / 不限";
  elements[`account${prefix}Bar`].style.width = `${percent}%`;
  elements[`account${prefix}Bar`].dataset.level = usageLevel(percent);
}

function renderTokenStatistic(element, usage) {
  element.textContent = usage?.available && Number.isSafeInteger(usage.totalTokens)
    ? formatTokenCount(usage.totalTokens)
    : usage?.reportingStatus === "idle" ? "0" : "未上报";
}

function startAccountCountdown() {
  clearInterval(state.accountCountdownTimer);
  updateAccountCountdowns();
  state.accountCountdownTimer = setInterval(updateAccountCountdowns, 1_000);
}

function updateAccountCountdowns() {
  if (!elements.accountDialog.open || !state.accountSnapshot) return;
  const user = state.accountSnapshot.user;
  if (state.accountSnapshot.assignedApi?.assigned !== true && user?.role !== "owner") return;
  const definitions = [
    ["FiveHour", "fiveHour", "fiveHourTokenLimit"],
    ["Weekly", "weekly", "weeklyTokenLimit"],
    ["Monthly", "monthly", "monthlyTokenLimit"],
  ];
  for (const [prefix, usageKey, limitKey] of definitions) {
    const usage = state.accountSnapshot.tokenUsage?.[usageKey];
    const limit = state.account?.[limitKey];
    const exhausted = Number.isSafeInteger(limit) && usage?.available && usage.totalTokens >= limit;
    elements[`account${prefix}Reset`].textContent = `${exhausted ? "解锁" : "重置"} ${formatResetCountdown(usage?.resetsAt)}`;
  }
}

function closeAccountDialog() {
  clearInterval(state.accountCountdownTimer);
  state.accountCountdownTimer = null;
  elements.accountCurrentPasswordInput.value = "";
  elements.accountNewPasswordInput.value = "";
  elements.accountConfirmPasswordInput.value = "";
  elements.accountError.textContent = "";
}

async function submitAccountProfile(event) {
  if (event.submitter?.value === "cancel") return;
  event.preventDefault();
  const newPassword = elements.accountNewPasswordInput.value;
  if (newPassword && newPassword.length < 16) {
    elements.accountError.textContent = "新密码至少需要 16 个字符";
    return;
  }
  if (newPassword !== elements.accountConfirmPasswordInput.value) {
    elements.accountError.textContent = "两次输入的新密码不一致";
    return;
  }
  if (newPassword && !elements.accountCurrentPasswordInput.value) {
    elements.accountError.textContent = "修改密码前请输入当前密码";
    return;
  }
  elements.saveAccountButton.disabled = true;
  elements.accountError.textContent = "";
  try {
    const response = await fetch("/api/account", {
      method: "PATCH",
      headers: { "Content-Type": "application/json", "X-Codex-Desktop-Action": "account-profile-update" },
      body: JSON.stringify({
        displayName: elements.accountDisplayNameInput.value.trim(),
        currentPassword: newPassword ? elements.accountCurrentPasswordInput.value : undefined,
        newPassword: newPassword || undefined,
      }),
    });
    const data = await response.json().catch(() => ({}));
    if (!response.ok) throw new Error(data.error || "个人资料保存失败");
    await loadAccount();
    elements.accountCurrentPasswordInput.value = "";
    elements.accountNewPasswordInput.value = "";
    elements.accountConfirmPasswordInput.value = "";
    toast(data.sessionRenewed ? "资料已保存，其他登录会话已退出" : "个人资料已保存");
  } catch (error) {
    elements.accountError.textContent = error.message;
  } finally {
    elements.saveAccountButton.disabled = state.accountSnapshot?.mode?.configured !== true;
  }
}

function accountInitial(value) {
  return Array.from(String(value || "账").trim())[0]?.toUpperCase() || "账";
}

function quotaModeLabel(mode) {
  return { filesystem: "文件系统硬配额", application: "应用层配额", "host-owner": "主机所有者空间" }[mode] || "应用层配额";
}

function usageLevel(percent) {
  if (percent >= 95) return "critical";
  if (percent >= 80) return "warning";
  return "normal";
}

function formatResetCountdown(timestamp) {
  const remaining = Number(timestamp) - Date.now();
  if (!Number.isFinite(remaining)) return "时间待上报";
  if (remaining <= 0) return "即将刷新";
  const totalMinutes = Math.ceil(remaining / 60_000);
  const days = Math.floor(totalMinutes / 1440);
  const hours = Math.floor(totalMinutes % 1440 / 60);
  const minutes = totalMinutes % 60;
  if (days) return `${days} 天 ${hours} 小时`;
  if (hours) return `${hours} 小时 ${minutes} 分`;
  return `${minutes} 分钟`;
}

function formatAccountDate(timestamp) {
  if (!Number.isFinite(timestamp)) return "--";
  return new Intl.DateTimeFormat(interfaceLocale(), { year: "numeric", month: "2-digit", day: "2-digit" }).format(new Date(timestamp));
}

function accountTierExpirationLabel(user) {
  if (user.legacy) return "所有者账号长期有效";
  if (!user.tierName) return "自定义配置 · 不设到期时间";
  if (!Number.isFinite(user.tierExpiresAt)) return "套餐长期有效";
  const date = formatAccountDate(user.tierExpiresAt);
  return user.tierExpiresAt <= Date.now() ? `套餐已于 ${date} 到期` : `套餐有效期至 ${date}`;
}

function renderAnnouncementIndicators() {
  const unread = announcementIsUnread();
  elements.accountButton.dataset.announcementUnread = String(unread);
  elements.announcementShortcutBadge.hidden = !unread;
  renderAccountButton();
}

function announcementIsUnread() {
  const id = state.appInfo?.announcement?.id;
  return Boolean(id && localStorage.getItem("codexDesktop.announcementSeen") !== id);
}

function scheduleUnreadAnnouncement() {
  if (!state.interfaceReady || !announcementIsUnread()) return;
  clearTimeout(state.announcementAutoOpenTimer);
  state.announcementAutoOpenTimer = setTimeout(openUnreadAnnouncement, 350);
}

function openUnreadAnnouncement() {
  state.announcementAutoOpenTimer = null;
  if (!announcementIsUnread() || elements.announcementDialog.open) return;
  const blockingDialog = document.querySelector("dialog[open]");
  if (blockingDialog) {
    blockingDialog.addEventListener("close", scheduleUnreadAnnouncement, { once: true });
    return;
  }
  openAnnouncementDialog({ announcementOnly: true });
}

function openAnnouncementDialog({ announcementOnly = false } = {}) {
  state.announcementReadOnlyView = announcementOnly;
  renderAnnouncementDialog({ resetEditor: true });
  if (!elements.announcementDialog.open) elements.announcementDialog.showModal();
  markAnnouncementSeen();
  if (!state.appInfo) {
    checkForUpdate({ showErrors: true }).then(() => {
      if (!elements.announcementDialog.open) return;
      renderAnnouncementDialog({ resetEditor: true });
      markAnnouncementSeen();
    });
  }
}

function renderAnnouncementDialog({ resetEditor = false } = {}) {
  const info = state.appInfo;
  const announcement = info?.announcement;
  const canManage = Boolean(info?.canManageAnnouncement && isAccountAdmin() && !state.announcementReadOnlyView);
  elements.announcementEditor.hidden = !canManage;
  elements.saveAnnouncementDraftButton.hidden = !canManage;
  elements.publishAnnouncementButton.hidden = !canManage;
  elements.unpublishAnnouncementButton.hidden = !canManage || !announcement;
  if (announcement) {
    elements.announcementPublished.dataset.empty = "false";
    elements.announcementCategory.textContent = announcementCategoryLabel(announcement.category);
    elements.announcementCategory.dataset.category = announcement.category;
    elements.announcementPublishedAt.textContent = formatAnnouncementDate(announcement.publishedAt);
    elements.announcementTitle.textContent = announcement.title;
    elements.announcementBody.textContent = announcement.body;
  } else {
    elements.announcementPublished.dataset.empty = "true";
    elements.announcementCategory.textContent = "公告";
    elements.announcementCategory.dataset.category = "notice";
    elements.announcementPublishedAt.textContent = "尚未发布";
    elements.announcementTitle.textContent = "暂无公告";
    elements.announcementBody.textContent = "管理员尚未发布公告。";
  }
  if (!canManage || !resetEditor) return;
  const draft = info.announcementDraft || announcement;
  elements.announcementCategoryInput.value = draft?.category || "notice";
  elements.announcementTitleInput.value = draft?.title || "";
  elements.announcementBodyInput.value = draft?.body || "";
  elements.announcementDraftState.textContent = info.announcementDraft?.updatedAt
    ? `草稿保存于 ${formatAnnouncementDate(info.announcementDraft.updatedAt)}`
    : "尚未保存草稿";
  elements.announcementError.textContent = "";
}

function markAnnouncementSeen() {
  const id = state.appInfo?.announcement?.id;
  if (!id) return;
  localStorage.setItem("codexDesktop.announcementSeen", id);
  renderAnnouncementIndicators();
}

function announcementInput() {
  return {
    category: elements.announcementCategoryInput.value,
    title: elements.announcementTitleInput.value.trim(),
    body: elements.announcementBodyInput.value.trim(),
  };
}

async function saveAnnouncementDraft() {
  await submitAnnouncementChange("/api/announcement/draft", {
    method: "PUT",
    action: "announcement-draft-save",
    body: announcementInput(),
    pendingLabel: "正在保存",
    successMessage: "公告草稿已保存",
  });
}

async function publishAnnouncement() {
  await submitAnnouncementChange("/api/announcement/publish", {
    method: "POST",
    action: "announcement-publish",
    body: announcementInput(),
    pendingLabel: "正在发布",
    successMessage: "公告已向用户发布",
  });
}

async function unpublishAnnouncement() {
  if (!window.confirm("确认撤下当前公告？草稿会保留，普通用户将不再看到这条公告。")) return;
  await submitAnnouncementChange("/api/announcement", {
    method: "DELETE",
    action: "announcement-unpublish",
    pendingLabel: "正在撤下",
    successMessage: "公告已撤下",
  });
}

async function submitAnnouncementChange(url, { method, action, body, pendingLabel, successMessage }) {
  if (state.announcementRequestPending) return;
  state.announcementRequestPending = true;
  const buttons = [
    elements.saveAnnouncementDraftButton,
    elements.publishAnnouncementButton,
    elements.unpublishAnnouncementButton,
  ];
  buttons.forEach((button) => (button.disabled = true));
  elements.announcementDraftState.textContent = pendingLabel;
  elements.announcementError.textContent = "";
  try {
    const response = await fetch(url, {
      method,
      headers: {
        ...(body ? { "Content-Type": "application/json" } : {}),
        "X-Codex-Desktop-Action": action,
      },
      ...(body ? { body: JSON.stringify(body) } : {}),
    });
    const data = await response.json().catch(() => ({}));
    if (!response.ok) throw new Error(data.error || "公告操作失败");
    state.appInfo = {
      ...state.appInfo,
      announcement: data.published || null,
      announcementDraft: data.draft || null,
    };
    renderAnnouncementDialog({ resetEditor: true });
    markAnnouncementSeen();
    toast(successMessage);
  } catch (error) {
    elements.announcementError.textContent = error.message;
  } finally {
    state.announcementRequestPending = false;
    buttons.forEach((button) => (button.disabled = false));
  }
}

function announcementCategoryLabel(category) {
  return { notice: "通知", update: "更新", maintenance: "维护" }[category] || "公告";
}

function formatAnnouncementDate(timestamp) {
  if (!Number.isFinite(timestamp)) return "--";
  return new Intl.DateTimeFormat(interfaceLocale(), {
    month: "2-digit",
    day: "2-digit",
    hour: "2-digit",
    minute: "2-digit",
  }).format(new Date(timestamp));
}

function formatReleaseDate(value) {
  return /^\d{4}-\d{2}-\d{2}$/.test(String(value || "")) ? value.replaceAll("-", ".") : "未记录";
}

async function checkForUpdate({ showErrors = false } = {}) {
  if (state.releaseStatusRequestPending) return state.releaseInfo;
  state.releaseStatusRequestPending = true;
  elements.versionButton.classList.add("checking");
  try {
    const infoResponse = await fetchWithTimeout(`/api/version?_=${Date.now()}`, { cache: "no-store" }, 8_000);
    const info = await infoResponse.json();
    if (!infoResponse.ok || !info.version) throw new Error(info.error || "无法读取版本信息");
    state.appInfo = info;
    renderAnnouncementIndicators();
    scheduleUnreadAnnouncement();
    let data = {
      version: info.version,
      runningVersion: info.version,
      changelog: info.releaseNotes || info.changelog,
      releaseDate: info.releaseDate,
      userView: true,
    };
    if (info.canManageRelease && isAccountAdmin()) {
      const response = await fetchWithTimeout(`/api/release/status?_=${Date.now()}`, { cache: "no-store" }, 8_000);
      const release = await response.json();
      if (!response.ok || !release.version) throw new Error(release.error || "无法读取发布状态");
      data = {
        ...release,
        changelog: info.releaseNotes || release.changelog,
        releaseDate: info.releaseDate,
        userView: false,
      };
    }
    state.releaseInfo = data;
    if (data.claudeComponent) {
      state.claudeComponent = data.claudeComponent;
      renderClaudeRuntimeAvailability();
    }
    const runningVersion = data.runningVersion || data.version;
    const updateAvailable = runningVersion !== UI_VERSION;
    const releaseAvailable = isAccountAdmin() && data.sourceVersion && data.sourceVersion !== runningVersion;
    const remoteAvailable = isAccountAdmin() && data.remote?.updateAvailable === true;
    elements.versionButton.dataset.update = String(Boolean(updateAvailable || releaseAvailable || remoteAvailable));
    elements.versionButton.dataset.mobileLabel = compactMobileVersion(UI_VERSION_LABEL);
    elements.versionLabel.textContent = `v${UI_VERSION_LABEL}`;
    elements.versionButton.title = !isAccountAdmin()
      ? `查看 v${runningVersion} 更新内容`
      : remoteAvailable
      ? `远程稳定版 v${data.remote.version} 可以安全同步`
      : releaseAvailable
      ? `v${data.sourceVersion} 等待完成更新`
      : updateAvailable
        ? `服务端已更新到 v${runningVersion}`
        : `当前已是 v${UI_VERSION_LABEL}`;
    elements.versionButton.setAttribute(
      "aria-label",
      updateAvailable || releaseAvailable || remoteAvailable
        ? `当前网页 ${UI_VERSION_LABEL}，打开版本中心`
        : `当前版本 ${UI_VERSION_LABEL}，查看更新内容`,
    );
    if (elements.versionDialog.open) renderVersionDialog();
    return data;
  } catch (error) {
    if (elements.versionDialog.open) {
      elements.versionState.dataset.status = "error";
      elements.versionState.textContent = error.message;
    }
    if (showErrors) toast(error.message, "error");
    return null;
  } finally {
    state.releaseStatusRequestPending = false;
    elements.versionButton.classList.remove("checking");
  }
}

function scheduleVersionCheck(delay = 60_000) {
  clearTimeout(state.versionCheckTimer);
  state.versionCheckTimer = null;
  if (document.visibilityState === "hidden") return;
  state.versionCheckTimer = setTimeout(async () => {
    state.versionCheckTimer = null;
    await checkForUpdate();
    scheduleVersionCheck();
  }, delay);
}

function openVersionDialog() {
  const admin = isAccountAdmin();
  configureVersionDialogAccess(admin);
  elements.currentVersionValue.textContent = `v${UI_VERSION_LABEL}`;
  elements.versionDateValue.textContent = "正在读取";
  elements.latestVersionValue.textContent = "正在检查";
  elements.sourceVersionValue.textContent = "正在检查";
  elements.remoteVersionValue.textContent = "正在检查";
  elements.versionState.dataset.status = "checking";
  elements.versionState.textContent = "正在读取版本信息";
  elements.releaseProgress.hidden = true;
  elements.releaseCandidatePanel.hidden = true;
  elements.codexVersionValue.textContent = "正在检查";
  elements.codexUpdateState.textContent = "正在读取安装状态";
  elements.codexUpdateProgress.hidden = true;
  elements.claudeComponentVersion.textContent = "正在检查";
  elements.claudeComponentState.textContent = "正在读取安装状态";
  elements.claudeComponentProgress.hidden = true;
  elements.installClaudeButton.disabled = true;
  elements.installClaudeButton.querySelector("span").textContent = "检查并升级";
  setCodexCompatibilityExpanded(false);
  renderCodexCompatibility(null);
  setClaudeVersionCompatibilityExpanded(false);
  renderClaudeVersionCompatibility(state.claudeConfig?.compatibility || null, state.claudeComponent);
  elements.updateCodexButton.disabled = true;
  elements.updateCodexButton.querySelector("span").textContent = "检查并升级";
  elements.syncReleaseButton.disabled = true;
  elements.syncReleaseButton.querySelector("span").textContent = "同步更新";
  elements.confirmUpgradeButton.disabled = true;
  elements.confirmUpgradeButton.querySelector("span").textContent = "刷新到新版本";
  setVersionNotesExpanded(!admin);
  elements.versionDialog.showModal();
  checkForUpdate({ showErrors: true });
}

function configureVersionDialogAccess(admin) {
  elements.versionDialog.dataset.admin = String(admin);
  elements.versionDialogTitle.textContent = admin ? "检查更新" : "版本信息";
  elements.versionOverview.dataset.admin = String(admin);
  elements.currentVersionLabel.textContent = admin ? "当前网页" : "当前版本";
  elements.versionDateTile.hidden = admin;
  elements.runningVersionTile.hidden = !admin;
  elements.sourceVersionTile.hidden = !admin;
  elements.remoteVersionTile.hidden = !admin;
  elements.codexUpdatePanel.hidden = !admin;
  elements.claudeComponentPanel.hidden = false;
  elements.installClaudeButton.hidden = !admin;
  elements.syncReleaseButton.hidden = !admin;
}

function operationTimestamp(operation) {
  return Math.max(
    Number(operation?.completedAt) || 0,
    Number(operation?.updatedAt) || 0,
    Number(operation?.startedAt) || 0,
  );
}

function failedUpdateIsCurrent(appUpdate, release) {
  if (appUpdate?.status !== "failed") return false;
  if (release?.status !== "completed") return true;
  const updateTime = operationTimestamp(appUpdate);
  const releaseTime = operationTimestamp(release);
  return !updateTime || !releaseTime || updateTime >= releaseTime;
}

function renderVersionDialog() {
  const release = state.releaseInfo;
  if (!release) return;
  const admin = isAccountAdmin() && release.userView !== true;
  configureVersionDialogAccess(admin);
  const runningVersion = release.runningVersion || release.version;
  const sourceVersion = release.sourceVersion;
  const updateAvailable = runningVersion !== UI_VERSION;
  const releaseAvailable = sourceVersion && sourceVersion !== runningVersion;
  const activeRelease = release.release?.status === "running";
  const activeAppUpdate = release.appUpdate?.status === "running";
  const failedAppUpdate = failedUpdateIsCurrent(release.appUpdate, release.release);
  const activeOperation = activeRelease || activeAppUpdate;
  const failedRelease = release.release?.status === "failed" && release.release.version === sourceVersion;
  const candidate = release.candidates?.current || null;
  elements.currentVersionValue.textContent = `v${admin ? UI_VERSION_LABEL : runningVersion}`;
  elements.versionDateValue.textContent = formatReleaseDate(release.releaseDate);
  renderClaudeComponent(release.claudeComponent || state.claudeComponent, { admin, activeOperation });
  if (!admin) {
    elements.versionState.dataset.status = runningVersion === UI_VERSION ? "current" : "available";
    elements.versionState.textContent = runningVersion === UI_VERSION
      ? `当前正在使用 v${runningVersion}`
      : `服务已更新到 v${runningVersion}，刷新网页即可使用`;
    elements.releaseProgress.hidden = true;
    elements.versionNotes.textContent = release.changelog || "本版本暂无更新说明";
    elements.confirmUpgradeButton.disabled = runningVersion === UI_VERSION;
    return;
  }
  elements.latestVersionValue.textContent = `v${runningVersion}`;
  elements.sourceVersionValue.textContent = sourceVersion ? `v${sourceVersion}` : "不可用";
  elements.remoteVersionValue.textContent = release.remote?.version ? `v${release.remote.version}` : "不可用";
  const progress = activeAppUpdate || failedAppUpdate ? release.appUpdate : release.release;
  elements.releaseProgress.hidden = !activeAppUpdate && !failedAppUpdate && !activeRelease && !failedRelease;
  if (!elements.releaseProgress.hidden) renderReleaseProgress(progress);
  renderReleaseCandidate(release.candidates, activeOperation);

  if (activeAppUpdate) {
    elements.versionState.dataset.status = "checking";
    elements.versionState.textContent = release.appUpdate.detail || "正在后台同步并验证远程稳定版";
  } else if (failedAppUpdate) {
    elements.versionState.dataset.status = "error";
    elements.versionState.textContent = release.appUpdate.error || "远程同步失败，活动版本未切换";
  } else if (activeRelease) {
    elements.versionState.dataset.status = "checking";
    elements.versionState.textContent = `正在后台发布 v${release.release.version || sourceVersion}`;
  } else if (failedRelease) {
    elements.versionState.dataset.status = "error";
    elements.versionState.textContent = release.release.error || "发布失败，原运行版本未切换";
  } else if (candidate?.phase === "awaiting-approval") {
    elements.versionState.dataset.status = "available";
    elements.versionState.textContent = `候选 v${candidate.version} 等待主服务器实际验证`;
  } else if (candidate?.phase === "failed") {
    elements.versionState.dataset.status = "error";
    elements.versionState.textContent = candidate.error || "候选发布失败，正式稳定通道未改变";
  } else if (updateAvailable) {
    elements.versionState.dataset.status = "available";
    elements.versionState.textContent = `运行服务已更新到 v${runningVersion}`;
  } else if (releaseAvailable) {
    elements.versionState.dataset.status = "available";
    elements.versionState.textContent = `服务器源码已是 v${sourceVersion}，可以重新验证并完成更新`;
  } else if (release.remote?.updateAvailable) {
    elements.versionState.dataset.status = "available";
    elements.versionState.textContent = `远程稳定版 v${release.remote.version} 可以安全同步`;
  } else if (release.remote?.relation === "behind") {
    elements.versionState.dataset.status = "current";
    elements.versionState.textContent = `本地 v${sourceVersion || runningVersion} 领先远程稳定版 v${release.remote.version}，无需同步`;
  } else {
    elements.versionState.dataset.status = "current";
    elements.versionState.textContent = release.remote?.error || release.sourceError || "当前网页和运行服务已经是最新版本";
  }

  elements.versionNotes.textContent = releaseAvailable
    ? release.sourceChangelog || "暂无待部署版本更新日志"
    : release.changelog || "暂无版本更新日志";
  elements.syncReleaseButton.disabled = Boolean(
    release.remote?.disabled || (!release.remote?.updateAvailable && !releaseAvailable) || activeOperation,
  );
  elements.syncReleaseButton.querySelector("span").textContent = activeAppUpdate ? "正在同步" : "同步更新";
  elements.confirmUpgradeButton.disabled = !updateAvailable || activeOperation;
  renderCodexUpdate(release.codexUpdate, activeOperation);
}

function renderClaudeComponent(component, { admin = isAccountAdmin(), activeOperation = false } = {}) {
  const snapshot = component || {};
  const operation = snapshot.operation || {};
  const active = ["queued", "downloading", "verifying"].includes(operation.phase);
  state.claudeComponent = component || state.claudeComponent;
  elements.claudeComponentVersion.textContent = snapshot.installed
    ? `v${snapshot.version || "未知"}`
    : "未安装";
  const sourceLabel = snapshot.source === "managed"
    ? "可选组件"
    : snapshot.source === "bundled"
      ? "随应用保留"
      : snapshot.source === "override"
        ? "外部命令"
        : null;
  const stateLabels = {
    ready: `已安装${sourceLabel ? ` · ${sourceLabel}` : ""}`,
    "not-installed": `可选安装 · 兼容基线 ${snapshot.reviewedVersion || "2.1.236"}`,
    installing: operation.detail || "正在安装 Claude Code",
    "version-drift": snapshot.ready
      ? "当前版本存在兼容差异，请查看受限功能"
      : `当前版本缺少核心能力 · 兼容基线 ${snapshot.reviewedVersion || "2.1.236"}`,
    failed: operation.error || "上次安装失败，Codex 未受影响",
  };
  elements.claudeComponentState.textContent = stateLabels[snapshot.state]
    || "Claude Code 安装状态未知";
  elements.claudeComponentProgress.hidden = !active && operation.phase !== "failed";
  if (!elements.claudeComponentProgress.hidden) {
    elements.claudeComponentProgress.dataset.status = operation.status || (operation.phase === "failed" ? "failed" : "running");
    elements.claudeComponentProgressLabel.textContent = operation.error || operation.detail || "正在处理 Claude Code 安装";
    elements.claudeComponentProgressTime.textContent = operation.startedAt
      ? `已运行 ${formatElapsedTime(Date.now() - operation.startedAt)}`
      : "正在启动";
  }
  elements.installClaudeButton.hidden = !admin;
  elements.installClaudeButton.disabled = Boolean(
    !admin || active || activeOperation || snapshot.installSupported === false || snapshot.pendingDecision,
  );
  elements.installClaudeButton.querySelector("span").textContent = active
    ? "正在安装"
    : operation.phase === "failed"
        ? "重新安装"
        : "检查并升级";
  renderClaudeVersionCompatibility(state.claudeConfig?.compatibility || null, snapshot);
  if (snapshot.pendingDecision) setClaudeVersionCompatibilityExpanded(true);
  renderClaudeRuntimeAvailability();
}

function toggleClaudeVersionCompatibility() {
  const expanded = elements.claudeVersionCompatibilityDetails.hidden;
  setClaudeVersionCompatibilityExpanded(expanded);
  if (
    expanded
    && claudeComponentReady()
    && !state.claudeConfig?.compatibility
    && !state.claudeVersionCompatibilityLoading
  ) {
    void loadClaudeVersionCompatibility();
  }
}

function setClaudeVersionCompatibilityExpanded(expanded) {
  elements.claudeVersionCompatibilityDetails.hidden = !expanded;
  elements.claudeVersionCompatibilityToggle.setAttribute("aria-expanded", String(expanded));
}

function renderClaudeVersionCompatibility(snapshot, component = state.claudeComponent) {
  const ready = component?.ready === true;
  const stateName = ready ? (snapshot?.state || "checking") : "unavailable";
  elements.claudeVersionCompatibilityPanel.dataset.state = stateName;
  elements.claudeVersionCompatibilityPanel.dataset.risk = snapshot?.risk || stateName;
  elements.claudeVersionCompatibilityInstalled.textContent = component?.version
    ? `v${component.version}`
    : "未安装";
  elements.claudeVersionCompatibilityBaseline.textContent = snapshot?.reviewedVersion
    || String(snapshot?.baseline || "").replace(/^claude-code\s+/, "")
    || component?.reviewedVersion
    || "2.1.236";
  elements.claudeVersionCompatibilityCommit.textContent = snapshot?.doctor?.commit || "--";
  elements.claudeVersionCompatibilityChecked.textContent = compatibilityTime(snapshot?.checkedAt);
  const stateLabels = {
    compatible: "当前 CLI 与兼容基线完全匹配",
    "version-drift": snapshot?.activationAllowed === true
      ? "版本未纳入兼容基线，未发现核心能力缺失"
      : "版本差异影响核心能力",
    "capability-drift": snapshot?.activationAllowed === true
      ? snapshot?.limitations?.length
        ? `检测到 ${snapshot.limitations.length} 项功能限制，可自行决定是否回退`
        : "检测到未接入的新能力，现有功能未发现缺失"
      : "核心会话能力缺失，将保留原版本",
    unhealthy: "Claude Doctor 检测到安装异常",
    unavailable: ready ? (snapshot?.error || "兼容性检查不可用") : "安装 Claude Code 后可检查",
    checking: state.claudeVersionCompatibilityLoading ? "正在检查已审查快照" : "展开后检查已审查快照",
  };
  elements.claudeVersionCompatibilityState.textContent = stateLabels[stateName] || "协议状态未知";

  const aggregate = { total: 0, implemented: 0, partial: 0, deferred: 0 };
  for (const item of Object.values(snapshot?.coverage || {})) {
    aggregate.total += Number(item?.total || 0);
    aggregate.implemented += Number(item?.counts?.runtime || 0)
      + Number(item?.counts?.internal || 0)
      + Number(item?.counts?.["custom-equivalent"] || 0);
    aggregate.partial += Number(item?.counts?.partial || 0);
    aggregate.deferred += Number(item?.counts?.deferred || 0);
  }
  elements.claudeVersionCompatibilityCounts.replaceChildren();
  for (const [label, value, note] of [
    ["已纳入清单", aggregate.total, "参数、命令与协议"],
    ["已实现", aggregate.implemented, "原生、内部与安全替代"],
    ["部分实现", aggregate.partial, "主路径已可用"],
    ["主动延期", aggregate.deferred, "明确安全边界"],
  ]) {
    const card = document.createElement("div");
    const heading = document.createElement("span");
    const count = document.createElement("strong");
    const description = document.createElement("small");
    heading.textContent = label;
    count.textContent = snapshot ? String(value) : "--";
    description.textContent = note;
    card.append(heading, count, description);
    elements.claudeVersionCompatibilityCounts.append(card);
  }

  const limitations = snapshot?.limitations || [];
  const additions = snapshot?.unreviewedAdditions || [];
  const drift = [
    ...(snapshot?.doctor?.warnings || []).map((warning) => `Doctor 警告 · ${warning}`),
    ...(snapshot?.doctor?.fatalIssues || []).map((issue) => `Doctor 致命问题 · ${issue}`),
    ...limitations.map((item) => `${item.severity === "blocked" ? "核心不可用" : "功能受限"} · ${item.feature} · ${item.method}`),
    ...additions.map((item) => `新版能力未接入 · ${item.feature} · ${item.method}`),
  ];
  if (snapshot?.semanticReviewed === false) drift.unshift("CLI 帮助语义摘要发生变化");
  if (snapshot?.commitReviewed === false) drift.unshift("CLI 构建提交与审查基线不一致");
  elements.claudeVersionCompatibilityDrift.hidden = !drift.length;
  elements.claudeVersionCompatibilityDrift.replaceChildren();
  for (const text of drift.slice(0, 24)) {
    const row = document.createElement("code");
    row.textContent = text;
    elements.claudeVersionCompatibilityDrift.append(row);
  }

  const pendingDecision = component?.pendingDecision || null;
  const canDecide = Boolean(pendingDecision && isAccountAdmin());
  elements.claudeCompatibilityDecision.hidden = !canDecide;
  const componentBusy = ["queued", "downloading", "verifying"].includes(component?.operation?.phase);
  elements.keepClaudeUpdateButton.disabled = !canDecide || componentBusy;
  elements.rollbackClaudeUpdateButton.disabled = !canDecide || componentBusy;
  if (canDecide) {
    const limitationText = limitations.length
      ? `${limitations.length} 项现有功能受限：${[...new Set(limitations.map((item) => item.feature))].slice(0, 4).join("、")}`
      : additions.length
        ? `${additions.length} 项新版能力尚未接入，现有功能未发现缺失`
        : "版本或构建尚未纳入兼容基线，未发现核心能力缺失";
    elements.claudeCompatibilityDecisionSummary.textContent = `${pendingDecision.beforeVersion ? `v${pendingDecision.beforeVersion}` : "未安装"} → v${pendingDecision.afterVersion}；${limitationText}`;
  }

  elements.claudeVersionCompatibilityDeferred.replaceChildren();
  for (const group of snapshot?.deferredGroups || []) {
    const row = document.createElement("details");
    const summary = document.createElement("summary");
    const title = document.createElement("span");
    const count = document.createElement("small");
    const body = document.createElement("div");
    title.textContent = group.surface;
    count.textContent = `${group.count} 项`;
    summary.append(title, count);
    const reason = document.createElement("p");
    reason.textContent = (group.reasons || []).join("；") || "经安全审查后主动延期";
    const methods = document.createElement("code");
    methods.textContent = (group.methods || []).join("\n");
    body.append(reason, methods);
    row.append(summary, body);
    elements.claudeVersionCompatibilityDeferred.append(row);
  }
}

async function loadClaudeVersionCompatibility() {
  if (state.claudeVersionCompatibilityLoading || !claudeComponentReady()) return;
  state.claudeVersionCompatibilityLoading = true;
  renderClaudeVersionCompatibility({ state: "checking" }, state.claudeComponent);
  try {
    const response = await fetchWithTimeout(
      `/api/claude/compatibility?refresh=1&_=${Date.now()}`,
      { cache: "no-store" },
      30_000,
    );
    const data = await response.json().catch(() => ({}));
    if (!response.ok) throw new Error(data.error || "Claude 兼容性检查失败");
    state.claudeConfig ||= {};
    state.claudeConfig.compatibility = data;
    renderClaudeCompatibility(data);
    renderClaudeVersionCompatibility(data, state.claudeComponent);
  } catch (error) {
    renderClaudeVersionCompatibility({
      state: "unavailable",
      compatible: false,
      error: error.message,
      checkedAt: Date.now(),
    }, state.claudeComponent);
  } finally {
    state.claudeVersionCompatibilityLoading = false;
  }
}

async function startClaudeInstall() {
  if (!isAccountAdmin()) return;
  if (state.claudeComponent?.pendingDecision) {
    setClaudeVersionCompatibilityExpanded(true);
    toast("请先决定保留新版或恢复上一版 Claude Code", "error");
    return;
  }
  const installed = claudeComponentReady();
  const confirmation = installed
    ? "确认检查 Claude Code 官方最新版？非核心差异会列出受限功能，由你决定保留或恢复上一版；核心能力检查失败不会替换当前版本。"
    : "确认检查并安装 Claude Code 官方最新版？核心能力检查失败不会启用，Codex 和当前对话不会停止。";
  if (!window.confirm(confirmation)) return;
  elements.installClaudeButton.disabled = true;
  elements.installClaudeButton.querySelector("span").textContent = "正在启动";
  try {
    const response = await fetch("/api/claude/component/install", {
      method: "POST",
      headers: { "X-Codex-Desktop-Action": "claude-component-install" },
    });
    const data = await response.json().catch(() => ({}));
    if (!response.ok) throw new Error(data.error || "无法启动 Claude Code 安装");
    toast("Claude Code 已开始后台检查，Codex 可以继续使用");
    await refreshClaudeComponentStatus();
    scheduleClaudeInstallPoll();
  } catch (error) {
    toast(error.message, "error");
    renderClaudeComponent(state.claudeComponent);
  }
}

async function decideClaudeUpdate(decision) {
  const pending = state.claudeComponent?.pendingDecision;
  if (!pending) {
    toast("当前没有待决定的 Claude Code 升级", "error");
    return;
  }
  const rollback = decision === "rollback";
  const message = rollback
    ? `确认${pending.beforeVersion ? `恢复 Claude Code v${pending.beforeVersion}` : "撤销本次 Claude Code 安装"}？`
    : `确认保留 Claude Code v${pending.afterVersion}？确认后会清理上一版恢复副本。`;
  if (!window.confirm(message)) return;
  elements.keepClaudeUpdateButton.disabled = true;
  elements.rollbackClaudeUpdateButton.disabled = true;
  try {
    const response = await fetch("/api/claude/component/decision", {
      method: "POST",
      headers: {
        "Content-Type": "application/json",
        "X-Codex-Desktop-Action": "claude-component-decision",
      },
      body: JSON.stringify({ decision }),
    });
    const data = await response.json().catch(() => ({}));
    if (!response.ok) throw new Error(data.error || "无法提交 Claude Code 版本决定");
    toast(rollback ? "正在恢复上一版 Claude Code" : "正在确认保留新版 Claude Code");
    await refreshClaudeComponentStatus();
    scheduleClaudeInstallPoll();
  } catch (error) {
    elements.keepClaudeUpdateButton.disabled = false;
    elements.rollbackClaudeUpdateButton.disabled = false;
    toast(error.message, "error");
  }
}

async function refreshClaudeComponentStatus() {
  const response = await fetchWithTimeout(`/api/claude/component?_=${Date.now()}`, { cache: "no-store" }, 8_000);
  const data = await response.json().catch(() => ({}));
  if (!response.ok) throw new Error(data.error || "无法读取 Claude Code 安装状态");
  const wasReady = claudeComponentReady();
  const previousVersion = state.claudeComponent?.version || null;
  state.claudeComponent = data;
  if (previousVersion !== (data.version || null)) {
    state.claudeConfig ||= {};
    state.claudeConfig.compatibility = null;
  }
  if (state.releaseInfo && !state.releaseInfo.userView) state.releaseInfo.claudeComponent = data;
  renderClaudeComponent(data);
  if (!wasReady && data.ready) toast(`Claude Code ${data.version} 已安装，可以切换使用`, "success");
  if (data.pendingDecision && data.ready && !state.claudeVersionCompatibilityLoading) {
    void loadClaudeVersionCompatibility();
  }
  return data;
}

function scheduleClaudeInstallPoll() {
  clearTimeout(state.claudeInstallPollTimer);
  const poll = async () => {
    try {
      const component = await refreshClaudeComponentStatus();
      if (!["queued", "downloading", "verifying"].includes(component.operation?.phase)) {
        state.claudeInstallPollTimer = null;
        return;
      }
    } catch {
      // A transient status read should not cancel the background installation.
    }
    state.claudeInstallPollTimer = setTimeout(poll, 1_500);
  };
  state.claudeInstallPollTimer = setTimeout(poll, 1_500);
}

function renderReleaseCandidate(snapshot, activeOperation) {
  const enabled = snapshot?.enabled === true;
  elements.releaseCandidatePanel.hidden = !enabled;
  if (!enabled) return;
  const candidate = snapshot.current;
  const phase = candidate?.phase || "idle";
  const phaseLabels = {
    idle: "待准备",
    preparing: "准备中",
    testing: "完整测试",
    "browser-verification": "浏览器验证",
    deploying: "候选部署",
    verifying: "服务验证",
    "awaiting-approval": "待人工确认",
    discarding: "正在恢复旧版本",
    promoting: "正式提升中",
    stable: "正式版本",
    failed: "失败",
    discarded: "已废弃",
  };
  elements.releaseCandidateVersion.textContent = candidate ? `v${candidate.version}` : "尚未准备";
  elements.releaseCandidateId.textContent = candidate?.id || "--";
  elements.releaseCandidateDetail.textContent = candidate?.detail || "--";
  elements.releaseCandidateState.dataset.phase = phase;
  elements.releaseCandidateState.textContent = phaseLabels[phase] || phase;
  const candidateBusy = [
    "preparing", "testing", "browser-verification", "deploying", "verifying", "discarding", "promoting",
  ].includes(phase);
  elements.startReleaseCandidateButton.disabled = Boolean(activeOperation || candidateBusy || phase === "awaiting-approval");
  elements.startReleaseCandidateButton.querySelector("span").textContent = candidateBusy ? "候选处理中" : "准备候选";
  const owner = isAccountOwner();
  elements.promoteReleaseCandidateButton.hidden = !owner;
  elements.discardReleaseCandidateButton.hidden = !owner;
  elements.promoteReleaseCandidateButton.disabled = activeOperation || phase !== "awaiting-approval";
  elements.discardReleaseCandidateButton.disabled = activeOperation || !["awaiting-approval", "discarding", "failed"].includes(phase);
}

function renderCodexUpdate(codex, activeRelease) {
  if (!codex) {
    elements.codexVersionValue.textContent = "不可用";
    elements.codexUpdateState.textContent = "无法读取官方 Codex 状态";
    elements.updateCodexButton.disabled = true;
    renderCodexCompatibility(null, null, { active: false });
    return;
  }
  const update = codex.update || {};
  const active = update.status === "running";
  const failed = update.status === "failed";
  const recovered = update.status === "recovered";
  elements.codexVersionValue.textContent = formatCodexVersion(codex.installedVersion);
  elements.codexUpdateProgress.hidden = !active && !failed && !recovered;
  if (!elements.codexUpdateProgress.hidden) renderCodexUpdateProgress(update);

  if (active) elements.codexUpdateState.textContent = update.detail || "正在后台升级官方 Codex";
  else if (recovered) elements.codexUpdateState.textContent = update.detail || "升级未生效，已安全恢复上一版 Codex，可以重试";
  else if (failed) elements.codexUpdateState.textContent = update.error || "升级失败，当前后端保持运行";
  else if (update.status === "completed") elements.codexUpdateState.textContent = update.detail || "官方 Codex 检查完成";
  else if (codex.error) elements.codexUpdateState.textContent = codex.error;
  else if (codex.disabled) elements.codexUpdateState.textContent = "此环境未启用网页升级";
  else elements.codexUpdateState.textContent = codex.appServerReady ? "CLI 与 app-server 可用" : "app-server 不可用";

  elements.updateCodexButton.disabled = Boolean(
    codex.disabled || !codex.appServerReady || active || activeRelease || codex.pendingDecision,
  );
  elements.updateCodexButton.querySelector("span").textContent = active ? "正在升级" : "检查并升级";
  renderCodexCompatibility(codex.compatibility, codex.pendingDecision, { active: active || activeRelease });
}

function toggleCodexCompatibility() {
  setCodexCompatibilityExpanded(elements.codexCompatibilityDetails.hidden);
}

function setCodexCompatibilityExpanded(expanded) {
  elements.codexCompatibilityDetails.hidden = !expanded;
  elements.codexCompatibilityToggle.setAttribute("aria-expanded", String(expanded));
}

function renderCodexCompatibility(snapshot, pendingDecision = null, { active = false } = {}) {
  const stateName = snapshot?.state || "checking";
  renderCodexVersionApplicability(snapshot);
  elements.codexCompatibilityPanel.dataset.state = stateName;
  elements.codexCompatibilityPanel.dataset.risk = snapshot?.risk || stateName;
  elements.codexCompatibilityInstalled.textContent = snapshot?.installedVersion || "正在读取";
  elements.codexCompatibilityBaseline.textContent = snapshot?.baseline || "正在读取";
  elements.codexCompatibilityGenerated.textContent = compatibilityTime(snapshot?.generatedAt);
  elements.codexCompatibilityChecked.textContent = compatibilityTime(snapshot?.checkedAt);
  const stateLabels = {
    compatible: "当前 CLI 与兼容基线完全匹配",
    "version-drift": snapshot?.activationAllowed === true
      ? snapshot?.partiallyCompatible === true
        ? `${codexVersionDirectionLabel(snapshot)}；核心聊天可用，功能按探测结果启用或降级`
        : snapshot?.featureLimitations?.length
          ? `核心聊天可用；${snapshot.featureLimitations.length} 项新版功能需升级 Codex 后开放`
          : "版本未纳入兼容基线，未发现现有功能缺失"
      : "版本差异影响核心协议，无法继续使用",
    "protocol-drift": snapshot?.activationAllowed === true
      ? snapshot?.partiallyCompatible === true
        ? `${codexVersionDirectionLabel(snapshot)}；检测到 ${snapshot.limitations?.length || 0} 项可降级能力`
        : snapshot?.limitations?.length
          ? `检测到 ${snapshot.limitations.length} 项功能限制，可自行决定是否回退`
          : "检测到未接入的新能力，现有功能未发现缺失"
      : "核心会话协议缺失，将自动恢复上一版",
    unavailable: snapshot?.error || "无法完成协议检查",
    checking: "正在检查已审查快照",
  };
  elements.codexCompatibilityState.textContent = stateLabels[stateName] || "协议状态未知";
  elements.codexCompatibilityCounts.replaceChildren();
  const coverage = snapshot?.coverage || {};
  const coverageLabels = {
    clientRequests: "客户端请求",
    serverRequests: "服务端请求",
    serverNotifications: "服务端通知",
    clientNotifications: "客户端通知",
  };
  for (const [name, label] of Object.entries(coverageLabels)) {
    const item = coverage[name];
    if (!item) continue;
    const card = document.createElement("div");
    const heading = document.createElement("span");
    const value = document.createElement("strong");
    const note = document.createElement("small");
    heading.textContent = label;
    value.textContent = String(item.total ?? "--");
    note.textContent = name === "clientRequests"
      ? `浏览器 ${item.counts?.browser || 0} · 内部 ${item.counts?.internal || 0} · 替代 ${item.counts?.["custom-equivalent"] || 0}`
      : `处理 ${Number(item.counts?.browser || 0) + Number(item.counts?.internal || 0)} · 延期 ${item.counts?.deferred || 0}`;
    card.append(heading, value, note);
    elements.codexCompatibilityCounts.append(card);
  }
  const limitations = snapshot?.limitations || [];
  const featureLimitations = snapshot?.featureLimitations || [];
  const additions = snapshot?.unreviewedAdditions || [];
  const drift = [
    ...featureLimitations.map((item) => `兼容回退 · ${item.label} · ${item.fallback}；需 Codex ${item.requiredVersion}+`),
    ...limitations.map((item) => `${item.severity === "blocked" ? "核心不可用" : "功能受限"} · ${item.feature} · ${item.method}`),
    ...additions.map((item) => `新版能力未接入 · ${item.feature} · ${item.method}`),
  ];
  elements.codexCompatibilityDrift.hidden = !drift.length;
  elements.codexCompatibilityDrift.replaceChildren();
  for (const text of drift.slice(0, 24)) {
    const row = document.createElement("code");
    row.textContent = text;
    elements.codexCompatibilityDrift.append(row);
  }
  elements.codexCompatibilityDecision.hidden = !pendingDecision;
  elements.keepCodexUpdateButton.disabled = active || !pendingDecision;
  elements.rollbackCodexUpdateButton.disabled = active || !pendingDecision;
  if (pendingDecision) {
    const limitationText = limitations.length
      ? `${limitations.length} 项现有功能受限：${[...new Set(limitations.map((item) => item.feature))].slice(0, 4).join("、")}`
      : additions.length
        ? `${additions.length} 项新版能力尚未接入，现有功能未发现缺失`
        : "版本尚未纳入兼容基线，现有协议方法未发现差异";
    elements.codexCompatibilityDecisionSummary.textContent = `${formatCodexVersion(pendingDecision.beforeVersion)} → ${formatCodexVersion(pendingDecision.afterVersion)}；${limitationText}`;
    setCodexCompatibilityExpanded(true);
  }
  elements.codexCompatibilityDeferred.replaceChildren();
  for (const group of snapshot?.deferredGroups || []) {
    const row = document.createElement("details");
    const summary = document.createElement("summary");
    const title = document.createElement("span");
    const count = document.createElement("small");
    const body = document.createElement("div");
    title.textContent = group.surface;
    count.textContent = `${group.count} 项`;
    summary.append(title, count);
    const reason = document.createElement("p");
    reason.textContent = (group.reasons || []).join("；");
    const methods = document.createElement("code");
    methods.textContent = (group.methods || []).join("\n");
    body.append(reason, methods);
    for (const replacement of group.replacements || []) {
      const alternative = document.createElement("small");
      alternative.textContent = `${replacement.method} → 安全替代 ${replacement.replacement}`;
      body.append(alternative);
    }
    row.append(summary, body);
    elements.codexCompatibilityDeferred.append(row);
  }
}

function renderCodexVersionApplicability(snapshot) {
  const baseline = snapshot?.baseline ? formatCodexVersion(snapshot.baseline) : "目标版本";
  const installed = snapshot?.installedVersion ? formatCodexVersion(snapshot.installedVersion) : "版本未知";
  let state = snapshot?.state || "checking";
  let text = `当前网页版本 v${UI_VERSION_LABEL} 正在确认 Codex 适用范围（审查基线 ${baseline}）`;
  if (snapshot?.compatible === true) {
    state = "compatible";
    text = `当前网页版本 v${UI_VERSION_LABEL} 适用于 ${baseline}；当前检测到 ${installed}`;
  } else if (snapshot?.partiallyCompatible === true) {
    state = "limited";
    text = `当前网页版本 v${UI_VERSION_LABEL} 支持${codexVersionDirectionLabel(snapshot)}的 ${installed}；以 ${baseline} 为审查基线，功能按协议探测结果启用或降级`;
  } else if (snapshot?.state === "unavailable") {
    state = "unavailable";
    text = `当前网页版本 v${UI_VERSION_LABEL} 以 ${baseline} 为适用基线；暂时无法确认当前 Codex CLI`;
  } else if (snapshot?.activationAllowed === false) {
    state = "blocked";
    text = `当前网页版本 v${UI_VERSION_LABEL} 与 ${installed} 不兼容；请使用 ${baseline}`;
  }
  elements.codexVersionApplicability.dataset.state = state;
  elements.codexVersionApplicabilityText.textContent = text;
}

function codexVersionDirectionLabel(snapshot) {
  if (snapshot?.versionDirection === "downward") return "向下兼容";
  if (snapshot?.versionDirection === "upward") return "向上兼容";
  return "部分兼容";
}

function compatibilityTime(value) {
  const timestamp = typeof value === "string" ? Date.parse(value) : Number(value);
  if (!Number.isFinite(timestamp)) return "--";
  return new Date(timestamp).toLocaleString(interfaceLocale(), { hour12: false });
}

function renderCodexUpdateProgress(update) {
  const labels = {
    queued: "等待官方 Codex 升级任务启动",
    checking: "检查官方 Codex CLI 与 app-server",
    forcing: "不等待对话，正在立即切换 Codex 后端",
    waiting: "等待安全切换窗口，对话服务保持开放",
    draining: "已确认任务空闲，正在短时切换",
    updating: "正在更新官方 Codex，当前对话服务保持开放",
    deploying: "在备用后端验证新版 Codex",
    verifying: "确认网关和新版 Codex 对话接口",
    failed: "升级失败，当前活动后端保持运行",
    recovered: "升级未生效，已安全恢复上一版 Codex",
  };
  elements.codexUpdateProgress.dataset.status = update.status;
  elements.codexUpdateProgressLabel.textContent = update.detail || labels[update.phase] || "正在处理 Codex 升级";
  if (update.status === "running") {
    elements.codexUpdateProgressTime.textContent = update.startedAt
      ? `已运行 ${formatElapsedTime(Date.now() - update.startedAt)}`
      : "正在启动";
  } else {
    const duration = update.startedAt && update.completedAt
      ? ` · 用时 ${formatElapsedTime(Math.max(0, update.completedAt - update.startedAt))}`
      : "";
    elements.codexUpdateProgressTime.textContent = update.completedAt
      ? `完成于 ${new Date(update.completedAt).toLocaleString(interfaceLocale(), { hour12: false })}${duration}`
      : "已结束";
  }
}

async function startCodexUpdate() {
  const codex = state.releaseInfo?.codexUpdate;
  const compatibility = codex?.compatibility;
  if (codex?.pendingDecision) {
    setCodexCompatibilityExpanded(true);
    toast("请先决定保留新版或恢复上一版", "error");
    return;
  }
  const compatibilityText = compatibility?.compatible === true
    ? `当前 ${compatibility.installedVersion} 已匹配兼容基线。新版若只有非核心差异，将列出受限功能并由你决定是否回退。`
    : compatibility?.activationAllowed === true
      ? "当前版本存在非核心兼容差异，但基本对话可用；新的升级结果仍会单独列出限制。"
      : "当前核心协议检查未通过，请先恢复可用版本。";
  if (compatibility?.activationAllowed !== true) {
    toast(compatibilityText, "error");
    return;
  }
  if (!window.confirm(`确认检查并升级官方 Codex？${compatibilityText}\n\n更新不会等待运行中的对话；核心协议或后端验证失败仍会自动恢复，其他差异不会强制回退。切换时正在执行的任务可能中断，浏览器会自动重连。`)) return;
  elements.updateCodexButton.disabled = true;
  elements.updateCodexButton.querySelector("span").textContent = "正在启动";
  try {
    const response = await fetch("/api/codex/update/start", {
      method: "POST",
      headers: { "X-Codex-Desktop-Action": "codex-update" },
    });
    const data = await response.json();
    if (!response.ok) throw new Error(data.error || "无法启动官方 Codex 升级");
    toast("官方 Codex 升级已在后台启动；默认不等待空闲，任务可能中断，浏览器会自动重连");
    await checkForUpdate({ showErrors: true });
  } catch (error) {
    elements.updateCodexButton.disabled = false;
    elements.updateCodexButton.querySelector("span").textContent = "检查并升级";
    toast(error.message, "error");
  }
}

async function decideCodexUpdate(decision) {
  const pending = state.releaseInfo?.codexUpdate?.pendingDecision;
  if (!pending) {
    toast("当前没有待决定的 Codex 升级", "error");
    return;
  }
  const rollback = decision === "rollback";
  const message = rollback
    ? `确认恢复 ${formatCodexVersion(pending.beforeVersion)}？\n\n将通过蓝绿流程切换后端，正在执行的任务可能中断。`
    : `确认保留 ${formatCodexVersion(pending.afterVersion)}？\n\n确认后会清理上一版离线恢复副本，兼容限制仍会保留显示。`;
  if (!window.confirm(message)) return;
  elements.keepCodexUpdateButton.disabled = true;
  elements.rollbackCodexUpdateButton.disabled = true;
  try {
    const response = await fetch("/api/codex/update/decision", {
      method: "POST",
      headers: {
        "Content-Type": "application/json",
        "X-Codex-Desktop-Action": "codex-update-decision",
      },
      body: JSON.stringify({ decision }),
    });
    const data = await response.json();
    if (!response.ok) throw new Error(data.error || "无法提交 Codex 版本决定");
    toast(rollback ? "正在后台恢复上一版 Codex" : "正在确认保留新版 Codex");
    await checkForUpdate({ showErrors: true });
  } catch (error) {
    elements.keepCodexUpdateButton.disabled = false;
    elements.rollbackCodexUpdateButton.disabled = false;
    toast(error.message, "error");
  }
}

function formatCodexVersion(value) {
  if (!value) return "不可用";
  return value.replace(/^codex-cli\s+/i, "v");
}

function renderReleaseProgress(release) {
  const phaseLabels = {
    queued: "等待后台发布任务启动",
    checking: "检查本地源码和远程稳定标签",
    repairing: "隔离错误版本生成物",
    fetching: "拉取远程稳定标签",
    preparing: "在隔离目录安装锁定依赖",
    preflight: "检查版本、提交和发布标签",
    testing: "运行完整测试和浏览器检查",
    backup: "生成并校验版本备份",
    activating: "测试通过，准备本地控制源码",
    forcing: "不等待对话，正在立即切换后端",
    waiting: "等待安全切换窗口，对话服务保持开放",
    draining: "已确认任务空闲，正在短时切换",
    deploying: "验证候选服务并执行蓝绿切换",
    "rescue-updating": "同步独立备用窗口 v1.0",
    verifying: "确认网关和对话服务状态",
    failed: "发布失败，原运行版本保持不变",
  };
  const status = release?.status || "running";
  const running = status === "running";
  const iconName = running ? "loader-circle" : status === "completed" ? "circle-check" : "circle-alert";
  const iconNode = elements.releaseProgress.querySelector("[data-release-progress-icon]");
  if (iconNode && iconNode.getAttribute("data-lucide") !== iconName) {
    const replacement = document.createElement("i");
    replacement.setAttribute("data-lucide", iconName);
    replacement.setAttribute("data-release-progress-icon", "");
    iconNode.replaceWith(replacement);
    refreshIcons();
  }
  elements.releaseProgress.dataset.status = status;
  elements.releaseProgressLabel.textContent = release.detail || phaseLabels[release.phase] || "正在处理发布任务";
  if (running) {
    elements.releaseProgressTime.textContent = release.startedAt
      ? `已运行 ${formatElapsedTime(Math.max(0, Date.now() - release.startedAt))}`
      : "正在启动";
    return;
  }
  const startedAt = Number(release.startedAt);
  const completedAt = Number(release.completedAt);
  const duration = Number.isFinite(startedAt) && startedAt > 0 && Number.isFinite(completedAt) && completedAt >= startedAt
    ? ` · 用时 ${formatElapsedTime(completedAt - startedAt)}`
    : "";
  if (status === "completed" && Number.isFinite(completedAt) && completedAt > 0) {
    elements.releaseProgressTime.textContent = `完成于 ${new Date(completedAt).toLocaleString(interfaceLocale(), { hour12: false })}${duration}`;
  } else {
    elements.releaseProgressTime.textContent = `已结束${duration}`;
  }
}

async function startAppUpdate() {
  const release = state.releaseInfo;
  const runningVersion = release?.runningVersion || release?.version;
  const sourcePending = release?.sourceVersion && release.sourceVersion !== runningVersion;
  const target = release?.remote?.version || (sourcePending ? release.sourceVersion : null);
  if (!target) return;
  const confirmation = sourcePending && !release?.remote?.updateAvailable
    ? `确认重新验证 v${target} 并完成更新？当前运行版本会保持在线，全部检查通过后才会切换。`
    : `确认同步 v${target}？默认会在候选验证通过后立即切换，不等待运行中的对话；任务可能中断，浏览器会自动重连。`;
  if (!window.confirm(confirmation)) return;
  elements.syncReleaseButton.disabled = true;
  elements.syncReleaseButton.querySelector("span").textContent = "正在启动";
  try {
    const response = await fetch("/api/app/update/start", {
      method: "POST",
      headers: { "X-Codex-Desktop-Action": "app-update" },
    });
    const data = await response.json();
    if (!response.ok) throw new Error(data.error || "无法启动远程安全更新");
    toast(`v${data.version} 已进入后台安全同步，默认不等待对话空闲，候选验证通过后立即切换`);
    await checkForUpdate({ showErrors: true });
  } catch (error) {
    elements.syncReleaseButton.disabled = false;
    elements.syncReleaseButton.querySelector("span").textContent = "同步更新";
    toast(error.message, "error");
  }
}

async function startReleaseCandidate() {
  if (state.releaseCandidateRequestPending) return;
  if (!window.confirm("准备候选将运行完整测试、浏览器验证和主服务器蓝绿部署，通常需要 10–20 分钟。确认启动？")) {
    return;
  }
  state.releaseCandidateRequestPending = true;
  elements.startReleaseCandidateButton.disabled = true;
  elements.startReleaseCandidateButton.querySelector("span").textContent = "正在启动";
  try {
    const response = await fetch("/api/release/candidates/start", {
      method: "POST",
      headers: { "X-Codex-Desktop-Action": "release-candidate-start" },
    });
    const data = await response.json().catch(() => ({}));
    if (!response.ok) throw new Error(data.error || "无法启动候选发布");
    toast(`候选 ${data.candidateId || "任务"} 已进入后台验证`);
    await checkForUpdate({ showErrors: true });
  } catch (error) {
    toast(error.message, "error");
  } finally {
    state.releaseCandidateRequestPending = false;
    if (state.releaseInfo) renderVersionDialog();
  }
}

function openReleaseCandidateConfirmation(action) {
  const candidate = state.releaseInfo?.candidates?.current;
  if (!candidate || !isAccountOwner()) return;
  const promote = action === "promote";
  if (promote && candidate.phase !== "awaiting-approval") return;
  if (!promote && !["awaiting-approval", "discarding", "failed"].includes(candidate.phase)) return;
  elements.releaseCandidateConfirmDialog.dataset.action = action;
  elements.releaseCandidateConfirmTitle.textContent = promote ? "提升为正式版本" : "废弃候选版本";
  elements.releaseCandidateConfirmVersion.textContent = `v${candidate.version}`;
  elements.releaseCandidateConfirmCommit.textContent = candidate.commitSha?.slice(0, 12) || "--";
  elements.releaseCandidateConfirmId.textContent = candidate.id;
  elements.releaseCandidateValidationField.hidden = !promote;
  elements.releaseCandidateValidationInput.checked = false;
  elements.releaseCandidatePasswordInput.value = "";
  elements.releaseCandidateConfirmationInput.value = "";
  elements.releaseCandidateConfirmError.textContent = "";
  elements.submitReleaseCandidateConfirmButton.classList.toggle("danger", !promote);
  elements.submitReleaseCandidateConfirmButton.querySelector("span").textContent = promote ? "确认提升" : "确认废弃";
  elements.releaseCandidateConfirmDialog.showModal();
  elements.releaseCandidatePasswordInput.focus();
}

function closeReleaseCandidateConfirmation() {
  if (state.releaseCandidateRequestPending) return;
  elements.releaseCandidatePasswordInput.value = "";
  elements.releaseCandidateConfirmationInput.value = "";
  elements.releaseCandidateConfirmDialog.close();
}

async function submitReleaseCandidateConfirmation(event) {
  event.preventDefault();
  if (state.releaseCandidateRequestPending) return;
  const candidate = state.releaseInfo?.candidates?.current;
  const action = elements.releaseCandidateConfirmDialog.dataset.action;
  const promote = action === "promote";
  if (!candidate || !["promote", "discard"].includes(action)) return;
  if (promote && !elements.releaseCandidateValidationInput.checked) {
    elements.releaseCandidateConfirmError.textContent = "请确认已完成主服务器实际功能验证";
    return;
  }
  state.releaseCandidateRequestPending = true;
  elements.submitReleaseCandidateConfirmButton.disabled = true;
  elements.releaseCandidateConfirmError.textContent = "";
  try {
    const response = await fetch(`/api/release/candidates/${encodeURIComponent(candidate.id)}/${action}`, {
      method: "POST",
      headers: {
        "Content-Type": "application/json",
        "X-Codex-Desktop-Action": promote ? "release-candidate-promote" : "release-candidate-discard",
      },
      body: JSON.stringify({
        password: elements.releaseCandidatePasswordInput.value,
        confirmation: elements.releaseCandidateConfirmationInput.value,
        actualValidationConfirmed: promote && elements.releaseCandidateValidationInput.checked,
      }),
    });
    const data = await response.json().catch(() => ({}));
    if (!response.ok) throw new Error(data.error || (promote ? "正式提升失败" : "候选废弃失败"));
    elements.releaseCandidatePasswordInput.value = "";
    elements.releaseCandidateConfirmationInput.value = "";
    elements.releaseCandidateConfirmDialog.close();
    toast(promote ? `v${candidate.version} 已提升为正式稳定版本` : `候选 v${candidate.version} 已废弃`);
    await checkForUpdate({ showErrors: true });
  } catch (error) {
    elements.releaseCandidateConfirmError.textContent = error.message;
  } finally {
    state.releaseCandidateRequestPending = false;
    elements.submitReleaseCandidateConfirmButton.disabled = false;
  }
}

function toggleVersionNotes() {
  setVersionNotesExpanded(elements.versionNotes.hidden);
}

function setVersionNotesExpanded(expanded) {
  elements.versionNotes.hidden = !expanded;
  elements.versionNotesButton.setAttribute("aria-expanded", String(expanded));
  elements.versionNotesButtonLabel.textContent = expanded ? "收起版本更新日志" : "查看版本更新日志";
}

async function confirmUpgrade() {
  const release = state.releaseInfo;
  if (!release || release.version === UI_VERSION) return;
  elements.confirmUpgradeButton.disabled = true;
  elements.confirmUpgradeButton.querySelector("span").textContent = "正在刷新";
  try {
    await verifyReleaseAssets(release.version);
    const runningVersion = release.runningVersion || release.version;
    toast(`正在刷新到 v${runningVersion}`);
    const target = new URL(location.href);
    target.searchParams.set("version", runningVersion);
    target.searchParams.set("reload", String(Date.now()));
    setTimeout(() => location.replace(target), 120);
  } catch (error) {
    elements.confirmUpgradeButton.disabled = false;
    elements.confirmUpgradeButton.querySelector("span").textContent = "刷新到新版本";
    toast(error.message, "error");
  }
}

function formatElapsedTime(milliseconds) {
  const seconds = Math.max(0, Math.floor(milliseconds / 1000));
  if (seconds < 60) return `${seconds} 秒`;
  const minutes = Math.floor(seconds / 60);
  return `${minutes} 分 ${seconds % 60} 秒`;
}

async function verifyReleaseAssets(version) {
  const timestamp = Date.now();
  const urls = [
    "styles.css",
    "boot.js",
    "app.js",
    "thread-state.js",
    "conversation-state.js",
  ].map(
    (asset) => `/${asset}?v=${encodeURIComponent(version)}&verify=${timestamp}`,
  );
  const responses = await Promise.all(urls.map((url) => fetch(url, { cache: "reload" })));
  if (responses.some((response) => !response.ok)) {
    throw new Error("新版本资源尚未就绪，请稍后重试");
  }
}

function connectSocket() {
  if (state.socket?.readyState === WebSocket.OPEN || state.socket?.readyState === WebSocket.CONNECTING) {
    return state.socket;
  }
  clearTimeout(state.reconnectTimer);
  state.reconnectTimer = null;
  const protocol = location.protocol === "https:" ? "wss:" : "ws:";
  const socketGeneration = ++state.socketGeneration;
  const query = new URLSearchParams({
    windowId: CLIENT_WINDOW_ID,
    generation: String(socketGeneration),
  });
  const socket = new WebSocket(`${protocol}//${location.host}/ws?${query}`);
  state.socket = socket;
  if (state.connectionPhase !== "reconnecting") {
    state.connectionPhase = state.bootstrapped ? "recovering" : "cold";
    setConnection("starting", "正在连接");
  }
  const connectTimer = setTimeout(() => {
    if (socketIsCurrent(socket, socketGeneration) && socket.readyState === WebSocket.CONNECTING) {
      if (state.connectionPhase !== "reconnecting") setConnection("error", "连接超时");
      retireCurrentSocket(socket, socketGeneration, SOCKET_CLOSE_REPLACED, "Connection timeout");
    }
  }, SOCKET_CONNECT_TIMEOUT_MS);
  state.socketConnectTimer = connectTimer;
  const clearConnectTimer = () => {
    clearTimeout(connectTimer);
    if (state.socketConnectTimer === connectTimer) state.socketConnectTimer = null;
  };

  socket.addEventListener("open", () => {
    if (!socketIsCurrent(socket, socketGeneration)) return;
    clearConnectTimer();
    state.reconnectAttempts = 0;
    state.socketOpenedAt = Date.now();
    sendClientState();
  });

  socket.addEventListener("message", (event) => {
    if (!socketIsCurrent(socket, socketGeneration)) return;
    clearConnectTimer();
    let message;
    try {
      message = JSON.parse(event.data);
    } catch {
      toast("收到无效的服务端消息", "error");
      return;
    }
    handleSocketMessage(message, socketGeneration, typeof event.data === "string" ? event.data : null);
  });

  socket.addEventListener("close", (event) => {
    clearConnectTimer();
    if (!socketIsCurrent(socket, socketGeneration)) return;
    state.socket = null;
    console.warn("Codex WebSocket closed", {
      code: event.code,
      reason: event.reason || "",
      wasClean: event.wasClean,
      connectedMs: state.socketOpenedAt ? Date.now() - state.socketOpenedAt : null,
      visibility: document.visibilityState,
      online: navigator.onLine,
    });
    beginConnectionInterruption();
    rejectPendingRpc("连接已断开", true, socketGeneration);
    scheduleSocketReconnect();
  });

  socket.addEventListener("error", () => {
    if (socketIsCurrent(socket, socketGeneration) && state.connectionPhase !== "reconnecting") {
      setConnection("error", "连接错误");
    }
  });
  return socket;
}

function socketIsCurrent(socket, socketGeneration) {
  return state.socket === socket && state.socketGeneration === socketGeneration;
}

function retireCurrentSocket(socket, socketGeneration, code, reason, { reconnect = true } = {}) {
  if (!socketIsCurrent(socket, socketGeneration)) return false;
  state.socket = null;
  clearTimeout(state.socketConnectTimer);
  state.socketConnectTimer = null;
  beginConnectionInterruption();
  rejectPendingRpc("连接已断开", true, socketGeneration);
  try {
    if (socket.readyState !== WebSocket.CLOSED && socket.readyState !== WebSocket.CLOSING) {
      socket.close(code, reason);
    }
  } catch (error) {
    console.warn("Unable to close stale WebSocket", error);
  }
  if (reconnect) scheduleSocketReconnect();
  return true;
}

function handleBrowserOffline() {
  const socket = state.socket;
  if (socket && socket.readyState !== WebSocket.CLOSED && socket.readyState !== WebSocket.CLOSING) {
    retireCurrentSocket(socket, state.socketGeneration, SOCKET_CLOSE_BROWSER_OFFLINE, "Browser offline");
    return;
  }
  beginConnectionInterruption();
  scheduleSocketReconnect();
}

function handleBrowserOnline() {
  if (
    state.connectionPhase === "reconnecting"
    && state.socket?.readyState === WebSocket.CONNECTING
  ) {
    const staleSocket = state.socket;
    retireCurrentSocket(
      staleSocket,
      state.socketGeneration,
      SOCKET_CLOSE_REPLACED,
      "Connectivity resumed",
      { reconnect: false },
    );
    clearTimeout(state.reconnectTimer);
    state.reconnectTimer = null;
    connectSocket();
    return;
  }
  resumeConnectivity();
}

function codexSoftReconnectEligible() {
  return Boolean(
    state.runtime === "codex"
    && state.bootstrapped
    && state.conversationReady
    && state.initialDataReady
    && state.currentProject
  );
}

function clearConnectionNotice() {
  clearTimeout(state.connectionNoticeTimer);
  state.connectionNoticeTimer = null;
}

function beginConnectionInterruption() {
  const soft = codexSoftReconnectEligible();
  state.bridgeReady = false;
  state.reconnectRecoveryGeneration += 1;
  if (!soft) {
    invalidateConversationRecovery();
    state.connectionPhase = "offline";
    setConnection("offline", "连接断开");
    return;
  }
  if (state.connectionPhase !== "reconnecting") state.reconnectStartedAt = Date.now();
  state.connectionPhase = "reconnecting";
  clearConnectionNotice();
  state.connectionNoticeTimer = setTimeout(() => {
    state.connectionNoticeTimer = null;
    if (state.connectionPhase !== "reconnecting") return;
    setConnection("reconnecting", "正在重连");
  }, SOCKET_RECONNECT_NOTICE_MS);
  setTurnBusy(conversationBusy(), conversationBusy() ? conversationBusyLabel() : "正在重连");
}

function invalidateConversationRecovery() {
  state.bootstrapGeneration += 1;
  state.bootstrapped = false;
  state.conversationReady = false;
  finishContextCompaction(state.contextCompactionThreadId);
  if (state.activeThread) markCodexThreadNeedsResume(state.activeThread.id, true);
}

function applyCodexRecoveryStatus(payload = {}) {
  if (!payload || typeof payload !== "object" || Array.isArray(payload)) return state.codexRecovery;
  const pendingThreadIds = Array.isArray(payload.pendingThreadIds)
    ? [...new Set(payload.pendingThreadIds.filter((value) => typeof value === "string" && value))]
    : [];
  state.codexRecovery = {
    state: typeof payload.state === "string" && payload.state ? payload.state : "ready",
    ready: payload.ready === true && pendingThreadIds.length === 0,
    pendingThreadIds,
    error: typeof payload.error === "string" && payload.error ? payload.error : null,
    observedAt: Number(payload.observedAt) || Date.now(),
  };
  return state.codexRecovery;
}

function codexRecoveryReady() {
  return state.codexRecovery?.ready !== false;
}

function codexRecoveryAllowsThread(threadId) {
  if (typeof threadId !== "string" || !threadId) return true;
  return !state.codexRecovery?.pendingThreadIds?.includes(threadId);
}

function applyCodexRuntimeStatus(payload = {}) {
  const previousEpoch = state.codexRuntimeEpoch;
  const previousSequence = state.codexEventSequence;
  const runtimeEpoch = typeof payload.runtimeEpoch === "string" && payload.runtimeEpoch
    ? payload.runtimeEpoch
    : null;
  const eventSequence = Number.isSafeInteger(payload.eventSequence) && payload.eventSequence >= 0
    ? payload.eventSequence
    : previousSequence;
  const sameEpoch = Boolean(previousEpoch && runtimeEpoch && previousEpoch === runtimeEpoch);
  applyCodexRecoveryStatus(payload.codexRecovery);
  applyCodexRuntimeCapabilities(payload.runtimeCapabilities);
  if (runtimeEpoch) state.codexRuntimeEpoch = runtimeEpoch;
  state.codexEventSequence = sameEpoch
    ? Math.max(previousSequence, eventSequence)
    : eventSequence;
  return {
    sameEpoch,
    epochChanged: Boolean(previousEpoch && runtimeEpoch && previousEpoch !== runtimeEpoch),
    missedEvents: sameEpoch && eventSequence > previousSequence,
  };
}

function applyCodexRuntimeCapabilities(value) {
  const input = value && typeof value === "object" && !Array.isArray(value) ? value : {};
  state.codexRuntimeCapabilities = {
    version: typeof input.version === "string" && input.version ? input.version : null,
    detected: input.detected === true,
    conversationSections: input.conversationSections === true,
    sectionPositionSort: input.sectionPositionSort === true,
    pluginSearch: input.pluginSearch === true,
    cursorMigration: input.cursorMigration === true,
  };
  refreshCodexRuntimeFeatureControls();
}

function codexRuntimeFeatureAvailable(feature) {
  return state.codexRuntimeCapabilities.detected === true
    && state.codexRuntimeCapabilities[feature] === true;
}

function refreshCodexRuntimeFeatureControls() {
  if (elements.threadSectionsButton) {
    const sectionsAvailable = state.runtime === "codex"
      && codexRuntimeFeatureAvailable("conversationSections");
    elements.threadSectionsButton.hidden = state.threadPaneView === "worktrees" || !sectionsAvailable;
    elements.threadSectionsButton.title = sectionsAvailable
      ? "管理对话分区"
      : "Codex 0.147 或更高版本才提供持久对话分区";
  }
  updateThreadPaneRefreshControl();
  if (elements.codexPluginSearchButton) {
    const available = codexRuntimeFeatureAvailable("pluginSearch");
    elements.codexPluginSearchInput.disabled = !available;
    elements.codexPluginSearchScope.disabled = !available;
    elements.codexPluginSearchButton.disabled = !available
      || state.codexPluginSearchLoading
      || !state.codexPluginsQuery.trim();
  }
}

async function restoreCodexConnection(
  payload,
  socketGeneration = state.socketGeneration,
  { transportReconnect = true } = {},
) {
  const recoveryGeneration = ++state.reconnectRecoveryGeneration;
  const hadSoftConversation = codexSoftReconnectEligible();
  const runtimeStatus = applyCodexRuntimeStatus(payload);
  const soft = hadSoftConversation && runtimeStatus.sameEpoch;
  state.codexBridgeStatusPayload = { ...payload };
  state.bridgeReady = true;
  clearConnectionNotice();
  if (state.activeThread?.id && !codexRecoveryAllowsThread(state.activeThread.id)) {
    state.conversationReady = false;
    state.connectionPhase = "recovering";
    setConnection("starting", "正在恢复对话");
    setTurnBusy(conversationBusy(), conversationBusyLabel());
    return;
  }
  setConnection("ready", statusText("ready"));
  sendClientState();

  if (!soft) {
    invalidateConversationRecovery();
    state.connectionPhase = "recovering";
    await bootstrapCodex();
  } else {
    const shouldSynchronize = runtimeStatus.missedEvents && transportReconnect;
    state.connectionPhase = shouldSynchronize ? "synchronizing" : "online";
    if (shouldSynchronize) {
      await synchronizeCodexAfterReconnect(recoveryGeneration, socketGeneration);
    } else {
      void loadTaskStatus({ force: true });
    }
  }
  if (
    recoveryGeneration !== state.reconnectRecoveryGeneration
    || socketGeneration !== state.socketGeneration
    || !state.bridgeReady
    || state.runtime !== "codex"
  ) return;
  if (!state.conversationReady) {
    state.connectionPhase = "recovering";
    setTurnBusy(conversationBusy(), conversationBusyLabel());
    return;
  }
  state.connectionPhase = "online";
  state.reconnectStartedAt = null;
  setConnection("ready", statusText("ready"));
  setTurnBusy(conversationBusy(), conversationBusyLabel());
  retryPendingTurnRequest();
  retryPendingSteerRequest();
  flushQueuedPromptAfterReconnect();
}

async function synchronizeCodexAfterReconnect(recoveryGeneration, socketGeneration = state.socketGeneration) {
  const threadId = state.activeThread?.id || null;
  const taskStatus = loadTaskStatus({ force: true });
  const resumed = threadId
    ? resumeThread(state.activeThread, {
        preserveExisting: true,
        showLoading: false,
        scrollToBottom: false,
      })
    : Promise.resolve(true);
  const [, resumeResult] = await Promise.allSettled([taskStatus, resumed]);
  if (
    recoveryGeneration !== state.reconnectRecoveryGeneration
    || socketGeneration !== state.socketGeneration
    || !state.bridgeReady
    || state.runtime !== "codex"
  ) return;
  if (
    threadId
    && state.activeThread?.id === threadId
    && (resumeResult.status === "rejected" || resumeResult.value !== true)
  ) {
    throw resumeResult.reason || new Error("对话原子恢复失败，请稍后重试");
  }
  if (!threadId) void loadThreads();
}

function scheduleSocketReconnect() {
  if (state.reconnectTimer) return;
  const attempt = state.reconnectAttempts++;
  const baseDelay = Math.min(8_000, 1_000 * (1.6 ** attempt));
  const delay = Math.round(baseDelay + Math.random() * 350);
  state.reconnectTimer = setTimeout(() => {
    state.reconnectTimer = null;
    connectSocket();
  }, delay);
}

function resumeConnectivity() {
  scheduleTaskStatusPoll(0);
  if (state.socket?.readyState === WebSocket.OPEN || state.socket?.readyState === WebSocket.CONNECTING) return;
  clearTimeout(state.reconnectTimer);
  state.reconnectTimer = null;
  connectSocket();
}

async function refreshConversation() {
  if (state.refreshingConversation) return;
  state.refreshingConversation = true;
  const activeThread = state.activeThread;
  elements.refreshConversationButton.disabled = true;
  elements.refreshConversationButton.classList.add("refreshing");
  try {
    if (activeThread && state.bridgeReady && state.socket?.readyState === WebSocket.OPEN) {
      const refreshed = await resumeThread(activeThread, { preserveExisting: true, showLoading: false });
      if (!refreshed) throw new Error("当前对话恢复失败");
    } else {
      invalidateConversationRecovery();
      state.connectionPhase = "recovering";
      setConnection("starting", "正在恢复");
      const previousSocket = state.socket;
      if (previousSocket && previousSocket.readyState !== WebSocket.CLOSED) {
        retireCurrentSocket(
          previousSocket,
          state.socketGeneration,
          SOCKET_CLOSE_MANUAL_REFRESH,
          "Conversation refresh requested",
          { reconnect: false },
        );
      }
      resumeConnectivity();
      await waitForConversationReady();
    }
    await loadThreads();
    toast("当前对话已刷新");
  } catch (error) {
    toast(`无法刷新当前对话：${error.message}`, "error");
  } finally {
    state.refreshingConversation = false;
    elements.refreshConversationButton.disabled = false;
    elements.refreshConversationButton.classList.remove("refreshing");
  }
}

async function waitForConversationReady(timeoutMs = 15_000) {
  const deadline = Date.now() + timeoutMs;
  while (Date.now() < deadline) {
    if (
      state.bridgeReady
      && state.conversationReady
      && codexRecoveryAllowsThread(state.activeThread?.id || null)
    ) return;
    if (!state.socket || state.socket.readyState === WebSocket.CLOSED) resumeConnectivity();
    await new Promise((resolve) => setTimeout(resolve, 100));
  }
  throw new Error("等待 Codex 恢复超时");
}

function rejectPendingRpc(message, deliveryUnknown = false, socketGeneration = null) {
  for (const [requestId, pending] of state.pendingRpc) {
    if (socketGeneration !== null && pending.socketGeneration !== socketGeneration) continue;
    clearTimeout(pending.timer);
    pending.reject(rpcError(message, deliveryUnknown));
    state.pendingRpc.delete(requestId);
  }
}

function handleSocketMessage(message, socketGeneration = state.socketGeneration, rawFrame = null) {
  if (message.type === "codex/recovery-status") {
    applyCodexRecoveryStatus(message.payload);
    if (state.codexBridgeStatusPayload?.status === "ready") {
      state.codexBridgeStatusPayload = {
        ...state.codexBridgeStatusPayload,
        codexRecovery: message.payload,
      };
      scheduleCodexConnectionRecovery(state.codexBridgeStatusPayload, socketGeneration);
    }
    setTurnBusy(conversationBusy(), conversationBusyLabel());
    return;
  }
  if (message.type === "bridge/status") {
    const payload = message.payload || {};
    if (payload.codexRecovery) applyCodexRecoveryStatus(payload.codexRecovery);
    state.codexBridgeStatusPayload = payload;
    const wasReady = state.bridgeReady;
    if (payload.status === "ready") {
      if (Date.now() - state.providerProfilesLoadedAt > 2_000) void loadProviderProfiles();
      if (state.runtime === "claude") {
        state.bridgeReady = true;
        clearConnectionNotice();
        state.connectionPhase = "online";
        setConnection("ready", statusText("ready"));
        setTurnBusy(conversationBusy(), conversationBusyLabel());
        bootstrapClaude();
      } else {
        scheduleCodexConnectionRecovery(payload, socketGeneration);
      }
      if (elements.resourceDialog.open && state.resourceDirectory) {
        void startResourceWatcher(state.resourceDirectory);
      }
    } else {
      if (wasReady) rejectPendingRpc("Codex 服务连接中断", true);
      beginConnectionInterruption();
    }
    return;
  }

  if (message.type?.startsWith("conversation/")) return;

  if (message.type === "rpc/result" || message.type === "rpc/error") {
    const pending = state.pendingRpc.get(String(message.requestId));
    if (!pending || pending.socketGeneration !== socketGeneration) return;
    state.pendingRpc.delete(String(message.requestId));
    clearTimeout(pending.timer);
    if (pending.onResponseMetrics) {
      try {
        pending.onResponseMetrics({
          approxBytes: approximateUtf8ByteLength(rawFrame),
        });
      } catch (error) {
        console.warn("Unable to report RPC response size", error);
      }
    }
    if (message.type === "rpc/error") {
      const error = rpcError(message.message, message.deliveryUnknown === true);
      if (typeof message.code === "string") error.code = message.code;
      if (message.details && typeof message.details === "object") error.details = message.details;
      if (error.code === "ERR_USER_THREAD_LIMIT_REACHED") showThreadLimitDialog(error);
      pending.reject(error);
    }
    else pending.resolve(message.result);
    return;
  }

  if (message.type === "codex-terminal/output") {
    handleTerminalOutput(message.payload);
    return;
  }

  if (message.type === "codex-terminal/exited") {
    if (message.payload?.processId === state.terminalProcessId) {
      appendTerminalOutput(`\n[${message.payload.error || "终端连接已结束"}]\n`);
      finishTerminalProcess();
    }
    return;
  }

  if (message.type === "resource/changed") {
    handleResourceWatchChange(message.payload);
    return;
  }

  if (message.type === "resource/watch-ended") {
    if (message.payload?.watchId === state.resourceWatchId) {
      state.resourceWatchId = null;
      state.resourceWatchPath = null;
    }
    return;
  }

  if (message.type === "codex/background-task") {
    const task = message.payload?.task;
    if (task?.id) {
      const index = state.codexBackgroundTasks.findIndex((entry) => entry.id === task.id);
      if (index === -1) state.codexBackgroundTasks.unshift(task);
      else state.codexBackgroundTasks[index] = { ...state.codexBackgroundTasks[index], ...task };
      state.taskCenterSnapshot = {
        ...(state.taskCenterSnapshot || { observedAt: Date.now(), tasks: [], goals: [] }),
        backgroundAllowed: true,
        backgroundTasks: state.codexBackgroundTasks,
      };
      renderCodexBackgroundTasks();
      queueTaskCenterRender();
      if (elements.backgroundTaskDrawer.open) {
        void refreshTaskCenter({ silent: true });
      }
    }
    return;
  }

  if (message.type === "codex-app/install-browser-closed") {
    state.codexAppInstall = { appId: null, browser: null, busy: false };
    if (state.officialBrowserRuntime === "codex-app") closeOfficialBrowserDialog();
    if (elements.codexExtensionDialog.open) renderCodexAppsCenter();
    toast(message.payload?.expired ? "Codex App 连接窗口已超时" : "Codex App 连接窗口已关闭", "error");
    return;
  }

  if (message.type === "codex-file-search/updated") {
    handleFileSearchUpdated(message.payload);
    return;
  }

  if (message.type === "codex-file-search/completed") {
    if (message.payload?.sessionId === state.fileSearchSessionId) {
      state.fileSearchLoading = false;
      renderFileSearchResults();
    }
    return;
  }

  if (message.type === "codex-file-search/ended") {
    if (message.payload?.sessionId === state.fileSearchSessionId) {
      state.fileSearchSessionId = null;
      state.fileSearchLoading = false;
      elements.fileSearchSummary.textContent = message.payload?.error || "文件搜索连接已结束";
      renderFileSearchResults();
    }
    return;
  }

  if (message.type === "worktree/thread-rebound") {
    handleWorktreeThreadRebound(message.payload);
    return;
  }

  if (message.type === "worktree/updated") {
    handleWorktreeUpdated(message.payload);
    return;
  }

  if (message.type === "worktree/purged") {
    handleWorktreePurged(message.payload);
    return;
  }

  if (message.type === "worktree/unbound") {
    handleWorktreeUnbound(message.payload);
    return;
  }

  if (message.type === "codex/notification") {
    const runtimeEpoch = typeof message.runtimeEpoch === "string" ? message.runtimeEpoch : null;
    const eventSequence = Number.isSafeInteger(message.eventSequence) ? message.eventSequence : null;
    if (runtimeEpoch && state.codexRuntimeEpoch && runtimeEpoch !== state.codexRuntimeEpoch) {
      state.codexRuntimeEpoch = runtimeEpoch;
      state.codexEventSequence = eventSequence || 0;
      invalidateConversationRecovery();
      if (state.bridgeReady) void bootstrapCodex();
      return;
    }
    if (runtimeEpoch) state.codexRuntimeEpoch = runtimeEpoch;
    if (eventSequence !== null) {
      if (eventSequence <= state.codexEventSequence) return;
      state.codexEventSequence = eventSequence;
    }
    handleCodexNotification(message.payload);
    return;
  }

  if (message.type === "goal/control/updated") {
    const threadId = message.payload?.threadId;
    if (typeof threadId === "string" && threadId) {
      rememberGoalControl(threadId, message.payload?.control);
      if (message.payload?.control?.manualPauseState === "paused") {
        void loadThreadGoal(threadId, { silent: true });
      }
    }
    return;
  }

  if (message.type === "provider/thread-binding") {
    const threadId = message.payload?.threadId;
    const binding = message.payload?.binding;
    if (typeof threadId === "string" && binding?.threadId === threadId) {
      const bindings = Array.isArray(state.providerRouting.bindings)
        ? state.providerRouting.bindings.filter((entry) => entry.threadId !== threadId)
        : [];
      state.providerRouting = {
        ...state.providerRouting,
        bindings: [binding, ...bindings].slice(0, 1_000),
      };
      renderThreadProviderBinding();
    }
    return;
  }

  if (message.type === "provider/routing-updated") {
    applyProviderRoutingSnapshot(message.payload);
    return;
  }

  if (message.type === "claude/status") {
    state.claudeRuntimeStatus = message.payload || null;
    if (state.claudeConfig) {
      state.claudeConfig.runtime = message.payload || {};
      if (elements.claudeDialog.open) renderClaudeOfficialState();
    }
    return;
  }

  if (message.type === "claude/event") {
    handleClaudeEvent(message.payload || {});
    return;
  }

  if (message.type === "claude/controlRequest") {
    enqueueClaudeApproval(message.payload);
    return;
  }

  if (message.type === "claude/controlRequestResolved") {
    resolveApproval(message.payload?.id);
    return;
  }

  if (message.type === "claude/log") {
    console.error(message.payload?.message || message.payload);
    return;
  }

  if (message.type === "thread/import/materialized") {
    materializeActiveImportedThread(message.payload);
    return;
  }

  if (message.type === "official-account/login-completed") {
    closeOfficialBrowserDialog();
    if (message.payload?.success === true) {
      stopOfficialLoginPolling();
      const current = state.officialAccount || {};
      state.officialAccount = {
        ...current,
        account: {
          type: "chatgpt",
          email: current.account?.email || null,
          planType: current.account?.planType || "unknown",
        },
        pendingLogin: null,
        provider: {
          ...(current.provider || {}),
          canActivate: true,
        },
      };
      elements.officialAccountError.textContent = "";
      renderOfficialAccount();
      toast("Codex 官方登录成功");
    } else {
      elements.officialAccountError.textContent = message.payload?.expired
        ? "服务器登录窗口已过期，请重新登录"
        : "官方登录未完成";
    }
    if (elements.providerDialog.open && state.editingProviderId === "default") {
      void loadOfficialAccount({ silent: true });
    }
    return;
  }

  if (message.type === "codex-mcp/oauth-completed") {
    state.codexMcpOAuthBrowser = null;
    if (state.officialBrowserRuntime === "codex-mcp") closeOfficialBrowserDialog();
    if (message.payload?.success === true) {
      toast(`${message.payload?.name || "MCP"} OAuth 登录成功`);
    } else {
      const error = message.payload?.error || "MCP OAuth 登录未完成";
      elements.codexExtensionError.textContent = error;
      toast(error, "error");
    }
    if (canUseCodexMcp()) {
      void loadCodexMcpServers()
        .then(renderCodexExtensionCenter)
        .catch((error) => { elements.codexExtensionError.textContent = error.message; });
    }
    return;
  }

  if (message.type === "codex-external-migration/updated") {
    if (message.payload?.history) {
      state.codexMigration.history = message.payload.history;
    }
    if (message.payload?.snapshot) {
      state.codexMigration.snapshot = message.payload.snapshot;
      const latestDetection = message.payload.snapshot.detections?.[0] || null;
      if (
        latestDetection
        && (!state.codexMigration.detection || state.codexMigration.detection.id === latestDetection.id)
      ) {
        state.codexMigration.detection = latestDetection;
      }
    }
    if (canUseCodexMigration()) renderCodexExternalMigration();
    return;
  }

  if (message.type === "codex/serverRequest") {
    enqueueApproval(message.payload);
    return;
  }

  if (message.type === "codex/serverRequestResolved") {
    resolveApproval(message.payload?.id);
    if (message.payload?.autoResolved === true) {
      toast("等待选择已超时，Codex 将按最佳判断继续", "warning");
    }
    return;
  }

  if (message.type === "bridge/log") {
    console.error(message.payload?.message || message.payload);
    return;
  }

  if (message.type === "error") toast(message.message, "error");
}

function codexRecoveryPayloadKey(payload = {}) {
  const recovery = payload?.codexRecovery && typeof payload.codexRecovery === "object"
    ? payload.codexRecovery
    : {};
  const pendingThreadIds = Array.isArray(recovery.pendingThreadIds)
    ? [...new Set(recovery.pendingThreadIds.filter((value) => typeof value === "string" && value))].sort()
    : [];
  return JSON.stringify({
    status: typeof payload.status === "string" ? payload.status : "",
    runtimeEpoch: typeof payload.runtimeEpoch === "string" ? payload.runtimeEpoch : "",
    recoveryState: typeof recovery.state === "string" ? recovery.state : "",
    recoveryReady: recovery.ready === true,
    pendingThreadIds,
    recoveryError: typeof recovery.error === "string" ? recovery.error : null,
  });
}

function scheduleCodexConnectionRecovery(payload, socketGeneration) {
  if (socketGeneration !== state.socketGeneration) return state.reconnectRecoveryPromise;
  const key = codexRecoveryPayloadKey(payload);
  const transportReconnect = state.reconnectRecoverySocketGeneration !== socketGeneration
    && state.reconnectRecoveryLastSocketGeneration !== socketGeneration;
  const request = { payload, socketGeneration, key, transportReconnect };
  if (
    state.reconnectRecoveryPromise
    && state.reconnectRecoverySocketGeneration === socketGeneration
  ) {
    if (
      state.reconnectRecoveryActiveKey === key
      || state.reconnectRecoveryRequest?.key === key
    ) return state.reconnectRecoveryPromise;
    state.reconnectRecoveryRequest = request;
    return state.reconnectRecoveryPromise;
  }
  if (
    state.reconnectRecoveryLastSocketGeneration === socketGeneration
    && state.reconnectRecoveryLastKey === key
  ) return state.reconnectRecoveryPromise;
  state.reconnectRecoveryRequest = null;
  state.reconnectRecoveryActiveKey = key;
  const recovery = (async () => {
    let currentRequest = request;
    while (currentRequest) {
      state.reconnectRecoveryActiveKey = currentRequest.key;
      try {
        await restoreCodexConnection(
          currentRequest.payload,
          currentRequest.socketGeneration,
          { transportReconnect: currentRequest.transportReconnect },
        );
      } catch (error) {
        if (state.bridgeReady && currentRequest.socketGeneration === state.socketGeneration) {
          setConnection("error", "恢复失败");
          toast(error.message, "error");
        }
      }
      state.reconnectRecoveryLastKey = currentRequest.key;
      state.reconnectRecoveryLastSocketGeneration = currentRequest.socketGeneration;
      if (
        state.reconnectRecoveryPromise !== recovery
        || currentRequest.socketGeneration !== state.socketGeneration
      ) return;
      const nextRequest = state.reconnectRecoveryRequest?.socketGeneration === socketGeneration
        && state.reconnectRecoveryRequest.key !== currentRequest.key
        ? state.reconnectRecoveryRequest
        : null;
      state.reconnectRecoveryRequest = null;
      currentRequest = nextRequest;
    }
  })().finally(() => {
    if (state.reconnectRecoveryPromise !== recovery) return;
    state.reconnectRecoveryPromise = null;
    state.reconnectRecoverySocketGeneration = null;
    state.reconnectRecoveryActiveKey = null;
    state.reconnectRecoveryRequest = null;
  });
  state.reconnectRecoveryPromise = recovery;
  state.reconnectRecoverySocketGeneration = socketGeneration;
  return recovery;
}

async function bootstrapCodex() {
  if (state.bootstrapPromise) {
    const activeBootstrap = state.bootstrapPromise;
    await activeBootstrap;
    if (state.bootstrapPromise && state.bootstrapPromise !== activeBootstrap) {
      return state.bootstrapPromise;
    }
    if (
      !state.bootstrapped
      && state.bridgeReady
      && state.initialDataReady
      && state.currentProject
    ) {
      return bootstrapCodex();
    }
    return;
  }
  if (
    state.bootstrapped
    || !state.bridgeReady
    || !state.initialDataReady
    || !state.currentProject
    || (state.activeThread?.id && !codexRecoveryAllowsThread(state.activeThread.id))
  ) return;
  const generation = ++state.bootstrapGeneration;
  state.bootstrapped = true;
  state.conversationReady = false;
  const bootstrap = (async () => {
    try {
      await Promise.all([
        loadModels(),
        loadConfig(),
        loadCapabilities(),
      ]);
      if (generation !== state.bootstrapGeneration || !state.bridgeReady) return;
      const recovered = await recoverActiveThread();
      if (generation !== state.bootstrapGeneration || !state.bridgeReady) return;
      // Task status is auxiliary metadata. The native Thread and notifications
      // own conversation readiness; status polling continues in the background
      // and will reconcile active-turn controls when it becomes available.
      if (recovered && state.activeThread?.id) {
        void loadTaskStatus({ force: true });
      }
      if (generation !== state.bootstrapGeneration || !state.bridgeReady) return;
      state.conversationReady = true;
      state.connectionPhase = "online";
      setTurnBusy(conversationBusy(), conversationBusyLabel());
      restoreSidebarView();
      retryPendingTurnRequest();
      retryPendingSteerRequest();
      flushQueuedPromptAfterReconnect();
      // Sidebar history is deliberately outside the send-readiness critical
      // path. The selected Thread above is already recovered and task-gated;
      // the complete list and loaded subscriptions can catch up in the
      // background without making refresh appear stuck for minutes.
      void loadThreads();
      void loadLoadedThreads().catch((error) => {
        console.warn("Unable to refresh loaded Codex Threads after bootstrap:", error);
      });
    } catch (error) {
      if (generation !== state.bootstrapGeneration) return;
      state.bootstrapped = false;
      state.conversationReady = false;
      setTurnBusy(conversationBusy(), conversationBusyLabel());
      toast(error.message, "error");
    }
  })();
  state.bootstrapPromise = bootstrap;
  try {
    await bootstrap;
  } finally {
    if (state.bootstrapPromise === bootstrap) state.bootstrapPromise = null;
    if (
      generation !== state.bootstrapGeneration
      && state.bridgeReady
      && !state.bootstrapped
      && state.runtime === "codex"
    ) {
      void bootstrapCodex();
    }
  }
}

function rpc(method, params = {}, options = {}) {
  const socket = state.socket;
  const socketGeneration = state.socketGeneration;
  if (socket?.readyState !== WebSocket.OPEN) {
    return Promise.reject(new Error(`${state.runtime === "claude" ? "Claude" : "Codex"} 服务尚未连接`));
  }
  const requestId = state.rpcId++;
  return new Promise((resolve, reject) => {
    const timeoutMs = Number.isSafeInteger(options.timeoutMs)
      ? Math.min(Math.max(options.timeoutMs, 1_000), 6 * 60 * 60_000 + 30_000)
      : 125_000;
    const timer = setTimeout(() => {
      state.pendingRpc.delete(String(requestId));
      const error = rpcError(`${method} 请求超时`, true);
      error.code = "ERR_RPC_CLIENT_TIMEOUT";
      error.method = method;
      reject(error);
    }, timeoutMs);
    state.pendingRpc.set(String(requestId), {
      resolve,
      reject,
      timer,
      socketGeneration,
      onResponseMetrics: typeof options.onResponseMetrics === "function"
        ? options.onResponseMetrics
        : null,
    });
    try {
      socket.send(JSON.stringify({
        type: "rpc",
        requestId,
        method,
        params,
        windowId: CLIENT_WINDOW_ID,
        socketGeneration,
      }));
    } catch (error) {
      clearTimeout(timer);
      state.pendingRpc.delete(String(requestId));
      reject(rpcError(error.message || `${method} 发送失败`, true));
    }
  });
}

async function rpcWithSameRuntimeRetry(method, params, options = {}) {
  const expectedEpoch = state.codexRuntimeEpoch;
  const maxAttempts = Number.isSafeInteger(options.maxAttempts)
    ? Math.min(Math.max(options.maxAttempts, 1), 5)
    : 3;
  for (let attempt = 1; attempt <= maxAttempts; attempt += 1) {
    try {
      return await rpc(method, params, options);
    } catch (error) {
      if (!error.deliveryUnknown || attempt >= maxAttempts) throw error;
      setTurnBusy(true, "等待连接确认");
      await waitForCodexTransport(expectedEpoch);
    }
  }
  throw new Error(`${method} 无法确认`);
}

async function waitForCodexTransport(expectedEpoch, timeoutMs = SOCKET_RECOVERY_TIMEOUT_MS) {
  const deadline = Date.now() + timeoutMs;
  while (Date.now() < deadline) {
    if (expectedEpoch && state.codexRuntimeEpoch && state.codexRuntimeEpoch !== expectedEpoch) {
      throw new Error("服务器已重启，未自动重试可能已执行的新建对话请求");
    }
    if (state.bridgeReady && state.socket?.readyState === WebSocket.OPEN) return;
    if (!state.socket || state.socket.readyState === WebSocket.CLOSED) resumeConnectivity();
    await new Promise((resolve) => setTimeout(resolve, 100));
  }
  throw new Error("等待连接恢复超时，未重复执行新建对话请求");
}

function sendClientState(
  threadId = (state.runtime === "claude" ? state.activeClaudeSession?.id : state.activeThread?.id) || null,
  visible = document.visibilityState === "visible",
) {
  if (state.socket?.readyState !== WebSocket.OPEN) return;
  state.socket.send(JSON.stringify({
    type: "client/state",
    threadId,
    visible,
    codexRuntimeEpoch: state.codexRuntimeEpoch,
    codexEventSequence: state.codexEventSequence,
    windowId: CLIENT_WINDOW_ID,
    socketGeneration: state.socketGeneration,
  }));
}

function releaseBrowserConversationWindow() {
  closeGameWorkModeChannel();
  sendClientState(undefined, false);
  const socket = state.socket;
  if (!socket || socket.readyState === WebSocket.CLOSED || socket.readyState === WebSocket.CLOSING) return;
  retireCurrentSocket(socket, state.socketGeneration, 1000, "Browser page closed", { reconnect: false });
}

async function releaseThreadSubscription(threadId) {
  if (
    state.runtime !== "codex"
    || typeof threadId !== "string"
    || !threadId
    || state.socket?.readyState !== WebSocket.OPEN
    || !state.bridgeReady
  ) return;
  try {
    const result = await rpc("thread/unsubscribe", { threadId }, { timeoutMs: 12_000 });
    if (result?.status === "notLoaded") state.loadedThreadIds.delete(threadId);
  } catch (error) {
    console.error(`Unable to release thread subscription ${threadId}:`, error);
  }
}

function rpcError(message, deliveryUnknown = false) {
  const error = new Error(message);
  error.deliveryUnknown = deliveryUnknown;
  return error;
}

async function loadProjects() {
  elements.projectList.innerHTML = '<div class="list-loading">正在读取工程</div>';
  try {
    const response = await fetchWithTimeout("/api/projects", {}, 12_000);
    const data = await response.json();
    if (!response.ok) throw new Error(data.error || "无法读取工程");
    state.projects = data.projects;
    state.projectRoot = data.root;
    state.projectRoots = Array.isArray(data.roots) ? data.roots : [{
      id: "legacy-root",
      path: data.root,
      label: "主存储",
      isDefault: true,
    }];
    state.defaultProject = data.defaultProject || null;
    setDataContent(elements.projectRoot, data.root);
    renderProjectRootOptions();
    const remembered = localStorage.getItem(accountStorageKey("codexDesktop.project"));
    const previousProjectPath = state.currentProject?.path || null;
    const previousThreadListProjectPath = state.threadListProjectPath;
    state.currentProject =
      state.projects.find((project) => project.path === state.currentProject?.path) ||
      state.projects.find((project) => project.path === remembered) ||
      state.projects.find((project) => project.path === data.defaultProject) ||
      state.projects[0] ||
      null;
    const nextThreadListProjectPath = state.projects.some(
      (project) => project.path === previousThreadListProjectPath,
    )
      ? previousThreadListProjectPath
      : state.currentProject?.path || null;
    if (nextThreadListProjectPath !== previousThreadListProjectPath) {
      state.threadListLoadVersion += 1;
      state.claudeSessionLoadVersion += 1;
      state.threadListViewKey = null;
      state.threads = [];
    }
    state.threadListProjectPath = nextThreadListProjectPath;
    state.selectedCodexWorktreeId = state.currentProject?.worktree
      ? state.currentProject.worktreeId || null
      : null;
    if (state.currentProject?.path !== previousProjectPath) {
      state.claudeSessionLoadVersion += 1;
      clearSelectedCodexSkills();
      invalidateCodexExtensions(state.currentProject?.path || null);
      invalidateCodexWorktreeInspection();
    }
    renderProjects();
    renderProjectContext();
    renderSidebarWorktrees();
  } catch (error) {
    elements.projectList.innerHTML = '<div class="list-empty">无法读取工程</div>';
    toast(error.message, "error");
  }
}

function threadListProject() {
  if (state.threadListProjectPath) {
    const browsed = state.projects.find((project) => project.path === state.threadListProjectPath);
    if (browsed) return browsed;
  }
  return state.currentProject;
}

function browseProjectThreads(project) {
  if (!project?.path) return;
  state.threadListProjectPath = project.path;
  state.threadListLoadVersion += 1;
  state.claudeSessionLoadVersion += 1;
  state.threadListViewKey = null;
  state.threads = [];
  elements.allThreadsToggle.checked = false;
  renderProjects();
  renderThreads();
  renderSidebarWorktrees();
  renderProjectNavigationContext();
  elements.threadList.innerHTML = '<div class="list-loading">正在读取所选工程对话</div>';
  openMobilePanels("threads");
  void loadThreads();
}

function renderProjects() {
  const query = elements.projectSearch.value.trim().toLowerCase();
  const projects = state.projects.filter(
    (project) => !project.worktree
      && (project.name.toLowerCase().includes(query) || project.path.toLowerCase().includes(query)),
  );
  elements.projectList.replaceChildren();
  if (!projects.length) {
    elements.projectList.innerHTML = '<div class="list-empty">没有匹配的工程</div>';
    return;
  }

  for (const project of projects) {
    const wrapper = document.createElement("div");
    wrapper.className = "project-row-wrap";
    const button = document.createElement("button");
    button.className = `project-row${project.path === state.threadListProjectPath ? " active" : ""}`;
    button.dataset.path = project.path;
    button.innerHTML = `
      <span class="project-row-icon"><i data-lucide="folder"></i></span>
      <span class="row-copy"><strong></strong><span></span></span>
      <span class="project-row-state">
        <span class="project-task-status" hidden></span>
        <span class="git-badge">${project.git ? '<i data-lucide="git-branch"></i>' : ""}</span>
      </span>
    `;
    setDataContent(button.querySelector("strong"), project.name);
    setDataContent(button.querySelector(".row-copy span"), project.worktree
      ? `Worktree · ${project.branch || project.baseRef || "Detached HEAD"}`
      : project.shared
        ? `${project.access === "write" ? "可编辑" : "只读"}共享 · ${project.sharedBy}`
        : project.path);
    if (project.shared) {
      button.querySelector(".project-row-icon").innerHTML = '<i data-lucide="folder-symlink"></i>';
    } else if (project.worktree) {
      button.querySelector(".project-row-icon").innerHTML = '<i data-lucide="git-branch"></i>';
    }
    const projectTask = projectTaskStatus(project.path);
    const projectTaskNode = button.querySelector(".project-task-status");
    if (projectTask) {
      projectTaskNode.hidden = false;
      projectTaskNode.dataset.status = projectTask.status;
      projectTaskNode.textContent = projectTask.count > 1
        ? `${taskStatusLabels[projectTask.status]} · ${projectTask.count}`
        : taskStatusLabels[projectTask.status];
      projectTaskNode.title = projectTask.title;
    }
    button.addEventListener("click", () => browseProjectThreads(project));
    const actions = document.createElement("div");
    actions.className = "project-row-actions";
    if (project.path !== state.currentProject?.path) {
      const switchButton = document.createElement("button");
      switchButton.type = "button";
      switchButton.className = "project-row-action project-row-switch";
      switchButton.title = "切换当前工程（保留现有对话）";
      switchButton.setAttribute("aria-label", switchButton.title);
      switchButton.innerHTML = '<i data-lucide="log-in"></i>';
      switchButton.addEventListener("click", (event) => {
        event.stopPropagation();
        switchButton.disabled = true;
        void selectProject(project)
          .catch((error) => toast(error.message || "无法切换工程", "error"))
          .finally(() => {
            if (switchButton.isConnected) switchButton.disabled = false;
          });
      });
      actions.append(switchButton);
    }
    const remove = document.createElement("button");
    remove.type = "button";
    remove.className = "project-row-action danger-hover";
    const protectedProject = project.shared
      || project.path === state.currentProject?.path
      || project.path === state.defaultProject;
    remove.disabled = protectedProject;
    remove.title = protectedProject
      ? project.shared ? "共享工程不能从这里移除" : "当前工程或默认工程不能移除"
      : "移除工程（可恢复）";
    remove.setAttribute("aria-label", remove.title);
    remove.innerHTML = '<i data-lucide="trash-2"></i>';
    remove.addEventListener("click", (event) => {
      event.stopPropagation();
      void removeProject(project);
    });
    actions.append(remove);
    wrapper.append(button, actions);
    elements.projectList.append(wrapper);
  }
  refreshIcons();
}

async function removeProject(project) {
  if (!project?.path || project.shared || project.path === state.currentProject?.path || project.path === state.defaultProject) return;
  if (!confirm(`移除工程“${project.name}”？\n\n工程目录会移动到可恢复回收区，对话记录不会主动删除。`)) return;
  try {
    const response = await fetchWithTimeout("/api/projects", {
      method: "DELETE",
      headers: {
        "Content-Type": "application/json",
        "X-Codex-Desktop-Action": "project-remove",
      },
      body: JSON.stringify({ project: project.path, confirmation: project.path }),
    }, 70_000);
    const data = await response.json().catch(() => ({}));
    if (!response.ok) throw new Error(data.error || "无法移除工程");
    await loadProjects();
    toast(`工程已移入可恢复回收区（${data.trashId || "已完成"}）`);
  } catch (error) {
    toast(error.message, "error");
  }
}

function setThreadPaneView(view, { persist = true } = {}) {
  const nextView = view === "worktrees" ? "worktrees" : "threads";
  state.threadPaneView = nextView;
  if (persist) localStorage.setItem("codexDesktop.threadPaneView", nextView);
  const showingThreads = nextView === "threads";
  elements.threadViewTab.classList.toggle("active", showingThreads);
  elements.worktreeViewTab.classList.toggle("active", !showingThreads);
  elements.threadViewTab.setAttribute("aria-selected", String(showingThreads));
  elements.worktreeViewTab.setAttribute("aria-selected", String(!showingThreads));
  elements.threadPaneContent.hidden = !showingThreads;
  elements.worktreePaneContent.hidden = showingThreads;
  if (!showingThreads) {
    renderSidebarWorktrees();
    void loadCodexWorktrees({ all: true });
  }
  updateThreadPaneRefreshControl();
  refreshIcons();
}

function updateThreadPaneRefreshControl() {
  const showingWorktrees = state.threadPaneView === "worktrees";
  elements.threadSectionsButton.hidden = showingWorktrees
    || state.runtime !== "codex"
    || !codexRuntimeFeatureAvailable("conversationSections");
  elements.recoveryButton.hidden = showingWorktrees;
  elements.refreshThreadsButton.hidden = showingWorktrees;
  elements.refreshThreadsButton.disabled = false;
  if (!showingWorktrees) {
    elements.refreshThreadsButton.title = "刷新对话";
    elements.refreshThreadsButton.setAttribute("aria-label", "刷新对话");
  }
}

function worktreeStateLabel(worktree) {
  const location = worktree.location === "local" ? "Local" : "Worktree";
  if (worktree.state === "ready") return location;
  return {
    restorable: "可恢复",
    missing: "目录缺失",
    deleted: "已清理",
  }[worktree.state] || worktree.state || "未知状态";
}

function worktreeSyncLabel(worktree) {
  if (worktree?.sync?.available) return "有新代码";
  if (worktree?.sync?.action === "create-branch") return "先创建分支";
  if (worktree?.sync?.action === "handoff") return "先交接回 Worktree";
  if (worktree?.sync?.state === "blocked") return "需手动处理";
  return "";
}

function worktreeAutoAdvanceLabel(worktree) {
  return {
    eligible: "可自动推进",
    "not-needed": "无需推进",
    "not-applicable": "不在自动范围",
    blocked: "无法自动推进",
    unknown: "无法确认",
  }[worktree?.sync?.autoAdvance?.state] || "";
}

function appendWorktreeAutoAdvanceBadge(actions, worktree) {
  const label = worktreeAutoAdvanceLabel(worktree);
  if (!label) return;
  const badge = document.createElement("span");
  badge.className = "worktree-auto-advance-badge";
  badge.dataset.state = worktree.sync.autoAdvance.state;
  badge.textContent = label;
  badge.title = worktree.sync.autoAdvance.reason || label;
  actions.append(badge);
}

function appendWorktreePurgeActions(actions, worktree) {
  if (!worktree || !["restorable", "missing", "deleted"].includes(worktree.state)) return;
  actions.append(worktreeRecordButton(
    worktree.threadId
      ? "彻底删除 Worktree 和绑定对话（保留 Git 分支）"
      : "彻底删除 Worktree 记录和恢复快照（保留 Git 分支）",
    "trash-2",
    () => { void purgeManagedCodexWorktree(worktree); },
    true,
  ));
  if (worktree.branch) {
    actions.append(worktreeRecordButton(
      "彻底删除 Worktree 记录、恢复快照和 Git 分支",
      "git-branch",
      () => { void purgeManagedCodexWorktree(worktree, { deleteBranch: true }); },
      true,
    ));
  }
}

function worktreeSyncAction(worktree) {
  return worktree?.sync?.action || null;
}

function worktreeRunStatus(worktree) {
  if (!worktree?.threadId) {
    return { status: "unbound", label: "未绑定", detail: "尚未绑定对话" };
  }
  const task = state.threadTaskStatuses.get(worktree.threadId)
    || (state.taskStatusSnapshot?.threadId === worktree.threadId ? state.taskStatusSnapshot : null);
  const activeThreadMatches = state.activeThread?.worktree?.id === worktree.id;
  const active = task?.status || (
    activeThreadMatches && state.activeTurnId ? "running" : null
  );
  if (!active) {
    return state.threadTaskStatusesReady
      ? { status: "idle", label: "空闲", detail: "没有运行中的任务" }
      : { status: "unknown", label: "状态同步中", detail: "正在读取任务状态" };
  }
  const label = taskStatusLabels[active] || active;
  const phase = taskPhaseLabels[task?.phase] || task?.phase || "";
  return {
    status: active,
    label,
    detail: phase ? `${label} · ${phase}` : label,
  };
}

function codexWorktreeSourceProjectPath(project) {
  if (!project) return null;
  if (project.worktree) return project.sourceProjectPath || null;
  return project.path || null;
}

function currentCodexWorktreeSourceProjectPath() {
  return codexWorktreeSourceProjectPath(state.currentProject);
}

function threadListCodexWorktreeSourceProjectPath() {
  return codexWorktreeSourceProjectPath(threadListProject());
}

function visibleCodexWorktrees(sourceProjectPath = currentCodexWorktreeSourceProjectPath()) {
  if (!sourceProjectPath) return [];
  return (Array.isArray(state.codexWorktrees) ? state.codexWorktrees : [])
    .filter((worktree) => sameProjectPath(worktree?.projectPath, sourceProjectPath));
}

function renderSidebarWorktrees() {
  const worktrees = visibleCodexWorktrees(threadListCodexWorktreeSourceProjectPath());
  const availableSyncCount = worktrees.filter((worktree) => worktree.sync?.available).length;
  elements.worktreeCount.textContent = String(worktrees.filter((worktree) => worktree.state !== "deleted").length);
  elements.worktreeViewState.textContent = state.codexWorktreesLoading
    ? "正在读取 Worktree"
    : state.runtime !== "codex"
      ? "Worktree 仅支持 Codex 对话"
      : `${worktrees.length} 个 Worktree${availableSyncCount ? ` · ${availableSyncCount} 个有新代码` : ""}`;
  elements.refreshWorktreesButton.disabled = state.codexWorktreesLoading;
  updateThreadPaneRefreshControl();
  elements.worktreeList.replaceChildren();
  if (state.codexWorktreesLoading && !worktrees.length) {
    elements.worktreeList.innerHTML = '<div class="list-loading">正在读取 Worktree</div>';
    return;
  }
  const query = elements.worktreeSearch.value.trim().toLowerCase();
  const visible = worktrees.filter((worktree) => {
    const text = [
      worktree.label,
      worktree.projectPath,
      worktree.branch,
      worktree.baseRef,
      worktree.threadId,
      worktreeStateLabel(worktree),
    ].filter(Boolean).join(" ").toLowerCase();
    return !query || text.includes(query);
  });
  if (!visible.length) {
    elements.worktreeList.innerHTML = `<div class="list-empty">${query ? "没有匹配的 Worktree" : "还没有 Worktree"}</div>`;
    return;
  }
  for (const worktree of visible) {
    const row = document.createElement("article");
    row.className = "worktree-row";
    const active = state.selectedCodexWorktreeId === worktree.id
      || state.currentProject?.worktreeId === worktree.id
      || state.activeThread?.worktree?.id === worktree.id;
    if (active) row.classList.add("active");
    const main = document.createElement("button");
    main.className = "worktree-row-main";
    main.type = "button";
    main.title = worktree.threadId
      ? "选择此 Worktree；绑定关系保留在对应对话属性中"
      : "选择此 Worktree，作为下个 Codex 对话的工作区";
    main.innerHTML = '<i data-lucide="git-branch"></i><span class="worktree-row-copy"><strong></strong><small></small></span>';
    main.querySelector("strong").textContent = worktree.label || `Worktree ${worktree.id.slice(-8)}`;
    main.querySelector("small").textContent = [
      pathBasename(worktree.projectPath),
      worktree.branch || worktree.baseRef || "Detached HEAD",
      relativeTime(worktree.lastUsedAt / 1_000),
    ].filter(Boolean).join(" · ");
    main.addEventListener("click", () => { openWorktreeFromRecord(worktree, main); });
    const actions = document.createElement("div");
    actions.className = "worktree-row-actions";
    appendWorktreeAutoAdvanceBadge(actions, worktree);
    const syncLabel = worktreeSyncLabel(worktree);
    if (syncLabel) {
      const syncBadge = document.createElement("span");
      syncBadge.className = "worktree-sync-badge";
      syncBadge.dataset.state = worktree.sync?.state || "blocked";
      syncBadge.textContent = syncLabel;
      syncBadge.title = worktree.sync?.reason || syncLabel;
      actions.append(syncBadge);
    }
    const stateBadge = document.createElement("span");
    stateBadge.className = "worktree-row-status";
    stateBadge.dataset.state = worktree.state || "unknown";
    stateBadge.textContent = worktreeStateLabel(worktree);
    stateBadge.title = worktree.worktreeProjectPath || worktree.projectPath || "";
    const runStatus = worktreeRunStatus(worktree);
    const runBadge = document.createElement("span");
    runBadge.className = "worktree-run-status";
    runBadge.dataset.status = runStatus.status;
    runBadge.textContent = runStatus.label;
    runBadge.title = runStatus.detail;
    actions.append(runBadge, stateBadge);
    if (worktree.state !== "deleted") {
      actions.append(worktreeRecordButton(
        "修改 Worktree 名称",
        "pencil",
        () => { void renameManagedCodexWorktree(worktree); },
      ));
    }
    if (worktree.sync?.available) {
      actions.append(worktreeRecordButton(
        worktree.sync.dirty ? "同步最新代码并保留未提交修改" : "同步到来源分支最新代码",
        "refresh-cw",
        () => { void syncManagedCodexWorktree(worktree); },
      ));
    } else if (worktreeSyncAction(worktree) === "create-branch") {
      actions.append(worktreeRecordButton(
        "先创建 Git 分支，再同步来源分支最新代码",
        "git-branch-plus",
        () => { void createManagedCodexWorktreeBranch(worktree); },
      ));
    } else if (worktreeSyncAction(worktree) === "handoff") {
      actions.append(worktreeRecordButton(
        "先把绑定对话和代码交接回 Worktree",
        "replace",
        () => { void handoffManagedCodexWorktree(worktree); },
      ));
    }
    if (["restorable", "missing"].includes(worktree.state) && worktree.snapshot) {
      actions.append(worktreeRecordButton("恢复", "archive-restore", () => restoreCodexWorktree(worktree)));
    }
    if (worktree.state === "ready") {
      actions.append(worktreeRecordButton(
        worktree.pinned ? "取消固定" : "固定",
        worktree.pinned ? "pin-off" : "pin",
        () => pinManagedCodexWorktree(worktree),
      ));
    }
    const canRemoveWorktree = worktree.state === "ready"
      && worktree.location !== "local";
    if (canRemoveWorktree) {
      const removeLabel = worktree.threadId
        ? "删除 Worktree（保留绑定对话和恢复快照）"
        : "删除 Worktree（保留恢复快照和 Git 分支）";
      actions.append(worktreeRecordButton(
        removeLabel,
        "trash-2",
        () => {
          void removeManagedCodexWorktree(worktree);
        },
        true,
      ));
    }
    if (canRemoveWorktree && !worktree.threadId && worktree.branch) {
      actions.append(worktreeRecordButton(
        worktree.state === "ready" ? "删除 Worktree 和 Git 分支" : "删除 Git 分支（保留恢复快照）",
        "git-branch",
        () => removeManagedCodexWorktree(worktree, { deleteBranch: true }),
        true,
      ));
    }
    appendWorktreePurgeActions(actions, worktree);
    row.append(main, actions);
    elements.worktreeList.append(row);
  }
  refreshIcons();
}

function codexWorktreeProjectForRecord(worktree) {
  if (!worktree?.id) return null;
  const sourceProject = state.projects.find((project) => (
    project.path === worktree.projectPath && !project.worktree
  ));
  if (worktree.location === "local") return sourceProject || null;
  const existing = state.projects.find((project) => project.worktreeId === worktree.id);
  if (existing) return { ...existing, ...worktree, worktree: true, worktreeId: worktree.id };
  const projectPath = worktree.worktreeProjectPath;
  return {
    ...(sourceProject || {}),
    id: worktree.id,
    name: worktree.label || `${pathBasename(worktree.projectPath)} · Worktree`,
    path: projectPath,
    git: true,
    worktree: true,
    worktreeId: worktree.id,
    sourceProjectPath: worktree.projectPath,
    branch: worktree.branch,
    baseRef: worktree.baseRef,
    pinned: worktree.pinned,
    modifiedAt: worktree.lastUsedAt || Date.now(),
  };
}

function threadWithManagedCodexWorktree(thread) {
  if (!thread?.id || thread.worktree?.id) return thread;
  const worktree = state.codexWorktrees.find((entry) => entry.threadId === thread.id);
  if (!worktree) return thread;
  const cwd = worktree.location === "local"
    ? worktree.projectPath
    : worktree.worktreeProjectPath;
  return {
    ...thread,
    cwd,
    worktree,
  };
}

function openWorktreeFromRecord(worktree, trigger = null) {
  if (trigger?.disabled) return;
  if (trigger) trigger.disabled = true;
  void openSidebarWorktree(worktree)
    .catch((error) => {
      console.error("Unable to open Codex Worktree:", error);
      toast(error.message || "无法选择 Worktree", "error");
    })
    .finally(() => {
      if (trigger?.isConnected) trigger.disabled = false;
    });
}

async function openSidebarWorktree(worktree) {
  if (!worktree?.id) return;
  if (state.runtime !== "codex") {
    toast("Worktree 只能在 Codex 对话中使用", "error");
    return;
  }
  if (worktree.state !== "ready") {
    toast(worktree.snapshot ? "请先点击恢复，再打开这个 Worktree" : "这个 Worktree 当前不可用", "error");
    return;
  }
  const sourceProject = state.projects.find((project) => (
    project.path === worktree.projectPath && !project.worktree
  )) || codexWorkspaceSourceProject();
  const project = sourceProject || codexWorktreeProjectForRecord(worktree);
  if (!project) {
    toast("Worktree 的来源工程当前不可用", "error");
    return;
  }
  if (
    !state.bridgeReady
    || state.socket?.readyState !== WebSocket.OPEN
    || !state.conversationReady
  ) {
    resumeConnectivity();
    await waitForConversationReady();
  }
  if (!state.bridgeReady || state.socket?.readyState !== WebSocket.OPEN) {
    throw new Error("Codex 对话连接尚未就绪，请稍后重试");
  }
  if (worktree.threadId) {
    const cwd = worktree.location === "local"
      ? worktree.projectPath
      : worktree.worktreeProjectPath;
    activateCodexProject(project);
    state.threadListProjectPath = project.path;
    state.selectedCodexWorktreeId = null;
    const listedThread = state.threads.find((entry) => entry.id === worktree.threadId) || null;
    // The cached thread list can predate the Worktree binding and therefore
    // omit the Worktree metadata. The durable Worktree record is authoritative
    // for this opener; merge it into the target before attempting recovery.
    const thread = {
      ...(listedThread || {}),
      id: worktree.threadId,
      cwd,
      name: listedThread?.name || worktree.label || "Worktree 对话",
      preview: listedThread?.preview || "",
      worktree,
    };
    const opened = await resumeThread(thread);
    if (!opened) return false;
    setThreadPaneView("worktrees");
    openMobilePanels("threads");
    renderSidebarWorktrees();
    toast("已打开此 Worktree 的对话");
    return true;
  }
  state.selectedCodexWorktreeId = worktree.id;
  if (!state.activeThread && project.path !== state.currentProject?.path) {
    activateCodexProject(project, { selectedWorktreeId: worktree.id });
  }
  const created = await createAndBindWorktreeConversation(worktree);
  if (!created) return false;
  setThreadPaneView("worktrees");
  openMobilePanels("threads");
  renderSidebarWorktrees();
  toast("已创建并打开此 Worktree 的对话");
  return true;
}

async function startEmptyCodexWorktreeConversation(worktree, project) {
  if (!worktree?.id || !project?.path) throw new Error("Worktree 或工程信息不完整");
  if (worktree.threadId) throw new Error("所选 Worktree 已绑定对话");
  if (state.runtime !== "codex") throw new Error("Worktree 只能在 Codex 对话中使用");
  if (!state.bridgeReady || state.socket?.readyState !== WebSocket.OPEN || !state.conversationReady) {
    resumeConnectivity();
    await waitForConversationReady();
  }
  if (!state.bridgeReady || state.socket?.readyState !== WebSocket.OPEN) {
    throw new Error("Codex 对话连接尚未就绪，请稍后重试");
  }

  const previousThreadId = state.activeThread?.id || null;
  const selectionVersion = ++state.threadSelectionVersion;
  state.threadSelectionPending = true;
  state.activeThread = null;
  state.activeTurnId = null;
  state.codexActiveTurnId = null;
  syncCodexActiveThreadRecoveryProjection();
  state.threadHistoryCursor = null;
  state.threadHistoryTopTriggerThreadId = null;
  state.threadHistoryTopTriggerArmed = true;
  state.pendingUserMessage = null;
  clearThreadItemPages(previousThreadId);
  if (previousThreadId) void releaseThreadSubscription(previousThreadId);
  clearThreadRecovery();
  state.selectedCodexWorktreeId = worktree.id;
  state.threadListProjectPath = project.path;
  elements.threadTitleInput.value = "新对话";
  renderActiveThread();
  renderThreads();
  setTurnBusy(true, "正在创建对话");
  try {
    const params = {
      model: state.selectedModel,
      effort: state.selectedEffort,
      cwd: project.path,
      ephemeral: false,
      _wflClientThreadRequestId: createClientMessageId(),
      _wflWorktreeId: worktree.id,
    };
    addPolicyParams(params);
    const result = await rpcWithSameRuntimeRetry("thread/start", params);
    if (selectionVersion !== state.threadSelectionVersion) return null;
    if (!result?.thread?.id) throw new Error("Codex 未返回新对话");
    const thread = result.thread;
    replaceActiveConversationThread(thread);
    state.threadHistoryCursor = null;
    markCodexThreadNeedsResume(thread.id, false);
    state.loadedThreadIds.add(thread.id);
    if (thread.status) state.threadRuntimeStatuses.set(thread.id, thread.status);
    state.selectedModel = resolveRememberedCodexModel(result.model || state.selectedModel);
    state.selectedEffort = resolveRememberedCodexEffort(
      state.selectedModel,
      result.reasoningEffort || state.selectedEffort,
    );
    state.threads = [thread, ...state.threads.filter((entry) => entry.id !== thread.id)];
    const boundWorktree = thread.worktree?.id === worktree.id ? thread.worktree : null;
    if (boundWorktree) {
      state.codexWorktrees = state.codexWorktrees.map((entry) => (
        entry.id === boundWorktree.id ? boundWorktree : entry
      ));
    }
    rememberActiveThread(thread, "created");
    sendClientState(thread.id);
    renderProjectContext();
    renderActiveThread({ scrollToBottom: true });
    renderThreads();
    renderSidebarWorktrees();
    void loadThreads();
    return thread;
  } finally {
    if (selectionVersion === state.threadSelectionVersion) {
      state.threadSelectionPending = false;
      setTurnBusy(conversationBusy(), conversationBusyLabel());
      elements.promptInput.focus();
    }
  }
}

function clearActiveCodexThreadForWorktreeSelection() {
  const previousThreadId = state.activeThread?.id || null;
  if (!previousThreadId) return;
  state.threadSelectionVersion += 1;
  state.threadSelectionPending = false;
  state.activeThread = null;
  state.activeTurnId = null;
  state.codexActiveTurnId = null;
  syncCodexActiveThreadRecoveryProjection();
  state.threadHistoryCursor = null;
  state.threadHistoryTopTriggerThreadId = null;
  state.threadHistoryTopTriggerArmed = true;
  state.pendingUserMessage = null;
  clearThreadItemPages(previousThreadId);
  clearThreadRecovery();
  void releaseThreadSubscription(previousThreadId);
  sendClientState(null);
  renderActiveThread();
  renderThreads();
  setTurnBusy(false, "就绪");
}

async function selectProject(project) {
  if (state.terminalRunning && project.path !== state.currentProject?.path) {
    toast("当前工程仍有集成终端命令运行，请先停止命令", "error");
    return false;
  }
  if (state.imageGenerating && project.path !== state.currentProject?.path) {
    toast("图片正在生成，完成后再切换工程", "error");
    return false;
  }
  if (state.turnPreparationPending) {
    toast("任务正在准备，完成后再切换工程", "error");
    return false;
  }
  if (state.pendingTurnRequest) {
    toast("当前消息仍在确认发送，请等待连接恢复", "error");
    return false;
  }
  if (state.pendingSteerRequest || state.steerRequestPending) {
    toast("追加指令仍在确认发送，请等待确认后再切换工程", "error");
    return false;
  }
  if (state.pendingClaudeTurnRequest) {
    toast("Claude 消息仍在确认投递，请等待连接恢复", "error");
    return false;
  }
  state.threadListProjectPath = project.path;
  if (project.path === state.currentProject?.path) {
    renderProjects();
    renderSidebarWorktrees();
    openMobilePanels("threads");
    return true;
  }
  const previousCodexThreadId = state.runtime === "codex" ? state.activeThread?.id || null : null;
  const selectionVersion = ++state.threadSelectionVersion;
  cancelConversationLoadProgress();
  state.threadListLoadVersion += 1;
  state.claudeSessionLoadVersion += 1;
  state.threadSelectionPending = false;
  // A project switch is a readiness boundary. Do not leave the old project's
  // task authority or composer state active while the new project is loading.
  state.conversationReady = false;
  state.taskStatusSnapshot = null;
  state.currentProject = project;
  state.selectedCodexWorktreeId = project.worktree ? project.worktreeId || null : null;
  invalidateMapManagedAuthorizations();
  state.threadListViewKey = null;
  state.threads = [];
  clearSelectedCodexSkills();
  invalidateCodexExtensions(project.path);
  invalidateCodexWorktreeInspection();
  if (state.runtime === "claude") state.activeClaudeSession = null;
  else {
    state.activeThread = null;
    state.codexActiveTurnId = null;
  }
  state.activeTurnId = null;
  syncCodexActiveThreadRecoveryProjection();
  state.threadHistoryCursor = null;
  state.threadHistoryTopTriggerThreadId = null;
  state.threadHistoryTopTriggerArmed = true;
  state.pendingUserMessage = null;
  if (state.runtime === "codex") clearThreadRecovery();
  state.attachments = [];
  renderAttachmentList();
  localStorage.setItem(accountStorageKey("codexDesktop.project"), project.path);
  renderProjects();
  renderProjectContext();
  renderSidebarWorktrees();
  if (previousCodexThreadId) void releaseThreadSubscription(previousCodexThreadId);
  if (elements.resourceDialog.open) loadResourceDirectory(project.path);
  if (elements.browserDialog.open) loadBrowserPreviewEntries();
  if (elements.mapWorkspaceDialog.open) void loadMapWorkspaceProject();
  renderActiveThread();
  renderThreads();
  elements.threadList.innerHTML = '<div class="list-loading">正在读取当前工程对话</div>';
  setTurnBusy(true, "正在切换工程");
  openMobilePanels("threads");
  if (state.bridgeReady) {
    // Start the list request immediately. Configuration and list loading are
    // independent; the old sequential order made the previous project's
    // threads remain visible until config/policy RPCs completed.
    void loadThreads();
    try {
      if (state.runtime === "claude") await loadClaudeConfig();
      else await loadConfig();
    } catch (error) {
      if (selectionVersion === state.threadSelectionVersion) {
        toast(`无法读取当前工程配置：${error.message}`, "error");
      }
      return false;
    }
    if (selectionVersion !== state.threadSelectionVersion || state.currentProject?.path !== project.path) return false;
    state.conversationReady = true;
    setTurnBusy(conversationBusy(), conversationBusyLabel());
  }
  return true;
}

function renderProjectContext() {
  const project = state.currentProject;
  renderProjectNavigationContext();
  setDataContent(elements.currentProjectName, project?.name || "未选择工程", Boolean(project));
  setDataContent(elements.chatProjectLabel, project?.name || "未选择工程", Boolean(project));
  const selectedWorktree = !state.activeThread && state.selectedCodexWorktreeId
    ? state.codexWorktrees.find((worktree) => worktree.id === state.selectedCodexWorktreeId)
    : null;
  const activeWorktree = selectedWorktree
    || state.activeThread?.worktree
    || (project?.worktree
      ? state.codexWorktrees.find((worktree) => worktree.id === project.worktreeId)
      : null);
  const branch = state.runtime === "codex"
    ? activeWorktree?.branch || state.activeThread?.gitInfo?.branch || project?.branch || null
    : null;
  const detachedLabel = activeWorktree && !branch
    ? `Detached HEAD · ${String(activeWorktree.baseCommit || "").slice(0, 8)}`
    : null;
  const pendingWorktree = Boolean(selectedWorktree && !selectedWorktree.threadId && !state.activeThread);
  const branchLabel = branch
    ? pendingWorktree ? `下个对话 · ${branch}` : `分支 · ${branch}`
    : detachedLabel;
  const canSwitchChatBranch = Boolean(
    state.runtime === "codex"
    && state.activeThread?.id
    && state.activeThread?.worktree?.id,
  );
  elements.chatBranchSwitcher.hidden = !branchLabel;
  elements.chatBranchLabel.hidden = !branchLabel;
  elements.chatBranchLabel.querySelector("span").textContent = branchLabel || "";
  elements.chatBranchLabel.disabled = !canSwitchChatBranch;
  elements.chatBranchLabel.setAttribute("aria-disabled", String(!canSwitchChatBranch));
  elements.chatBranchLabel.title = !branchLabel
    ? ""
    : canSwitchChatBranch
      ? "点击切换当前对话绑定的 Git 分支"
      : `当前对话：${branchLabel}`;
  if (!canSwitchChatBranch) closeChatBranchMenu();
  renderChatBranchMenu();
  elements.composerProject.innerHTML = '<i data-lucide="folder"></i>';
  elements.composerProject.append(document.createTextNode(` ${project?.path || state.projectRoot}`));
  elements.gitStatus.textContent = project?.git ? "Git 仓库" : "普通目录";
  if (project?.worktree) {
    elements.gitStatus.textContent = `Worktree · ${project.branch || project.baseRef || "Detached HEAD"}`;
  }
  if (pendingWorktree) {
    elements.gitStatus.textContent = `下个对话 · Worktree · ${branch || "已选择"}`;
  }
  if (project?.shared) {
    elements.gitStatus.textContent = project.access === "write" ? "共享 · 可编辑" : "共享 · 只读";
  }
  elements.gitDrawerButton.disabled = !project;
  elements.mapWorkspaceButton.disabled = false;
  elements.backgroundTaskDrawerButton.disabled = false;
  const readOnlyShare = project?.shared && project.access !== "write";
  for (const button of [elements.attachmentButton, elements.imageAttachmentButton]) {
    button.disabled = readOnlyShare;
    button.title = readOnlyShare ? "只读共享工程不能上传附件" : button === elements.attachmentButton ? "上传文件" : "上传图片";
  }
  refreshImageStudioControl();
  renderImageContextIsolationSetting();
  refreshIcons();
}

function renderProjectNavigationContext() {
  const current = state.currentProject;
  const browsed = threadListProject();
  const browsingAnotherProject = Boolean(
    browsed?.path
    && current?.path
    && browsed.path !== current.path,
  );
  elements.threadListProjectContext.hidden = !browsingAnotherProject;
  elements.threadListProjectContext.textContent = browsingAnotherProject
    ? `浏览：${browsed.name || pathBasename(browsed.path)}`
    : "";
  const newLabel = browsingAnotherProject
    ? `在 ${browsed.name || pathBasename(browsed.path)} 新对话`
    : "新对话";
  elements.sidebarNewThreadButton.title = newLabel;
  elements.sidebarNewThreadButton.setAttribute("aria-label", newLabel);
  const label = elements.sidebarNewThreadButton.querySelector("span");
  if (label) label.textContent = newLabel;
}

function openTerminalDrawer() {
  if (!canUseCodexTerminal()) {
    toast("当前账号没有使用 Codex Terminal 的权限", "error");
    return;
  }
  if (state.runtime !== "codex" || !state.currentProject) {
    toast("请先在 Codex 中选择工程", "error");
    return;
  }
  elements.terminalSummary.textContent = `${state.currentProject.path} · 工作区写入 · 网络关闭`;
  elements.terminalThreadShellButton.hidden = !isAccountAdmin()
    || !state.activeThread
    || state.activeThread.imported === true;
  if (!elements.terminalDrawer.open) elements.terminalDrawer.show();
  updateTerminalControls();
  elements.terminalInput.focus();
  if (elements.terminalBackgroundDetails.open) void loadBackgroundTerminals();
}

function handleTerminalInputKeydown(event) {
  if (event.key === "Enter" && !event.shiftKey) {
    event.preventDefault();
    elements.terminalInputForm.requestSubmit();
    return;
  }
  if (state.terminalRunning || !["ArrowUp", "ArrowDown"].includes(event.key)) return;
  if (!state.terminalHistory.length) return;
  event.preventDefault();
  if (event.key === "ArrowUp") {
    state.terminalHistoryIndex = Math.min(
      state.terminalHistory.length - 1,
      state.terminalHistoryIndex < 0 ? state.terminalHistory.length - 1 : state.terminalHistoryIndex + 1,
    );
  } else {
    state.terminalHistoryIndex = Math.max(-1, state.terminalHistoryIndex - 1);
  }
  elements.terminalInput.value = state.terminalHistoryIndex < 0
    ? ""
    : state.terminalHistory[state.terminalHistory.length - 1 - state.terminalHistoryIndex];
}

async function submitTerminalInput(event) {
  event.preventDefault();
  const value = elements.terminalInput.value;
  if (!value.trim()) return;
  if (state.terminalRunning) {
    elements.terminalInput.value = "";
    try {
      await writeTerminalBytes(`${value}\n`);
    } catch (error) {
      toast(error.message, "error");
    }
    return;
  }
  if (!state.currentProject || !canUseCodexTerminal()) return;
  const command = value.trim();
  elements.terminalInput.value = "";
  state.terminalHistory.push(command);
  if (state.terminalHistory.length > 100) state.terminalHistory.shift();
  state.terminalHistoryIndex = -1;
  const processId = `term_${crypto.randomUUID().replaceAll("-", "")}`;
  state.terminalProcessId = processId;
  state.terminalRunning = true;
  state.terminalDecoder = new TextDecoder();
  appendTerminalOutput(`${state.terminalOutput && !state.terminalOutput.endsWith("\n") ? "\n" : ""}$ ${command}\n`);
  updateTerminalControls();
  try {
    const result = await rpc("command/exec", {
      processId,
      command: ["/bin/bash", "-lc", command],
      cwd: state.currentProject.path,
      timeoutMs: 30 * 60_000,
      size: terminalSize(),
    }, { timeoutMs: 30 * 60_000 + 20_000 });
    const buffered = [result?.stdout, result?.stderr].filter((entry) => typeof entry === "string" && entry);
    if (buffered.length) appendTerminalOutput(buffered.join(""));
    appendTerminalOutput(`\n[进程结束，退出码 ${Number.isInteger(result?.exitCode) ? result.exitCode : "未知"}]\n`);
  } catch (error) {
    appendTerminalOutput(`\n[终端错误：${error.message}]\n`);
  } finally {
    if (state.terminalProcessId === processId) finishTerminalProcess();
  }
}

function terminalSize() {
  const width = Math.max(320, elements.terminalOutput.clientWidth || 800);
  const height = Math.max(160, elements.terminalOutput.clientHeight || 360);
  return {
    cols: Math.min(400, Math.max(40, Math.floor(width / 8))),
    rows: Math.min(200, Math.max(12, Math.floor(height / 18))),
  };
}

function scheduleTerminalResize() {
  clearTimeout(state.terminalResizeTimer);
  if (!state.terminalRunning || !state.terminalProcessId) return;
  state.terminalResizeTimer = setTimeout(() => {
    if (!state.terminalRunning || !state.terminalProcessId) return;
    void rpc("command/exec/resize", {
      processId: state.terminalProcessId,
      size: terminalSize(),
    }, { timeoutMs: 15_000 }).catch(() => {});
  }, 180);
}

function handleTerminalOutput(payload) {
  if (!state.terminalRunning || payload?.processId !== state.terminalProcessId) return;
  try {
    const bytes = terminalBase64Bytes(payload.deltaBase64);
    appendTerminalOutput(state.terminalDecoder.decode(bytes, { stream: true }));
  } catch {
    appendTerminalOutput("\n[收到无法解码的终端输出]\n");
  }
  if (payload.capReached) appendTerminalOutput("\n[输出已达到 4 MiB 安全上限]\n");
}

function terminalBase64Bytes(value) {
  const binary = atob(String(value || ""));
  const bytes = new Uint8Array(binary.length);
  for (let index = 0; index < binary.length; index += 1) bytes[index] = binary.charCodeAt(index);
  return bytes;
}

function terminalBytesBase64(value) {
  const bytes = new TextEncoder().encode(value);
  let binary = "";
  for (let index = 0; index < bytes.length; index += 1) binary += String.fromCharCode(bytes[index]);
  return btoa(binary);
}

async function writeTerminalBytes(value) {
  if (!state.terminalRunning || !state.terminalProcessId) throw new Error("当前没有运行中的终端");
  await rpc("command/exec/write", {
    processId: state.terminalProcessId,
    deltaBase64: terminalBytesBase64(value),
  }, { timeoutMs: 15_000 });
}

async function sendTerminalControl(key) {
  const controls = {
    "ctrl-c": "\u0003",
    tab: "\t",
    escape: "\u001b",
    "arrow-up": "\u001b[A",
    "arrow-down": "\u001b[B",
  };
  if (!state.terminalRunning) {
    if (key === "arrow-up" || key === "arrow-down") {
      handleTerminalInputKeydown({
        key: key === "arrow-up" ? "ArrowUp" : "ArrowDown",
        preventDefault() {},
      });
      elements.terminalInput.focus();
    }
    return;
  }
  try {
    await writeTerminalBytes(controls[key] || "");
    elements.terminalInput.focus();
  } catch (error) {
    toast(error.message, "error");
  }
}

async function stopTerminalProcess() {
  if (!state.terminalRunning || !state.terminalProcessId) return;
  elements.terminalStopButton.disabled = true;
  elements.terminalStatus.textContent = "正在停止";
  try {
    await rpc("command/exec/terminate", { processId: state.terminalProcessId }, { timeoutMs: 15_000 });
  } catch (error) {
    toast(error.message, "error");
    updateTerminalControls();
  }
}

function finishTerminalProcess() {
  try {
    const tail = state.terminalDecoder?.decode();
    if (tail) appendTerminalOutput(tail);
  } catch {}
  state.terminalRunning = false;
  state.terminalProcessId = null;
  clearTimeout(state.terminalResizeTimer);
  state.terminalResizeTimer = null;
  state.terminalDecoder = new TextDecoder();
  updateTerminalControls();
}

function updateTerminalControls() {
  elements.terminalStopButton.disabled = !state.terminalRunning;
  elements.terminalSendButton.querySelector("span").textContent = state.terminalRunning ? "输入" : "运行";
  elements.terminalSendButton.querySelector("i")?.setAttribute("data-lucide", state.terminalRunning ? "corner-down-left" : "play");
  elements.terminalStatus.textContent = state.terminalRunning ? "终端运行中" : "终端";
  elements.terminalInput.placeholder = state.terminalRunning
    ? "输入内容并发送到当前进程；下方快捷键适合手机"
    : "输入命令；Shift+Enter 换行";
  refreshIcons();
}

function appendTerminalOutput(value) {
  if (!value) return;
  const output = String(value)
    .replace(/\u001B(?:[@-_][0-?]*[ -/]*[@-~]|\][^\u0007]*(?:\u0007|\u001B\\))/g, "")
    .replace(/\r\n/g, "\n")
    .replace(/\r/g, "\n");
  const nearBottom = elements.terminalOutput.scrollHeight
    - elements.terminalOutput.scrollTop
    - elements.terminalOutput.clientHeight < 80;
  state.terminalOutput += output;
  if (state.terminalOutput.length > 1_000_000) {
    state.terminalOutput = `[较早输出已折叠]\n${state.terminalOutput.slice(-800_000)}`;
  }
  elements.terminalOutput.textContent = state.terminalOutput;
  if (nearBottom) elements.terminalOutput.scrollTop = elements.terminalOutput.scrollHeight;
}

function clearTerminalOutput() {
  state.terminalOutput = "";
  elements.terminalOutput.textContent = "";
}

async function runThreadShellCommand() {
  if (!isAccountAdmin() || !state.activeThread || state.activeThread.imported === true) return;
  const command = elements.terminalInput.value.trim();
  if (!command) {
    toast("请先输入要发送到对话的命令", "error");
    return;
  }
  if (!confirm("该命令将作为当前对话的无沙箱 Shell 命令运行，拥有服务器账号的完整访问能力。确认继续？")) return;
  elements.terminalThreadShellButton.disabled = true;
  try {
    await rpc("thread/shellCommand", { threadId: state.activeThread.id, command }, { timeoutMs: 35_000 });
    elements.terminalInput.value = "";
    elements.terminalDrawer.close();
    toast("命令已发送到当前 Codex 对话");
  } catch (error) {
    toast(error.message, "error");
  } finally {
    elements.terminalThreadShellButton.disabled = false;
  }
}

async function loadBackgroundTerminals() {
  const thread = state.runtime === "codex" ? state.activeThread : null;
  if (!thread || thread.imported === true) {
    state.terminalBackground = [];
    renderBackgroundTerminals();
    return;
  }
  elements.terminalBackgroundRefreshButton.disabled = true;
  try {
    const result = await rpc("thread/backgroundTerminals/list", { threadId: thread.id, limit: 50 }, { timeoutMs: 35_000 });
    state.terminalBackground = Array.isArray(result?.data) ? result.data : [];
    renderBackgroundTerminals();
  } catch (error) {
    elements.terminalBackgroundList.textContent = error.message;
  } finally {
    elements.terminalBackgroundRefreshButton.disabled = false;
  }
}

async function cleanBackgroundTerminals() {
  if (!state.activeThread || state.activeThread.imported === true) return;
  elements.terminalBackgroundCleanButton.disabled = true;
  try {
    await rpc("thread/backgroundTerminals/clean", {
      threadId: state.activeThread.id,
    }, { timeoutMs: 20_000 });
    await loadBackgroundTerminals();
  } catch (error) {
    toast(error.message, "error");
  } finally {
    elements.terminalBackgroundCleanButton.disabled = false;
  }
}

function renderBackgroundTerminals() {
  elements.terminalBackgroundCount.textContent = String(state.terminalBackground.length);
  elements.terminalBackgroundList.replaceChildren();
  if (!state.terminalBackground.length) {
    const empty = document.createElement("p");
    empty.textContent = state.activeThread ? "当前对话没有后台终端。" : "选择原生 Codex 对话后可查看。";
    elements.terminalBackgroundList.append(empty);
    return;
  }
  for (const terminal of state.terminalBackground) {
    const row = document.createElement("div");
    row.className = "terminal-background-row";
    const copy = document.createElement("span");
    const command = document.createElement("strong");
    command.textContent = terminal.command || terminal.processId || "后台命令";
    const detail = document.createElement("small");
    detail.textContent = [
      terminal.osPid ? `PID ${terminal.osPid}` : null,
      Number.isFinite(terminal.cpuPercent) ? `CPU ${terminal.cpuPercent.toFixed(1)}%` : null,
      terminal.cwd || null,
    ].filter(Boolean).join(" · ");
    copy.append(command, detail);
    const stop = document.createElement("button");
    stop.type = "button";
    stop.className = "secondary-button danger-button";
    stop.textContent = "终止";
    stop.addEventListener("click", () => terminateBackgroundTerminal(terminal, stop));
    row.append(copy, stop);
    elements.terminalBackgroundList.append(row);
  }
}

async function terminateBackgroundTerminal(terminal, button) {
  if (!state.activeThread || !terminal?.processId) return;
  button.disabled = true;
  try {
    await rpc("thread/backgroundTerminals/terminate", {
      threadId: state.activeThread.id,
      processId: terminal.processId,
    }, { timeoutMs: 20_000 });
    await loadBackgroundTerminals();
  } catch (error) {
    toast(error.message, "error");
    button.disabled = false;
  }
}

async function openBackgroundTaskDrawer() {
  if (canUseCodexBackground()) {
    populateBackgroundTaskModels();
  }
  if (canUseCodexBackground() && !elements.backgroundTaskOnceInput.value) {
    elements.backgroundTaskOnceInput.value = new Date(Date.now() + 60 * 60_000)
      .toISOString()
      .slice(0, 16);
  }
  renderBackgroundTaskForm();
  selectTaskCenterTab("overview");
  if (!elements.backgroundTaskDrawer.open) elements.backgroundTaskDrawer.showModal();
  await refreshTaskCenter();
  startTaskCenterPolling();
}

function selectTaskCenterTab(tab) {
  state.taskCenterTab = tab === "schedules" && canUseCodexBackground() ? "schedules" : "overview";
  const overview = state.taskCenterTab === "overview";
  elements.taskCenterOverviewTab.setAttribute("aria-selected", String(overview));
  elements.taskCenterSchedulesTab.setAttribute("aria-selected", String(!overview));
  elements.taskCenterSchedulesTab.hidden = !canUseCodexBackground();
  elements.taskCenterOverviewPanel.hidden = !overview;
  elements.backgroundTaskBody.hidden = overview;
  if (overview) {
    renderTaskCenterOverview();
    return;
  }
  renderCodexBackgroundTasks();
  if (!state.codexBackgroundSummary) void loadCodexBackgroundTasks({ force: true });
}

async function refreshTaskCenter(options = {}) {
  const silent = options?.silent === true;
  if (state.taskCenterLoading) return;
  state.taskCenterLoading = true;
  elements.backgroundTaskRefreshButton.disabled = true;
  elements.backgroundTaskRefreshButton.classList.add("refreshing");
  if (!silent && state.taskCenterTab === "overview") {
    elements.backgroundTaskSummary.textContent = "正在同步服务器任务状态…";
  }
  try {
    const response = await fetchWithTimeout(
      `/api/task/center?_=${Date.now()}`,
      { cache: "no-store" },
      15_000,
    );
    const result = await readApiJson(response, "无法读取任务中心");
    state.taskCenterSnapshot = {
      observedAt: Number(result.observedAt) || Date.now(),
      tasks: Array.isArray(result.tasks) ? result.tasks : [],
      admission: result.admission && typeof result.admission === "object" ? result.admission : null,
      goals: Array.isArray(result.goals)
        ? result.goals.filter((goal) => !state.threadGoalTombstones.has(goal?.threadId))
        : [],
      backgroundAllowed: result.backgroundAllowed === true,
      backgroundTasks: Array.isArray(result.backgroundTasks) ? result.backgroundTasks : [],
      claudeAllowed: result.claudeAllowed === true,
      claudeBackgroundAllowed: result.claudeBackgroundAllowed === true,
      claudeSessions: Array.isArray(result.claudeSessions) ? result.claudeSessions : [],
      claudeBackgroundTasks: Array.isArray(result.claudeBackgroundTasks)
        ? result.claudeBackgroundTasks
        : [],
    };
    rememberThreadTaskStatuses(result.tasks);
    if (result.backgroundAllowed === true) {
      state.codexBackgroundTasks = state.taskCenterSnapshot.backgroundTasks;
      state.codexBackgroundSummary = result.backgroundSummary || null;
    } else {
      state.codexBackgroundTasks = [];
      state.codexBackgroundSummary = null;
      if (state.taskCenterTab === "schedules") selectTaskCenterTab("overview");
    }
    renderTaskCenterOverview();
    if (state.taskCenterTab === "schedules") renderCodexBackgroundTasks();
  } catch (error) {
    if (!silent) {
      elements.backgroundTaskSummary.textContent = error.message;
      toast(error.message, "error");
    }
  } finally {
    state.taskCenterLoading = false;
    elements.backgroundTaskRefreshButton.disabled = false;
    elements.backgroundTaskRefreshButton.classList.remove("refreshing");
  }
}

function startTaskCenterPolling() {
  stopTaskCenterPolling();
  state.taskCenterPollingTimer = setInterval(() => {
    if (elements.backgroundTaskDrawer.open && document.visibilityState === "visible") {
      void refreshTaskCenter({ silent: true });
    }
  }, 5_000);
}

function stopTaskCenterPolling() {
  clearInterval(state.taskCenterPollingTimer);
  state.taskCenterPollingTimer = null;
}

function queueTaskCenterRefresh() {
  clearTimeout(state.taskCenterRefreshTimer);
  state.taskCenterRefreshTimer = setTimeout(() => {
    state.taskCenterRefreshTimer = null;
    void refreshTaskCenter({ silent: true });
  }, 180);
}

function taskCenterRows() {
  const rows = new Map();
  const snapshot = state.taskCenterSnapshot || {};
  const ensureThread = (threadId) => {
    if (!rows.has(threadId)) rows.set(threadId, { kind: "thread", threadId });
    return rows.get(threadId);
  };
  for (const task of snapshot.tasks || []) {
    if (typeof task?.threadId !== "string" || !task.threadId) continue;
    ensureThread(task.threadId).task = task;
  }
  for (const [threadId, task] of state.threadTaskStatuses) {
    ensureThread(threadId).task = task;
  }
  for (const goal of snapshot.goals || []) {
    if (typeof goal?.threadId !== "string" || !goal.threadId) continue;
    if (state.threadGoalTombstones.has(goal.threadId)) continue;
    ensureThread(goal.threadId).goal = goal;
  }
  for (const [threadId, goal] of state.threadGoals) {
    if (goal && !state.threadGoalTombstones.has(threadId)) ensureThread(threadId).goal = goal;
  }
  for (const [threadId, agents] of state.threadSubagents) {
    const statuses = [...agents.values()].map((entry) => normalizeSubagentStatus(entry.status));
    const active = statuses.filter((status) => ["pendingInit", "running"].includes(status)).length;
    const failed = statuses.filter((status) => ["errored", "notFound"].includes(status)).length;
    if (!active && !failed && !rows.has(threadId)) continue;
    ensureThread(threadId).agents = { total: statuses.length, active, failed };
  }
  for (const approval of state.approvals) {
    const threadId = typeof approval?.params?.threadId === "string" ? approval.params.threadId : null;
    if (threadId) ensureThread(threadId).approval = true;
  }
  for (const background of snapshot.backgroundTasks || []) {
    const runningThreadId = typeof background.currentThreadId === "string"
      ? background.currentThreadId
      : null;
    if (runningThreadId && rows.has(runningThreadId)) {
      rows.get(runningThreadId).background = background;
      continue;
    }
    rows.set(`background:${background.id}`, { kind: "background", background });
  }
  for (const session of snapshot.claudeSessions || []) {
    if (typeof session?.id !== "string" || !session.id) continue;
    rows.set(`claude:${session.id}`, { kind: "claude", claude: session });
  }
  for (const agent of snapshot.claudeBackgroundTasks || []) {
    if (typeof agent?.id !== "string" || !agent.id) continue;
    rows.set(`claude-background:${agent.id}`, { kind: "claudeBackground", claudeBackground: agent });
  }
  return [...rows.values()]
    .map(normalizeTaskCenterRow)
    .sort((left, right) => (
      taskCenterStatusRank(right.status) - taskCenterStatusRank(left.status)
      || (right.updatedAt || 0) - (left.updatedAt || 0)
    ))
    .slice(0, 80);
}

function normalizeTaskCenterRow(row) {
  if (row.kind === "claude") {
    const session = row.claude;
    const retryClass = session.failureClass;
    const status = session.pendingApprovals > 0
      ? "waitingApproval"
      : session.status === "inProgress"
        ? "running"
        : session.status === "stopping"
          ? "stopping"
          : session.status === "paused"
            ? "paused"
            : session.status === "retryWaiting"
              ? ["auth", "quota"].includes(retryClass) ? "waitingAccount" : "retry"
              : session.status === "recoveryPending"
                ? ["runtime-restarted", "process-exit"].includes(session.recoveryReason)
                  ? "disconnected"
                  : "recoveryPending"
                : session.status === "interrupted"
                  ? "interrupted"
                  : "waiting";
    return {
      ...row,
      status,
      title: session.name || `Claude 对话 ${session.id.slice(0, 12)}`,
      sessionId: session.id,
      project: pathBasename(session.projectPath || ""),
      projectPath: session.projectPath || null,
      model: session.model || null,
      providerName: session.provider?.name || null,
      updatedAt: Number(session.lastActivityAt) || Number(session.updatedAt) || 0,
      lastActivityAt: Number(session.lastActivityAt) || Number(session.updatedAt) || null,
      startedAt: Number(session.startedAt) || null,
      nextRetryAt: Number(session.nextRetryAt) || null,
      retryAttempts: Math.max(0, Number(session.retryAttempts) || 0),
      recoveryReason: session.recoveryReason || null,
    };
  }
  if (row.kind === "claudeBackground") {
    const agent = row.claudeBackground;
    const status = agent.state === "failed"
      ? "failed"
      : agent.state === "blocked"
        ? "waitingApproval"
        : ["working", "running"].includes(agent.state)
          ? "running"
          : "waiting";
    return {
      ...row,
      status,
      title: agent.name || `Claude 后台 Agent ${agent.id}`,
      sessionId: agent.sourceSessionId || null,
      project: pathBasename(agent.projectPath || ""),
      projectPath: agent.projectPath || null,
      model: agent.model || null,
      providerName: agent.provider?.name || null,
      updatedAt: Number(agent.updatedAt) || 0,
      lastActivityAt: Number(agent.updatedAt) || null,
      startedAt: Number(agent.startedAt) || Number(agent.createdAt) || null,
      error: agent.state === "failed" ? "Claude 后台 Agent 执行失败" : null,
    };
  }
  if (row.kind === "background") {
    const task = row.background;
    const status = ({
      queued: task.lastError && Number(task.attempts) > 0 ? "retry" : "scheduled",
      starting: "running",
      running: "running",
      cancelling: "stopping",
      uncertain: "recoveryPending",
      paused: "paused",
      completed: "completed",
      failed: "failed",
      cancelled: "interrupted",
      interrupted: "interrupted",
    })[task.status] || "waiting";
    return {
      ...row,
      status,
      title: task.name || "后台计划",
      project: pathBasename(task.projectPath || ""),
      projectPath: task.projectPath || null,
      updatedAt: Number(task.updatedAt) || 0,
      startedAt: Number(task.lastRunAt) || null,
      finishedAt: Number(task.completedAt) || null,
      nextRetryAt: Number(task.nextRunAt) || null,
      error: task.lastError || null,
    };
  }
  const task = row.task || null;
  const goal = row.goal || null;
  const control = state.threadGoalControls.get(row.threadId) || null;
  const manualPauseState = control?.manualPauseState || goal?.manualPauseState || null;
  let status = "completed";
  if (row.approval || task?.status === "waiting") status = "waitingApproval";
  else if (manualPauseState === "pausing") status = "pausing";
  else if (manualPauseState === "paused" || goal?.status === "paused") status = "paused";
  else if (goal?.resumeWhenAvailable && goal?.nextRetryAt) status = "retry";
  else if (goal?.resumeWhenAvailable) status = "waitingAccount";
  else if (task?.status === "queued") status = "queued";
  else if (task?.status === "uncertain") status = "recoveryPending";
  else if (task?.status === "stopping") status = "stopping";
  else if (task?.status === "running" || goal?.status === "active" || row.agents?.active) status = "running";
  else if (goal?.status === "blocked") status = "blocked";
  else if (
    task?.status === "failed"
    || row.agents?.failed
    || ["usageLimited", "budgetLimited"].includes(goal?.status)
  ) status = "failed";
  else if (task?.status === "interrupted") status = "interrupted";
  const thread = taskCenterThread(row.threadId, task?.cwd);
  return {
    ...row,
    status,
    title: thread?.name || `对话 ${row.threadId.slice(0, 12)}`,
    thread,
    project: pathBasename(task?.cwd || thread?.cwd || ""),
    projectPath: task?.cwd || thread?.cwd || null,
    turnId: task?.turnId || row.background?.currentTurnId || null,
    updatedAt: Number(task?.updatedAt) || Number(goal?.observedAt) || 0,
    queuedAt: Number(task?.queuedAt) || null,
    startedAt: Number(task?.startedAt) || null,
    finishedAt: Number(task?.finishedAt) || null,
    nextRetryAt: Number(goal?.nextRetryAt) || null,
    error: goal?.lastError || null,
  };
}

function taskCenterThread(threadId, cwd = null) {
  const known = conversationThreadById(threadId, cwd);
  if (known) return known;
  return cwd ? { id: threadId, cwd, name: `对话 ${threadId.slice(0, 12)}` } : null;
}

function taskCenterStatusRank(status) {
  return {
    waitingApproval: 10,
    waitingAccount: 9,
    disconnected: 8.5,
    recoveryPending: 8.25,
    retry: 8,
    queued: 7.5,
    pausing: 7,
    stopping: 6,
    running: 5,
    paused: 4,
    blocked: 3.5,
    failed: 3,
    interrupted: 2,
    scheduled: 1.5,
    completed: 1,
  }[status] || 0;
}

function taskCenterStatusLabel(status) {
  return {
    waitingApproval: "等待审批",
    waitingAccount: "等待账号",
    disconnected: "断线待恢复",
    recoveryPending: "等待恢复",
    retry: "等待重试",
    queued: "等待执行",
    pausing: "暂停中",
    stopping: "终止中",
    running: "运行中",
    paused: "已暂停",
    blocked: "受阻",
    failed: "失败",
    interrupted: "已终止",
    scheduled: "等待计划",
    completed: "已完成",
  }[status] || "等待";
}

function queueTaskCenterRender() {
  if (state.taskCenterRenderFrame !== null) return;
  state.taskCenterRenderFrame = requestAnimationFrame(() => {
    state.taskCenterRenderFrame = null;
    renderTaskCenterOverview();
  });
}

function renderTaskCenterOverview() {
  const rows = taskCenterRows();
  const active = rows.filter((row) => [
    "waitingApproval", "waitingAccount", "disconnected", "recoveryPending",
    "retry", "queued", "pausing", "stopping", "running",
  ].includes(row.status)).length;
  const paused = rows.filter((row) => row.status === "paused").length;
  const failed = rows.filter((row) => ["failed", "blocked"].includes(row.status)).length;
  const codexAdmission = state.taskCenterSnapshot?.admission;
  const codexCapacity = codexAdmission
    ? `${Number(codexAdmission.active) || 0}/${Number(codexAdmission.maxActive) || 8}`
    : "--";
  elements.backgroundTaskStatus.textContent = active
    ? `任务 ${active} 运行`
    : paused
      ? `任务 ${paused} 暂停`
      : failed ? `任务 ${failed} 异常` : "任务中心";
  if (state.taskCenterTab === "overview") {
    elements.backgroundTaskSummary.textContent = rows.length
      ? `${active} 个活跃 · ${paused} 个暂停 · ${failed} 个异常`
      : "当前没有运行或保留的任务状态。";
  }
  elements.taskCenterMetrics.replaceChildren(
    taskCenterMetric("活跃", active, "running"),
    taskCenterMetric("暂停", paused, "paused"),
    taskCenterMetric("异常", failed, "failed"),
    taskCenterMetric("Codex 并发", codexCapacity, "running"),
    taskCenterMetric("总计", rows.length, "total"),
  );
  elements.taskCenterList.replaceChildren();
  if (!rows.length) {
    const empty = document.createElement("p");
    empty.className = "task-center-empty";
    empty.textContent = "任务将在这里显示；关闭页面不会停止服务器托管的 Goal。";
    elements.taskCenterList.append(empty);
    return;
  }
  for (const row of rows) elements.taskCenterList.append(renderTaskCenterRow(row));
  refreshIcons();
}

function taskCenterMetric(label, value, status) {
  const metric = document.createElement("div");
  metric.dataset.status = status;
  const strong = document.createElement("strong");
  strong.textContent = String(value);
  const span = document.createElement("span");
  span.textContent = label;
  metric.append(strong, span);
  return metric;
}

function renderTaskCenterRow(row) {
  const card = document.createElement("article");
  card.className = "task-center-card";
  card.dataset.status = row.status;
  const heading = document.createElement("div");
  heading.className = "task-center-card-heading";
  const status = document.createElement("span");
  status.className = "task-center-state";
  status.textContent = taskCenterStatusLabel(row.status);
  const title = document.createElement("strong");
  title.textContent = row.title;
  heading.append(status, title);
  const detail = document.createElement("div");
  detail.className = "task-center-card-detail";
  const source = document.createElement("span");
  source.textContent = [
    row.kind === "background"
      ? "Codex 计划任务"
      : row.kind === "claude"
        ? "Claude 前台"
        : row.kind === "claudeBackground"
          ? "Claude 后台 Agent"
          : "Codex 对话",
    row.project || null,
    row.model || null,
    row.providerName || null,
    row.goal ? "Goal" : null,
    row.agents?.total ? `${row.agents.active} / ${row.agents.total} 子代理运行` : null,
  ].filter(Boolean).join(" · ");
  const timing = document.createElement("small");
  timing.textContent = taskCenterTiming(row);
  detail.append(source, timing);
  if (row.error) {
    const error = document.createElement("p");
    error.className = "task-center-card-error";
    error.textContent = row.error;
    detail.append(error);
  }
  const actions = document.createElement("div");
  actions.className = "task-center-card-actions";
  if (row.kind === "thread" && row.threadId && row.status !== "waitingApproval") {
    actions.append(taskCenterActionButton("打开对话", "message-square", () => openTaskCenterThread(row)));
  }
  if (row.status === "waitingApproval" && row.threadId) {
    actions.append(taskCenterActionButton("处理审批", "shield-check", () => openTaskCenterThread(row)));
  }
  if (row.kind === "claude") {
    actions.append(taskCenterActionButton(
      row.status === "waitingApproval" ? "处理审批" : "打开对话",
      row.status === "waitingApproval" ? "shield-check" : "message-square",
      () => openTaskCenterClaudeSession(row),
    ));
  }
  if (row.kind === "claudeBackground") {
    if (row.sessionId) {
      actions.append(taskCenterActionButton(
        "来源对话",
        "message-square",
        () => openTaskCenterClaudeSession(row),
      ));
    }
    actions.append(taskCenterActionButton(
      "查看后台任务",
      "bot",
      () => openTaskCenterClaudeBackground(row),
    ));
  }
  if (["waitingAccount", "retry"].includes(row.status)) {
    actions.append(taskCenterActionButton(
      "账号 / API",
      "settings-2",
      () => openTaskCenterProviderSettings(row.kind === "claude" ? "claude" : "codex"),
    ));
  }
  if (row.goal && row.status === "running") {
    actions.append(taskCenterActionButton(
      "安全暂停",
      "pause",
      () => updateGoalControl("pause", "after-turn", row.threadId),
    ));
  } else if (row.goal && row.status === "paused") {
    actions.append(taskCenterActionButton(
      "继续",
      "play",
      () => updateGoalControl("resume", null, row.threadId),
    ));
  } else if (row.goal?.status === "blocked") {
    actions.append(taskCenterActionButton(
      "重新启动",
      "play",
      () => updateGoalControl("resume", null, row.threadId),
    ));
  }
  if (row.kind === "thread" && row.goal) {
    actions.append(taskCenterActionButton(
      "清除 Goal",
      "trash-2",
      () => clearGoal({ threadId: row.threadId, closeDialog: false }),
      true,
    ));
  }
  if (row.kind === "thread" && row.status === "queued") {
    actions.append(taskCenterActionButton(
      "取消排队",
      "x",
      () => cancelTaskCenterQueuedTurn(row),
      true,
    ));
  }
  if (
    row.kind === "thread"
    && row.turnId
    && ["running", "waitingApproval", "stopping", "recoveryPending"].includes(row.status)
  ) {
    actions.append(taskCenterActionButton(
      "立即终止",
      "square",
      () => terminateTaskCenterTurn(row),
      true,
    ));
  }
  if (row.kind === "claude") {
    if (row.status === "running") {
      actions.append(taskCenterActionButton(
        "安全暂停",
        "pause",
        () => pauseTaskCenterClaudeSession(row),
      ));
    } else if (row.status === "paused") {
      actions.append(taskCenterActionButton(
        "继续",
        "play",
        () => continueTaskCenterClaudeSession(row),
      ));
    }
    if ([
      "running",
      "waitingApproval",
      "waitingAccount",
      "retry",
      "paused",
      "stopping",
      "disconnected",
      "recoveryPending",
      "interrupted",
    ].includes(row.status)) {
      actions.append(taskCenterActionButton(
        "终止",
        "square",
        () => terminateTaskCenterClaudeSession(row),
        true,
      ));
    }
  }
  if (
    row.kind === "claudeBackground"
    && ["running", "waitingApproval"].includes(row.status)
  ) {
    actions.append(taskCenterActionButton(
      "停止",
      "square",
      () => terminateTaskCenterClaudeBackground(row),
      true,
    ));
  }
  if (row.kind === "background") {
    const task = row.background;
    if (["starting", "running", "cancelling"].includes(task.status)) {
      actions.append(taskCenterActionButton(
        "终止",
        "square",
        () => mutateCodexBackgroundTask(task.id, "cancel"),
        true,
      ));
    } else if (task.status === "paused") {
      actions.append(taskCenterActionButton("继续", "play", () => mutateCodexBackgroundTask(task.id, "resume")));
    } else if (task.enabled) {
      actions.append(taskCenterActionButton("暂停计划", "pause", () => mutateCodexBackgroundTask(task.id, "pause")));
    }
  }
  card.append(heading, detail, actions);
  return card;
}

function taskCenterTiming(row) {
  const now = Date.now();
  if (row.status === "queued" && row.queuedAt) {
    return `已排队 ${formatTaskDuration(now - row.queuedAt)}`;
  }
  if ([
    "running",
    "waitingApproval",
    "disconnected",
    "recoveryPending",
    "pausing",
    "stopping",
  ].includes(row.status) && row.startedAt) {
    return [
      `已运行 ${formatTaskDuration(now - row.startedAt)}`,
      row.lastActivityAt ? `最近活动 ${formatTaskClock(row.lastActivityAt)}` : null,
    ].filter(Boolean).join(" · ");
  }
  if (row.status === "retry" && row.nextRetryAt) {
    const retries = row.kind === "background"
      ? Math.max(0, Number(row.background?.attempts) || 0)
      : row.kind === "claude"
        ? row.retryAttempts
        : Math.max(0, Number(row.goal?.retryAttempts) || 0);
    return `已重试 ${retries} 次 · 下次 ${relativeTime(row.nextRetryAt / 1_000)}`;
  }
  if (row.goal && Number.isFinite(Number(row.goal.timeUsedSeconds))) {
    return `累计 ${formatGoalDuration(row.goal.timeUsedSeconds)}`;
  }
  if (row.finishedAt) return `完成于 ${formatTaskClock(row.finishedAt)}`;
  if (row.nextRetryAt) return `下次 ${backgroundTaskDate(row.nextRetryAt)} UTC`;
  return row.updatedAt ? `更新于 ${formatTaskClock(row.updatedAt)}` : "状态已同步";
}

function taskCenterActionButton(label, icon, action, danger = false) {
  const button = document.createElement("button");
  button.type = "button";
  button.className = `secondary-button${danger ? " danger-button" : ""}`;
  button.innerHTML = `<i data-lucide="${icon}"></i><span></span>`;
  button.querySelector("span").textContent = label;
  button.addEventListener("click", async () => {
    button.disabled = true;
    try {
      await action();
      await refreshTaskCenter({ silent: true });
    } catch (error) {
      toast(error.message || "任务操作失败", "error");
    } finally {
      if (button.isConnected) button.disabled = false;
    }
  });
  return button;
}

async function openTaskCenterThread(row) {
  if (!row?.threadId) return;
  let thread = row.thread || null;
  if (!thread) {
    const result = await rpc("thread/read", {
      threadId: row.threadId,
      includeTurns: false,
    }, { timeoutMs: THREAD_READ_RPC_TIMEOUT_MS });
    thread = result?.thread || null;
  }
  if (!thread?.id) throw new Error("当前任务对应的对话无法读取");
  if (!thread.cwd) {
    thread = {
      ...thread,
      cwd: row.projectPath || state.currentProject?.path || null,
    };
  }
  if (!thread.cwd) throw new Error("当前任务没有可用的工程窗口");
  elements.backgroundTaskDrawer.close();
  await resumeThread(thread);
  if (row.status === "waitingApproval") synchronizeApprovalView();
}

async function openTaskCenterClaudeSession(row) {
  if (!row.sessionId) return;
  const project = state.projects.find((entry) => entry.path === row.projectPath);
  if (!project) {
    toast("Claude 任务所属工程当前不可用", "error");
    return;
  }
  elements.backgroundTaskDrawer.close();
  if (project.path !== state.currentProject?.path) {
    await selectProject(project);
    if (state.currentProject?.path !== project.path) return;
  }
  if (state.runtime !== "claude") await switchRuntime("claude");
  if (state.runtime !== "claude") return;
  await resumeClaudeSession({ id: row.sessionId });
  if (row.kind === "claude" && row.status === "waitingApproval") synchronizeApprovalView();
}

async function openTaskCenterClaudeBackground(row) {
  const project = state.projects.find((entry) => entry.path === row.projectPath);
  if (!project) {
    toast("Claude 后台任务所属工程当前不可用", "error");
    return;
  }
  elements.backgroundTaskDrawer.close();
  if (project.path !== state.currentProject?.path) {
    await selectProject(project);
    if (state.currentProject?.path !== project.path) return;
  }
  if (state.runtime !== "claude") await switchRuntime("claude");
  if (state.runtime !== "claude") return;
  await openClaudeDialog();
  selectClaudeSettingsTab("background");
}

async function openTaskCenterProviderSettings(runtime = "codex") {
  elements.backgroundTaskDrawer.close();
  state.providerDialogRuntime = runtime;
  await openProviderDialog();
}

async function pauseTaskCenterClaudeSession(row) {
  if (!row.sessionId) return;
  await rpc("claude/turn/pause", { sessionId: row.sessionId, mode: "after-turn" });
  toast("Claude 将在本轮安全边界暂停");
}

async function continueTaskCenterClaudeSession(row) {
  if (!row.sessionId) return;
  await rpc("claude/turn/continue", { sessionId: row.sessionId });
  toast("Claude 任务已继续");
}

async function terminateTaskCenterClaudeSession(row) {
  if (!row.sessionId) return;
  if (!confirm("终止这个 Claude 任务？\n\n已经完成的输出会保留，尚未保存的部分可能丢失。")) return;
  if (["disconnected", "recoveryPending", "interrupted"].includes(row.status)) {
    await rpc("claude/turn/recover", { sessionId: row.sessionId, action: "dismiss" });
  } else {
    await rpc("claude/turn/interrupt", { sessionId: row.sessionId });
  }
  toast("Claude 任务已终止");
}

async function terminateTaskCenterClaudeBackground(row) {
  const id = row.claudeBackground?.id;
  if (!id || !confirm(`停止 Claude 后台任务“${row.title}”？`)) return;
  const response = await fetchWithTimeout(
    `/api/claude/background-agents/${encodeURIComponent(id)}/stop`,
    {
      method: "POST",
      headers: { "X-Codex-Desktop-Action": "claude-background-stop" },
    },
    25_000,
  );
  await readApiJson(response, "Claude 后台任务停止失败");
  toast("Claude 后台任务已停止");
}

async function terminateTaskCenterTurn(row) {
  if (!row.threadId || !row.turnId) return;
  if (!confirm("立即终止这个对话的当前任务？\n\n已经完成的输出会保留，尚未保存的部分可能丢失。")) return;
  const result = await rpc("turn/interrupt", { threadId: row.threadId, turnId: row.turnId });
  const returnedTaskIsInactive = Boolean(
    result?.taskStatus
    && !ACTIVE_TASK_STATUSES.has(result.taskStatus.status),
  );
  if (
    result?.confirmedInactive === true
    && result?.nativeVerified === true
    && result?.goalPauseConfirmed === true
    && result?.settlementEvidence !== "notification-terminal"
    && returnedTaskIsInactive
  ) {
    toast("已向 Codex 核实任务已结束，遗留状态已清理");
  } else if (result?.goalPauseConfirmed === false && result?.goalPausePending !== true) {
    toast("终止请求已送达，但 Goal 尚未确认暂停，正在刷新实际状态", "warning");
  } else if (result?.stale || result?.goalPausePending === true) {
    toast("终止请求已送达，正在核实实际任务和 Goal 状态");
  } else if (result?.reconciled) toast("已找到原生任务并发送终止请求");
  else toast("已发送终止请求");
  void refreshTaskCenter({ silent: true });
  scheduleTaskCenterInterruptRefresh(row.threadId);
}

function scheduleTaskCenterInterruptRefresh(threadId) {
  if (!threadId) return;
  for (const delay of [250, 1_000, 2_500]) {
    const timer = setTimeout(() => {
      if (elements.backgroundTaskDrawer.open) void refreshTaskCenter({ silent: true });
    }, delay);
    timer.unref?.();
  }
}

async function cancelTaskCenterQueuedTurn(row) {
  if (!row.threadId) return;
  if (!confirm("取消这个尚未发送的排队任务？")) return;
  const response = await fetchWithTimeout("/api/task/admission/cancel", {
    method: "POST",
    headers: {
      "Content-Type": "application/json",
      "X-Codex-Desktop-Action": "task-admission-cancel",
    },
    body: JSON.stringify({ threadId: row.threadId }),
  });
  await readApiJson(response, "取消排队任务失败");
  toast("排队任务已取消，未发送给 Codex");
}

function populateBackgroundTaskModels() {
  const previous = elements.backgroundTaskModelInput.value;
  elements.backgroundTaskModelInput.replaceChildren(new Option("跟随当前设置", ""));
  for (const model of state.models) {
    const option = new Option(model.displayName || model.model, model.model);
    option.title = [model.model, model.description].filter(Boolean).join(" · ");
    elements.backgroundTaskModelInput.add(option);
  }
  if ([...elements.backgroundTaskModelInput.options].some((option) => option.value === previous)) {
    elements.backgroundTaskModelInput.value = previous;
  }
}

function renderBackgroundTaskForm() {
  const kind = elements.backgroundTaskScheduleKindInput.value;
  elements.backgroundTaskOnceField.hidden = kind !== "once";
  elements.backgroundTaskIntervalField.hidden = kind !== "interval";
  elements.backgroundTaskClockField.hidden = !["daily", "weekly"].includes(kind);
  elements.backgroundTaskWeekdayField.hidden = kind !== "weekly";
  elements.backgroundTaskRruleField.hidden = kind !== "rrule";
  const existingOption = [...elements.backgroundTaskDestinationInput.options]
    .find((option) => option.value === "existingThread");
  if (existingOption) existingOption.disabled = state.runtime !== "codex" || !state.activeThread;
  if (existingOption?.disabled && elements.backgroundTaskDestinationInput.value === "existingThread") {
    elements.backgroundTaskDestinationInput.value = "newThread";
  }
  const existing = elements.backgroundTaskDestinationInput.value === "existingThread";
  elements.backgroundTaskWorkspaceInput.disabled = existing;
  if (existing) elements.backgroundTaskWorkspaceInput.value = "local";
  elements.backgroundTaskMaxAttemptsField.hidden = elements.backgroundTaskInfiniteRetryInput.checked;
  elements.backgroundTaskRunNowInput.disabled = kind === "manual";
  if (kind === "manual") elements.backgroundTaskRunNowInput.checked = true;
}

function backgroundTaskScheduleDraft() {
  const kind = elements.backgroundTaskScheduleKindInput.value;
  if (kind === "manual") return { kind };
  if (kind === "once") {
    const value = elements.backgroundTaskOnceInput.value;
    const at = Date.parse(`${value}Z`);
    if (!value || !Number.isFinite(at)) throw new Error("请选择有效的 UTC 执行时间");
    return { kind, at };
  }
  if (kind === "interval") {
    const minutes = Number(elements.backgroundTaskIntervalInput.value);
    if (!Number.isInteger(minutes) || minutes < 1 || minutes > 43_200) {
      throw new Error("任务间隔必须为 1–43200 分钟");
    }
    return { kind, intervalMs: minutes * 60_000 };
  }
  if (kind === "daily") {
    return { kind, time: elements.backgroundTaskClockInput.value || "09:00" };
  }
  if (kind === "weekly") {
    return {
      kind,
      time: elements.backgroundTaskClockInput.value || "09:00",
      weekdays: [Number(elements.backgroundTaskWeekdayInput.value)],
    };
  }
  const rrule = elements.backgroundTaskRruleInput.value.trim();
  if (!rrule) throw new Error("请输入 RRULE");
  return { kind: "rrule", rrule };
}

async function createCodexBackgroundTask(event) {
  event.preventDefault();
  if (!state.currentProject || state.runtime !== "codex") return;
  const destination = elements.backgroundTaskDestinationInput.value;
  if (destination === "existingThread" && !state.activeThread?.id) {
    elements.backgroundTaskError.textContent = "继续当前对话需要先选择一个原生 Codex 对话";
    return;
  }
  elements.backgroundTaskCreateButton.disabled = true;
  elements.backgroundTaskError.textContent = "";
  try {
    const body = {
      name: elements.backgroundTaskNameInput.value.trim(),
      prompt: elements.backgroundTaskPromptInput.value.trim(),
      projectPath: state.currentProject.path,
      destination,
      threadId: destination === "existingThread" ? state.activeThread.id : null,
      workspaceMode: destination === "existingThread"
        ? "local"
        : elements.backgroundTaskWorkspaceInput.value,
      baseRef: "HEAD",
      includeUncommitted: true,
      model: elements.backgroundTaskModelInput.value || null,
      effort: elements.backgroundTaskEffortInput.value,
      sandbox: elements.backgroundTaskSandboxInput.value,
      approvalPolicy: "never",
      schedule: backgroundTaskScheduleDraft(),
      runNow: elements.backgroundTaskRunNowInput.checked,
      infiniteRetry: elements.backgroundTaskInfiniteRetryInput.checked,
      maxAttempts: Number(elements.backgroundTaskMaxAttemptsInput.value),
      retryBackoff: elements.backgroundTaskRetryBackoffInput.value,
    };
    const response = await fetchWithTimeout("/api/codex/background-tasks", {
      method: "POST",
      headers: {
        "Content-Type": "application/json",
        "X-Codex-Desktop-Action": "codex-background-create",
      },
      body: JSON.stringify(body),
    }, 20_000);
    const result = await readApiJson(response, "无法创建 Codex 后台任务");
    state.codexBackgroundSelectedTask = result.task;
    elements.backgroundTaskPromptInput.value = "";
    elements.backgroundTaskNameInput.value = "";
    await loadCodexBackgroundTasks({ force: true, silent: true });
    renderCodexBackgroundTaskDetail();
    toast("Codex 后台任务已创建");
  } catch (error) {
    elements.backgroundTaskError.textContent = error.message;
  } finally {
    elements.backgroundTaskCreateButton.disabled = false;
  }
}

async function loadCodexBackgroundTasks({ force = false, silent = false } = {}) {
  if (!canUseCodexBackground() || state.codexBackgroundLoading) return;
  if (!force && state.codexBackgroundSummary) {
    renderCodexBackgroundTasks();
    return;
  }
  state.codexBackgroundLoading = true;
  elements.backgroundTaskRefreshButton.disabled = true;
  if (!silent) renderCodexBackgroundTasks();
  try {
    const response = await fetchWithTimeout(
      `/api/codex/background-tasks?_=${Date.now()}`,
      { cache: "no-store" },
      15_000,
    );
    const result = await readApiJson(response, "无法读取 Codex 后台任务");
    state.codexBackgroundTasks = Array.isArray(result.tasks) ? result.tasks : [];
    state.codexBackgroundSummary = result.summary || null;
    state.taskCenterSnapshot = {
      ...(state.taskCenterSnapshot || { observedAt: Date.now(), tasks: [], goals: [] }),
      backgroundAllowed: true,
      backgroundTasks: state.codexBackgroundTasks,
    };
    const selectedId = state.codexBackgroundSelectedTask?.id;
    if (selectedId && !state.codexBackgroundTasks.some((task) => task.id === selectedId)) {
      state.codexBackgroundSelectedTask = null;
    }
    renderCodexBackgroundTasks();
    renderTaskCenterOverview();
    if (selectedId && state.codexBackgroundSelectedTask) {
      await loadCodexBackgroundTaskDetail(selectedId, { silent: true });
    }
  } catch (error) {
    if (!silent) {
      elements.backgroundTaskList.replaceChildren();
      const message = document.createElement("p");
      message.textContent = error.message;
      elements.backgroundTaskList.append(message);
    }
  } finally {
    state.codexBackgroundLoading = false;
    elements.backgroundTaskRefreshButton.disabled = false;
  }
}

function renderCodexBackgroundTasks() {
  const tasks = state.codexBackgroundTasks;
  const active = tasks.filter((task) =>
    ["starting", "running", "cancelling", "uncertain"].includes(task.status)).length;
  const queued = tasks.filter((task) => task.status === "queued").length;
  elements.backgroundTaskCount.textContent = `${tasks.length} 个任务`;
  if (state.taskCenterTab === "schedules") {
    elements.backgroundTaskSummary.textContent = [
      active ? `${active} 个运行中` : null,
      queued ? `${queued} 个等待` : null,
      state.codexBackgroundSummary?.nextRunAt
        ? `下次 ${backgroundTaskDate(state.codexBackgroundSummary.nextRunAt)} UTC`
        : null,
    ].filter(Boolean).join(" · ") || "任务由服务器持久调度，关闭网页后仍会继续。";
  }
  elements.backgroundTaskList.replaceChildren();
  if (state.codexBackgroundLoading && !tasks.length) {
    const loading = document.createElement("p");
    loading.textContent = "正在读取后台任务…";
    elements.backgroundTaskList.append(loading);
    return;
  }
  if (!tasks.length) {
    const empty = document.createElement("p");
    empty.textContent = "还没有后台任务。";
    elements.backgroundTaskList.append(empty);
    elements.backgroundTaskDetail.hidden = true;
    return;
  }
  for (const task of tasks) {
    const card = document.createElement("article");
    card.className = "background-task-card";
    card.dataset.status = task.status;
    card.dataset.selected = String(task.id === state.codexBackgroundSelectedTask?.id);
    const copy = document.createElement("button");
    copy.type = "button";
    copy.className = "background-task-card-copy";
    const title = document.createElement("strong");
    title.textContent = task.name;
    const preview = document.createElement("span");
    preview.textContent = task.promptPreview || "后台任务";
    const meta = document.createElement("small");
    meta.textContent = [
      backgroundTaskStatusLabel(task.status),
      backgroundTaskScheduleLabel(task.schedule),
      task.infiniteRetry ? `无限重试 · ${backgroundTaskRetryLabel(task.retryBackoff)}` : `${task.maxAttempts} 次尝试`,
      task.nextRunAt ? `下次 ${backgroundTaskDate(task.nextRunAt)} UTC` : null,
    ].filter(Boolean).join(" · ");
    copy.append(title, preview, meta);
    copy.addEventListener("click", () => loadCodexBackgroundTaskDetail(task.id));
    const actions = document.createElement("div");
    actions.className = "background-task-card-actions";
    if (["starting", "running", "cancelling", "uncertain"].includes(task.status)) {
      actions.append(backgroundTaskActionButton("终止", "square", () => mutateCodexBackgroundTask(task.id, "cancel"), true));
    } else if (task.status === "paused") {
      actions.append(backgroundTaskActionButton("恢复", "play", () => mutateCodexBackgroundTask(task.id, "resume")));
    } else {
      actions.append(backgroundTaskActionButton("立即运行", "play", () => mutateCodexBackgroundTask(task.id, "runNow")));
      if (task.enabled) {
        actions.append(backgroundTaskActionButton("暂停", "pause", () => mutateCodexBackgroundTask(task.id, "pause")));
      }
    }
    card.append(copy, actions);
    elements.backgroundTaskList.append(card);
  }
  renderCodexBackgroundTaskDetail();
  refreshIcons();
}

function backgroundTaskActionButton(label, icon, action, danger = false) {
  const button = document.createElement("button");
  button.type = "button";
  button.className = `secondary-button${danger ? " danger-button" : ""}`;
  button.innerHTML = `<i data-lucide="${icon}"></i><span></span>`;
  button.querySelector("span").textContent = label;
  button.addEventListener("click", async (event) => {
    event.stopPropagation();
    button.disabled = true;
    try {
      await action();
    } finally {
      if (button.isConnected) button.disabled = false;
    }
  });
  return button;
}

async function loadCodexBackgroundTaskDetail(taskId, { silent = false } = {}) {
  try {
    const response = await fetchWithTimeout(
      `/api/codex/background-tasks/${encodeURIComponent(taskId)}?_=${Date.now()}`,
      { cache: "no-store" },
      15_000,
    );
    const result = await readApiJson(response, "无法读取后台任务详情");
    state.codexBackgroundSelectedTask = result.task;
    renderCodexBackgroundTasks();
  } catch (error) {
    if (!silent) toast(error.message, "error");
  }
}

function renderCodexBackgroundTaskDetail() {
  const task = state.codexBackgroundSelectedTask;
  elements.backgroundTaskDetail.replaceChildren();
  elements.backgroundTaskDetail.hidden = !task;
  if (!task) return;
  const header = document.createElement("header");
  const heading = document.createElement("div");
  const title = document.createElement("strong");
  title.textContent = task.name;
  const description = document.createElement("span");
  description.textContent = `${backgroundTaskStatusLabel(task.status)} · ${task.projectPath}`;
  heading.append(title, description);
  const close = document.createElement("button");
  close.type = "button";
  close.className = "icon-button";
  close.setAttribute("aria-label", "关闭任务详情");
  close.innerHTML = '<i data-lucide="x"></i>';
  close.addEventListener("click", () => {
    state.codexBackgroundSelectedTask = null;
    renderCodexBackgroundTasks();
  });
  header.append(heading, close);

  const prompt = document.createElement("p");
  prompt.className = "background-task-prompt";
  prompt.textContent = task.prompt || task.promptPreview;

  const retry = document.createElement("div");
  retry.className = "background-task-retry-settings";
  const infinite = document.createElement("label");
  const infiniteInput = document.createElement("input");
  infiniteInput.type = "checkbox";
  infiniteInput.checked = task.infiniteRetry === true;
  infinite.append(infiniteInput, document.createTextNode("无限重试"));
  const frequency = document.createElement("select");
  for (const [value, label] of [["fast", "快速"], ["balanced", "均衡"], ["patient", "耐心"]]) {
    frequency.add(new Option(label, value));
  }
  frequency.value = task.retryBackoff || "balanced";
  const attempts = document.createElement("input");
  attempts.type = "number";
  attempts.min = "1";
  attempts.max = "20";
  attempts.value = String(task.maxAttempts || 3);
  attempts.disabled = infiniteInput.checked;
  infiniteInput.addEventListener("change", () => { attempts.disabled = infiniteInput.checked; });
  const saveRetry = document.createElement("button");
  saveRetry.type = "button";
  saveRetry.className = "secondary-button";
  saveRetry.textContent = "保存重试设置";
  saveRetry.addEventListener("click", async () => {
    saveRetry.disabled = true;
    try {
      await mutateCodexBackgroundTask(task.id, "retrySettings", {
        infiniteRetry: infiniteInput.checked,
        retryBackoff: frequency.value,
        maxAttempts: Number(attempts.value),
      });
    } finally {
      saveRetry.disabled = false;
    }
  });
  retry.append(infinite, frequency, attempts, saveRetry);

  const actions = document.createElement("div");
  actions.className = "background-task-detail-actions";
  const threadId = task.currentThreadId || task.runs?.find((run) => run.threadId)?.threadId;
  if (threadId) {
    actions.append(backgroundTaskActionButton("打开对话", "message-square", async () => {
      elements.backgroundTaskDrawer.close();
      await resumeThread({ id: threadId, name: task.name });
    }));
  }
  actions.append(backgroundTaskActionButton("删除", "trash-2", () => deleteCodexBackgroundTask(task), true));

  const historyTitle = document.createElement("h4");
  historyTitle.textContent = "运行历史";
  const history = document.createElement("div");
  history.className = "background-task-runs";
  if (!task.runs?.length) {
    const empty = document.createElement("p");
    empty.textContent = "尚未运行。";
    history.append(empty);
  } else {
    for (const run of task.runs) {
      const row = document.createElement("div");
      const status = document.createElement("strong");
      status.textContent = `${backgroundTaskStatusLabel(run.status)} · 第 ${run.attempt} 次`;
      const meta = document.createElement("span");
      meta.textContent = [
        backgroundTaskDate(run.startedAt),
        run.threadId ? `对话 ${run.threadId.slice(0, 12)}` : null,
        run.error,
      ].filter(Boolean).join(" · ");
      row.append(status, meta);
      history.append(row);
    }
  }
  elements.backgroundTaskDetail.append(header, prompt, retry, actions, historyTitle, history);
  refreshIcons();
}

async function mutateCodexBackgroundTask(taskId, action, extra = {}) {
  try {
    const response = await fetchWithTimeout(
      `/api/codex/background-tasks/${encodeURIComponent(taskId)}/action`,
      {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
          "X-Codex-Desktop-Action": "codex-background-action",
        },
        body: JSON.stringify({ action, ...extra }),
      },
      20_000,
    );
    const result = await readApiJson(response, "无法更新 Codex 后台任务");
    state.codexBackgroundSelectedTask = result.task;
    await loadCodexBackgroundTasks({ force: true, silent: true });
  } catch (error) {
    toast(error.message, "error");
  }
}

async function deleteCodexBackgroundTask(task) {
  if (!window.confirm(`删除后台任务“${task.name}”？运行历史也会删除。`)) return;
  try {
    const response = await fetchWithTimeout(
      `/api/codex/background-tasks/${encodeURIComponent(task.id)}`,
      {
        method: "DELETE",
        headers: {
          "Content-Type": "application/json",
          "X-Codex-Desktop-Action": "codex-background-delete",
        },
        body: JSON.stringify({ confirmation: task.id }),
      },
      20_000,
    );
    if (!response.ok) await readApiJson(response, "无法删除 Codex 后台任务");
    state.codexBackgroundSelectedTask = null;
    await loadCodexBackgroundTasks({ force: true, silent: true });
    toast("后台任务已删除");
  } catch (error) {
    toast(error.message, "error");
  }
}

function backgroundTaskStatusLabel(status) {
  return ({
    queued: "等待执行",
    starting: "正在启动",
    running: "运行中",
    cancelling: "正在终止",
    uncertain: "等待权威确认",
    paused: "已暂停",
    completed: "已完成",
    failed: "失败",
    cancelled: "已取消",
    interrupted: "连接中断",
  })[status] || status || "未知";
}

function backgroundTaskRetryLabel(backoff) {
  return ({ fast: "快速", balanced: "均衡", patient: "耐心" })[backoff] || "均衡";
}

function backgroundTaskScheduleLabel(schedule = {}) {
  if (schedule.kind === "once") return `单次 ${backgroundTaskDate(schedule.at)} UTC`;
  if (schedule.kind === "interval") return `每 ${Math.round(schedule.intervalMs / 60_000)} 分钟`;
  if (schedule.kind === "daily") return `每天 ${schedule.time?.value || "09:00"} UTC`;
  if (schedule.kind === "weekly") return `每周 ${schedule.time?.value || "09:00"} UTC`;
  if (schedule.kind === "rrule") return schedule.rrule || "RRULE";
  return "手动";
}

function backgroundTaskDate(timestamp) {
  if (!Number.isFinite(Number(timestamp))) return "--";
  return new Date(Number(timestamp)).toISOString().slice(0, 16).replace("T", " ");
}

async function openGitDrawer() {
  if (!state.currentProject) {
    toast("请先选择工程", "error");
    return;
  }
  elements.gitDrawerTitle.textContent = state.currentProject.name || pathBasename(state.currentProject.path);
  elements.gitRemoteTab.hidden = !canUseCodexRemoteDiff();
  if (state.gitTab === "remote" && !canUseCodexRemoteDiff()) state.gitTab = "changes";
  selectGitTab(state.gitTab);
  updateGitReviewTarget();
  if (!elements.gitDrawer.open) elements.gitDrawer.showModal();
  await loadGitStatus({ preserveSelection: true });
}

function selectGitTab(tab) {
  state.gitTab = ["changes", "review", "remote", "history"].includes(tab) ? tab : "changes";
  if (state.gitTab === "remote" && !canUseCodexRemoteDiff()) state.gitTab = "changes";
  const entries = [
    ["changes", elements.gitChangesTab, elements.gitChangesPanel],
    ["review", elements.gitReviewTab, elements.gitReviewPanel],
    ["remote", elements.gitRemoteTab, elements.gitRemotePanel],
    ["history", elements.gitHistoryTab, elements.gitHistoryPanel],
  ];
  for (const [value, button, panel] of entries) {
    const active = value === state.gitTab;
    button.setAttribute("aria-selected", String(active));
    panel.hidden = !active;
  }
}

async function refreshGitDrawer() {
  await loadGitStatus({ preserveSelection: true });
  if (state.gitTab === "remote" && canUseCodexRemoteDiff()) {
    await loadGitRemoteDiff({ useSelection: true });
  }
}

async function loadGitStatus({ preserveSelection = false } = {}) {
  if (!state.currentProject || state.gitLoading) return;
  const projectPath = state.currentProject.path;
  state.gitLoading = true;
  elements.gitRefreshButton.disabled = true;
  elements.gitRefreshButton.classList.add("refreshing");
  try {
    const url = new URL("/api/git/status", location.origin);
    url.searchParams.set("project", projectPath);
    url.searchParams.set("_", Date.now());
    const response = await fetch(url, { cache: "no-store" });
    const snapshot = await readApiJson(response, "无法读取 Git 状态");
    if (state.currentProject?.path !== projectPath) return;
    state.gitSnapshot = snapshot;
    if (!preserveSelection || !gitSelectionExists(state.gitSelectedChange, snapshot)) {
      state.gitSelectedChange = null;
      state.gitDiff = null;
    }
    renderGitSnapshot();
    void syncActiveThreadGitMetadata(snapshot, projectPath);
    if (state.gitSelectedChange) await loadGitDiff(state.gitSelectedChange);
  } catch (error) {
    elements.gitDrawerSummary.textContent = error.message;
    if (elements.gitDrawer.open) toast(error.message, "error");
  } finally {
    state.gitLoading = false;
    elements.gitRefreshButton.disabled = false;
    elements.gitRefreshButton.classList.remove("refreshing");
  }
}

async function syncActiveThreadGitMetadata(snapshot, projectPath) {
  const thread = state.activeThread;
  if (
    state.runtime !== "codex"
    || !thread?.id
    || thread.imported === true
    || thread.cwd !== projectPath
    || !state.bridgeReady
  ) return;
  const gitInfo = snapshot?.repository
    ? {
      sha: typeof (snapshot.oid || snapshot.sha) === "string" && (snapshot.oid || snapshot.sha)
        ? (snapshot.oid || snapshot.sha)
        : null,
      branch: snapshot.detached !== true && typeof snapshot.branch === "string" && snapshot.branch
        ? snapshot.branch
        : null,
      originUrl: typeof snapshot.originUrl === "string" && snapshot.originUrl
        ? snapshot.originUrl
        : null,
    }
    : null;
  const key = JSON.stringify(gitInfo);
  const currentKey = JSON.stringify(thread.gitInfo || null);
  if (key === currentKey || state.threadMetadataSyncKeys.get(thread.id) === key) return;
  state.threadMetadataSyncKeys.set(thread.id, key);
  try {
    const result = await rpc("thread/metadata/update", {
      threadId: thread.id,
      gitInfo,
    }, { timeoutMs: 15_000 });
    if (state.activeThread?.id === thread.id && result?.thread) {
      replaceActiveConversationThread({
        ...state.activeThread,
        ...result.thread,
        turns: state.activeThread.turns || [],
      });
      state.threads = state.threads.map((entry) =>
        entry.id === thread.id ? { ...entry, ...result.thread, turns: entry.turns || [] } : entry);
      renderThreads();
    }
  } catch (error) {
    if (state.threadMetadataSyncKeys.get(thread.id) === key) {
      state.threadMetadataSyncKeys.delete(thread.id);
    }
    console.error(`Unable to synchronize Git metadata for ${thread.id}:`, error);
  }
}

async function syncActiveThreadGitMetadataFromServer(thread = state.activeThread) {
  if (
    state.runtime !== "codex"
    || !thread?.id
    || !thread.cwd
    || thread.imported === true
    || !state.bridgeReady
  ) return;
  try {
    const url = new URL("/api/git/metadata", location.origin);
    url.searchParams.set("project", thread.cwd);
    url.searchParams.set("_", Date.now());
    const response = await fetch(url, { cache: "no-store" });
    const metadata = await readApiJson(response, "无法读取 Git 元数据");
    if (state.activeThread?.id !== thread.id) return;
    await syncActiveThreadGitMetadata(metadata, thread.cwd);
  } catch (error) {
    console.error(`Unable to inspect Git metadata for ${thread.id}:`, error);
  }
}

function gitSelectionExists(selection, snapshot) {
  if (!selection || !snapshot?.repository) return false;
  if (["commit", "base"].includes(selection.scope)) return true;
  return (snapshot[selection.scope] || []).some((file) => file.path === selection.path);
}

function renderGitSnapshot() {
  const snapshot = state.gitSnapshot;
  if (!snapshot?.repository) {
    elements.gitDrawerSummary.textContent = "当前工程不是 Git 仓库";
    elements.gitStatus.textContent = "普通目录";
    elements.gitChangeGroups.innerHTML = '<div class="list-empty">当前工程没有 Git 仓库</div>';
    elements.gitCurrentBranch.textContent = "--";
    elements.gitBranchList.innerHTML = '<div class="list-empty">没有本地分支</div>';
    elements.gitCommitList.innerHTML = '<div class="list-empty">没有提交记录</div>';
    setGitMutationButtonsDisabled(true);
    elements.gitStartReviewButton.disabled = state.runtime !== "codex" || !state.activeThread || conversationBusy();
    elements.gitRemoteReviewButton.disabled = true;
    return;
  }
  const changed = snapshot.files.length;
  const branch = snapshot.branch || (snapshot.detached ? `detached @ ${snapshot.oid?.slice(0, 8) || "--"}` : "未命名分支");
  elements.gitDrawerSummary.textContent = `${branch} · ${changed} 个改动 · ahead ${snapshot.ahead || 0} / behind ${snapshot.behind || 0}`;
  elements.gitStatus.textContent = changed ? `${branch} · ${changed}` : branch;
  elements.gitCurrentBranch.textContent = branch;
  elements.gitChangeGroups.replaceChildren(
    renderGitChangeGroup("staged", "Staged · 已暂存", snapshot.staged),
    renderGitChangeGroup("unstaged", "Unstaged · 未暂存", snapshot.unstaged),
    renderGitChangeGroup("untracked", "Untracked · 未跟踪", snapshot.untracked),
  );
  setGitMutationButtonsDisabled(snapshot.writable === false || state.gitLoading);
  elements.gitStartReviewButton.disabled = state.runtime !== "codex" || !state.activeThread || conversationBusy();
  elements.gitRemoteReviewButton.disabled = !canStartRemoteGitReview();
  renderGitHistory(snapshot);
  renderGitDiffActions();
  refreshIcons();
}

function renderGitChangeGroup(scope, title, files) {
  const section = document.createElement("section");
  section.className = "git-change-group";
  const header = document.createElement("header");
  const heading = document.createElement("strong");
  heading.textContent = title;
  const count = document.createElement("span");
  count.textContent = String(files.length);
  header.append(heading, count);
  const list = document.createElement("div");
  list.className = "git-change-list";
  if (!files.length) {
    const empty = document.createElement("div");
    empty.className = "list-empty";
    empty.textContent = "无";
    list.append(empty);
  }
  for (const file of files) {
    const row = document.createElement("button");
    row.type = "button";
    row.className = `git-file-row${state.gitSelectedChange?.scope === scope && state.gitSelectedChange.path === file.path ? " active" : ""}`;
    const status = document.createElement("span");
    status.className = "git-file-status";
    status.textContent = file.untracked ? "?" : scope === "staged" ? file.indexStatus : file.worktreeStatus;
    const name = document.createElement("code");
    name.textContent = file.path;
    const action = document.createElement("span");
    action.textContent = "查看";
    row.append(status, name, action);
    row.addEventListener("click", () => selectGitChange(scope, file.path));
    list.append(row);
  }
  section.append(header, list);
  return section;
}

async function selectGitChange(scope, filePath) {
  state.gitSelectedChange = { scope, path: filePath, ref: null };
  renderGitSnapshot();
  await loadGitDiff(state.gitSelectedChange);
}

async function showGitReferenceDiff(scope, ref, title) {
  state.gitSelectedChange = { scope, path: null, ref, title };
  selectGitTab("changes");
  renderGitSnapshot();
  await loadGitDiff(state.gitSelectedChange);
}

async function loadGitDiff(selection) {
  if (!selection || !state.currentProject) return;
  elements.gitDiffScope.textContent = selection.scope.toUpperCase();
  elements.gitDiffTitle.textContent = selection.title || selection.path || selection.ref || "Diff";
  elements.gitDiffContent.innerHTML = "<p>正在读取差异…</p>";
  renderGitDiffActions();
  try {
    const url = new URL("/api/git/diff", location.origin);
    url.searchParams.set("project", state.currentProject.path);
    url.searchParams.set("scope", selection.scope);
    if (selection.path) url.searchParams.set("path", selection.path);
    if (selection.ref) url.searchParams.set("ref", selection.ref);
    const response = await fetch(url, { cache: "no-store" });
    const data = await readApiJson(response, "无法读取 Git 差异");
    if (
      state.gitSelectedChange?.scope !== selection.scope
      || state.gitSelectedChange?.path !== selection.path
      || state.gitSelectedChange?.ref !== selection.ref
    ) return;
    state.gitDiff = data;
    renderUnifiedDiff(data.diff || "", selection);
  } catch (error) {
    elements.gitDiffContent.replaceChildren();
    const empty = document.createElement("p");
    empty.textContent = error.message;
    elements.gitDiffContent.append(empty);
  }
}

function renderGitDiffActions() {
  const selection = state.gitSelectedChange;
  const writable = state.gitSnapshot?.writable !== false;
  elements.gitFileStageButton.hidden = !selection || !["unstaged", "untracked"].includes(selection.scope);
  elements.gitFileUnstageButton.hidden = !selection || selection.scope !== "staged";
  elements.gitFileRevertButton.hidden = !selection || !["unstaged", "untracked"].includes(selection.scope);
  for (const button of [elements.gitFileStageButton, elements.gitFileUnstageButton, elements.gitFileRevertButton]) {
    button.disabled = !writable || state.gitLoading || conversationBusy();
  }
  updateGitFeedbackButton();
}

function renderUnifiedDiff(diff, selection) {
  renderUnifiedDiffInto(elements.gitDiffContent, diff, selection);
}

function renderUnifiedDiffInto(container, diff, selection) {
  container.replaceChildren();
  if (!diff) {
    const empty = document.createElement("p");
    empty.textContent = "没有可显示的文本差异；文件可能为空、为二进制，或状态已经变化。";
    container.append(empty);
    return;
  }
  const files = parseUnifiedDiff(diff, selection.path);
  for (const file of files) {
    const section = document.createElement("section");
    section.className = "git-diff-file";
    const header = document.createElement("header");
    const name = document.createElement("strong");
    name.textContent = file.path || selection.path || "Diff";
    header.append(name);
    section.append(header);
    for (const line of file.headerLines) section.append(renderGitDiffLine(line, null));
    for (const hunk of file.hunks) {
      const block = document.createElement("section");
      block.className = "git-diff-hunk";
      const hunkHeader = document.createElement("header");
      const heading = document.createElement("code");
      heading.textContent = hunk.lines[0] || "@@";
      hunkHeader.append(heading);
      const operation = selection.scope === "staged"
        ? "unstage"
        : ["unstaged", "untracked"].includes(selection.scope) ? "stage" : null;
      if (operation && file.path) {
        const button = document.createElement("button");
        button.type = "button";
        button.className = "git-hunk-action";
        button.textContent = operation === "stage" ? "暂存区块" : "取消暂存区块";
        button.addEventListener("click", () =>
          mutateGitPatch(operation, file.path, `${file.patchHeader.join("\n")}\n${hunk.lines.join("\n")}\n`));
        hunkHeader.append(button);
      }
      block.append(hunkHeader);
      let oldLine = hunk.oldStart;
      let newLine = hunk.newStart;
      for (const line of hunk.lines.slice(1)) {
        const lineType = line.startsWith("+") ? "add" : line.startsWith("-") ? "delete" : "context";
        const currentOld = lineType === "add" ? null : oldLine++;
        const currentNew = lineType === "delete" ? null : newLine++;
        block.append(renderGitDiffLine(line, {
          type: lineType,
          oldLine: currentOld,
          newLine: currentNew,
          path: file.path,
        }));
      }
      section.append(block);
    }
    container.append(section);
  }
  refreshIcons();
}

function parseUnifiedDiff(diff, fallbackPath = null) {
  const lines = String(diff).replace(/\r\n?/g, "\n").split("\n");
  const files = [];
  let file = null;
  let hunk = null;
  const ensureFile = () => {
    if (!file) {
      file = { path: fallbackPath, headerLines: [], patchHeader: [], hunks: [] };
      files.push(file);
    }
    return file;
  };
  for (const line of lines) {
    if (line.startsWith("diff --git ")) {
      file = { path: fallbackPath, headerLines: [], patchHeader: [], hunks: [] };
      files.push(file);
      hunk = null;
    }
    const current = ensureFile();
    if (line.startsWith("+++ ")) {
      const raw = line.slice(4).split("\t", 1)[0];
      if (raw !== "/dev/null") current.path = raw.replace(/^b\//, "");
    }
    if (line.startsWith("@@ ")) {
      const match = line.match(/^@@ -(\d+)(?:,\d+)? \+(\d+)(?:,\d+)? @@/);
      hunk = {
        oldStart: Number(match?.[1] || 0),
        newStart: Number(match?.[2] || 0),
        lines: [line],
      };
      current.hunks.push(hunk);
      continue;
    }
    if (hunk) hunk.lines.push(line);
    else {
      current.headerLines.push(line);
      current.patchHeader.push(line);
    }
  }
  return files;
}

function renderGitDiffLine(line, metadata) {
  const row = document.createElement("div");
  row.className = `git-diff-line${metadata?.type ? ` ${metadata.type}` : ""}`;
  const oldNumber = document.createElement("span");
  oldNumber.textContent = metadata?.oldLine || "";
  const newNumber = document.createElement("span");
  newNumber.textContent = metadata?.newLine || "";
  const code = document.createElement("code");
  code.textContent = line;
  row.append(oldNumber, newNumber, code);
  if (metadata?.path && (metadata.oldLine || metadata.newLine)) {
    row.tabIndex = 0;
    row.title = "点击引用这一行";
    row.addEventListener("click", () => {
      const lineNumber = metadata.newLine || metadata.oldLine;
      const prefix = `[${metadata.path}:${lineNumber}] `;
      if (!elements.gitFeedbackInput.value.startsWith(prefix)) {
        elements.gitFeedbackInput.value = `${prefix}${elements.gitFeedbackInput.value}`;
      }
      elements.gitFeedbackInput.focus();
      updateGitFeedbackButton();
    });
  }
  return row;
}

function setGitMutationButtonsDisabled(disabled) {
  for (const button of [
    elements.gitStageAllButton,
    elements.gitUnstageAllButton,
    elements.gitCreateBranchButton,
    elements.gitCommitButton,
  ]) button.disabled = disabled;
}

async function mutateSelectedGitFile(action) {
  const selection = state.gitSelectedChange;
  if (!selection?.path) return;
  await mutateGit(action, { path: selection.path });
}

async function revertSelectedGitFile() {
  const selection = state.gitSelectedChange;
  if (!selection?.path) return;
  if (!confirm(`撤销“${selection.path}”的当前改动？未跟踪内容会移入服务器恢复区。`)) return;
  const confirmation = prompt(`此操作会改变工作区。请输入完整文件路径确认：\n${selection.path}`);
  if (confirmation !== selection.path) {
    if (confirmation != null) toast("文件路径确认不一致，已取消", "error");
    return;
  }
  await mutateGit("revert", { path: selection.path, confirmation });
}

async function mutateGitPatch(operation, filePath, patch) {
  let confirmation = null;
  if (operation === "revert") {
    if (!confirm(`撤销“${filePath}”的这个差异区块？`)) return;
    confirmation = prompt(`请输入完整文件路径确认：\n${filePath}`);
    if (confirmation !== filePath) return;
  }
  await mutateGit("applyPatch", { operation, path: filePath, patch, confirmation });
}

async function mutateGit(action, values = {}) {
  if (!state.currentProject || state.gitLoading) return false;
  state.gitLoading = true;
  setGitMutationButtonsDisabled(true);
  renderGitDiffActions();
  try {
    const response = await fetch("/api/git/action", {
      method: "POST",
      headers: {
        "Content-Type": "application/json",
        "X-Codex-Desktop-Action": "git-workspace-action",
      },
      body: JSON.stringify({ project: state.currentProject.path, action, ...values }),
    });
    const data = await readApiJson(response, "Git 操作失败");
    state.gitSnapshot = data.status;
    if (!gitSelectionExists(state.gitSelectedChange, data.status)) {
      state.gitSelectedChange = null;
      state.gitDiff = null;
    }
    renderGitSnapshot();
    if (state.gitSelectedChange) await loadGitDiff(state.gitSelectedChange);
    if (data.trashId) toast("未跟踪内容已移入服务器恢复区");
    else toast("Git 操作已完成");
    return true;
  } catch (error) {
    toast(error.message, "error");
    return false;
  } finally {
    state.gitLoading = false;
    renderGitSnapshot();
  }
}

function updateGitFeedbackButton() {
  elements.gitSendFeedbackButton.disabled = !elements.gitFeedbackInput.value.trim()
    || !state.gitSelectedChange
    || !state.activeThread
    || state.runtime !== "codex";
}

async function sendGitFeedback() {
  const feedback = elements.gitFeedbackInput.value.trim();
  const selection = state.gitSelectedChange;
  if (!feedback || !selection || !state.activeThread) return;
  const instruction = [
    "请根据以下代码审查反馈检查并处理当前工程：",
    `范围：${selection.path || selection.ref || selection.scope}`,
    feedback,
  ].join("\n\n");
  elements.gitFeedbackInput.value = "";
  updateGitFeedbackButton();
  elements.gitDrawer.close();
  elements.promptInput.value = [elements.promptInput.value.trim(), instruction].filter(Boolean).join("\n\n");
  resizePrompt();
  await sendPrompt();
}

function updateGitReviewTarget() {
  const target = elements.gitReviewTargetInput.value;
  elements.gitReviewValueField.hidden = !["baseBranch", "commit"].includes(target);
  elements.gitReviewInstructionsField.hidden = target !== "custom";
  elements.gitReviewValueLabel.textContent = target === "commit" ? "提交 SHA" : "基础分支";
  elements.gitReviewValueInput.placeholder = target === "commit" ? "例如 abc1234" : "例如 main";
}

async function loadGitRemoteDiff({ useSelection = false } = {}) {
  if (!state.currentProject || !canUseCodexRemoteDiff() || state.gitLoading) return;
  const projectPath = state.currentProject.path;
  const selectedRemote = useSelection ? elements.gitRemoteNameInput.value : "";
  const selectedBranch = useSelection ? elements.gitRemoteBranchInput.value : "";
  state.gitLoading = true;
  elements.gitRemoteError.textContent = "";
  elements.gitRemoteCompareButton.disabled = true;
  elements.gitRemoteReviewButton.disabled = true;
  try {
    const url = new URL("/api/git/remote-diff", location.origin);
    url.searchParams.set("project", projectPath);
    url.searchParams.set("_", Date.now());
    if (selectedRemote && selectedBranch) {
      url.searchParams.set("remote", selectedRemote);
      url.searchParams.set("branch", selectedBranch);
    }
    const response = await fetch(url, { cache: "no-store" });
    const data = await readApiJson(response, "无法比较远端 Git 差异");
    if (state.currentProject?.path !== projectPath) return;
    state.gitRemoteDiff = data;
    renderGitRemoteDiff();
  } catch (error) {
    elements.gitRemoteError.textContent = error.message;
    elements.gitRemoteFileList.replaceChildren();
    const empty = document.createElement("p");
    empty.textContent = error.message;
    elements.gitRemoteFileList.append(empty);
  } finally {
    state.gitLoading = false;
    elements.gitRemoteCompareButton.disabled = elements.gitRemoteBranchInput.options.length === 0;
    elements.gitRemoteReviewButton.disabled = !canStartRemoteGitReview();
  }
}

function renderGitRemoteDiff() {
  const data = state.gitRemoteDiff;
  renderGitRemoteSelectors(data);
  elements.gitRemoteFileList.replaceChildren();
  if (!data?.selected) {
    elements.gitRemoteWorkspace.textContent = gitRemoteWorkspaceLabel(data?.workspace);
    elements.gitRemoteWorkspaceSha.textContent = shortGitSha(data?.workspace?.sha);
    elements.gitRemoteTarget.textContent = "--";
    elements.gitRemoteTargetSha.textContent = "--";
    elements.gitRemoteRelation.textContent = "没有远端跟踪分支";
    elements.gitRemoteRelationDetail.textContent = "先在服务器 Git 仓库中配置远端跟踪引用";
    elements.gitRemoteFileCount.textContent = "0";
    elements.gitRemoteSafetyState.textContent = "未执行比较";
    const empty = document.createElement("p");
    empty.textContent = "没有可比较的远端跟踪分支。此页面不会自动联网 fetch。";
    elements.gitRemoteFileList.append(empty);
    elements.gitRemoteNotice.textContent = "此页面不会自动联网 fetch，也不会读取 Git 凭据。";
    elements.gitRemoteReviewButton.disabled = true;
    return;
  }
  elements.gitRemoteWorkspace.textContent = gitRemoteWorkspaceLabel(data.workspace);
  elements.gitRemoteWorkspaceSha.textContent = shortGitSha(data.workspace?.sha);
  elements.gitRemoteTarget.textContent = data.selected.ref;
  elements.gitRemoteTargetSha.textContent = shortGitSha(data.selected.sha);
  elements.gitRemoteRelation.textContent = gitRemoteRelationLabel(data.relation);
  elements.gitRemoteRelationDetail.textContent = `领先 ${data.ahead || 0} · 落后 ${data.behind || 0}${data.mergeBase ? ` · 基点 ${shortGitSha(data.mergeBase)}` : ""}`;
  elements.gitRemoteFileCount.textContent = `${data.fileCount || 0}${data.truncated ? "+" : ""}`;
  elements.gitRemoteSafetyState.textContent = [
    data.conflicts ? `${data.conflicts} 个冲突` : null,
    data.redactions ? `${data.redactions} 处敏感值已隐藏` : "未发现密钥形态",
    data.source === "codex-native" ? "Codex 原生比较" : "服务器安全比较",
  ].filter(Boolean).join(" · ");
  elements.gitRemoteNotice.textContent = data.truncated
    ? `差异已达到安全显示上限${data.omittedFileCount ? `，另有 ${data.omittedFileCount} 个文件未展示` : ""}。未跟踪文件仍请在“改动”中查看。`
    : "只读本地远端跟踪引用；未联网 fetch，未跟踪文件请在“改动”中查看。";
  const files = Array.isArray(data.files) ? data.files : [];
  if (!files.length) {
    const empty = document.createElement("p");
    empty.textContent = "当前工作区与所选远端基准没有可显示的已跟踪文件差异。";
    elements.gitRemoteFileList.append(empty);
  }
  for (const file of files) elements.gitRemoteFileList.append(renderGitRemoteFile(file));
  elements.gitRemoteReviewButton.disabled = !canStartRemoteGitReview();
  refreshIcons();
}

function renderGitRemoteSelectors(data) {
  const previousRemote = elements.gitRemoteNameInput.value;
  const previousBranch = elements.gitRemoteBranchInput.value;
  const remotes = Array.isArray(data?.remotes) ? data.remotes : [];
  elements.gitRemoteNameInput.replaceChildren(...remotes.map((remote) => dataOption(remote.name, remote.name)));
  const selectedRemote = data?.selected?.remote || (
    remotes.some((remote) => remote.name === previousRemote) ? previousRemote : remotes[0]?.name
  ) || "";
  elements.gitRemoteNameInput.value = selectedRemote;
  renderGitRemoteBranchOptions(data?.selected?.branch || previousBranch);
  elements.gitRemoteNameInput.disabled = remotes.length === 0;
  elements.gitRemoteBranchInput.disabled = remotes.length === 0;
  elements.gitRemoteCompareButton.disabled = remotes.length === 0 || state.gitLoading;
}

function renderGitRemoteBranchOptions(preferredBranch = "") {
  const remotes = Array.isArray(state.gitRemoteDiff?.remotes) ? state.gitRemoteDiff.remotes : [];
  const remote = remotes.find((entry) => entry.name === elements.gitRemoteNameInput.value);
  const branches = Array.isArray(remote?.branches) ? remote.branches : [];
  elements.gitRemoteBranchInput.replaceChildren(...branches.map((branch) => dataOption(branch.name, branch.name)));
  const selected = branches.some((branch) => branch.name === preferredBranch)
    ? preferredBranch
    : branches[0]?.name || "";
  elements.gitRemoteBranchInput.value = selected;
  elements.gitRemoteBranchInput.disabled = branches.length === 0;
  elements.gitRemoteCompareButton.disabled = branches.length === 0 || state.gitLoading;
}

function markGitRemoteSelectionDirty() {
  elements.gitRemoteReviewButton.disabled = true;
  elements.gitRemoteError.textContent = "远端选择已变化，请先点击“比较”。";
}

function renderGitRemoteFile(file) {
  const details = document.createElement("details");
  details.className = "git-remote-file";
  details.dataset.status = file.conflict ? "conflict" : file.status || "M";
  const summary = document.createElement("summary");
  const status = document.createElement("strong");
  status.textContent = file.conflict ? "冲突" : gitRemoteFileStatusLabel(file.status);
  const name = document.createElement("code");
  name.textContent = file.oldPath ? `${file.oldPath} → ${file.path}` : file.path;
  const stats = document.createElement("span");
  stats.textContent = file.binary
    ? "二进制 · 仅元数据"
    : `+${file.additions || 0} / -${file.deletions || 0}${file.truncated ? " · 已截断" : ""}`;
  const icon = document.createElement("i");
  icon.dataset.lucide = "chevron-down";
  summary.append(status, name, stats, icon);
  const content = document.createElement("div");
  content.className = "git-diff-content git-remote-diff-content";
  details.append(summary, content);
  details.addEventListener("toggle", () => {
    if (!details.open || content.dataset.rendered === "true") return;
    content.dataset.rendered = "true";
    if (file.binary) {
      const note = document.createElement("p");
      note.textContent = "二进制文件不向浏览器发送内容，只显示状态和统计信息。";
      content.append(note);
    } else {
      renderUnifiedDiffInto(content, file.diff || "", {
        scope: "remote",
        path: file.path,
        ref: state.gitRemoteDiff?.selected?.ref || null,
      });
    }
  });
  return details;
}

function gitRemoteWorkspaceLabel(workspace) {
  const kind = workspace?.type === "worktree" ? "Worktree" : "Local";
  const branch = workspace?.branch || (workspace?.detached ? "Detached HEAD" : "未命名分支");
  return `${kind} · ${branch}`;
}

function gitRemoteRelationLabel(relation) {
  return ({
    synced: "提交已同步",
    ahead: "本地领先",
    behind: "本地落后",
    diverged: "分支已分叉",
  })[relation] || "关系未知";
}

function gitRemoteFileStatusLabel(status) {
  return ({
    A: "新增",
    C: "复制",
    D: "删除",
    M: "修改",
    R: "重命名",
    T: "类型变化",
    U: "冲突",
    X: "未知",
    B: "配对异常",
  })[status] || status || "修改";
}

function shortGitSha(value) {
  return typeof value === "string" && value ? value.slice(0, 12) : "--";
}

function canStartRemoteGitReview() {
  return Boolean(
    state.gitRemoteDiff?.selected?.ref
    && state.gitRemoteDiff.selected.remote === elements.gitRemoteNameInput.value
    && state.gitRemoteDiff.selected.branch === elements.gitRemoteBranchInput.value
    && state.runtime === "codex"
    && state.activeThread
    && state.currentProject
    && state.activeThread.cwd === state.currentProject.path
    && !conversationBusy()
  );
}

async function startRemoteGitReview() {
  if (!canStartRemoteGitReview()) {
    elements.gitRemoteError.textContent = "请先打开当前工程的空闲 Codex 对话";
    return;
  }
  elements.gitReviewTargetInput.value = "baseBranch";
  updateGitReviewTarget();
  elements.gitReviewValueInput.value = state.gitRemoteDiff.selected.ref;
  selectGitTab("review");
  await startCodexReview();
}

async function startCodexReview() {
  elements.gitReviewError.textContent = "";
  if (state.runtime !== "codex" || !state.activeThread) {
    elements.gitReviewError.textContent = "请先打开一个 Codex 对话";
    return;
  }
  if (!state.currentProject || state.activeThread.cwd !== state.currentProject.path) {
    elements.gitReviewError.textContent = "当前 Codex 对话与 Git 工程不一致";
    return;
  }
  if (conversationBusy()) {
    elements.gitReviewError.textContent = "当前任务仍在运行，请完成或终止后再启动审查";
    return;
  }
  const type = elements.gitReviewTargetInput.value;
  let target;
  if (type === "uncommittedChanges") {
    target = { type };
  } else if (type === "baseBranch") {
    const branch = elements.gitReviewValueInput.value.trim();
    if (!branch) return void (elements.gitReviewError.textContent = "请输入基础分支");
    target = { type, branch };
  } else if (type === "commit") {
    const sha = elements.gitReviewValueInput.value.trim();
    if (!sha) return void (elements.gitReviewError.textContent = "请输入提交 SHA");
    const commit = state.gitSnapshot?.commits?.find((entry) => entry.sha === sha || entry.shortSha === sha);
    target = { type, sha, ...(commit?.subject ? { title: commit.subject } : {}) };
  } else {
    const instructions = elements.gitReviewInstructionsInput.value.trim();
    if (!instructions) return void (elements.gitReviewError.textContent = "请输入自定义审查要求");
    target = { type: "custom", instructions };
  }
  elements.gitStartReviewButton.disabled = true;
  let durableOperation = null;
  try {
    const delivery = elements.gitReviewDeliveryInput.value;
    const operationParams = {
      threadId: state.activeThread.id,
      target,
      delivery,
    };
    durableOperation = await beginDurableOperation("review/start", operationParams);
    const result = await rpc("review/start", {
      ...operationParams,
      _wflThreadLeaseOwnerId: THREAD_LEASE_OWNER_ID,
      _wflClientOperationId: durableOperation.clientOperationId,
    });
    settleDurableOperation(durableOperation);
    elements.gitDrawer.close();
    if (delivery === "detached" && result.reviewThreadId !== state.activeThread.id) {
      await loadThreads();
      const reviewThread = state.threads.find((thread) => thread.id === result.reviewThreadId) || {
        id: result.reviewThreadId,
        cwd: state.currentProject.path,
        name: "Codex Review",
        turns: [result.turn],
      };
      await resumeThread(reviewThread);
    } else {
      invalidateThreadTaskAuthority(state.activeThread.id);
      upsertTurn(result.turn);
      state.activeTurnId = turnStatusType(result.turn) === "inProgress" ? result.turn.id : null;
      state.codexActiveTurnId = state.activeTurnId;
      renderActiveThread({ preserveOptimistic: true, scrollToBottom: true });
      setTurnBusy(conversationBusy(), "正在审查");
    }
    toast(delivery === "detached" ? "已创建独立审查对话" : "Codex Review 已启动");
  } catch (error) {
    settleDurableOperation(durableOperation, error);
    elements.gitReviewError.textContent = error.message;
  } finally {
    elements.gitStartReviewButton.disabled = state.runtime !== "codex" || !state.activeThread || conversationBusy();
  }
}

function renderGitHistory(snapshot) {
  elements.gitBranchList.replaceChildren();
  for (const branch of snapshot.branches || []) {
    const row = document.createElement("button");
    row.type = "button";
    row.className = "git-history-row";
    row.innerHTML = '<i data-lucide="git-branch"></i><code></code><span></span>';
    row.querySelector("code").textContent = branch.name;
    row.querySelector("span:last-child").textContent = branch.name === snapshot.branch ? "当前" : branch.oid || "";
    row.addEventListener("click", () => showGitReferenceDiff("base", branch.name, `${branch.name}…HEAD`));
    elements.gitBranchList.append(row);
  }
  if (!snapshot.branches?.length) elements.gitBranchList.innerHTML = '<div class="list-empty">没有本地分支</div>';
  elements.gitCommitList.replaceChildren();
  for (const commit of snapshot.commits || []) {
    const row = document.createElement("button");
    row.type = "button";
    row.className = "git-history-row";
    row.innerHTML = '<code></code><span></span><time></time>';
    row.querySelector("code").textContent = commit.shortSha;
    row.querySelector("span").textContent = commit.subject;
    row.querySelector("time").textContent = commit.timestamp ? relativeTime(commit.timestamp) : "";
    row.addEventListener("click", () => showGitReferenceDiff("commit", commit.sha, commit.subject));
    elements.gitCommitList.append(row);
  }
  if (!snapshot.commits?.length) elements.gitCommitList.innerHTML = '<div class="list-empty">没有提交记录</div>';
}

async function createGitBranch() {
  const branch = elements.gitNewBranchInput.value.trim();
  if (!branch) return;
  if (await mutateGit("createBranch", { branch })) elements.gitNewBranchInput.value = "";
}

async function commitGitChanges() {
  const message = elements.gitCommitMessageInput.value.trim();
  if (!message) {
    toast("请输入提交说明", "error");
    return;
  }
  if (await mutateGit("commit", { message })) elements.gitCommitMessageInput.value = "";
}

async function loadModels() {
  const result = await rpc("model/list", { limit: 100, includeHidden: false });
  state.models = result.data || [];
  mergeDiscoveredProviderModels(currentProviderModelCatalogId());
  const defaultModel = state.models.find((model) => model.isDefault) || state.models[0];
  if (!state.selectedModel || !state.models.some((model) => model.model === state.selectedModel)) {
    const rememberedModel = loadRememberedCodexModel();
    state.selectedModel = state.models.some((model) => model.model === rememberedModel)
      ? rememberedModel
      : state.models.some((model) => model.model === state.config.model)
        ? state.config.model
        : defaultModel?.model || null;
  }
  populateModelSelects();
}

async function loadCapabilities() {
  try {
    state.capabilities = await rpc("modelProvider/capabilities/read", {});
  } catch {
    state.capabilities = {};
  }
  refreshImageGenerationControl();
}

function populateModelSelects() {
  const selects = [elements.modelSelect, elements.settingsModel];
  for (const select of selects) {
    select.replaceChildren();
    for (const model of state.models) {
      const option = new Option(
        select === elements.modelSelect ? compactModelLabel(model.model) : model.displayName,
        model.model,
      );
      option.title = [model.model, model.description].filter(Boolean).join(" · ");
      select.add(option);
    }
    if (state.selectedModel) select.value = state.selectedModel;
  }
  populateSubagentModelSelect();
  populateEffortSelects();
}

function populateSubagentModelSelect() {
  const select = elements.collaborationSubagentModelInput;
  if (!select) return;
  const configuredModel = collaborationConfigValue(state.config, "default_subagent_model", "");
  const selectedModel = select.value || configuredModel;
  select.replaceChildren(dataOption("跟随主模型", ""));
  for (const model of state.models) {
    const option = new Option(model.displayName || model.model, model.model);
    option.title = [model.model, model.description].filter(Boolean).join(" · ");
    select.append(option);
  }
  if (configuredModel && !state.models.some((model) => model.model === configuredModel)) {
    const option = dataOption(`${configuredModel}（当前不可用）`, configuredModel);
    option.disabled = true;
    select.append(option);
  }
  select.value = selectedModel && [...select.options].some((option) => option.value === selectedModel)
    ? selectedModel
    : "";
  select.disabled = state.models.length === 0;
}

function compactModelLabel(modelId) {
  return String(modelId || "").replace(/^gpt-/i, "") || "未选择";
}

function intelligenceModelLabel(modelId) {
  const id = String(modelId || "");
  if (!/^gpt-/i.test(id)) return id || "未选择模型";
  const parts = id.slice(4).split("-");
  return `GPT-${parts.map((part) => (
    /^\d/.test(part) ? part : `${part.charAt(0).toUpperCase()}${part.slice(1)}`
  )).join(" ")}`;
}

function compactIntelligenceModelLabel(modelId) {
  return compactModelLabel(modelId)
    .split("-")
    .filter(Boolean)
    .map((part) => /^[a-z]/i.test(part) ? `${part.charAt(0).toUpperCase()}${part.slice(1)}` : part)
    .join(" ");
}

function loadRememberedCodexModel(account = state.account) {
  try {
    const value = localStorage.getItem(accountStorageKey("codexDesktop.codexModel", account));
    return typeof value === "string" && value.length <= 256 ? value.trim() : "";
  } catch {
    return "";
  }
}

function rememberCodexModel(modelId, account = state.account) {
  if (
    typeof modelId !== "string"
    || !modelId
    || modelId.length > 256
    || !state.models.some((model) => model.model === modelId)
  ) return;
  try {
    localStorage.setItem(accountStorageKey("codexDesktop.codexModel", account), modelId);
  } catch {
    // The in-memory selection remains active when browser storage is unavailable.
  }
}

function loadRememberedCodexEffort(account = state.account) {
  try {
    const stored = localStorage.getItem(accountStorageKey("codexDesktop.codexEffort", account));
    const legacy = account?.legacy === true ? localStorage.getItem("codexDesktop.soloEffort") : null;
    const value = stored || legacy || "";
    return typeof value === "string" && value.length <= 32 ? value.trim() : "";
  } catch {
    return "";
  }
}

function resolveRememberedCodexModel(fallback = null) {
  const remembered = loadRememberedCodexModel();
  return state.models.some((model) => model.model === remembered) ? remembered : fallback;
}

function resolveRememberedCodexEffort(modelId, fallback = null) {
  const model = state.models.find((entry) => entry.model === modelId);
  const remembered = loadRememberedCodexEffort();
  return model?.supportedReasoningEfforts?.some((entry) => entry.reasoningEffort === remembered)
    ? remembered
    : fallback;
}

function populateEffortSelects(preferred = state.selectedEffort) {
  const model = state.models.find((entry) => entry.model === state.selectedModel) || state.models[0];
  const efforts = model?.supportedReasoningEfforts || [];
  const remembered = preferred || state.selectedSoloEffort;
  const selected = efforts.some((entry) => entry.reasoningEffort === remembered)
    ? remembered
    : model?.defaultReasoningEffort || efforts[0]?.reasoningEffort || "medium";
  state.selectedEffort = selected;
  for (const select of [elements.effortSelect, elements.settingsEffort]) {
    select.replaceChildren();
    for (const effort of efforts) {
      const value = effort.reasoningEffort;
      const option = new Option(effortLabels[value] || value, value);
      option.title = effort.description;
      select.add(option);
    }
    select.value = selected;
  }
  renderIntelligenceControl();
}

const COLLABORATION_SUBAGENT_EFFORTS = new Set([
  "none",
  "minimal",
  "low",
  "medium",
  "high",
  "xhigh",
  "max",
  "ultra",
]);
const COLLABORATION_THREAD_LIMITS = new Set([1, 2, 3, 4, 6, 8, 12, 16, 24, 32, 48, 64, 96, 128]);
const COLLABORATION_DEPTH_LIMITS = new Set([1, 2, 3]);

function selectedCollaborationPreset() {
  return state.codexPolicy.collaborationModes.find(
    (entry) => entry.name === state.selectedCollaborationPreset && entry.mode,
  ) || null;
}

function collaborationPresetLabel(preset) {
  const details = [
    preset.mode === "plan" ? "规划" : "默认",
    preset.model,
    preset.reasoning_effort ? effortLabels[preset.reasoning_effort] || preset.reasoning_effort : null,
  ].filter(Boolean);
  return `${preset.name}${details.length ? ` · ${details.join(" · ")}` : ""}`;
}

function collaborationModeForRequest() {
  const preset = selectedCollaborationPreset();
  if (!preset) return null;
  const model = preset.model || state.selectedModel;
  if (!model) return null;
  return {
    mode: preset.mode,
    settings: {
      model,
      reasoning_effort: preset.reasoning_effort ?? state.selectedEffort ?? null,
      developer_instructions: null,
    },
  };
}

function collaborationConfigValue(config, key, fallback) {
  const agents = config?.agents && typeof config.agents === "object" ? config.agents : {};
  const dotted = config?.[`agents.${key}`];
  const value = dotted !== undefined ? dotted : agents[key];
  return value === undefined || value === null ? fallback : value;
}

function collaborationSettingsSnapshot(config = state.config) {
  const enabledValue = collaborationConfigValue(config, "enabled", true);
  const modelValue = collaborationConfigValue(config, "default_subagent_model", "");
  const effortValue = String(collaborationConfigValue(config, "default_subagent_reasoning_effort", "high"));
  const threadsValue = Number(collaborationConfigValue(config, "max_concurrent_threads_per_session", 4));
  const depthValue = Number(collaborationConfigValue(config, "max_depth", 3));
  return {
    subagentEnabled: enabledValue !== false,
    subagentModel: typeof modelValue === "string" && modelValue.length <= 256 ? modelValue : "",
    subagentEffort: COLLABORATION_SUBAGENT_EFFORTS.has(effortValue) ? effortValue : "high",
    maxThreads: COLLABORATION_THREAD_LIMITS.has(threadsValue) ? threadsValue : 4,
    maxDepth: COLLABORATION_DEPTH_LIMITS.has(depthValue) ? depthValue : 3,
  };
}

function collaborationSettingsLabel(settings = collaborationSettingsSnapshot()) {
  const preset = selectedCollaborationPreset();
  const presetLabel = preset ? `${preset.name} · ` : "";
  const enabledLabel = settings.subagentEnabled ? "子代理已启用" : "子代理已关闭";
  return `${enabledLabel} · ${presetLabel}${collaborationSubagentModelLabel(settings.subagentModel)} · ${effortLabels[settings.subagentEffort] || settings.subagentEffort} · ${settings.maxThreads} 线程 · ${settings.maxDepth} 层`;
}

function collaborationSubagentModelLabel(modelId) {
  return modelId ? compactIntelligenceModelLabel(modelId) : "跟随主模型";
}

function renderCollaborationSettings() {
  const settings = collaborationSettingsSnapshot();
  const modes = state.codexPolicy.collaborationModes.filter((entry) => entry.mode);
  elements.collaborationSubagentEnabledInput.checked = settings.subagentEnabled;
  elements.collaborationPresetInput.replaceChildren(dataOption("关闭协作预设", ""));
  for (const preset of modes) {
    elements.collaborationPresetInput.append(dataOption(collaborationPresetLabel(preset), preset.name));
  }
  elements.collaborationPresetInput.value = selectedCollaborationPreset()?.name || "";
  elements.collaborationPresetInput.disabled = !modes.length;
  elements.collaborationPresetState.textContent = state.codexPolicy.error && !modes.length
    ? `官方预设暂不可用：${state.codexPolicy.error}`
    : modes.length
      ? "预设会覆盖本轮模型和主代理推理强度；下方子代理限制仍独立生效。"
      : "当前 Codex 没有返回可用的官方协作预设。";
  populateSubagentModelSelect();
  elements.collaborationSubagentModelInput.value = settings.subagentModel;
  elements.collaborationSubagentEffortInput.value = settings.subagentEffort;
  elements.collaborationThreadsInput.value = String(settings.maxThreads);
  elements.collaborationDepthInput.value = String(settings.maxDepth);
  elements.collaborationSettingsState.textContent = collaborationSettingsLabel(settings);
  elements.collaborationSettingsError.textContent = "";
}

function renderIntelligenceControl() {
  if (state.runtime === "claude") {
    elements.worktreeBranchButton.hidden = true;
    elements.worktreeHandoffButton.hidden = true;
    elements.worktreeSnapshotButton.hidden = true;
    renderClaudeIntelligenceControl();
    return;
  }
  const model = state.models.find((entry) => entry.model === state.selectedModel) || state.models[0];
  const efforts = model?.supportedReasoningEfforts || [];
  const collaborationEnabled = Boolean(
    selectedCollaborationPreset() || collaborationSettingsSnapshot().subagentEnabled,
  );
  const effortLabel = intelligenceEffortLabels[state.selectedEffort]
    || effortLabels[state.selectedEffort]
    || state.selectedEffort
    || "Medium";
  const modelLabel = intelligenceModelLabel(model?.model || state.selectedModel);
  const compactModel = compactIntelligenceModelLabel(model?.model || state.selectedModel);
  elements.intelligenceMenuLabel.textContent = [compactModel, effortLabel].filter(Boolean).join(" ");
  elements.intelligenceModelLabel.textContent = modelLabel;
  elements.intelligenceMenuButton.title = collaborationEnabled
    ? `${modelLabel} · ${effortLabel} · 官方子代理设置`
    : `${modelLabel} · ${effortLabel}`;
  elements.intelligenceMenuButton.disabled = !model || conversationBusy();
  elements.intelligenceEffortView.querySelector(".intelligence-menu-heading").textContent = "智能";
  elements.collaborationSettingsButton.hidden = false;
  elements.codexWorkspaceButton.hidden = false;
  elements.claudePermissionButton.hidden = true;
  elements.claudeWorkspaceButton.hidden = true;
  elements.claudeExecutionButton.hidden = true;
  renderCodexWorkspaceSettings();

  renderCollaborationSettings();

  elements.intelligenceEffortOptions.replaceChildren();
  for (const effort of efforts) {
    const value = effort.reasoningEffort;
    const button = document.createElement("button");
    button.className = "intelligence-option";
    button.type = "button";
    button.setAttribute("role", "menuitemradio");
    button.setAttribute("aria-checked", String(value === state.selectedEffort));
    button.title = effort.description || `推理强度：${effortLabels[value] || value}`;
    button.innerHTML = '<span></span><i data-lucide="check"></i>';
    button.querySelector("span").textContent = value === "ultra"
      ? "Ultra（最高，主动多代理）"
      : intelligenceEffortLabels[value] || effortLabels[value] || value;
    button.querySelector("svg, i").hidden = value !== state.selectedEffort;
    button.addEventListener("click", () => selectIntelligenceEffort(value));
    elements.intelligenceEffortOptions.append(button);
  }

  elements.intelligenceModelOptions.replaceChildren();
  for (const entry of state.models) {
    const button = document.createElement("button");
    button.className = "intelligence-option";
    button.type = "button";
    button.setAttribute("role", "menuitemradio");
    button.setAttribute("aria-checked", String(entry.model === state.selectedModel));
    button.title = [entry.model, entry.description].filter(Boolean).join(" · ");
    button.innerHTML = '<span></span><i data-lucide="check"></i>';
    button.querySelector("span").textContent = intelligenceModelLabel(entry.model);
    button.querySelector("svg, i").hidden = entry.model !== state.selectedModel;
    button.addEventListener("click", () => selectIntelligenceModel(entry.model));
    elements.intelligenceModelOptions.append(button);
  }
  refreshIcons();
}

function currentClaudeSettings() {
  const activeProfile = state.claudeConfig?.profiles?.find((profile) => profile.id === state.claudeConfig?.activeId);
  const session = state.activeClaudeSession;
  return {
    model: session?.model || state.selectedClaudeModel || activeProfile?.model || "sonnet",
    effort: session?.effort ?? state.selectedClaudeEffort ?? null,
    permissionMode: session?.permissionMode || state.selectedClaudePermissionMode || "acceptEdits",
    fallbackModel: session ? (session.fallbackModel || null) : (state.selectedClaudeFallbackModel || null),
    maxBudgetUsd: session
      ? (session.maxBudgetUsd === undefined ? null : session.maxBudgetUsd)
      : parseClaudeBudget(state.selectedClaudeMaxBudgetUsd),
    autocompact: session
      ? parseClaudeAutocompact(session.autocompact)
      : parseClaudeAutocompact(state.selectedClaudeAutocompact),
    allowedTools: session ? (Array.isArray(session.allowedTools) ? session.allowedTools : []) : parseClaudeToolRules(state.selectedClaudeAllowedTools),
    disallowedTools: session
      ? (Array.isArray(session.disallowedTools) ? session.disallowedTools : [])
      : parseClaudeToolRules(state.selectedClaudeDisallowedTools),
    agent: session ? (session.agent || null) : (state.selectedClaudeAgent || null),
    systemPrompt: session ? (session.systemPrompt || null) : (state.selectedClaudeSystemPrompt || null),
    excludeDynamicSystemPromptSections: session
      ? session.excludeDynamicSystemPromptSections === true
      : state.selectedClaudeExcludeDynamicPrompt,
    settingSources: session
      ? parseClaudeSettingSources(session.settingSources)
      : parseClaudeSettingSources(state.selectedClaudeSettingSources),
    safeMode: session ? session.safeMode === true : state.selectedClaudeSafeMode,
    strictMcpConfig: session ? session.strictMcpConfig === true : state.selectedClaudeStrictMcp,
    mcpServerNames: session
      ? parseClaudeMcpServerNames(session.mcpServerNames)
      : parseClaudeMcpServerNames(state.selectedClaudeMcpServerNames),
    noSessionPersistence: session
      ? session.noSessionPersistence === true
      : state.selectedClaudeNoPersistence,
    jsonSchema: session ? (session.jsonSchema || null) : (state.selectedClaudeJsonSchema || null),
    inlineAgentNames: session
      ? parseClaudeInlineAgentNames(session.inlineAgentNames)
      : parseClaudeInlineAgentNames(state.selectedClaudeInlineAgentNames),
    brief: session ? session.brief === true : state.selectedClaudeBrief,
    remoteFiles: session
      ? parseClaudeRemoteFiles(session.remoteFiles)
      : parseClaudeRemoteFiles(state.selectedClaudeRemoteFiles),
    fromPr: session ? (session.fromPr || null) : (state.selectedClaudeFromPr || null),
    pluginDirectories: session
      ? parseClaudeLineList(session.pluginDirectories, 8)
      : parseClaudeLineList(state.selectedClaudePluginDirectories, 8),
    pluginUrls: session
      ? parseClaudeLineList(session.pluginUrls, 4)
      : parseClaudeLineList(state.selectedClaudePluginUrls, 4),
    betaHeaders: session
      ? parseClaudeBetaHeaders(session.betaHeaders)
      : parseClaudeBetaHeaders(state.selectedClaudeBetaHeaders),
  };
}

function parseClaudeBudget(value) {
  if (value === null || value === undefined || value === "") return null;
  const number = Number(value);
  return Number.isFinite(number) && number >= 0 ? number : null;
}

function parseClaudeAutocompact(value) {
  if (value === "auto") return "auto";
  if (value === null || value === undefined || value === "") return null;
  const tokens = Number(value);
  return Number.isSafeInteger(tokens) && tokens >= 100_000 && tokens <= 1_000_000
    ? tokens
    : null;
}

function formatClaudeExecutionRules(value) {
  return Array.isArray(value) ? value.join(", ") : "";
}

function parseClaudeSettingSources(value) {
  const entries = Array.isArray(value) ? value : String(value || "").split(",");
  return [...new Set(entries.map((entry) => String(entry).trim())
    .filter((entry) => ["user", "project", "local"].includes(entry)))];
}

function parseClaudeMcpServerNames(value) {
  const entries = Array.isArray(value) ? value : String(value || "").split(",");
  return [...new Set(entries.map((entry) => String(entry).trim())
    .filter((entry) => /^[A-Za-z0-9][A-Za-z0-9_.-]{0,127}$/.test(entry)))].slice(0, 64);
}

function parseClaudeInlineAgentNames(value) {
  const entries = Array.isArray(value) ? value : String(value || "").split(",");
  return [...new Set(entries.map((entry) => String(entry).trim())
    .filter((entry) => /^[a-z0-9][a-z0-9_-]{0,63}$/.test(entry)))].slice(0, 16);
}

function parseClaudeRemoteFiles(value) {
  const entries = Array.isArray(value) ? value : String(value || "").split(/\r?\n/);
  const files = [];
  for (const entry of entries) {
    const raw = typeof entry === "string"
      ? entry
      : entry && typeof entry === "object"
        ? `${entry.fileId || ""}:${entry.relativePath || ""}`
        : "";
    const separator = raw.indexOf(":");
    const fileId = separator > 0 ? raw.slice(0, separator).trim() : "";
    const relativePath = separator > 0 ? raw.slice(separator + 1).trim() : "";
    if (!fileId && !relativePath) continue;
    files.push({ fileId, relativePath });
  }
  return files;
}

function formatClaudeRemoteFiles(value) {
  return parseClaudeRemoteFiles(value)
    .map((entry) => `${entry.fileId}:${entry.relativePath}`)
    .join("\n");
}

function parseClaudeLineList(value, maximum) {
  const entries = Array.isArray(value) ? value : String(value || "").split(/\r?\n/);
  return [...new Set(entries.map((entry) => String(entry || "").trim()).filter(Boolean))].slice(0, maximum);
}

function parseClaudeBetaHeaders(value, maximum = 16) {
  const entries = Array.isArray(value) ? value : String(value || "").split(",");
  return [...new Set(entries.map((entry) => String(entry || "").trim()).filter(Boolean))].slice(0, maximum);
}

function selectClaudeLaunchSettings(settings) {
  state.selectedClaudeSystemPrompt = settings.systemPrompt || "";
  state.selectedClaudeExcludeDynamicPrompt = settings.excludeDynamicSystemPromptSections === true;
  state.selectedClaudeSettingSources = parseClaudeSettingSources(settings.settingSources).join(",");
  state.selectedClaudeSafeMode = settings.safeMode === true;
  state.selectedClaudeStrictMcp = settings.strictMcpConfig === true;
  state.selectedClaudeMcpServerNames = parseClaudeMcpServerNames(settings.mcpServerNames).join(",");
  state.selectedClaudeNoPersistence = settings.noSessionPersistence === true;
  state.selectedClaudeAutocompact = settings.autocompact === "auto"
    ? "auto"
    : parseClaudeAutocompact(settings.autocompact)?.toString() || "";
  state.selectedClaudeJsonSchema = settings.jsonSchema || "";
  state.selectedClaudeInlineAgentNames = parseClaudeInlineAgentNames(settings.inlineAgentNames).join(",");
  state.selectedClaudeBrief = settings.brief === true;
  state.selectedClaudeRemoteFiles = formatClaudeRemoteFiles(settings.remoteFiles);
  state.selectedClaudeFromPr = settings.fromPr || "";
  state.selectedClaudePluginDirectories = parseClaudeLineList(settings.pluginDirectories, 8).join("\n");
  state.selectedClaudePluginUrls = parseClaudeLineList(settings.pluginUrls, 4).join("\n");
  state.selectedClaudeBetaHeaders = parseClaudeBetaHeaders(settings.betaHeaders).join(",");
}

function persistClaudeLaunchSettings(settings) {
  const textSettings = [
    ["codexDesktop.claudeSystemPrompt", settings.systemPrompt],
    ["codexDesktop.claudeSettingSources", parseClaudeSettingSources(settings.settingSources).join(",")],
    ["codexDesktop.claudeMcpServerNames", parseClaudeMcpServerNames(settings.mcpServerNames).join(",")],
    ["codexDesktop.claudeJsonSchema", settings.jsonSchema],
    ["codexDesktop.claudeAutocompact", settings.autocompact],
    ["codexDesktop.claudeInlineAgentNames", parseClaudeInlineAgentNames(settings.inlineAgentNames).join(",")],
    ["codexDesktop.claudeRemoteFiles", formatClaudeRemoteFiles(settings.remoteFiles)],
    ["codexDesktop.claudeFromPr", settings.fromPr],
    ["codexDesktop.claudePluginDirectories", parseClaudeLineList(settings.pluginDirectories, 8).join("\n")],
    ["codexDesktop.claudePluginUrls", parseClaudeLineList(settings.pluginUrls, 4).join("\n")],
    ["codexDesktop.claudeBetaHeaders", parseClaudeBetaHeaders(settings.betaHeaders).join(",")],
  ];
  for (const [key, value] of textSettings) {
    if (value) localStorage.setItem(key, value);
    else localStorage.removeItem(key);
  }
  const booleanSettings = [
    ["codexDesktop.claudeExcludeDynamicPrompt", settings.excludeDynamicSystemPromptSections],
    ["codexDesktop.claudeSafeMode", settings.safeMode],
    ["codexDesktop.claudeStrictMcp", settings.strictMcpConfig],
    ["codexDesktop.claudeNoPersistence", settings.noSessionPersistence],
    ["codexDesktop.claudeBrief", settings.brief],
  ];
  for (const [key, value] of booleanSettings) {
    if (value === true) localStorage.setItem(key, "true");
    else localStorage.removeItem(key);
  }
}

function currentClaudeWorkspaceSettings() {
  return {
    workspaceMode: state.selectedClaudeWorkspaceMode,
    worktreeName: state.selectedClaudeWorkspaceMode === "worktree" ? state.selectedClaudeWorktreeName || null : null,
    additionalDirectories: parseClaudeAdditionalDirectories(state.selectedClaudeAdditionalDirectories),
  };
}

function parseClaudeAdditionalDirectories(value) {
  const directories = [];
  for (const line of String(value || "").split("\n")) {
    const directory = line.trim();
    if (directory && !directories.includes(directory)) directories.push(directory);
  }
  return directories.slice(0, 8);
}

function claudeModelOptions() {
  const settings = currentClaudeSettings();
  const activeProfile = state.claudeConfig?.profiles?.find((profile) => profile.id === state.claudeConfig?.activeId);
  const candidates = [
    { value: settings.model, label: claudeModelLabel(settings.model) },
    activeProfile?.model ? { value: activeProfile.model, label: claudeModelLabel(activeProfile.model) } : null,
    { value: "sonnet", label: "Sonnet" },
    { value: "opus", label: "Opus" },
    { value: "haiku", label: "Haiku" },
  ].filter(Boolean);
  return candidates.filter((entry, index) => candidates.findIndex((candidate) => candidate.value === entry.value) === index);
}

function claudeModelLabel(model) {
  const value = String(model || "Claude");
  if (["sonnet", "opus", "haiku"].includes(value.toLowerCase())) {
    return `${value.charAt(0).toUpperCase()}${value.slice(1).toLowerCase()}`;
  }
  return value.replace(/^claude-/i, "Claude ").replaceAll("-", " ");
}

function claudePermissionLabel(mode) {
  return CLAUDE_PERMISSION_MODES.find((entry) => entry.value === mode)?.label || mode || "自动接受编辑";
}

function renderClaudePermissionStatus() {
  const permissionMode = currentClaudeSettings().permissionMode;
  const icon = permissionMode === "plan" ? "notebook-tabs" : permissionMode === "dontAsk" ? "shield-x" : "shield-check";
  elements.sandboxStatus.innerHTML = `<i data-lucide="${icon}"></i>`;
  elements.sandboxStatus.append(document.createTextNode(` ${claudePermissionLabel(permissionMode)}`));
}

function renderClaudeIntelligenceControl() {
  const settings = currentClaudeSettings();
  const effort = CLAUDE_EFFORTS.find((entry) => entry.value === settings.effort) || CLAUDE_EFFORTS[0];
  const modelLabel = claudeModelLabel(settings.model);
  elements.intelligenceMenuLabel.textContent = effort.label;
  elements.intelligenceModelLabel.textContent = modelLabel;
  elements.intelligenceMenuButton.title = `${modelLabel} · ${effort.label} · ${claudePermissionLabel(settings.permissionMode)}`;
  elements.intelligenceMenuButton.disabled = conversationBusy();
  elements.intelligenceEffortView.querySelector(".intelligence-menu-heading").textContent = "Claude";
  elements.collaborationSettingsButton.hidden = true;
  elements.codexWorkspaceButton.hidden = true;
  elements.claudePermissionButton.hidden = false;
  elements.claudeWorkspaceButton.hidden = false;
  elements.claudeExecutionButton.hidden = false;
  elements.claudePermissionState.textContent = claudePermissionLabel(settings.permissionMode);
  renderClaudeWorkspaceSettings();
  renderClaudeExecutionSettings();

  elements.intelligenceEffortOptions.replaceChildren();
  for (const entry of CLAUDE_EFFORTS) {
    const selected = entry.value === settings.effort;
    const button = document.createElement("button");
    button.className = "intelligence-option";
    button.type = "button";
    button.setAttribute("role", "menuitemradio");
    button.setAttribute("aria-checked", String(selected));
    button.innerHTML = '<span></span><i data-lucide="check"></i>';
    button.querySelector("span").textContent = entry.label;
    button.querySelector("i").hidden = !selected;
    button.addEventListener("click", () => selectClaudeEffort(entry.value));
    elements.intelligenceEffortOptions.append(button);
  }

  elements.intelligenceModelOptions.replaceChildren();
  for (const entry of claudeModelOptions()) {
    const selected = entry.value === settings.model;
    const button = document.createElement("button");
    button.className = "intelligence-option";
    button.type = "button";
    button.setAttribute("role", "menuitemradio");
    button.setAttribute("aria-checked", String(selected));
    button.innerHTML = '<span></span><i data-lucide="check"></i>';
    button.querySelector("span").textContent = entry.label;
    button.querySelector("i").hidden = !selected;
    button.addEventListener("click", () => selectClaudeModel(entry.value));
    elements.intelligenceModelOptions.append(button);
  }

  elements.claudePermissionOptions.replaceChildren();
  for (const entry of CLAUDE_PERMISSION_MODES) {
    const selected = entry.value === settings.permissionMode;
    const button = document.createElement("button");
    button.className = "intelligence-option claude-permission-option";
    button.type = "button";
    button.setAttribute("role", "menuitemradio");
    button.setAttribute("aria-checked", String(selected));
    button.title = entry.detail;
    button.innerHTML = '<span></span><i data-lucide="check"></i>';
    button.querySelector("span").textContent = entry.label;
    button.querySelector("i").hidden = !selected;
    button.addEventListener("click", () => selectClaudePermissionMode(entry.value));
    elements.claudePermissionOptions.append(button);
  }
  renderClaudePermissionStatus();
  refreshIcons();
}

async function applyClaudeSettings(next) {
  const previous = currentClaudeSettings();
  state.selectedClaudeModel = next.model;
  state.selectedClaudeEffort = next.effort;
  state.selectedClaudePermissionMode = next.permissionMode;
  state.selectedClaudeFallbackModel = next.fallbackModel || "";
  state.selectedClaudeMaxBudgetUsd = next.maxBudgetUsd === null || next.maxBudgetUsd === undefined
    ? ""
    : String(next.maxBudgetUsd);
  state.selectedClaudeAllowedTools = formatClaudeExecutionRules(next.allowedTools);
  state.selectedClaudeDisallowedTools = formatClaudeExecutionRules(next.disallowedTools);
  state.selectedClaudeAgent = next.agent || "";
  selectClaudeLaunchSettings(next);
  try {
    if (state.activeClaudeSession) {
      const result = await rpc("claude/session/configure", { sessionId: state.activeClaudeSession.id, ...next });
      state.activeClaudeSession = result.session;
      state.claudeSessions = state.claudeSessions.map((entry) => entry.id === result.session.id ? result.session : entry);
      state.threads = state.claudeSessions;
      renderThreads();
    }
    localStorage.setItem("codexDesktop.claudeModel", next.model);
    if (next.effort) localStorage.setItem("codexDesktop.claudeEffort", next.effort);
    else localStorage.removeItem("codexDesktop.claudeEffort");
    localStorage.setItem("codexDesktop.claudePermissionMode", next.permissionMode);
    if (next.fallbackModel) localStorage.setItem("codexDesktop.claudeFallbackModel", next.fallbackModel);
    else localStorage.removeItem("codexDesktop.claudeFallbackModel");
    if (next.maxBudgetUsd !== null && next.maxBudgetUsd !== undefined) {
      localStorage.setItem("codexDesktop.claudeMaxBudgetUsd", String(next.maxBudgetUsd));
    } else localStorage.removeItem("codexDesktop.claudeMaxBudgetUsd");
    if (next.allowedTools?.length) localStorage.setItem("codexDesktop.claudeAllowedTools", formatClaudeExecutionRules(next.allowedTools));
    else localStorage.removeItem("codexDesktop.claudeAllowedTools");
    if (next.disallowedTools?.length) {
      localStorage.setItem("codexDesktop.claudeDisallowedTools", formatClaudeExecutionRules(next.disallowedTools));
    } else localStorage.removeItem("codexDesktop.claudeDisallowedTools");
    if (next.agent) localStorage.setItem("codexDesktop.claudeAgent", next.agent);
    else localStorage.removeItem("codexDesktop.claudeAgent");
    persistClaudeLaunchSettings(next);
    renderClaudeIntelligenceControl();
    closeIntelligenceMenu();
    toast(state.activeClaudeSession ? "Claude 会话设置已更新" : "Claude 默认设置已更新");
    return true;
  } catch (error) {
    state.selectedClaudeModel = previous.model;
    state.selectedClaudeEffort = previous.effort;
    state.selectedClaudePermissionMode = previous.permissionMode;
    state.selectedClaudeFallbackModel = previous.fallbackModel || "";
    state.selectedClaudeMaxBudgetUsd = previous.maxBudgetUsd === null || previous.maxBudgetUsd === undefined
      ? ""
      : String(previous.maxBudgetUsd);
    state.selectedClaudeAllowedTools = formatClaudeExecutionRules(previous.allowedTools);
    state.selectedClaudeDisallowedTools = formatClaudeExecutionRules(previous.disallowedTools);
    state.selectedClaudeAgent = previous.agent || "";
    selectClaudeLaunchSettings(previous);
    renderClaudeIntelligenceControl();
    toast(error.message, "error");
    elements.claudeExecutionError.textContent = error.message;
    return false;
  }
}

function selectClaudeEffort(value) {
  void applyClaudeSettings({ ...currentClaudeSettings(), effort: value });
}

function selectClaudeModel(value) {
  void applyClaudeSettings({ ...currentClaudeSettings(), model: value });
}

function selectClaudePermissionMode(value) {
  void applyClaudeSettings({ ...currentClaudeSettings(), permissionMode: value });
}

function toggleIntelligenceMenu() {
  if (elements.intelligenceMenuButton.disabled) return;
  if (state.runtime === "claude") renderClaudeIntelligenceControl();
  if (elements.intelligenceMenu.hidden) {
    showIntelligenceEffortView();
    elements.intelligenceMenu.hidden = false;
    elements.intelligenceMenuButton.setAttribute("aria-expanded", "true");
    requestAnimationFrame(() => elements.intelligenceEffortOptions.querySelector('[aria-checked="true"]')?.focus());
  } else {
    closeIntelligenceMenu();
  }
}

function closeIntelligenceMenu() {
  elements.intelligenceMenu.hidden = true;
  elements.intelligenceMenuButton.setAttribute("aria-expanded", "false");
}

