    "document.generate": { output: "exports/document.docx", title: "新文档", sections: [{ heading: "第一节", paragraphs: ["正文"] }] },
    "media.transcode": { input: "media/input.mov", output: "exports/output.mp4", quality: "balanced" },
    "video.compose": { output: "exports/video.mp4", width: 1920, height: 1080, fps: 30, clips: [{ path: "media/clip.mp4", startMs: 0 }], titles: [] },
    "godot.export": { projectPath: "game", preset: "Windows Desktop", output: "exports/game.exe" },
