function requireSelectedOnlineWindowsDevice() {
  const device = selectedWindowsDevice();
  if (!device?.online) throw new Error("请选择一台在线 Windows Host");
  return device;
}

async function callWindowsHost({ deviceId, pluginId, threadId, method, params }) {
  const base = { deviceId, pluginId, threadId, windowId: CLIENT_WINDOW_ID };
  const acquired = await windowsJsonRequest("/api/windows-host/leases", {
    method: "POST",
    action: "windows-device-lease-acquire",
    body: base,
  });
  const leaseEpoch = acquired.lease.leaseEpoch;
  try {
    const called = await windowsJsonRequest("/api/windows-host/calls", {
      method: "POST",
      action: "windows-host-call",
      body: { ...base, leaseEpoch, method, params },
    });
    return called.result;
  } finally {
    await windowsJsonRequest("/api/windows-host/leases/release", {
      method: "POST",
      action: "windows-device-lease-release",
      body: { ...base, leaseEpoch },
    }).catch(() => {});
  }
}

async function windowsJsonRequest(url, { method = "GET", action = null, body = null } = {}) {
  const headers = {};
  if (action) headers["X-Codex-Desktop-Action"] = action;
  if (body !== null) headers["Content-Type"] = "application/json";
  const response = await fetch(url, {
    method,
    headers,
    ...(body !== null ? { body: JSON.stringify(body) } : {}),
    cache: "no-store",
  });
  if (response.status === 204) return {};
  const data = await response.json().catch(() => ({}));
  if (!response.ok) throw new Error(data.error || "Windows Host 请求失败");
  return data;
}

