    row.innerHTML = '<span class="ssh-access-record-icon"><i data-lucide="key-round"></i></span><span class="ssh-access-record-copy"><strong></strong><span class="ssh-access-record-id"></span><span class="ssh-access-record-fingerprint"></span><small></small></span><button class="icon-button danger-hover" type="button" title="撤销授权" aria-label="撤销 SSH 授权"><i data-lucide="trash-2"></i></button>';
    setDataContent(row.querySelector("strong"), `${record.username}@${record.host}:${record.port}`);
