async function authorizeSshAccess(event) {
  event.preventDefault();
  if (!elements.sshAccessForm.reportValidity()) return;
  setSshAccessBusy(true);
  elements.sshAccessError.textContent = "";
  const previousRecordIds = new Set(state.sshAccessRecords.map((record) => record.id));
  try {
    const request = fetch("/api/plugins/secure-ssh-access/access", {
      method: "POST",
      headers: {
        "Content-Type": "application/json",
        "X-Codex-Desktop-Action": "ssh-authorize",
      },
      body: JSON.stringify({
        host: elements.sshHostInput.value.trim(),
        port: Number(elements.sshPortInput.value),
        username: elements.sshUsernameInput.value.trim(),
        durationMinutes: Number(elements.sshDurationInput.value),
        password: elements.sshPasswordInput.value,
      }),
    });
    clearSshPassword();
    const response = await request;
    await readApiJson(response, "无法创建临时 SSH 授权", { sshOperation: true });
    await loadSshAccessRecords();
    toast("临时 SSH 授权已创建");
  } catch (error) {
    clearSshPassword();
    elements.sshAccessError.textContent = error.message;
    await loadSshAccessRecords();
    const recovered = state.sshAccessRecords.some((record) => !previousRecordIds.has(record.id));
    if (recovered) {
      elements.sshAccessError.textContent = "";
      toast("连接响应中断，但临时 SSH 授权已创建");
    }
  } finally {
    setSshAccessBusy(false);
  }
}

async function revokeSshAccess(record) {
  if (!confirm(`撤销 ${record.username}@${record.host}:${record.port} 的临时授权？`)) return;
  setSshAccessBusy(true);
  elements.sshAccessError.textContent = "";
  try {
    const response = await fetch(`/api/plugins/secure-ssh-access/access/${encodeURIComponent(record.id)}`, {
      method: "DELETE",
      headers: { "X-Codex-Desktop-Action": "ssh-revoke" },
    });
    await readApiJson(response, "无法撤销 SSH 授权", { sshOperation: true });
    await loadSshAccessRecords();
    toast("临时 SSH 授权已撤销");
  } catch (error) {
    elements.sshAccessError.textContent = error.message;
  } finally {
    setSshAccessBusy(false);
  }
}

