async function readApiJson(response, fallbackMessage, { sshOperation = false } = {}) {
  const contentType = response.headers.get("content-type") || "";
  let data = null;
  if (contentType.toLowerCase().includes("application/json")) {
    data = await response.json().catch(() => null);
  } else {
    await response.text().catch(() => "");
  }
  if (!response.ok) {
    const attachApiErrorDetails = (error) => {
      error.status = response.status;
      error.code = data?.code || null;
      return error;
    };
    if (data?.error) throw attachApiErrorDetails(new Error(data.error));
    if (sshOperation && (response.status === 502 || response.status === 504)) {
      throw attachApiErrorDetails(new Error("连接服务器失败，请检查 SSH 地址、端口、密码和 Cloudflare Tunnel 状态"));
    }
    throw attachApiErrorDetails(new Error(`${fallbackMessage}（HTTP ${response.status}）`));
  }
  if (!data) throw new Error(`${fallbackMessage}：服务器返回了无效响应`);
  return data;
}

function applyProviderRoutingSnapshot(value, { preserveDraft = true } = {}) {
  if (!value || typeof value !== "object" || Array.isArray(value)) return;
  const previousActiveKey = state.providerRouting?.targets?.find((target) => target?.active === true)?.key || null;
  const settings = value.settings && typeof value.settings === "object"
    ? {
        automaticFailover: value.settings.automaticFailover === true,
        priority: Array.isArray(value.settings.priority)
          ? value.settings.priority.filter((key) => typeof key === "string")
          : [],
      }
    : { automaticFailover: false, priority: [] };
  state.providerRouting = {
    settings,
    targets: Array.isArray(value.targets) ? value.targets : [],
    bindings: Array.isArray(value.bindings) ? value.bindings : [],
    audit: Array.isArray(value.audit) ? value.audit : [],
    pending: value.pending && typeof value.pending === "object" ? value.pending : null,
  };
  const nextActiveKey = state.providerRouting.targets.find((target) => target?.active === true)?.key || null;
  if (previousActiveKey && nextActiveKey && previousActiveKey !== nextActiveKey) {
    state.capabilities = {};
    if (state.bridgeReady) void loadCapabilities();
  }
  if (!preserveDraft || !state.providerRoutingDirty) {
    state.providerRoutingDraftPriority = [...settings.priority];
    state.providerRoutingDirty = false;
    if (elements.providerFailoverToggle) {
      elements.providerFailoverToggle.checked = settings.automaticFailover;
    }
  }
  renderThreadProviderBinding();
  refreshImageGenerationControl();
  if (elements.providerDialog?.open && state.editingProviderId === "default") {
    renderProviderFailover();
  }
}

async function loadProviderRouting({ silent = false } = {}) {
  try {
    const response = await fetchWithTimeout(
      `/api/providers/failover?_=${Date.now()}`,
      { cache: "no-store" },
      10_000,
    );
    const data = await readApiJson(response, "无法读取账号与 API 路由");
    applyProviderRoutingSnapshot(data, { preserveDraft: state.providerRoutingDirty });
    return data;
  } catch (error) {
    if (!silent) {
      elements.providerFailoverError.textContent = error.message;
    }
    return null;
  }
}

function renderThreadProviderBinding() {
  if (!elements.threadProviderBadge) return;
  const threadId = state.runtime === "codex" ? state.activeThread?.id : null;
  const binding = threadId
    ? state.providerRouting.bindings.find((entry) => entry.threadId === threadId)
    : null;
  elements.threadProviderBadge.hidden = !binding;
  if (!binding) {
    elements.threadProviderBadge.textContent = "";
    elements.threadProviderBadge.removeAttribute("data-status");
    elements.threadProviderBadge.removeAttribute("title");
    return;
  }
  const identity = binding.accountLabel || binding.label || "Codex 配置";
  const providerUsage = binding.kind === "managed" ? providerUsageForTarget(binding) : null;
  const quotaWindows = providerUsage?.windows?.length
    ? providerUsage.windows
    : codexQuotaWindowsForTarget({ ...binding, active: true });
  const usageText = providerQuickUsageText({ providerUsage, quotaWindows });
  let bindingLabel = providerQuickCompactLabel({
    label: identity,
    providerUsage,
    quotaWindows,
  }, identity);
  if (
    bindingLabel === identity
    && binding.quotaUsedPercent != null
    && Number.isFinite(Number(binding.quotaUsedPercent))
  ) {
    bindingLabel = `${identity} · 7 天 ${Number(binding.quotaUsedPercent).toFixed(0)}%`;
  }
  const badgeIdentity = document.createElement("span");
  badgeIdentity.className = "thread-provider-identity";
  badgeIdentity.textContent = identity;
  const badgeUsage = document.createElement("span");
  badgeUsage.className = "thread-provider-usage";
  badgeUsage.textContent = usageText
    || (bindingLabel !== identity ? bindingLabel.slice(identity.length).replace(/^\s*·\s*/u, "") : "");
  badgeUsage.hidden = !badgeUsage.textContent;
  elements.threadProviderBadge.replaceChildren(badgeIdentity, badgeUsage);
  elements.threadProviderBadge.dataset.status = binding.credentialStatus || "unknown";
  elements.threadProviderBadge.title = [
    `此对话最近绑定：${identity}`,
    providerUsage?.balance ? `余额：${formatProviderBalance(providerUsage.balance)}` : null,
    quotaWindows.find((window) => window.label === "5 小时")?.usedPercent != null
      ? `5 小时已用：${Math.round(Number(quotaWindows.find((window) => window.label === "5 小时").usedPercent))}%`
      : null,
    binding.model ? `模型：${binding.model}` : null,
    `状态：${providerCredentialLabel(binding.credentialStatus)}`,
    binding.checkedAt ? `最近检查：${formatProviderRoutingTime(binding.checkedAt)}` : null,
    binding.boundAt ? `最近使用：${formatProviderRoutingTime(binding.boundAt)}` : null,
  ].filter(Boolean).join("\n");
}

function renderProviderFailover() {
  if (!elements.providerFailoverSection) return;
  const routing = state.providerRouting;
  const targets = Array.isArray(routing.targets) ? routing.targets : [];
  const eligible = targets.filter((target) => target.eligible === true);
  const savedEnabled = routing.settings?.automaticFailover === true;
  if (!state.providerRoutingDirty) {
    elements.providerFailoverToggle.checked = savedEnabled;
  }
  const desiredEnabled = elements.providerFailoverToggle.checked;
  const enabling = desiredEnabled && !savedEnabled;
  elements.providerFailoverWarning.hidden = !enabling;
  elements.providerFailoverToggle.disabled = state.providerRoutingSaving
    || (!savedEnabled && eligible.length < 2);
  elements.providerFailoverStatus.textContent = routing.pending
    ? routing.pending.waitingForIdle
      ? "等待其他对话空闲后切换"
      : "正在执行故障切换"
    : desiredEnabled
      ? `自动切换已开启 · ${eligible.length} 项`
      : "自动切换已关闭";

  const targetByKey = new Map(targets.map((target) => [target.key, target]));
  const priority = [
    ...state.providerRoutingDraftPriority.filter((key) => targetByKey.get(key)?.eligible === true),
    ...eligible.map((target) => target.key)
      .filter((key) => !state.providerRoutingDraftPriority.includes(key)),
  ];
  state.providerRoutingDraftPriority = [...new Set(priority)];
  const eligibleOrder = new Map(state.providerRoutingDraftPriority.map((key, index) => [key, index]));
  const orderedTargets = [...targets].sort((left, right) => (
    (eligibleOrder.get(left.key) ?? Number.MAX_SAFE_INTEGER)
    - (eligibleOrder.get(right.key) ?? Number.MAX_SAFE_INTEGER)
    || Number(right.active) - Number(left.active)
    || String(left.label || "").localeCompare(String(right.label || ""), interfaceLocale())
  ));
  elements.providerFailoverList.replaceChildren();
  if (!orderedTargets.length) {
    const empty = document.createElement("p");
    empty.className = "list-empty";
    empty.textContent = "当前没有可用于路由的官方账号或 API 供应商";
    elements.providerFailoverList.append(empty);
  }
  for (const target of orderedTargets) {
    const row = document.createElement("div");
    row.className = "provider-failover-row";
    row.dataset.eligible = String(target.eligible === true);
    row.dataset.active = String(target.active === true);
    const copy = document.createElement("div");
    copy.className = "provider-failover-copy";
    const title = document.createElement("strong");
    title.textContent = `${target.active ? "当前 · " : ""}${target.accountLabel || target.label || "未知目标"}`;
    const detail = document.createElement("span");
    detail.textContent = [
      target.kind === "official" ? "官方账号" : target.kind === "managed" ? "API 供应商" : "Codex 原配置",
      providerCredentialLabel(target.credentialStatus),
      target.quotaUsedPercent != null && Number.isFinite(Number(target.quotaUsedPercent))
        ? `7 天已用 ${Number(target.quotaUsedPercent).toFixed(0)}%`
        : null,
      target.checkedAt ? `检查于 ${formatProviderRoutingTime(target.checkedAt)}` : null,
      target.disabledReason || null,
    ].filter(Boolean).join(" · ");
    copy.append(title, detail);
    const controls = document.createElement("div");
    controls.className = "provider-failover-controls";
    if (target.eligible) {
      const index = state.providerRoutingDraftPriority.indexOf(target.key);
      const rank = document.createElement("span");
      rank.className = "provider-failover-rank";
      rank.textContent = String(index + 1);
      const up = document.createElement("button");
      up.type = "button";
      up.className = "icon-button";
      up.title = "提高优先级";
      up.setAttribute("aria-label", `提高 ${target.label || "供应商"} 优先级`);
      up.innerHTML = '<i data-lucide="chevron-up"></i>';
      up.disabled = state.providerRoutingSaving || index <= 0;
      up.addEventListener("click", () => moveProviderFailoverTarget(target.key, -1));
      const down = document.createElement("button");
      down.type = "button";
      down.className = "icon-button";
      down.title = "降低优先级";
      down.setAttribute("aria-label", `降低 ${target.label || "供应商"} 优先级`);
      down.innerHTML = '<i data-lucide="chevron-down"></i>';
      down.disabled = state.providerRoutingSaving
        || index < 0
        || index >= state.providerRoutingDraftPriority.length - 1;
      down.addEventListener("click", () => moveProviderFailoverTarget(target.key, 1));
      controls.append(rank, up, down);
    }
    if (target.kind === "managed" && target.disabledReason !== "管理员未分配此 API") {
      const check = document.createElement("button");
      check.type = "button";
      check.className = "icon-button";
      check.title = "检查 API 连接";
      check.setAttribute("aria-label", `检查 ${target.label || "API 供应商"} 连接`);
      check.innerHTML = '<i data-lucide="activity"></i>';
      check.disabled = state.providerRoutingSaving || Boolean(state.providerRoutingCheckingKey);
      check.addEventListener("click", () => checkProviderRoutingTarget(target.key));
      controls.prepend(check);
    }
    row.append(copy, controls);
    elements.providerFailoverList.append(row);
  }

  elements.providerFailoverAudit.replaceChildren();
  for (const event of routing.audit.slice(0, 5)) {
    const row = document.createElement("div");
    row.className = "provider-failover-audit-row";
    const description = document.createElement("span");
    const target = targetByKey.get(event.toKey);
    description.textContent = [
      providerFailoverResultLabel(event.result),
      target?.accountLabel || target?.label || event.code || null,
      providerFailoverReasonLabel(event.reason),
    ].filter(Boolean).join(" · ");
    const time = document.createElement("time");
    time.textContent = formatProviderRoutingTime(event.at);
    row.append(description, time);
    elements.providerFailoverAudit.append(row);
  }
  elements.providerFailoverSaveButton.disabled = state.providerRoutingSaving
    || (desiredEnabled && eligible.length < 2);
  elements.providerFailoverSaveButton.querySelector("span").textContent = state.providerRoutingSaving
    ? "正在保存"
    : "保存路由";
  refreshIcons();
}

async function checkProviderRoutingTarget(key) {
  if (state.providerRoutingCheckingKey) return;
  state.providerRoutingCheckingKey = key;
  elements.providerFailoverError.textContent = "";
  renderProviderFailover();
  try {
    const response = await fetch("/api/providers/failover/check", {
      method: "POST",
      headers: {
        "Content-Type": "application/json",
        "X-Codex-Desktop-Action": "provider-failover-check",
      },
      body: JSON.stringify({ key }),
    });
    const data = await readApiJson(response, "API 连接检查失败");
    applyProviderRoutingSnapshot(data, { preserveDraft: state.providerRoutingDirty });
    toast("API 连接检查正常");
  } catch (error) {
    elements.providerFailoverError.textContent = error.message;
    await loadProviderRouting({ silent: true });
  } finally {
    state.providerRoutingCheckingKey = null;
    renderProviderFailover();
  }
}

function moveProviderFailoverTarget(key, offset) {
  const index = state.providerRoutingDraftPriority.indexOf(key);
  const next = index + offset;
  if (index < 0 || next < 0 || next >= state.providerRoutingDraftPriority.length) return;
  const priority = [...state.providerRoutingDraftPriority];
  [priority[index], priority[next]] = [priority[next], priority[index]];
  state.providerRoutingDraftPriority = priority;
  state.providerRoutingDirty = true;
  renderProviderFailover();
}

async function saveProviderFailoverSettings() {
  if (state.providerRoutingSaving) return;
  const automaticFailover = elements.providerFailoverToggle.checked;
  const enabling = automaticFailover && state.providerRouting.settings?.automaticFailover !== true;
  if (enabling && !elements.providerFailoverAcknowledge.checked) {
    elements.providerFailoverError.textContent = "请先确认自动切换可能改变身份与计费来源";
    return;
  }
  if (enabling && elements.providerFailoverConfirmation.value.trim() !== "启用自动故障切换") {
    elements.providerFailoverError.textContent = "请输入“启用自动故障切换”完成确认";
    return;
  }
  state.providerRoutingSaving = true;
  elements.providerFailoverError.textContent = "";
  renderProviderFailover();
  try {
    const eligibleKeys = new Set(
      state.providerRouting.targets
        .filter((target) => target.eligible === true)
        .map((target) => target.key),
    );
    const response = await fetch("/api/providers/failover", {
      method: "PUT",
      headers: {
        "Content-Type": "application/json",
        "X-Codex-Desktop-Action": "provider-failover-settings",
      },
      body: JSON.stringify({
        automaticFailover,
        priority: state.providerRoutingDraftPriority.filter((key) => eligibleKeys.has(key)),
        acknowledgeIdentityAndBilling: enabling && elements.providerFailoverAcknowledge.checked,
        confirmation: enabling ? elements.providerFailoverConfirmation.value.trim() : "",
      }),
    });
    const data = await readApiJson(response, "无法保存账号与 API 路由");
    state.providerRoutingDirty = false;
    applyProviderRoutingSnapshot(data, { preserveDraft: false });
    elements.providerFailoverAcknowledge.checked = false;
    elements.providerFailoverConfirmation.value = "";
    toast(automaticFailover ? "自动故障切换已开启" : "账号与 API 路由已保存");
  } catch (error) {
    elements.providerFailoverError.textContent = error.message;
  } finally {
    state.providerRoutingSaving = false;
    renderProviderFailover();
  }
}

function providerCredentialLabel(value) {
  return {
    configured: "凭据已配置",
    valid: "登录有效",
    unknown: "状态待检查",
    missing: "缺少凭据",
    invalid: "登录已失效",
  }[value] || "状态未知";
}

function providerFailoverReasonLabel(value) {
  return {
    manual: "手动切换",
    connectivity: "连接异常",
    credentials: "凭据失效",
    quota: "额度用尽",
    "provider-repaired": "API 已修复",
    "official-login": "登录已恢复",
  }[value] || "路由变更";
}

function codexFailureMessage(error) {
  return error?.message || error?.additionalDetails || "Codex 发生错误";
}

function providerFailoverResultLabel(value) {
  return {
    queued: "等待切换",
    skipped: "已取消",
    switched: "切换成功",
    restored: "已恢复原供应商",
    failed: "尝试失败",
    exhausted: "无可用目标",
  }[value] || "状态更新";
}

function formatProviderRoutingTime(value) {
  const timestamp = Number(value);
  if (!Number.isFinite(timestamp) || timestamp <= 0) return "--";
  return new Date(timestamp).toLocaleString(interfaceLocale(), { hour12: false });
}

function loadProviderProfiles() {
  if (state.providerProfilesRequest) return state.providerProfilesRequest;
  const request = fetchProviderProfiles().finally(() => {
    if (state.providerProfilesRequest === request) state.providerProfilesRequest = null;
  });
  state.providerProfilesRequest = request;
  return request;
}

function loadProviderUsage({ force = false } = {}) {
  const accountId = state.account?.id || null;
  if (state.providerUsageRequest && state.providerUsageRequestAccountId === accountId) {
    return state.providerUsageRequest;
  }
  const generation = state.providerUsageGeneration;
  const query = force ? "?refresh=1" : "";
  const request = fetchWithTimeout(`/api/providers/usage${query}`, { cache: "no-store" }, 20_000)
    .then(async (response) => {
      const data = await readApiJson(response, "无法查询供应商额度");
      // Logout/account switching can happen while the old request is in
      // flight. Never let that response populate the next account's provider panel.
      if (
        generation !== state.providerUsageGeneration
        || accountId !== (state.account?.id || null)
      ) return null;
      state.providerUsage = {
        providers: Array.isArray(data.providers) ? data.providers : [],
        updatedAt: Number.isFinite(Number(data.updatedAt)) ? Number(data.updatedAt) : Date.now(),
      };
      state.providerUsageAccountId = accountId;
      renderProviderQuickMenu();
      updateProviderQuickChrome();
      renderThreadProviderBinding();
      return data;
    })
    .catch((error) => {
      if (force) throw error;
      return null;
    })
    .finally(() => {
      if (state.providerUsageRequest === request) {
        state.providerUsageRequest = null;
        state.providerUsageRequestAccountId = null;
      }
    });
  state.providerUsageRequest = request;
  state.providerUsageRequestAccountId = accountId;
  return request;
}

function resetProviderUsageState(accountId = null) {
  state.providerUsageGeneration += 1;
  state.providerUsageRequest = null;
  state.providerUsageRequestAccountId = null;
  state.providerUsageAccountId = accountId;
  state.providerUsage = { providers: [], updatedAt: 0 };
  state.providerQuickStatusUpdatedAt = 0;
  renderProviderQuickMenu();
}

async function fetchProviderProfiles() {
  try {
    const response = await fetchWithTimeout("/api/providers", { cache: "no-store" }, 10_000);
    const data = await response.json();
    if (!response.ok) throw new Error(data.error || "无法读取 API 供应商");
    state.providers = data.profiles || [];
    state.activeProviderId = data.activeId || null;
    state.fallbackProvider = data.fallback || null;
    state.currentProviderId = data.currentProviderId || state.config.model_provider || null;
    state.currentProviderModel = data.currentModel || state.config.model || null;
    state.currentProvider = data.currentProvider || null;
    state.providerCanEdit = data.canEdit === true;
    state.providerConfigurationRequired = data.configurationRequired === true;
    applyProviderRoutingSnapshot(data.routing, { preserveDraft: false });
    state.providerProfilesLoadedAt = Date.now();
    if (state.models.length) {
      mergeDiscoveredProviderModels(currentProviderModelCatalogId());
      populateModelSelects();
    }
    state.imageApi = data.imageApi || {
      configured: false,
      providerId: null,
      providerName: null,
      model: "gpt-image-2",
      size: "1024x1024",
      quality: "auto",
    };
    elements.addProviderButton.hidden = !canEditProviderProfiles();
    elements.accountAddProviderButton.hidden = !canEditProviderProfiles();
    setTurnBusy(conversationBusy(), conversationBusyLabel());
    renderProviderContext();
    renderThreadProviderBinding();
    if (elements.providerDialog.open) {
      renderProviderList();
      if (
        state.editingProviderId &&
        state.editingProviderId !== "default" &&
        state.editingProviderId !== "image-api" &&
        !state.providers.some((profile) => profile.id === state.editingProviderId)
      ) {
        newProviderProfile();
      } else if (state.editingProviderId === "default") {
        selectProviderProfile("default");
      } else if (state.editingProviderId === "image-api") {
        selectProviderProfile("image-api");
      } else if (state.editingProviderId) {
        selectProviderProfile(state.editingProviderId);
      }
    }
    refreshImageGenerationControl();
    const catalogId = currentProviderModelCatalogId();
    if (catalogId && !Object.hasOwn(state.providerModelCatalogs, catalogId)) {
      void queryProviderModels(catalogId, "auto", { announce: false });
    }
  } catch (error) {
    if (elements.providerDialog.open) {
      elements.providerList.innerHTML = '<div class="list-empty">无法读取供应商</div>';
      toast(error.message, "error");
    }
  }
}

function renderProviderContext() {
  if (state.runtime === "claude") {
    renderClaudeQuickSwitcher();
    elements.sendButton.title = "发送";
    return;
  }
  const active = state.providers.find((profile) => profile.id === state.activeProviderId);
  const label = state.providerConfigurationRequired
    ? "未配置 API"
    : active?.name || state.currentProvider?.name || state.currentProviderId || state.config.model_provider || "Codex 配置";
  renderProviderQuickSwitcher(label);
  elements.sendButton.title = state.providerConfigurationRequired ? "需要先配置 API 供应商" : "发送";
}

function renderProviderQuickSwitcher(currentLabel) {
  const defaultLabel = state.activeProviderId
    ? `Codex 原配置 · ${state.fallbackProvider?.providerId || "默认"}`
    : currentLabel;
  const profiles = state.providers.filter((profile) => (
    state.activeProviderId || profile.id !== state.currentProvider?.editableProfileId
  ));
  const options = [
    dataOption(defaultLabel, "default"),
    ...profiles.map((profile) => dataOption(profile.name, profile.id)),
  ];
  if (canEditProviderProfiles()) options.push(new Option("设置供应商", ADD_PROVIDER_OPTION));
  elements.providerQuickSelect.replaceChildren(...options);
  elements.providerQuickSelect.value = state.activeProviderId || "default";
  elements.providerQuickSelect.disabled = state.providerConfigurationRequired
    && !state.providers.length
    && !canEditProviderProfiles();
  updateProviderQuickChrome();
}

function updateProviderQuickChrome() {
  const active = providerQuickEntries().find((entry) => entry.active);
  const selected = elements.providerQuickSelect.selectedOptions?.[0];
  const baseLabel = active?.label || selected?.textContent || (state.runtime === "claude" ? "Claude 连接" : "Codex 连接");
  const label = providerQuickCompactLabel(active, baseLabel);
  elements.providerQuickLabel.textContent = label;
  elements.providerQuickButton.title = conversationBusy()
    ? `${label} · 任务执行中可查看额度`
    : `${label} · 查看或切换连接`;
  elements.providerQuickButton.setAttribute("aria-label", elements.providerQuickButton.title);
  renderProviderQuickMenu();
}

function providerQuickCompactLabel(entry, fallback) {
  if (!entry) return fallback;
  const usageText = providerQuickUsageText(entry);
  if (usageText) return `${entry.label} · ${usageText}`;
  return entry.label || fallback;
}

function providerQuickUsageText(entry) {
  const balance = entry?.providerUsage?.balance;
  if (balance) return formatProviderBalance(balance);
  const windows = (entry.quotaWindows || [])
    .filter((window) => Number.isFinite(Number(window.usedPercent)));
  const primary = windows.find((window) => window.label === "5 小时") || windows[0];
  if (primary) {
    const label = String(primary.label || "额度").replace(/\s+/gu, "");
    return `${label} ${Math.round(Number(primary.usedPercent))}%`;
  }
  return null;
}

function providerQuickEntries() {
  return state.runtime === "claude" ? claudeProviderQuickEntries() : codexProviderQuickEntries();
}

function providerUsageForTarget(target) {
  if (target?.kind !== "managed") return null;
  if (
    state.providerUsageAccountId
    && state.providerUsageAccountId !== (state.account?.id || null)
  ) return null;
  return (state.providerUsage?.providers || []).find((entry) => entry.providerId === target.id) || null;
}

function codexProviderQuickEntries() {
  const targets = Array.isArray(state.providerRouting?.targets) ? state.providerRouting.targets : [];
  if (targets.length) {
    return targets.map((target) => {
      const providerUsage = providerUsageForTarget(target);
      return {
        key: target.key || `${target.kind}:${target.id}`,
        kind: target.kind,
        value: target.kind === "managed" ? target.id : target.kind === "default" ? "default" : null,
        label: target.accountLabel || target.label,
        detail: target.kind === "official"
          ? `${officialPlanLabel(officialAccountPlanForTarget(target))} · OpenAI 官方账号`
          : target.kind === "managed"
            ? [target.model, "API 供应商"].filter(Boolean).join(" · ")
            : [target.model, "Codex 原配置"].filter(Boolean).join(" · "),
        active: target.active === true,
        eligible: target.eligible === true,
        credentialStatus: target.credentialStatus || "unknown",
        disabledReason: target.disabledReason || null,
        checkedAt: target.checkedAt || null,
        providerUsage,
        quotaWindows: target.kind === "managed" && providerUsage
          ? providerUsage.windows || []
          : codexQuotaWindowsForTarget(target),
      };
    });
  }
  const activeId = state.activeProviderId || "default";
  return [...elements.providerQuickSelect.options]
    .filter((option) => option.value !== ADD_PROVIDER_OPTION && option.value !== "restricted")
    .map((option) => {
      const providerUsage = option.value === "default"
        ? null
        : providerUsageForTarget({ kind: "managed", id: option.value });
      return {
        key: `fallback:${option.value}`,
        kind: option.value === "default" ? "default" : "managed",
        value: option.value,
        label: option.textContent,
        detail: option.value === "default" ? "Codex 原配置" : "API 供应商",
        active: option.value === activeId,
        eligible: true,
        credentialStatus: "unknown",
        disabledReason: null,
        checkedAt: null,
        providerUsage,
        quotaWindows: providerUsage?.windows || [],
      };
    });
}

function officialAccountPlanForTarget(target) {
  const accounts = Array.isArray(state.officialAccount?.accounts) ? state.officialAccount.accounts : [];
  const account = accounts.find((entry) => entry.id === (target.accountId || target.id));
  return account?.planType || (target.active ? state.accountOfficialQuota?.account?.planType : null) || "unknown";
}

function codexQuotaWindowsForTarget(target) {
  if (target.kind !== "official") return [];
  if (target.active) {
    const windows = [];
    const seen = new Set();
    for (const bucket of state.accountOfficialQuota?.rateLimits?.buckets || []) {
      for (const window of [bucket.primary, bucket.secondary]) {
        if (!window || !Number.isFinite(Number(window.usedPercent))) continue;
        const duration = Number(window.windowDurationMins) || 0;
        const key = `${duration}:${window.resetsAt || ""}`;
        if (seen.has(key)) continue;
        seen.add(key);
        windows.push({
          label: providerQuotaWindowLabel(duration),
          usedPercent: Number(window.usedPercent),
          resetsAt: window.resetsAt || null,
        });
      }
    }
    if (windows.length) return windows.slice(0, 3);
  }
  if (Number.isFinite(Number(target.quotaUsedPercent))) {
    return [{ label: "7 天", usedPercent: Number(target.quotaUsedPercent), resetsAt: null }];
  }
  return [];
}

function claudeProviderQuickEntries() {
  const config = state.claudeConfig || {};
  const activeProfileId = config.activeId || null;
  const activeOfficialId = config.official?.activeId || null;
  const profiles = Array.isArray(config.profiles) ? config.profiles : [];
  const accounts = Array.isArray(config.official?.accounts) ? config.official.accounts : [];
  return [
    ...accounts.map((account) => ({
      key: `official:${account.id}`,
      kind: "official",
      value: account.credentialStatus === "valid" ? `official:${account.id}` : null,
      label: account.email || account.label || "Claude 官方账号",
      detail: [account.subscriptionType, "Claude 官方账号"].filter(Boolean).join(" · "),
      active: !activeProfileId && (account.id === activeOfficialId || account.active === true),
      eligible: account.credentialStatus === "valid",
      credentialStatus: account.credentialStatus || "unknown",
      disabledReason: account.credentialStatus === "invalid" ? "登录已失效" : null,
      checkedAt: account.quota?.updatedAt || account.lastCheckedAt || account.updatedAt || null,
      quotaWindows: (account.quota?.windows || []).map((window) => ({
        label: claudeQuotaWindowLabel(window.type),
        usedPercent: Number.isFinite(Number(window.utilization)) ? Number(window.utilization) * 100 : null,
        resetsAt: window.resetsAt || null,
      })),
    })),
    ...profiles.map((profile) => ({
      key: `managed:${profile.id}`,
      kind: "managed",
      value: profile.id,
      label: profile.name,
      detail: [profile.model, "API 供应商"].filter(Boolean).join(" · "),
      active: profile.id === activeProfileId,
      eligible: true,
      credentialStatus: profile.hasApiKey === false ? "missing" : "configured",
      disabledReason: profile.hasApiKey === false ? "API 密钥未配置" : null,
      checkedAt: profile.updatedAt || null,
      quotaWindows: [],
    })),
  ];
}

function providerQuotaWindowLabel(minutes) {
  if (minutes === 5 * 60) return "5 小时";
  if (minutes === 7 * 24 * 60) return "7 天";
  return minutes > 0 ? formatWindowDuration(minutes) : "额度";
}

function claudeQuotaWindowLabel(type) {
  return {
    five_hour: "5 小时",
    seven_day: "7 天",
    seven_day_opus: "7 天 Opus",
    seven_day_sonnet: "7 天 Sonnet",
    seven_day_overage_included: "7 天加量",
    overage: "超额用量",
  }[type] || "额度";
}

function renderProviderQuickMenu() {
  if (!elements.providerQuickMenu || !elements.providerQuickList) return;
  const entries = providerQuickEntries();
  const busy = conversationBusy();
  elements.providerQuickSummary.textContent = state.providerQuickStatusLoading
    ? "正在刷新连接与额度"
    : `${entries.length} 个连接 · ${busy ? "任务中只读" : "当前空闲"}`
      + (state.providerUsage?.updatedAt ? ` · 额度更新于 ${formatProviderUsageTime(state.providerUsage.updatedAt)}` : "");
  elements.providerQuickHint.textContent = busy
    ? "当前任务继续使用原连接；任务结束或暂停后才能切换。额度查询只读，不影响运行中的任务。"
    : "支持的供应商自动读取余额或时间窗口；未提供接口的供应商明确显示不可查询，不推测数值。";
  elements.providerQuickRefreshButton.disabled = state.providerQuickStatusLoading;
  elements.providerQuickRefreshButton.classList.toggle("refreshing", state.providerQuickStatusLoading);
  elements.providerQuickList.replaceChildren();
  if (!entries.length) {
    const empty = document.createElement("div");
    empty.className = "provider-quick-empty";
    empty.textContent = "当前账号没有可查看的供应商或官方账号";
    elements.providerQuickList.append(empty);
    refreshIcons();
    return;
  }
  for (const entry of entries) {
    elements.providerQuickList.append(createProviderQuickRow(entry, busy));
  }
  refreshIcons();
}

function createProviderQuickRow(entry, busy) {
  const row = document.createElement("button");
  row.type = "button";
  row.className = "provider-quick-row";
  row.dataset.active = String(entry.active === true);
  row.dataset.status = entry.credentialStatus || "unknown";
  row.dataset.usageStatus = entry.providerUsage?.status || "unknown";
  if (entry.value) row.dataset.providerValue = entry.value;
  const canSwitch = !busy && !entry.active && entry.eligible && Boolean(entry.value);
  row.disabled = !canSwitch;
  row.setAttribute("role", "menuitem");

  const identity = document.createElement("span");
  identity.className = "provider-quick-identity";
  const heading = document.createElement("span");
  const icon = document.createElement("i");
  icon.setAttribute("data-lucide", entry.kind === "official" ? "badge-user" : entry.kind === "managed" ? "plug-zap" : "settings-2");
  const label = document.createElement("strong");
  label.textContent = entry.label || "未命名连接";
  const badge = document.createElement("em");
  badge.textContent = entry.active ? (busy ? "任务使用中" : "当前") : providerCredentialLabel(entry.credentialStatus);
  heading.append(icon, label, badge);
  const detail = document.createElement("small");
  detail.textContent = entry.disabledReason || entry.detail || providerCredentialLabel(entry.credentialStatus);
  identity.append(heading, detail);

  const quota = document.createElement("span");
  quota.className = "provider-quick-quota";
  if (entry.providerUsage?.balance) {
    quota.append(createProviderQuickBalance(entry.providerUsage.balance));
  }
  const windows = (entry.quotaWindows || []).filter((window) => Number.isFinite(Number(window.usedPercent)));
  if (!windows.length) {
    if (!entry.providerUsage?.balance) {
      const unavailable = document.createElement("small");
      unavailable.textContent = entry.providerUsage?.message
        || (entry.kind === "managed" ? "供应商未提供额度接口" : "额度暂不可用");
      quota.append(unavailable);
    }
  } else {
    for (const window of windows) quota.append(createProviderQuickQuota(window));
  }
  const action = document.createElement("span");
  action.className = "provider-quick-action";
  action.innerHTML = entry.active
    ? '<i data-lucide="check"></i>'
    : canSwitch
      ? '<span>切换</span><i data-lucide="chevron-right"></i>'
      : entry.kind === "official" && !entry.value
        ? '<span>只读</span>'
        : '<i data-lucide="lock-keyhole"></i>';
  row.append(identity, quota, action);
  row.title = [
    entry.label,
    entry.active ? "当前连接" : canSwitch ? "切换到此连接" : busy ? "任务执行中只读" : entry.disabledReason,
    entry.checkedAt ? `更新时间：${formatProviderRoutingTime(entry.checkedAt)}` : null,
    entry.providerUsage?.updatedAt ? `额度更新时间：${formatProviderUsageTime(entry.providerUsage.updatedAt)}` : null,
    entry.providerUsage?.usage?.todayRequests != null
      ? `今日请求：${entry.providerUsage.usage.todayRequests}`
      : null,
  ].filter(Boolean).join(" · ");
  return row;
}

function createProviderQuickBalance(balance) {
  const item = document.createElement("span");
  item.className = "provider-quick-balance";
  const label = document.createElement("span");
  label.textContent = balance.remaining != null && balance.amount !== balance.remaining ? "剩余" : "余额";
  const amount = document.createElement("strong");
  amount.textContent = formatProviderBalance(balance);
  item.append(label, amount);
  return item;
}

function createProviderQuickQuota(window) {
  const item = document.createElement("span");
  item.className = "provider-quick-quota-window";
  const used = Math.max(0, Math.min(100, Number(window.usedPercent) || 0));
  const heading = document.createElement("span");
  heading.innerHTML = `<span></span><strong>${Math.round(used)}%</strong>`;
  heading.querySelector("span").textContent = window.label || "额度";
  const track = document.createElement("span");
  track.className = "provider-quick-quota-track";
  const fill = document.createElement("span");
  fill.style.width = `${used}%`;
  fill.dataset.level = usageLevel(used);
  track.append(fill);
  item.append(heading, track);
  if (window.resetsAt) {
    const reset = document.createElement("small");
    reset.textContent = `重置 ${formatProviderUsageTime(window.resetsAt)}`;
    item.append(reset);
  }
  item.title = [
    window.label || "额度",
    `已用 ${Math.round(used)}%`,
    window.resetsAt ? `重置于 ${formatProviderUsageTime(window.resetsAt)}` : null,
  ].filter(Boolean).join(" · ");
  return item;
}

function formatProviderBalance(balance) {
  const amount = Number(balance?.remaining ?? balance?.amount);
  if (!Number.isFinite(amount)) return "--";
  const currency = String(balance?.currency || "").toUpperCase();
  const formatted = amount.toLocaleString(interfaceLocale(), {
    minimumFractionDigits: 0,
    maximumFractionDigits: 4,
  });
  if (currency === "USD") return `$${formatted}`;
  if (currency === "CNY" || currency === "RMB") return `¥${formatted}`;
  return `${formatted} ${balance?.currency || ""}`.trim();
}

function formatProviderUsageTime(value) {
  const timestamp = typeof value === "number" ? value : Date.parse(String(value || ""));
  if (!Number.isFinite(timestamp)) return "--";
  return new Date(timestamp).toLocaleString(interfaceLocale(), { hour12: false });
}

function toggleProviderQuickMenu() {
  if (elements.providerQuickMenu.hidden) openProviderQuickMenu();
  else closeProviderQuickMenu();
}

function openProviderQuickMenu() {
  renderProviderQuickMenu();
  elements.providerQuickMenu.hidden = false;
  elements.providerQuickButton.setAttribute("aria-expanded", "true");
  positionProviderQuickMenu();
  if (Date.now() - state.providerQuickStatusUpdatedAt > 30_000) {
    void refreshProviderQuickStatus();
  }
}

function closeProviderQuickMenu() {
  elements.providerQuickMenu.hidden = true;
  elements.providerQuickButton.setAttribute("aria-expanded", "false");
}

function positionProviderQuickMenu() {
  if (!elements.providerQuickMenu || elements.providerQuickMenu.hidden) return;
  elements.providerQuickMenu.style.removeProperty("left");
  elements.providerQuickMenu.style.removeProperty("top");
  elements.providerQuickMenu.style.removeProperty("right");
  elements.providerQuickMenu.style.removeProperty("bottom");
  if (matchMedia("(max-width: 600px)").matches) return;
  const trigger = elements.providerQuickButton.getBoundingClientRect();
  const menu = elements.providerQuickMenu.getBoundingClientRect();
  const left = Math.max(8, Math.min(window.innerWidth - menu.width - 8, trigger.left));
  const below = trigger.bottom + 6;
  const top = below + menu.height <= window.innerHeight - 8
    ? below
    : Math.max(8, trigger.top - menu.height - 6);
  elements.providerQuickMenu.style.left = `${Math.round(left)}px`;
  elements.providerQuickMenu.style.top = `${Math.round(top)}px`;
}

function handleProviderQuickOutsidePointer(event) {
  if (elements.providerQuickMenu.hidden) return;
  const target = event.target instanceof Node ? event.target : null;
  if (target && elements.providerQuickSwitcher.contains(target)) return;
  closeProviderQuickMenu();
}

function handleProviderQuickKeydown(event) {
  if (event.key !== "Escape" || elements.providerQuickMenu.hidden) return;
  closeProviderQuickMenu();
  elements.providerQuickButton.focus();
}

async function refreshProviderQuickStatus({ force = false } = {}) {
  if (state.providerQuickStatusLoading) return;
  state.providerQuickStatusLoading = true;
  renderProviderQuickMenu();
  try {
    if (state.runtime === "claude") {
      await loadClaudeConfig();
    } else {
      const jobs = [loadProviderRouting({ silent: true }), loadAccountOfficialQuota({
        refresh: force && !conversationBusy(),
      }), loadProviderUsage({ force })];
      if (force || Date.now() - state.providerProfilesLoadedAt > 30_000) jobs.push(loadProviderProfiles());
      await Promise.all(jobs);
    }
    state.providerQuickStatusUpdatedAt = Date.now();
  } catch (error) {
    if (force) toast(error.message, "error");
  } finally {
    state.providerQuickStatusLoading = false;
    updateProviderQuickChrome();
    if (!elements.providerQuickMenu.hidden) positionProviderQuickMenu();
  }
}

async function handleProviderQuickMenuClick(event) {
  const button = event.target.closest("[data-provider-value]");
  if (!button || button.disabled || conversationBusy()) return;
  const value = button.dataset.providerValue;
  closeProviderQuickMenu();
  elements.providerQuickButton.disabled = true;
  try {
    if (state.runtime === "claude") {
      elements.providerQuickSelect.value = value;
      await switchClaudeProviderFromHome();
    } else if (value === "default") {
      await activateDefaultProvider({ preferOfficial: false });
    } else {
      await activateProviderProfile(value);
    }
    await refreshProviderQuickStatus();
  } catch (error) {
    toast(error.message, "error");
  } finally {
    elements.providerQuickButton.disabled = false;
    updateProviderQuickChrome();
  }
}

async function openProviderSettingsFromQuickMenu() {
  closeProviderQuickMenu();
  state.providerDialogRuntime = state.runtime;
  await openProviderDialog();
}

async function switchProviderFromHome() {
  if (conversationBusy()) {
    toast("请先等待当前任务结束再切换供应商", "error");
    renderProviderContext();
    return;
  }
  if (state.runtime === "claude") {
    await switchClaudeProviderFromHome();
    return;
  }
  const targetId = elements.providerQuickSelect.value;
  const currentId = state.activeProviderId || "default";
  if (targetId === ADD_PROVIDER_OPTION) {
    renderProviderContext();
    await openProviderDialog();
    newProviderProfile();
    return;
  }
  if (!targetId || targetId === currentId) return;
  elements.providerQuickSelect.disabled = true;
  try {
    if (targetId === "default") await activateDefaultProvider({ preferOfficial: false });
    else await activateProviderProfile(targetId);
  } catch (error) {
    toast(error.message, "error");
  } finally {
    renderProviderContext();
  }
}

async function switchClaudeProviderFromHome() {
  const targetId = elements.providerQuickSelect.value;
  if (targetId === ADD_PROVIDER_OPTION) {
    if (!canUseClaudeProviders()) {
      toast("管理员尚未授权当前账号管理 Claude API 供应商", "error");
      renderClaudeQuickSwitcher();
      return;
    }
    state.providerDialogRuntime = "claude";
    await openProviderDialog();
    newClaudeProvider();
    return;
  }
  const currentId = state.claudeConfig?.activeId
    || (state.claudeConfig?.official?.activeId
      ? `official:${state.claudeConfig.official.activeId}`
      : "official");
  if (!targetId || targetId === currentId) return;
  elements.providerQuickSelect.disabled = true;
  try {
    if (targetId.startsWith("official:")) {
      if (!canUseClaudeOfficialLogin()) throw new Error("管理员尚未授权 Claude 官方账号");
      await activateClaudeOfficialAccount(targetId.slice("official:".length));
    } else if (targetId === "official") {
      await activateClaudeDefaultProvider();
    } else {
      if (!canUseClaudeProviders()) throw new Error("管理员尚未授权当前账号切换 Claude API 供应商");
      await activateClaudeProvider(targetId);
    }
  } catch (error) {
    toast(error.message, "error");
  } finally {
    renderClaudeQuickSwitcher();
  }
}

async function openProviderDialog() {
  ensureClaudeSettingsView();
  const runtime = state.providerDialogRuntime || state.runtime;
  state.providerDialogRuntime = runtime;
  const isClaude = runtime === "claude";
  if (isClaude && !canUseClaudeRuntime()) {
    toast("管理员尚未授权当前账号使用 Claude Code", "error");
    return;
  }
  elements.providerDialogEyebrow.textContent = isClaude ? "Claude Code" : "连接配置";
  elements.providerDialogTitle.textContent = isClaude ? "Claude 设置" : "API 供应商";
  elements.providerDialog.setAttribute("data-runtime", runtime);
  elements.providerWorkspace?.toggleAttribute("hidden", isClaude);
  elements.claudeProviderWorkspace.hidden = !isClaude;
  if (isClaude) {
    elements.providerList.innerHTML = "";
    elements.addProviderButton.hidden = true;
    elements.claudeProviderWorkspace.hidden = false;
    selectClaudeSettingsTab(state.claudeSettingsTab);
    selectClaudeExtensionTab(state.claudeExtensionTab);
    const requests = [loadClaudeConfig().catch(() => {})];
    if (canUseClaudeExtensions()) {
      requests.push(loadClaudeExtensions().catch(() => {}));
    }
    if (canUseClaudeMemory()) requests.push(loadClaudeMemory().catch(() => {}));
    if (canUseClaudeHooks()) requests.push(loadClaudeHooks().catch(() => {}));
    await Promise.all(requests);
    // Do not expose editable Claude forms until their initial snapshot has
    // arrived. Otherwise a slow plugin/extension query can overwrite fields
    // filled immediately after the dialog opens and make the first save look
    // like a lost request.
    if (!elements.providerDialog.open) elements.providerDialog.showModal();
    return;
  }
  state.editingProviderId = state.activeProviderId || "default";
  elements.addProviderButton.hidden = !canEditProviderProfiles();
  elements.providerList.innerHTML = '<div class="list-loading">正在读取供应商</div>';
  elements.providerDialog.showModal();
  await loadProviderProfiles();
  renderProviderList();
  if (state.activeProviderId) selectProviderProfile(state.activeProviderId);
  else selectProviderProfile("default");
}

function renderProviderList() {
  elements.providerList.replaceChildren();
  const defaultRow = createProviderRow(
    "default",
    state.fallbackProvider ? "Codex 原配置" : "Codex 当前配置",
    state.fallbackProvider?.providerId || state.currentProviderId || "默认",
    !state.activeProviderId,
    "rotate-ccw",
    false,
    Boolean(state.fallbackProvider?.providerId || state.currentProviderId),
  );
  elements.providerList.append(defaultRow);
  elements.providerList.append(createProviderRow(
    "image-api",
    "图片生成",
    state.imageApi.configured
      ? `${state.imageApi.providerName || "旧独立配置"} · ${state.imageApi.model}`
      : "未选择图片供应商",
    state.imageApi.configured,
    "image",
    false,
    state.imageApi.configured,
  ));
  for (const profile of state.providers) {
    elements.providerList.append(
      createProviderRow(
        profile.id,
        profile.name,
        `${profile.model || "模型由主页选择"} · ${profile.hasApiKey ? "密钥已配置" : "本地无密钥"}`,
        profile.id === state.activeProviderId,
        "server",
        true,
        true,
      ),
    );
  }
  refreshIcons();
}

function createProviderRow(id, name, detail, active, icon, protectedName = false, protectedDetail = false) {
  const button = document.createElement("button");
  button.type = "button";
  button.className = `provider-row${active ? " active" : ""}${state.editingProviderId === id ? " selected" : ""}`;
  button.innerHTML = `<span class="provider-row-icon"><i data-lucide="${icon}"></i></span><span class="provider-row-copy"><strong></strong><span></span></span><span class="provider-row-status"></span>`;
  setDataContent(button.querySelector("strong"), name, protectedName);
  setDataContent(button.querySelector(".provider-row-copy span"), detail, protectedDetail);
  button.addEventListener("click", () => selectProviderProfile(id));
  return button;
}

function selectProviderProfile(id) {
  state.editingProviderId = id;
  renderProviderList();
  clearProviderKeyInput();
  elements.providerFormError.textContent = "";
  const isDefault = id === "default";
  const isImageApi = id === "image-api";
  elements.providerForm.hidden = isDefault || isImageApi;
  elements.imageApiForm.hidden = !isImageApi;
  elements.providerDefaultView.hidden = !isDefault;
  if (isImageApi) {
    renderImageApiSettings();
    return;
  }
  if (isDefault) {
    const providerId = state.fallbackProvider?.providerId || state.currentProviderId || "默认";
    const model = state.fallbackProvider?.model || state.currentProviderModel || "由 Codex 决定";
    setDataContent(elements.providerDefaultSummary, `${providerId} · ${model}`);
    elements.activateDefaultProviderButton.hidden = !canEditProviderProfiles();
    elements.activateDefaultProviderButton.disabled = !state.activeProviderId || !state.fallbackProvider;
    elements.activateDefaultProviderButton.querySelector("span").textContent = state.activeProviderId
      ? "切回原配置"
      : "当前使用";
    const canEditCurrent = canEditProviderProfiles()
      && !state.activeProviderId
      && Boolean(state.currentProvider?.baseUrl);
    elements.editCurrentProviderButton.hidden = !canEditCurrent;
    elements.editCurrentProviderButton.querySelector("span").textContent = state.currentProvider?.editableProfileId
      ? "编辑当前 API"
      : "接管当前 API";
    renderProviderFailover();
    refreshIcons();
    void loadOfficialAccount({ silent: true });
    void loadProviderRouting({ silent: true });
    return;
  }

  const profile = state.providers.find((entry) => entry.id === id);
  if (!profile) {
    newProviderProfile();
    return;
  }
  elements.providerNameInput.value = profile.name;
  elements.providerBaseUrlInput.value = profile.baseUrl;
  elements.providerModelInput.value = profile.model || "";
  renderProviderModelOptions(profile.id);
  setDataContent(elements.providerEditorTitle, profile.name);
  elements.providerEditorStatus.textContent = profile.id === state.activeProviderId ? "当前使用" : "已保存";
  elements.providerKeyStatus.textContent = profile.hasApiKey ? "已配置，留空则保留" : "未配置";
  elements.providerApiKeyInput.placeholder = profile.hasApiKey ? "留空则保留已保存密钥" : "输入新的 API Key";
  elements.providerModelsRefreshButton.disabled = false;
  const canEdit = canEditProviderProfiles();
  for (const input of [elements.providerNameInput, elements.providerBaseUrlInput, elements.providerModelInput, elements.providerApiKeyInput]) {
    input.disabled = !canEdit;
  }
  elements.deleteProviderButton.hidden = !canEdit;
  elements.deleteProviderButton.disabled = profile.id === state.activeProviderId;
  elements.deleteProviderButton.title = "";
  elements.saveProviderButton.hidden = !canEdit || profile.id === state.activeProviderId;
  elements.activateProviderButton.querySelector("span").textContent = canEdit
    ? profile.id === state.activeProviderId ? "保存并重新启用" : "保存并启用"
    : profile.id === state.activeProviderId ? "当前使用" : "启用";
  elements.activateProviderButton.disabled = !canEdit && profile.id === state.activeProviderId;
  refreshIcons();
}

function newProviderProfile() {
  if (!canEditProviderProfiles()) return;
  state.editingProviderId = null;
  elements.providerForm.hidden = false;
  elements.imageApiForm.hidden = true;
  elements.providerDefaultView.hidden = true;
  elements.providerForm.reset();
  elements.providerModelInput.value = "";
  elements.providerModelOptions.replaceChildren();
  elements.providerModelCatalogSelect.replaceChildren();
  elements.providerModelCatalogSelect.hidden = true;
  elements.providerModelsRefreshButton.disabled = true;
  setDataContent(elements.providerEditorTitle, "供应商设置", false);
  elements.providerEditorStatus.textContent = "未保存";
  elements.providerKeyStatus.textContent = "未配置";
  elements.providerApiKeyInput.placeholder = "输入新的 API Key";
  elements.providerFormError.textContent = "";
  elements.deleteProviderButton.hidden = true;
  elements.saveProviderButton.hidden = false;
  elements.activateProviderButton.querySelector("span").textContent = "保存并启用";
  renderProviderList();
  requestAnimationFrame(() => elements.providerNameInput.focus());
}

function editCurrentProviderConfiguration() {
  const current = state.currentProvider;
  if (!current || state.activeProviderId || !canEditProviderProfiles()) return;
  const existing = state.providers.find((profile) => profile.id === current.editableProfileId);
  if (existing) {
    selectProviderProfile(existing.id);
    return;
  }
  newProviderProfile();
  elements.providerNameInput.value = current.name || current.id || "当前 API";
  elements.providerBaseUrlInput.value = current.baseUrl || "";
  elements.providerModelInput.value = current.model || state.currentProviderModel || "";
  elements.providerModelOptions.replaceChildren();
  elements.providerModelCatalogSelect.replaceChildren();
  elements.providerModelCatalogSelect.hidden = true;
  elements.providerModelsRefreshButton.disabled = true;
  setDataContent(elements.providerEditorTitle, "接管当前 API 配置", false);
  elements.providerEditorStatus.textContent = "需要保存并启用";
  elements.providerKeyStatus.textContent = "请重新输入";
  elements.providerApiKeyInput.placeholder = "现有密钥不可读取，请重新输入 API Key";
  requestAnimationFrame(() => elements.providerApiKeyInput.focus());
}

async function activateAssignedProvider() {
  const id = state.editingProviderId;
  if (!id || id === "default") return;
  try {
    const response = await fetch(`/api/providers/${encodeURIComponent(id)}/activate`, { method: "POST" });
    const data = await response.json();
    if (!response.ok) throw new Error(data.error || "无法启用供应商");
    await loadProviderProfiles();
    selectProviderProfile(id);
    toast("API 供应商已切换");
  } catch (error) {
    elements.providerFormError.textContent = error.message;
  }
}

async function saveProviderProfile({ activate = false } = {}) {
  if (!elements.providerForm.reportValidity()) return;
  const existingId = state.editingProviderId;
  const payload = {
    name: elements.providerNameInput.value.trim(),
    baseUrl: elements.providerBaseUrlInput.value.trim(),
    model: elements.providerModelInput.value.trim(),
    apiKey: elements.providerApiKeyInput.value.trim(),
  };
  setProviderFormBusy(true);
  elements.providerFormError.textContent = "";
  try {
    const response = await fetch(existingId ? `/api/providers/${encodeURIComponent(existingId)}` : "/api/providers", {
      method: existingId ? "PUT" : "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify(payload),
    });
    const data = await response.json();
    if (!response.ok) throw new Error(data.error || "无法保存 API 供应商");
    state.editingProviderId = data.profile.id;
    clearProviderKeyInput();
    await loadProviderProfiles();
    if (activate) await activateProviderProfile(data.profile.id);
    else toast("API 供应商已保存");
  } catch (error) {
    elements.providerFormError.textContent = error.message;
  } finally {
    setProviderFormBusy(false);
  }
}

async function activateProviderProfile(id) {
  const restore = prepareProviderSwitch();
  try {
    const response = await fetch(`/api/providers/${encodeURIComponent(id)}/activate`, { method: "POST" });
    const data = await response.json();
    if (!response.ok) throw new Error(data.error || "无法启用 API 供应商");
    state.activeProviderId = data.activeId;
    await loadProviderProfiles();
    if (elements.providerDialog.open) elements.providerDialog.close();
    toast(`已切换到 ${data.provider.name}`);
  } catch (error) {
    restore();
    throw error;
  }
}

async function activateDefaultProvider({ preferOfficial = true } = {}) {
  if (preferOfficial && state.officialAccount?.provider?.canActivate) {
    await activateOfficialAccount();
    return;
  }
  if (!state.activeProviderId || !state.fallbackProvider) return;
  setProviderFormBusy(true);
  const restore = prepareProviderSwitch();
  try {
    const response = await fetch("/api/providers/default/activate", { method: "POST" });
    const data = await response.json();
    if (!response.ok) throw new Error(data.error || "无法切回 Codex 原配置");
    state.activeProviderId = null;
    await loadProviderProfiles();
    if (elements.providerDialog.open) elements.providerDialog.close();
    toast("已切回 Codex 原配置");
  } catch (error) {
    restore();
    toast(error.message, "error");
  } finally {
    setProviderFormBusy(false);
  }
}

function prepareProviderSwitch() {
  const activeThreadId = state.activeThread?.id || null;
  const previous = {
    activeTurnId: state.activeTurnId,
    activeThreadId,
    activeThreadNeedsResume: activeThreadId ? codexThreadNeedsResume(activeThreadId) : false,
    bootstrapped: state.bootstrapped,
  };
  if (state.activeThread) rememberActiveThread(state.activeThread);
  state.activeTurnId = null;
  if (activeThreadId) markCodexThreadNeedsResume(activeThreadId, true);
  syncCodexActiveThreadRecoveryProjection();
  state.bootstrapped = false;
  renderActiveThread({ preserveOptimistic: true });
  return () => {
    if (!state.bridgeReady || state.bootstrapped) return;
    state.activeTurnId = previous.activeTurnId;
    state.bootstrapped = previous.bootstrapped;
    if (previous.activeThreadId) {
      markCodexThreadNeedsResume(previous.activeThreadId, previous.activeThreadNeedsResume);
    }
    syncCodexActiveThreadRecoveryProjection();
    renderActiveThread();
  };
}

async function deleteProviderProfile() {
  const profile = state.providers.find((entry) => entry.id === state.editingProviderId);
  if (!profile || profile.id === state.activeProviderId) return;
  if (!confirm(`删除 API 供应商“${profile.name}”？`)) return;
  setProviderFormBusy(true);
  try {
    const response = await fetch(`/api/providers/${encodeURIComponent(profile.id)}`, { method: "DELETE" });
    if (!response.ok) {
      const data = await response.json();
      throw new Error(data.error || "无法删除 API 供应商");
    }
    state.editingProviderId = "default";
    await loadProviderProfiles();
    selectProviderProfile("default");
    toast("API 供应商已删除");
  } catch (error) {
    elements.providerFormError.textContent = error.message;
  } finally {
    setProviderFormBusy(false);
  }
}

function toggleProviderKeyVisibility() {
  const visible = elements.providerApiKeyInput.type === "text";
  elements.providerApiKeyInput.type = visible ? "password" : "text";
  elements.providerKeyVisibilityButton.title = visible ? "显示密钥" : "隐藏密钥";
  elements.providerKeyVisibilityButton.setAttribute("aria-label", elements.providerKeyVisibilityButton.title);
  elements.providerKeyVisibilityButton.innerHTML = `<i data-lucide="${visible ? "eye" : "eye-off"}"></i>`;
  refreshIcons();
}

function clearProviderKeyInput() {
  elements.providerApiKeyInput.value = "";
  elements.providerApiKeyInput.type = "password";
  elements.providerKeyVisibilityButton.title = "显示密钥";
  elements.providerKeyVisibilityButton.setAttribute("aria-label", "显示密钥");
  elements.providerKeyVisibilityButton.innerHTML = '<i data-lucide="eye"></i>';
  refreshIcons();
}

function renderImageApiSettings() {
  const configured = state.imageApi.configured === true;
  const canEdit = canEditProviderProfiles();
  elements.imageApiStatus.textContent = configured ? "已配置" : "未配置";
  elements.imageApiProviderInput.replaceChildren(
    ...state.providers.map((provider) => dataOption(provider.name, provider.id)),
  );
  if (state.imageApi.providerId && state.providers.some((provider) => provider.id === state.imageApi.providerId)) {
    elements.imageApiProviderInput.value = state.imageApi.providerId;
  }
  elements.imageApiModelInput.value = state.imageApi.model || "gpt-image-2";
  renderImageModelOptions();
  const preset = imageApiAdminPreset(state.imageApi.preset);
  populateImageApiAdminFields({
    ...preset,
    ...state.imageApi,
    capabilities: { ...preset.capabilities, ...(state.imageApi.capabilities || {}) },
    operationCapabilities: {
      ...(preset.operationCapabilities || {}),
      ...(state.imageApi.operationCapabilities || {}),
    },
    defaults: {
      ...preset.defaults,
      ...(state.imageApi.defaults || {}),
      size: state.imageApi.defaults?.size || state.imageApi.size || preset.defaults.size,
      quality: state.imageApi.defaults?.quality || state.imageApi.quality || preset.defaults.quality,
    },
    limits: { ...preset.limits, ...(state.imageApi.limits || {}) },
  });
  elements.imageApiError.textContent = canEdit
    ? state.providers.length ? "" : "请先添加一个支持图片生成的 API 供应商"
    : configured ? "此图片供应商由管理员分配" : "管理员尚未分配图片供应商";
  setImageApiControlsEditable(canEdit);
  elements.saveImageApiButton.disabled = !canEdit || !state.providers.length;
  elements.imageApiModelsRefreshButton.disabled = !canEdit || !state.providers.length;
  elements.removeImageApiButton.hidden = !configured || !canEdit;
  refreshImageApiProbeControls(canEdit);
  refreshIcons();
}

function imageApiAdminPreset(presetId) {
  const normalized = Object.hasOwn(IMAGE_API_ADMIN_PRESETS, presetId)
    ? presetId
    : "generation-only";
  return structuredClone(IMAGE_API_ADMIN_PRESETS[normalized]);
}

function populateImageApiAdminFields(configuration) {
  const preset = imageApiAdminPreset(configuration?.preset);
  const capabilities = { ...preset.capabilities, ...(configuration?.capabilities || {}) };
  const operationCapabilities = {
    ...(preset.operationCapabilities || {}),
    ...(configuration?.operationCapabilities || {}),
  };
  const defaults = { ...preset.defaults, ...(configuration?.defaults || {}) };
  const limits = { ...preset.limits, ...(configuration?.limits || {}) };
  elements.imageApiPresetInput.value = preset.preset;
  elements.imageApiSizeInput.value = defaults.size;
  elements.imageApiQualityInput.value = defaults.quality;
  elements.imageApiOutputFormatInput.value = defaults.outputFormat;
  elements.imageApiOutputCompressionInput.value = defaults.outputCompression;
  elements.imageApiBackgroundInput.value = defaults.background;
  elements.imageApiModerationInput.value = defaults.moderation;
  elements.imageApiNInput.value = defaults.n;
  elements.imageApiPartialImagesInput.value = defaults.partialImages;
  elements.imageApiMaskInput.checked = capabilities.mask === true;
  elements.imageApiMultiInput.checked = capabilities.multiInput === true;
  elements.imageApiStreamingInput.checked = capabilities.streaming === true;
  for (const [operation, customInput, sizesInput] of imageApiOperationSizeInputs()) {
    const value = operationCapabilities[operation] || { customSize: false, sizes: [] };
    customInput.checked = value.customSize === true;
    sizesInput.value = Array.isArray(value.sizes) ? value.sizes.join(", ") : "";
  }
  setImageApiCapabilityValues("imageApiOperation", capabilities.operations);
  setImageApiCapabilityValues("imageApiInputFormat", capabilities.inputFormats);
  setImageApiCapabilityValues("imageApiOutputFormat", capabilities.outputFormats);
  setImageApiCapabilityValues("imageApiQuality", capabilities.qualities);
  setImageApiCapabilityValues("imageApiBackground", capabilities.backgrounds);
  setImageApiCapabilityValues("imageApiModeration", capabilities.moderations);
  elements.imageApiMaxInputImagesInput.value = limits.maxInputImages;
  elements.imageApiMaxOutputsInput.value = limits.maxOutputs;
  elements.imageApiMaxPartialImagesInput.value = limits.maxPartialImages;
  elements.imageApiTimeoutMsInput.value = limits.timeoutMs;
  elements.imageApiMaxInputBytesPerImageInput.value = limits.maxInputBytesPerImage;
  elements.imageApiMaxInputBytesTotalInput.value = limits.maxInputBytesTotal;
  elements.imageApiMaxOutputBytesPerImageInput.value = limits.maxOutputBytesPerImage;
  elements.imageApiMaxResponseBytesInput.value = limits.maxResponseBytes;
  setImageApiControlsEditable(canEditProviderProfiles());
}

function setImageApiCapabilityValues(name, values) {
  const selected = new Set(Array.isArray(values) ? values : []);
  for (const input of elements.imageApiForm.querySelectorAll(`input[name="${name}"]`)) {
    input.checked = selected.has(input.value);
  }
}

function imageApiCapabilityValues(name) {
  return [...elements.imageApiForm.querySelectorAll(`input[name="${name}"]:checked`)]
    .map((input) => input.value);
}

function setImageApiControlsEditable(editable) {
  const preset = imageApiAdminPreset(elements.imageApiPresetInput.value);
  const ordinaryInputs = [
    elements.imageApiProviderInput,
    elements.imageApiPresetInput,
    elements.imageApiModelInput,
    elements.imageApiSizeInput,
    elements.imageApiQualityInput,
    elements.imageApiOutputFormatInput,
    elements.imageApiOutputCompressionInput,
    elements.imageApiBackgroundInput,
    elements.imageApiModerationInput,
    elements.imageApiNInput,
    elements.imageApiPartialImagesInput,
    elements.imageApiGenerateCustomSizeInput,
    elements.imageApiGenerateSizesInput,
    elements.imageApiEditCustomSizeInput,
    elements.imageApiEditSizesInput,
    elements.imageApiOutpaintCustomSizeInput,
    elements.imageApiOutpaintSizesInput,
    elements.imageApiMaxInputImagesInput,
    elements.imageApiMaxOutputsInput,
    elements.imageApiMaxPartialImagesInput,
    elements.imageApiTimeoutMsInput,
    elements.imageApiMaxInputBytesPerImageInput,
    elements.imageApiMaxInputBytesTotalInput,
    elements.imageApiMaxOutputBytesPerImageInput,
    elements.imageApiMaxResponseBytesInput,
  ];
  for (const input of ordinaryInputs) input.disabled = !editable;

  for (const [operation, customInput, sizesInput] of imageApiOperationSizeInputs()) {
    const supported = Object.hasOwn(preset.operationCapabilities || {}, operation);
    customInput.disabled = !editable || !supported;
    sizesInput.disabled = !editable || !supported;
    customInput.closest("fieldset").hidden = !supported;
  }

  const supportedSets = new Map([
    ["imageApiOperation", preset.capabilities.operations],
    ["imageApiInputFormat", preset.capabilities.inputFormats],
    ["imageApiOutputFormat", preset.capabilities.outputFormats],
    ["imageApiQuality", preset.capabilities.qualities],
    ["imageApiBackground", preset.capabilities.backgrounds],
    ["imageApiModeration", preset.capabilities.moderations],
  ]);
  for (const [name, supported] of supportedSets) {
    for (const input of elements.imageApiForm.querySelectorAll(`input[name="${name}"]`)) {
      const mandatoryGenerate = name === "imageApiOperation" && input.value === "generate";
      input.disabled = !editable || mandatoryGenerate || !supported.includes(input.value);
      if (!supported.includes(input.value)) input.checked = false;
    }
  }
  for (const [input, supported] of [
    [elements.imageApiMaskInput, preset.capabilities.mask],
    [elements.imageApiMultiInput, preset.capabilities.multiInput],
    [elements.imageApiStreamingInput, preset.capabilities.streaming],
  ]) {
    input.disabled = !editable || supported !== true;
    if (supported !== true) input.checked = false;
  }
  setImageApiSelectAvailability(elements.imageApiQualityInput, preset.capabilities.qualities);
  setImageApiSelectAvailability(elements.imageApiOutputFormatInput, preset.capabilities.outputFormats);
  setImageApiSelectAvailability(elements.imageApiBackgroundInput, preset.capabilities.backgrounds);
  setImageApiSelectAvailability(elements.imageApiModerationInput, preset.capabilities.moderations);
  const allowedLimits = preset.limits;
  elements.imageApiMaxInputImagesInput.max = String(allowedLimits.maxInputImages);
  elements.imageApiMaxOutputsInput.max = String(allowedLimits.maxOutputs);
  elements.imageApiNInput.max = String(allowedLimits.maxOutputs);
  elements.imageApiMaxPartialImagesInput.max = String(allowedLimits.maxPartialImages);
  elements.imageApiPartialImagesInput.max = String(allowedLimits.maxPartialImages);
  elements.imageApiMaxInputBytesTotalInput.max = String(allowedLimits.maxInputBytesTotal);
  refreshImageApiProbeControls(editable);
}

function refreshImageApiProbeControls(editable = canEditProviderProfiles()) {
  const configured = state.imageApi.configured === true;
  const capabilities = state.imageApi.capabilities || {};
  const operations = new Set(Array.isArray(capabilities.operations) ? capabilities.operations : []);
  const available = new Set(["generate-standard"]);
  if (operations.has("edit")) available.add("edit-standard");
  if (operations.has("edit") && capabilities.mask === true) available.add("edit-mask");
  if (operations.has("outpaint")) {
    available.add("outpaint-standard");
    available.add("outpaint-custom");
  }
  for (const input of elements.imageApiForm.querySelectorAll('input[name="imageApiProbeTest"]')) {
    input.disabled = !editable || !configured || !available.has(input.value);
    input.closest("label").hidden = configured && !available.has(input.value);
  }
  elements.imageApiProbeButton.disabled = !editable || !configured;
  if (!configured) elements.imageApiProbeStatus.textContent = "请先保存图片供应商配置";
}

function setImageApiSelectAvailability(select, supported) {
  for (const option of select.options) option.disabled = !supported.includes(option.value);
}

async function queryProviderModels(providerId, target, { announce = true } = {}) {
  if (!providerId || ["default", "image-api"].includes(providerId)) {
    if (announce) toast("请先保存 API 供应商", "error");
    return;
  }
  const button = target === "image"
    ? elements.imageApiModelsRefreshButton
    : target === "provider"
      ? elements.providerModelsRefreshButton
      : null;
  const errorElement = target === "image"
    ? elements.imageApiError
    : target === "provider"
      ? elements.providerFormError
      : null;
  if (button) button.disabled = true;
  if (errorElement) errorElement.textContent = "";
  try {
    const response = await fetch(`/api/providers/${encodeURIComponent(providerId)}/models`, {
      method: "POST",
      headers: { "X-Codex-Desktop-Action": "provider-models-query" },
    });
    const data = await readApiJson(response, "无法查询供应商模型");
    state.providerModelCatalogs[providerId] = data.models || [];
    if (target === "image") renderImageModelOptions();
    else if (target === "provider") renderProviderModelOptions(providerId);
    if (providerId === currentProviderModelCatalogId()) {
      mergeDiscoveredProviderModels(providerId);
      populateModelSelects();
    }
    if (announce) toast(`已读取 ${data.models.length} 个供应商模型`);
  } catch (error) {
    if (errorElement) errorElement.textContent = error.message;
    else if (announce) toast(error.message, "error");
    else console.error("Unable to refresh the active provider model catalog:", error);
  } finally {
    if (button) {
      button.disabled = target === "image"
        ? !canEditProviderProfiles() || !state.providers.length
        : !state.editingProviderId || ["default", "image-api"].includes(state.editingProviderId);
    }
  }
}

function renderProviderModelOptions(providerId) {
  const models = state.providerModelCatalogs[providerId] || [];
  elements.providerModelOptions.replaceChildren(...models.map((model) => new Option(model, model)));
  renderQueriedModelSelect(elements.providerModelCatalogSelect, models);
}

function renderImageModelOptions() {
  const providerId = elements.imageApiProviderInput.value;
  const discovered = state.providerModelCatalogs[providerId] || [];
  const models = [
    "gpt-image-2",
    ...discovered,
  ];
  elements.imageApiModelPresets.replaceChildren(
    ...[...new Set(models)].map((model) => new Option(model, model)),
  );
  renderQueriedModelSelect(elements.imageApiModelCatalogSelect, discovered);
}

function renderQueriedModelSelect(select, models) {
  select.replaceChildren(
    new Option(`已查询 ${models.length} 个模型，点击选择`, ""),
    ...models.map((model) => new Option(model, model)),
  );
  select.value = "";
  select.hidden = !models.length;
}

function currentProviderModelCatalogId() {
  return state.activeProviderId || state.currentProvider?.editableProfileId || null;
}

function mergeDiscoveredProviderModels(providerId) {
  const builtIn = state.models.filter((model) => model.providerCatalog !== true);
  const known = new Set(builtIn.map((model) => model.model));
  const template = builtIn.find((model) => model.isDefault) || builtIn[0] || {};
  const discovered = (state.providerModelCatalogs[providerId] || [])
    .filter((model) => !known.has(model))
    .map((model) => ({
      model,
      displayName: model,
      description: "由当前 API 供应商 /models 返回",
      supportedReasoningEfforts: template.supportedReasoningEfforts || [],
      defaultReasoningEffort: template.defaultReasoningEffort || null,
      providerCatalog: true,
    }));
  state.models = [...builtIn, ...discovered];
}

async function saveImageApiSettings(event) {
  event.preventDefault();
  if (!canEditProviderProfiles() || !elements.imageApiForm.reportValidity()) return;
  setImageApiBusy(true);
  elements.imageApiError.textContent = "";
  try {
    const settings = collectImageApiAdminSettings();
    const response = await fetch("/api/images/settings", {
      method: "PUT",
      headers: {
        "Content-Type": "application/json",
        "X-Codex-Desktop-Action": "image-api-save",
      },
      body: JSON.stringify({
        providerId: elements.imageApiProviderInput.value,
        model: elements.imageApiModelInput.value.trim(),
        ...settings,
      }),
    });
    await readApiJson(response, "无法保存图片 API");
    await loadProviderProfiles();
    selectProviderProfile("image-api");
    toast("图片供应商设置已保存");
  } catch (error) {
    elements.imageApiError.textContent = error.message;
  } finally {
    setImageApiBusy(false);
  }
}

async function runImageApiCompatibilityProbe() {
  if (!state.imageApi.configured || !canEditProviderProfiles() || elements.imageApiProbeButton.disabled) return;
  const tests = [...elements.imageApiForm.querySelectorAll('input[name="imageApiProbeTest"]:checked:not(:disabled)')]
    .map((input) => input.value);
  if (!tests.length) {
    elements.imageApiError.textContent = "请至少选择一个兼容性探测项目";
    return;
  }
  if (!confirm(`将使用当前已保存配置向图片供应商发起 ${tests.length} 个真实请求，可能产生费用。不会自动重试或修改能力设置。确认继续？`)) return;
  elements.imageApiError.textContent = "";
  elements.imageApiProbeResults.hidden = true;
  elements.imageApiProbeResults.replaceChildren();
  elements.imageApiProbeButton.disabled = true;
  elements.imageApiProbeStatus.textContent = "已进入图片 Worker 队列，等待探测完成";
  try {
    const response = await fetch("/api/images/compatibility-probe", {
      method: "POST",
      headers: {
        "Content-Type": "application/json",
        "X-Codex-Desktop-Action": "image-api-probe",
      },
      body: JSON.stringify({ tests, acknowledgeCharges: true }),
    });
    const data = await readApiJson(response, "图片兼容性探测失败");
    renderImageApiCompatibilityProbe(data.report);
  } catch (error) {
    elements.imageApiError.textContent = error.message;
    elements.imageApiProbeStatus.textContent = "兼容性探测失败";
  } finally {
    refreshImageApiProbeControls(canEditProviderProfiles());
  }
}

function renderImageApiCompatibilityProbe(report) {
  const tests = Array.isArray(report?.tests) ? report.tests : [];
  if (!tests.length) throw new Error("服务器没有返回兼容性探测结果");
  const labels = {
    "generate-standard": "标准生成",
    "edit-standard": "标准编辑",
    "edit-mask": "编辑蒙版",
    "outpaint-standard": "标准扩图",
    "outpaint-custom": "自定义尺寸扩图",
  };
  const nodes = tests.map((entry) => {
    const row = document.createElement("div");
    row.className = "image-api-probe-result";
    row.dataset.ok = String(entry.ok === true);
    const title = document.createElement("strong");
    title.textContent = `${entry.ok ? "通过" : "失败"} · ${labels[entry.id] || entry.id}`;
    const detail = document.createElement("span");
    detail.textContent = [
      entry.requestedSize,
      entry.providerRequestId,
      entry.error?.providerStatusCode ? `HTTP ${entry.error.providerStatusCode}` : null,
      entry.error?.code,
      entry.error?.message,
    ].filter(Boolean).join(" · ");
    row.append(title, detail);
    return row;
  });
  const note = document.createElement("p");
  note.textContent = report.recommendations?.note
    || "探测报告仅供管理员判断，不会自动修改能力声明。";
  elements.imageApiProbeResults.replaceChildren(...nodes, note);
  elements.imageApiProbeResults.hidden = false;
  const passed = tests.filter((entry) => entry.ok).length;
  elements.imageApiProbeStatus.textContent = `探测完成：${passed}/${tests.length} 通过 · 设置未自动更改`;
}

function collectImageApiAdminSettings() {
  const preset = elements.imageApiPresetInput.value;
  const presetDefaults = imageApiAdminPreset(preset);
  const retainCurrent = state.imageApi.preset === preset;
  const baseline = retainCurrent ? state.imageApi : presetDefaults;
  const capabilities = {
    ...(baseline.capabilities || {}),
    operations: imageApiCapabilityValues("imageApiOperation"),
    inputFormats: imageApiCapabilityValues("imageApiInputFormat"),
    mask: elements.imageApiMaskInput.checked,
    multiInput: elements.imageApiMultiInput.checked,
    outputFormats: imageApiCapabilityValues("imageApiOutputFormat"),
    qualities: imageApiCapabilityValues("imageApiQuality"),
    backgrounds: imageApiCapabilityValues("imageApiBackground"),
    moderations: imageApiCapabilityValues("imageApiModeration"),
    streaming: elements.imageApiStreamingInput.checked,
  };
  const operationCapabilities = Object.fromEntries(imageApiOperationSizeInputs()
    .filter(([operation]) => Object.hasOwn(presetDefaults.operationCapabilities || {}, operation))
    .map(([operation, customInput, sizesInput]) => [operation, {
      customSize: customInput.checked,
      sizes: imageApiSizeListValue(sizesInput.value, operation),
    }]));
  const limits = {
    ...(baseline.limits || {}),
    maxInputImages: imageApiIntegerValue(elements.imageApiMaxInputImagesInput),
    maxOutputs: imageApiIntegerValue(elements.imageApiMaxOutputsInput),
    maxPartialImages: imageApiIntegerValue(elements.imageApiMaxPartialImagesInput),
    timeoutMs: imageApiIntegerValue(elements.imageApiTimeoutMsInput),
    maxInputBytesPerImage: imageApiIntegerValue(elements.imageApiMaxInputBytesPerImageInput),
    maxInputBytesTotal: imageApiIntegerValue(elements.imageApiMaxInputBytesTotalInput),
    maxOutputBytesPerImage: imageApiIntegerValue(elements.imageApiMaxOutputBytesPerImageInput),
    maxResponseBytes: imageApiIntegerValue(elements.imageApiMaxResponseBytesInput),
  };
  const defaults = {
    ...(baseline.defaults || {}),
    size: elements.imageApiSizeInput.value.trim(),
    quality: elements.imageApiQualityInput.value,
    outputFormat: elements.imageApiOutputFormatInput.value,
    outputCompression: imageApiIntegerValue(elements.imageApiOutputCompressionInput),
    background: elements.imageApiBackgroundInput.value,
    moderation: elements.imageApiModerationInput.value,
    n: imageApiIntegerValue(elements.imageApiNInput),
    partialImages: imageApiIntegerValue(elements.imageApiPartialImagesInput),
  };
  validateImageApiAdminSettings({ preset, capabilities, operationCapabilities, limits, defaults });
  return { preset, capabilities, operationCapabilities, limits, defaults };
}

function imageApiOperationSizeInputs() {
  return [
    ["generate", elements.imageApiGenerateCustomSizeInput, elements.imageApiGenerateSizesInput],
    ["edit", elements.imageApiEditCustomSizeInput, elements.imageApiEditSizesInput],
    ["outpaint", elements.imageApiOutpaintCustomSizeInput, elements.imageApiOutpaintSizesInput],
  ];
}

function imageApiSizeListValue(value, operation) {
  const sizes = [...new Set(String(value || "")
    .split(/[\s,，;；]+/u)
    .map((entry) => entry.trim())
    .filter(Boolean))];
  if (sizes.length > 64 || sizes.some((entry) => !/^(?:auto|[1-9]\d{0,4}x[1-9]\d{0,4})$/u.test(entry))) {
    throw new Error(`${operation} 的已知支持尺寸格式不正确`);
  }
  return sizes;
}

function imageApiIntegerValue(input) {
  const value = Number(input.value);
  if (!Number.isSafeInteger(value)) throw new Error("图片设置中的数值必须是整数");
  return value;
}

function validateImageApiAdminSettings({ preset, capabilities, operationCapabilities, limits, defaults }) {
  if (!capabilities.operations.includes("generate")) throw new Error("图片能力必须保留生成功能");
  if (!capabilities.outputFormats.length) throw new Error("至少启用一种输出格式");
  for (const [value, supported, label] of [
    [defaults.outputFormat, capabilities.outputFormats, "默认输出格式"],
    [defaults.quality, capabilities.qualities, "默认图片质量"],
    [defaults.background, capabilities.backgrounds, "默认背景"],
    [defaults.moderation, capabilities.moderations, "默认审核档位"],
  ]) {
    if (!supported.includes(value)) throw new Error(`${label}必须在已启用的能力中`);
  }
  if (!capabilities.multiInput && limits.maxInputImages > 1) {
    throw new Error("关闭多图输入时，最大输入图片数不能超过 1");
  }
  if (!capabilities.streaming && (limits.maxPartialImages > 0 || defaults.partialImages > 0)) {
    throw new Error("关闭流式预览时，流式预览数量必须为 0");
  }
  if (defaults.n > limits.maxOutputs) throw new Error("默认输出图片数不能超过最大输出图片数");
  if (defaults.partialImages > limits.maxPartialImages) throw new Error("默认流式预览数不能超过最大流式预览数");
  for (const operation of capabilities.operations) {
    const entry = operationCapabilities[operation];
    if (!entry) throw new Error(`${operation} 缺少按操作尺寸能力`);
    if (!entry.customSize && !entry.sizes.length) {
      throw new Error(`${operation} 关闭自定义尺寸后必须至少保留一个已知支持尺寸`);
    }
  }
  const generateSize = operationCapabilities.generate;
  if (generateSize && !generateSize.customSize && !generateSize.sizes.includes(defaults.size)) {
    throw new Error("默认图片尺寸不在生成操作的支持尺寸中");
  }
  if (
    preset === "generation-only"
    && !IMAGE_API_ADMIN_PRESETS["generation-only"].limits.fixedSizes.includes(defaults.size)
  ) throw new Error("仅生成预设只支持列出的固定尺寸");
}

async function removeImageApiSettings() {
  if (!state.imageApi.configured || !canEditProviderProfiles()) return;
  if (!confirm("移除当前图片供应商配置？")) return;
  setImageApiBusy(true);
  elements.imageApiError.textContent = "";
  try {
    const response = await fetch("/api/images/settings", {
      method: "DELETE",
      headers: { "X-Codex-Desktop-Action": "image-api-remove" },
    });
    if (!response.ok) await readApiJson(response, "无法移除图片 API");
    await loadProviderProfiles();
    selectProviderProfile("image-api");
    setImageGenerationMode(false);
    toast("图片供应商配置已移除");
  } catch (error) {
    elements.imageApiError.textContent = error.message;
  } finally {
    setImageApiBusy(false);
  }
}

function setImageApiBusy(busy) {
  elements.saveImageApiButton.disabled = busy || !canEditProviderProfiles() || !state.providers.length;
  elements.removeImageApiButton.disabled = busy;
  elements.imageApiModelsRefreshButton.disabled = busy || !canEditProviderProfiles() || !state.providers.length;
  setImageApiControlsEditable(!busy && canEditProviderProfiles());
}

function setProviderFormBusy(busy) {
  elements.saveProviderButton.disabled = busy;
  elements.activateProviderButton.disabled = busy;
  elements.deleteProviderButton.disabled = busy
    || state.editingProviderId === state.activeProviderId;
  elements.providerModelsRefreshButton.disabled = busy
    || !state.editingProviderId
    || ["default", "image-api"].includes(state.editingProviderId);
  const canEdit = canEditProviderProfiles() && !busy;
  elements.activateDefaultProviderButton.disabled = busy || (
    !state.officialAccount?.provider?.canActivate
    && (!state.activeProviderId || !state.fallbackProvider)
  );
}

async function loadOfficialAccount({ silent = false } = {}) {
  if (state.editingProviderId !== "default") return;
  if (state.officialAccountLoading) {
    state.officialAccountReloadPending = true;
    return;
  }
  state.officialAccountReloadPending = false;
  stopOfficialLoginPolling();
  state.officialAccountLoading = true;
  if (!silent) elements.officialAccountError.textContent = "";
  renderOfficialAccount();
  try {
    const response = await fetch(`/api/providers/official?_=${Date.now()}`, { cache: "no-store" });
    const data = await readApiJson(response, "无法查询官方账户");
    state.officialAccount = data;
    if (
      elements.officialBrowserDialog.open
      && state.officialBrowserRuntime === "codex"
      && !data.pendingLogin?.browser?.active
    ) closeOfficialBrowserDialog();
    renderOfficialAccount();
  } catch (error) {
    elements.officialAccountStatus.textContent = "查询失败";
    elements.officialAccountError.textContent = error.message;
  } finally {
    state.officialAccountLoading = false;
    renderOfficialAccount();
    if (state.officialAccountReloadPending) {
      state.officialAccountReloadPending = false;
      void loadOfficialAccount({ silent: true });
      return;
    }
    if (state.officialAccount?.pendingLogin) scheduleOfficialLoginPolling();
    void loadProviderRouting({ silent: true });
  }
}

function renderOfficialAccount() {
  const data = state.officialAccount;
  const account = data?.account || null;
  const accounts = Array.isArray(data?.accounts) ? data.accounts : [];
  const activeStoredAccount = accounts.find(
    (storedAccount) => storedAccount.id === data?.activeAccountId || storedAccount.active === true,
  ) || null;
  const credentialInvalid = data?.credentialInvalid === true
    || activeStoredAccount?.credentialStatus === "invalid";
  const loggedIn = account?.type === "chatgpt" && !credentialInvalid;
  const displayAccount = account?.type === "chatgpt" ? account : activeStoredAccount;
  const pending = data?.pendingLogin || null;
  const authorized = data?.authorized !== false;
  const loading = state.officialAccountLoading;
  const providerActive = data?.provider?.active === true;
  const canActivate = data?.provider?.canActivate === true;
  const browserLogin = pending?.type === "chatgpt" && pending?.browser?.active === true;

  elements.officialAccountStatus.textContent = loading
    ? "正在查询"
    : !authorized
      ? "需要管理员授权"
    : pending
      ? "等待授权"
      : credentialInvalid
        ? "登录已失效"
      : loggedIn
        ? providerActive ? "已登录 · 当前使用" : "已登录 · 未启用"
        : account?.type === "apiKey" ? "API Key 登录" : "未登录";
  elements.officialLoginButton.hidden = !authorized;
  elements.officialLoginButton.disabled = loading || Boolean(pending);
  elements.officialLoginButton.querySelector("span").textContent = credentialInvalid
    ? "重新登录"
    : loggedIn ? "添加账号" : "官方登录";
  elements.officialContinueLoginButton.hidden = !browserLogin || !authorized;
  elements.officialContinueLoginButton.disabled = loading;
  elements.officialRefreshButton.disabled = loading;
  elements.officialLogoutButton.hidden = (!account && !activeStoredAccount) || !authorized;
  elements.officialLogoutButton.disabled = loading;
  elements.activateDefaultProviderButton.hidden = !authorized;
  elements.activateDefaultProviderButton.disabled = loading || !canActivate;
  elements.activateDefaultProviderButton.querySelector("span").textContent = providerActive
    ? "当前使用"
    : "启用官方配置";

  elements.officialLoginCode.hidden = pending?.type !== "chatgptDeviceCode";
  if (pending?.type === "chatgptDeviceCode") {
    elements.officialUserCode.textContent = pending.userCode || "--";
    const url = safeOfficialAuthUrl(pending.verificationUrl);
    elements.officialVerificationLink.href = url || "#";
    elements.officialVerificationLink.hidden = !url;
  } else {
    elements.officialUserCode.textContent = "--";
    elements.officialVerificationLink.href = "#";
  }

  renderOfficialAccountSlots(accounts, data?.activeAccountId, loading);
  renderOfficialWorkspaceMessages(
    loggedIn ? data?.workspaceMessages : null,
    loggedIn && data?.workspaceMessagesAuthorized === true,
    loading,
    data?.queryErrors || [],
  );
  elements.officialAccountEmpty.hidden = loggedIn;
  elements.officialAccountDetails.hidden = !loggedIn && !credentialInvalid;
  if (!loggedIn) {
    if (!authorized) {
      elements.officialAccountEmpty.textContent = "官方登录默认关闭，请联系管理员在用户管理中授权。";
    } else if (credentialInvalid) {
      elements.officialAccountEmpty.textContent = "当前账号登录已失效。账号资料和最近 7 天额度已保留，请重新登录。";
    } else if (account?.type === "apiKey") {
      elements.officialAccountEmpty.textContent = "当前 Codex 使用 API Key 登录，可退出后改用服务器 OAuth。";
    } else if (browserLogin) {
      elements.officialAccountEmpty.textContent = "服务器 OAuth · 等待完成";
    } else {
      elements.officialAccountEmpty.textContent = "服务器 OAuth · 临时隔离浏览器";
    }
    if (!credentialInvalid) {
      refreshIcons();
      return;
    }
  }

  setDataContent(
    elements.officialAccountEmail,
    displayAccount?.email || "未提供",
    Boolean(displayAccount?.email),
  );
  elements.officialAccountPlan.textContent = officialPlanLabel(displayAccount?.planType);
  elements.officialLifetimeTokens.textContent = formatOptionalInteger(data.usage?.lifetimeTokens);
  const resetCount = data.rateLimits?.resetCredits?.availableCount;
  elements.officialResetCount.textContent = Number.isSafeInteger(resetCount) ? String(resetCount) : "--";
  elements.officialUsageSummary.textContent = credentialInvalid
    ? "登录已失效 · 保留最近一次用量"
    : data.usage
    ? `连续 ${formatOptionalInteger(data.usage.currentStreakDays)} 天 · 峰值 ${formatOptionalInteger(data.usage.peakDailyTokens)} Token`
    : data.queryErrors?.includes("usage") ? "官方用量暂不可用" : "暂无用量数据";
  elements.officialResetSummary.textContent = credentialInvalid
    ? "重新登录后才能查询或使用重置额度。"
    : Number.isSafeInteger(resetCount)
    ? resetCount > 0
      ? `官方账户当前有 ${resetCount} 次可用重置额度，执行前仍会重新查询。`
      : "官方账户当前没有可用的重置额度。"
    : data.queryErrors?.includes("rateLimits")
      ? "官方限额查询暂不可用，请稍后刷新。"
      : "官方账户未返回重置额度信息。";
  elements.officialPrepareResetButton.disabled = credentialInvalid
    || loading
    || !Number.isSafeInteger(resetCount)
    || resetCount < 1;
  renderOfficialRateLimits(data.rateLimits?.buckets || []);
  refreshIcons();
}

function renderOfficialWorkspaceMessages(messages, authorized, loading, queryErrors) {
  elements.officialWorkspaceSection.hidden = !authorized;
  elements.officialWorkspaceList.replaceChildren();
  elements.officialWorkspaceActionStatus.textContent = state.officialWorkspaceActionStatus;
  if (elements.officialWorkspaceSection.hidden) return;
  const payload = messages && typeof messages === "object" ? messages : {};
  const rows = Array.isArray(payload.messages) ? payload.messages : [];
  const unreadCount = Number.isSafeInteger(payload.unreadCount) ? payload.unreadCount : 0;
  elements.officialWorkspaceUnread.textContent = unreadCount > 0 ? `${unreadCount} 条未读` : "已读";
  elements.officialWorkspaceUnread.dataset.unread = String(unreadCount > 0);
  elements.officialWorkspaceSummary.textContent = queryErrors.includes("workspaceMessages")
    ? messages ? "工作区消息刷新失败，正在显示最近一次结果。" : "工作区消息刷新失败，请稍后重试。"
    : payload.featureEnabled
      ? rows.length ? `官方返回 ${rows.length} 条有效消息` : "当前没有有效的工作区消息"
      : "当前官方账号未开放工作区消息";
  if (!rows.length) {
    const empty = document.createElement("p");
    empty.className = "official-workspace-empty";
    empty.textContent = payload.featureEnabled ? "没有新的工作区公告" : "此功能暂不可用";
    elements.officialWorkspaceList.append(empty);
  }
  for (const message of rows) {
    const row = document.createElement("article");
    row.className = "official-workspace-message";
    row.dataset.category = message.category || "announcement";
    row.dataset.unread = String(message.unread === true);
    const header = document.createElement("div");
    const category = document.createElement("strong");
    const time = document.createElement("time");
    category.textContent = officialWorkspaceCategoryLabel(message.category);
    time.textContent = message.createdAt
      ? new Date(message.createdAt * 1_000).toLocaleString(interfaceLocale(), { hour12: false })
      : "时间未知";
    header.append(category, time);
    const body = document.createElement("p");
    setDataContent(body, message.messageBody || "官方消息内容不可用");
    row.append(header, body);
    elements.officialWorkspaceList.append(row);
  }
  elements.officialWorkspaceReadButton.disabled = loading || unreadCount < 1;
  const nudgeSupported = payload.featureEnabled === true;
  elements.officialCreditsNudgeButton.hidden = !nudgeSupported;
  elements.officialUsageNudgeButton.hidden = !nudgeSupported;
  const cooldown = officialNudgeCooldown(payload.nudges, payload.nudgeCooldownMs);
  elements.officialCreditsNudgeButton.disabled = loading || cooldown.credits > 0;
  elements.officialUsageNudgeButton.disabled = loading || cooldown.usage_limit > 0;
  elements.officialCreditsNudgeButton.title = cooldown.credits > 0
    ? `请在 ${Math.ceil(cooldown.credits / 60_000)} 分钟后重试`
    : "请工作区所有者补充 Credits";
  elements.officialUsageNudgeButton.title = cooldown.usage_limit > 0
    ? `请在 ${Math.ceil(cooldown.usage_limit / 60_000)} 分钟后重试`
    : "请工作区所有者调整使用限额";
}

function officialWorkspaceCategoryLabel(category) {
  return {
    quota: "额度通知",
    plan: "套餐与工作区",
    account: "账号安全",
    notice: "重要通知",
    announcement: "工作区公告",
  }[category] || "官方消息";
}

function officialNudgeCooldown(nudges, cooldownMs) {
  const duration = Number.isFinite(Number(cooldownMs)) ? Number(cooldownMs) : 0;
  const values = { credits: 0, usage_limit: 0 };
  for (const record of Array.isArray(nudges) ? nudges : []) {
    if (record?.status !== "sent" || !Object.hasOwn(values, record.creditType)) continue;
    values[record.creditType] = Math.max(
      values[record.creditType],
      Math.max(0, Number(record.at || 0) + duration - Date.now()),
    );
  }
  return values;
}

async function markOfficialWorkspaceMessagesRead() {
  elements.officialWorkspaceReadButton.disabled = true;
  state.officialWorkspaceActionStatus = "";
  try {
    const response = await fetch("/api/providers/official/workspace-messages/read", {
      method: "POST",
      headers: { "X-Codex-Desktop-Action": "official-workspace-messages-read" },
    });
    const result = await readApiJson(response, "无法确认工作区消息");
    state.officialAccount.workspaceMessages = result.workspaceMessages;
    renderOfficialAccount();
  } catch (error) {
    elements.officialAccountError.textContent = error.message;
  }
}

async function sendOfficialCreditsNudge(creditType) {
  const label = creditType === "usage_limit" ? "请求工作区所有者调整使用限额" : "请求工作区所有者补充 Credits";
  if (!window.confirm(`${label}？同一类型发送后 10 分钟内不能重复提交。`)) return;
  const button = creditType === "usage_limit"
    ? elements.officialUsageNudgeButton
    : elements.officialCreditsNudgeButton;
  button.disabled = true;
  state.officialWorkspaceActionStatus = "正在请求官方发送提醒邮件";
  elements.officialWorkspaceActionStatus.textContent = state.officialWorkspaceActionStatus;
  try {
    const response = await fetch("/api/providers/official/credits-nudge", {
      method: "POST",
      headers: {
        "Content-Type": "application/json",
        "X-Codex-Desktop-Action": "official-credits-nudge",
      },
      body: JSON.stringify({ creditType, confirmation: "发送额度提醒" }),
    });
    const result = await readApiJson(response, "无法发送额度提醒");
    const messages = state.officialAccount.workspaceMessages;
    messages.nudges = [
      { creditType: result.creditType, status: "sent", at: result.sentAt },
      ...(messages.nudges || []),
    ].slice(0, 32);
    state.officialWorkspaceActionStatus = "官方已接受请求，提醒邮件不会包含当前对话内容。";
    renderOfficialAccount();
  } catch (error) {
    state.officialWorkspaceActionStatus = error.message;
    elements.officialWorkspaceActionStatus.textContent = state.officialWorkspaceActionStatus;
    button.disabled = false;
  }
}

function renderOfficialAccountSlots(accounts, activeId, loading) {
  elements.officialAccountSlots.hidden = accounts.length === 0;
  elements.officialAccountSlotSummary.textContent = accounts.length ? `${accounts.length} / 10` : "--";
  elements.officialAccountSlotList.replaceChildren();
  for (const account of accounts) {
    const row = document.createElement("div");
    row.className = "official-account-slot";
    row.dataset.active = String(account.id === activeId || account.active === true);
    row.dataset.credentialStatus = account.credentialStatus || "unknown";
    const credentialInvalid = row.dataset.credentialStatus === "invalid";

    const identity = document.createElement("div");
    identity.className = "official-account-slot-identity";
    const email = document.createElement("strong");
    setDataContent(email, account.email || "未提供邮箱", Boolean(account.email));
    const meta = document.createElement("span");
    meta.textContent = [
      officialPlanLabel(account.planType),
      row.dataset.active === "true" ? "当前账号" : "已保存",
      credentialInvalid ? "登录已失效" : null,
    ].filter(Boolean).join(" · ");
    const proxy = document.createElement("span");
    proxy.className = "official-account-slot-proxy";
    proxy.textContent = officialProxySummary(account.proxy);
    proxy.dataset.status = account.proxy?.health?.status || (account.proxy ? "unknown" : "direct");
    identity.append(email, meta, proxy);

    const quota = document.createElement("div");
    quota.className = "official-account-slot-quota";
    const quotaHeading = document.createElement("div");
    const quotaLabel = document.createElement("span");
    quotaLabel.textContent = "7 天用量";
    const quotaValue = document.createElement("strong");
    quotaValue.textContent = Number.isFinite(account.weekly?.usedPercent) ? `${account.weekly.usedPercent}%` : "--";
    quotaHeading.append(quotaLabel, quotaValue);
    const track = document.createElement("div");
    track.className = "official-account-slot-track";
    const fill = document.createElement("span");
    fill.style.width = `${account.weekly?.usedPercent || 0}%`;
    track.append(fill);
    quota.append(quotaHeading, track);

    const actions = document.createElement("div");
    actions.className = "official-account-slot-actions";
    if (row.dataset.active === "true") {
      const active = document.createElement("span");
      active.className = "official-account-active-label";
      active.innerHTML = '<i data-lucide="check"></i><span>当前</span>';
      actions.append(active);
    } else if (!credentialInvalid) {
      const activate = document.createElement("button");
      activate.className = "secondary-button compact-button";
      activate.type = "button";
      activate.disabled = loading;
      activate.innerHTML = '<i data-lucide="repeat-2"></i><span>切换</span>';
      activate.addEventListener("click", () => switchOfficialAccount(account.id));
      actions.append(activate);
    }
    if (credentialInvalid) {
      const relogin = document.createElement("button");
      relogin.className = "secondary-button compact-button";
      relogin.type = "button";
      relogin.disabled = loading;
      relogin.innerHTML = '<i data-lucide="refresh-cw"></i><span>重新登录</span>';
      relogin.addEventListener("click", () => openOfficialProxyDialogForLogin(account));
      actions.append(relogin);
    }
    const route = document.createElement("button");
    route.className = "secondary-button compact-button";
    route.type = "button";
    route.disabled = loading;
    route.title = "设置账号网络出口";
    route.setAttribute("aria-label", `设置 ${account.email || "官方账号"} 的网络出口`);
    route.innerHTML = '<i data-lucide="route"></i><span>出口</span>';
    route.addEventListener("click", () => openOfficialProxyDialogForAccount(account));
    actions.append(route);
    if (row.dataset.active !== "true") {
      const remove = document.createElement("button");
      remove.className = "icon-button";
      remove.type = "button";
      remove.disabled = loading;
      remove.title = "移除已保存账号";
      remove.setAttribute("aria-label", `移除 ${account.email || "官方账号"}`);
      remove.innerHTML = '<i data-lucide="trash-2"></i>';
      remove.addEventListener("click", () => removeOfficialAccount(account));
      actions.append(remove);
    }
    row.append(identity, quota, actions);
    elements.officialAccountSlotList.append(row);
  }
}

function renderOfficialRateLimits(buckets) {
  renderOfficialRateLimitList(elements.officialLimitList, buckets, "官方账户暂未返回速率限额");
}

function renderOfficialRateLimitList(container, buckets, emptyText) {
  container.replaceChildren();
  if (!buckets.length) {
    const empty = document.createElement("div");
    empty.className = "official-limit-empty";
    empty.textContent = emptyText;
    container.append(empty);
    return;
  }
  for (const bucket of buckets) {
    const row = document.createElement("div");
    row.className = "official-limit-row";
    const name = document.createElement("div");
    name.className = "official-limit-name";
    const title = document.createElement("strong");
    setDataContent(title, bucket.name || bucket.id || "Codex", Boolean(bucket.name || bucket.id));
    const plan = document.createElement("span");
    plan.textContent = bucket.planType ? officialPlanLabel(bucket.planType) : "官方限额";
    name.append(title, plan);
    row.append(name, createOfficialLimitWindow("主要窗口", bucket.primary), createOfficialLimitWindow("次要窗口", bucket.secondary));
    container.append(row);
  }
}

function createOfficialLimitWindow(label, window) {
  const container = document.createElement("div");
  container.className = `official-limit-window${(window?.usedPercent || 0) >= 90 ? " warning" : ""}`;
  const heading = document.createElement("strong");
  heading.textContent = window && Number.isFinite(window.usedPercent) ? `${label} ${window.usedPercent}%` : `${label} --`;
  const track = document.createElement("div");
  track.className = "official-limit-track";
  const fill = document.createElement("span");
  fill.style.width = `${window?.usedPercent || 0}%`;
  track.append(fill);
  const detail = document.createElement("span");
  detail.textContent = window
    ? `${formatWindowDuration(window.windowDurationMins)} · ${formatOfficialResetTime(window.resetsAt)}`
    : "未提供";
  container.append(heading, track, detail);
  return container;
}

function officialProxySummary(proxy) {
  if (!proxy?.configured) return "服务器直连";
  const health = proxy.health;
  const status = health?.status === "ready"
    ? health.exitIp ? `出口 ${health.exitIp}` : "测试正常"
    : health?.status === "failed" ? "连接异常" : "尚未测试";
  return `${proxy.label || proxy.protocol.toUpperCase()} · ${proxy.host}:${proxy.port} · ${status}`;
}

function activeStoredOfficialAccount() {
  const accounts = Array.isArray(state.officialAccount?.accounts) ? state.officialAccount.accounts : [];
  return accounts.find((account) =>
    account.id === state.officialAccount?.activeAccountId || account.active === true) || null;
}

function openOfficialProxyDialogForLogin(account = null) {
  const source = account || activeStoredOfficialAccount();
  openOfficialProxyDialog({
    mode: "login",
    account: source,
  });
}

function openOfficialProxyDialogForAccount(account) {
  openOfficialProxyDialog({ mode: "save", account });
}

function openOfficialProxyDialog({ mode, account = null }) {
  const proxy = account?.proxy || null;
  state.officialProxyContext = {
    mode,
    account,
    sourceAccountId: account?.id || null,
    sourceProxy: proxy,
  };
  state.officialProxyBusy = false;
  state.officialProxyHealth = proxy?.health || null;
  elements.officialProxyModeInput.value = proxy?.protocol || "direct";
  elements.officialProxyLabelInput.value = proxy?.label || "";
  elements.officialProxyHostInput.value = proxy?.host || "";
  elements.officialProxyPortInput.value = proxy?.port || "";
  elements.officialProxyAuthInput.checked = proxy?.hasAuthentication === true;
  elements.officialProxyUsernameInput.value = "";
  elements.officialProxyPasswordInput.value = "";
  elements.officialProxyError.textContent = "";
  renderOfficialProxyDialog();
  elements.officialProxyDialog.showModal();
  refreshIcons();
  requestAnimationFrame(() => elements.officialProxyModeInput.focus());
}

function closeOfficialProxyDialog() {
  if (state.officialProxyBusy) return;
  elements.officialProxyDialog.close();
  elements.officialProxyPasswordInput.value = "";
  elements.officialProxyUsernameInput.value = "";
  state.officialProxyContext = null;
  state.officialProxyHealth = null;
}

function renderOfficialProxyDialog() {
  const context = state.officialProxyContext;
  if (!context) return;
  const direct = elements.officialProxyModeInput.value === "direct";
  const authentication = !direct && elements.officialProxyAuthInput.checked;
  const existingAuthentication = context.sourceProxy?.hasAuthentication === true;
  elements.officialProxyTitle.textContent = context.mode === "save"
    ? "设置账号网络出口"
    : context.account?.credentialStatus === "invalid"
      ? "重新登录并恢复账号"
      : "登录前选择网络出口";
  elements.officialProxyAccountLabel.textContent = context.mode === "save"
    ? "此设置仅绑定到当前账号"
    : context.account ? "沿用此账号的出口配置" : "新官方账号";
  elements.officialProxyAccountEmail.textContent = context.account?.email
    || (context.mode === "save" ? "未提供邮箱" : "登录成功后自动绑定到账号");
  elements.officialProxyFields.hidden = direct;
  elements.officialProxyCredentialFields.hidden = !authentication;
  elements.officialProxySecretHint.textContent = authentication && existingAuthentication
    ? "用户名和密码留空会保留原认证；填写时必须同时更新两项。凭据始终加密保存。"
    : "代理凭据会加密保存在服务器，仅用于这个官方账号的 OpenAI / ChatGPT 连接。";
  elements.officialProxyResult.hidden = direct || !state.officialProxyHealth;
  if (!elements.officialProxyResult.hidden) {
    const health = state.officialProxyHealth;
    elements.officialProxyResult.dataset.status = health.status || "unknown";
    elements.officialProxyResult.textContent = health.status === "ready"
      ? `测试正常${health.exitIp ? ` · 出口 IP ${health.exitIp}` : ""}${Number.isFinite(health.latencyMs) ? ` · ${health.latencyMs} ms` : ""}`
      : `连接异常${health.code ? ` · ${health.code}` : ""}`;
  }
  elements.officialProxyModeInput.disabled = state.officialProxyBusy;
  elements.officialProxyLabelInput.disabled = state.officialProxyBusy;
  elements.officialProxyHostInput.disabled = state.officialProxyBusy;
  elements.officialProxyPortInput.disabled = state.officialProxyBusy;
  elements.officialProxyAuthInput.disabled = state.officialProxyBusy;
  elements.officialProxyUsernameInput.disabled = state.officialProxyBusy;
  elements.officialProxyPasswordInput.disabled = state.officialProxyBusy;
  elements.officialProxyTestButton.disabled = state.officialProxyBusy || direct;
  elements.officialProxyCancelButton.disabled = state.officialProxyBusy;
  elements.officialProxyCloseButton.disabled = state.officialProxyBusy;
  elements.officialProxySubmitButton.disabled = state.officialProxyBusy;
  elements.officialProxySubmitButton.querySelector("span").textContent = state.officialProxyBusy
    ? context.mode === "save" ? "正在保存" : "正在启动"
    : context.mode === "save" ? "保存出口" : "开始登录";
  elements.officialProxySubmitButton.querySelector("svg")?.setAttribute(
    "data-lucide",
    context.mode === "save" ? "save" : "log-in",
  );
}

function officialProxyDialogPayload() {
  const context = state.officialProxyContext;
  if (!context) throw new Error("代理设置已关闭");
  const protocol = elements.officialProxyModeInput.value;
  if (protocol === "direct") return { proxy: null };
  const host = elements.officialProxyHostInput.value.trim();
  const port = Number(elements.officialProxyPortInput.value);
  if (!host) throw new Error("请输入代理主机");
  if (!Number.isInteger(port) || port < 1 || port > 65535) throw new Error("请输入有效代理端口");
  const authentication = elements.officialProxyAuthInput.checked;
  const username = authentication ? elements.officialProxyUsernameInput.value : "";
  const password = authentication ? elements.officialProxyPasswordInput.value : "";
  const preserveAuthentication = authentication
    && context.sourceProxy?.hasAuthentication === true
    && !username
    && !password;
  if (authentication && !preserveAuthentication && (!username || !password)) {
    throw new Error("代理认证需要同时填写用户名和密码");
  }
  return {
    proxy: {
      protocol,
      host,
      port,
      label: elements.officialProxyLabelInput.value.trim(),
      username,
      password,
    },
    ...(context.sourceAccountId ? { proxyAccountId: context.sourceAccountId } : {}),
    ...(preserveAuthentication ? { preserveAuthentication: true } : {}),
  };
}

async function testOfficialProxyDialog() {
  elements.officialProxyError.textContent = "";
  let payload;
  try {
    payload = officialProxyDialogPayload();
  } catch (error) {
    elements.officialProxyError.textContent = error.message;
    return;
  }
  if (!payload.proxy) return;
  state.officialProxyBusy = true;
  renderOfficialProxyDialog();
  try {
    const response = await fetch("/api/providers/official/proxy/test", {
      method: "POST",
      headers: {
        "Content-Type": "application/json",
        "X-Codex-Desktop-Action": "official-proxy-test",
      },
      body: JSON.stringify(payload),
    });
    const data = await readApiJson(response, "住宅代理测试失败");
    state.officialProxyHealth = data.proxy?.health || null;
  } catch (error) {
    state.officialProxyHealth = { status: "failed", code: "connect" };
    elements.officialProxyError.textContent = error.message;
  } finally {
    state.officialProxyBusy = false;
    renderOfficialProxyDialog();
  }
}

async function submitOfficialProxyDialog(event) {
  event.preventDefault();
  const context = state.officialProxyContext;
  if (!context) return;
  elements.officialProxyError.textContent = "";
  let payload;
  try {
    payload = officialProxyDialogPayload();
  } catch (error) {
    elements.officialProxyError.textContent = error.message;
    return;
  }
  if (context.mode === "login") {
    await startOfficialLogin(payload);
    return;
  }
  state.officialProxyBusy = true;
  renderOfficialProxyDialog();
  try {
    const response = await fetch(
      `/api/providers/official/accounts/${encodeURIComponent(context.account.id)}/proxy`,
      {
        method: "PUT",
        headers: {
          "Content-Type": "application/json",
          "X-Codex-Desktop-Action": "official-proxy-save",
        },
        body: JSON.stringify(payload),
      },
    );
    state.officialAccount = await readApiJson(response, "无法保存账号网络出口");
    state.officialProxyBusy = false;
    closeOfficialProxyDialog();
    toast(payload.proxy ? "账号住宅出口已保存" : "账号已改为服务器直连");
  } catch (error) {
    elements.officialProxyError.textContent = error.message;
    state.officialProxyBusy = false;
    renderOfficialProxyDialog();
  } finally {
    elements.officialProxyPasswordInput.value = "";
    renderOfficialAccount();
  }
}

async function startOfficialLogin(proxyPayload = { proxy: null }) {
  elements.officialAccountError.textContent = "";
  state.officialProxyBusy = true;
  state.officialAccountLoading = true;
  renderOfficialProxyDialog();
  renderOfficialAccount();
  try {
    const response = await fetch("/api/providers/official/login/start", {
      method: "POST",
      headers: {
        "Content-Type": "application/json",
        "X-Codex-Desktop-Action": "official-login-start",
      },
      body: JSON.stringify({
        viewport: desiredOfficialBrowserViewport(),
        ...proxyPayload,
      }),
    });
    const data = await readApiJson(response, "无法开始官方登录");
    state.officialAccount = { ...(state.officialAccount || {}), pendingLogin: data.pendingLogin };
    state.officialProxyBusy = false;
    closeOfficialProxyDialog();
    if (data.pendingLogin?.browser?.active) openOfficialBrowserDialog();
  } catch (error) {
    elements.officialProxyError.textContent = error.message;
  } finally {
    elements.officialProxyPasswordInput.value = "";
    state.officialProxyBusy = false;
    state.officialAccountLoading = false;
    renderOfficialProxyDialog();
    renderOfficialAccount();
    if (state.officialAccount?.pendingLogin) scheduleOfficialLoginPolling();
  }
}

async function cancelOfficialLogin() {
  state.officialAccountLoading = true;
  renderOfficialAccount();
  try {
    const response = await fetch("/api/providers/official/login/cancel", {
      method: "POST",
      headers: { "X-Codex-Desktop-Action": "official-login-cancel" },
    });
    if (!response.ok) await readApiJson(response, "无法取消官方登录");
    state.officialAccount.pendingLogin = null;
    stopOfficialLoginPolling();
    closeOfficialBrowserDialog();
  } catch (error) {
    elements.officialAccountError.textContent = error.message;
  } finally {
    state.officialAccountLoading = false;
    renderOfficialAccount();
  }
}

function closeActiveOfficialBrowser() {
  if (state.officialBrowserRuntime === "codex-app") {
    void cancelCodexAppInstallBrowser();
    return;
  }
  if (state.officialBrowserRuntime === "codex-mcp") {
    void closeCodexMcpOAuthBrowser();
    return;
  }
  if (["claude", "claude-mcp"].includes(state.officialBrowserRuntime)) {
    closeOfficialBrowserDialog();
    return;
  }
  void cancelOfficialLogin();
}

function cancelActiveOfficialBrowserLogin() {
  if (state.officialBrowserRuntime === "codex-app") {
    void cancelCodexAppInstallBrowser();
    return;
  }
  if (state.officialBrowserRuntime === "claude") {
    void cancelClaudeOfficialLogin();
    return;
  }
  if (state.officialBrowserRuntime === "claude-mcp") {
    closeOfficialBrowserDialog();
    return;
  }
  if (state.officialBrowserRuntime === "codex-mcp") {
    void closeCodexMcpOAuthBrowser();
    return;
  }
  void cancelOfficialLogin();
}

async function cancelCodexAppInstallBrowser() {
  state.codexAppInstall = { appId: null, browser: null, busy: false };
  closeOfficialBrowserDialog();
  if (elements.codexExtensionDialog.open) renderCodexAppsCenter();
  try {
    const response = await fetch("/api/codex/apps/install/browser/close", {
      method: "POST",
      headers: { "X-Codex-Desktop-Action": "codex-app-install-browser-close" },
    });
    await readApiJson(response, "无法关闭 Codex App 连接窗口");
  } catch (error) {
    toast(error.message, "error");
  }
}

async function closeCodexMcpOAuthBrowser() {
  try {
    const response = await fetch("/api/codex/mcp/oauth/browser/close", {
      method: "POST",
      headers: { "X-Codex-Desktop-Action": "codex-mcp-oauth-browser-close" },
    });
    await readApiJson(response, "无法关闭 MCP OAuth 浏览器");
  } catch (error) {
    toast(error.message, "error");
  } finally {
    state.codexMcpOAuthBrowser = null;
    closeOfficialBrowserDialog();
  }
}

function desiredOfficialBrowserViewport() {
  const mobile = window.matchMedia("(max-width: 600px)").matches;
  return mobile
    ? { width: Math.max(360, Math.min(480, window.innerWidth)), height: Math.max(560, Math.min(900, window.innerHeight - 110)) }
    : { width: Math.max(900, Math.min(1280, window.innerWidth - 120)), height: Math.max(560, Math.min(900, window.innerHeight - 120)) };
}

function openOfficialBrowserDialogLegacy() {
  const browser = state.officialAccount?.pendingLogin?.browser;
  if (!browser?.active) return;
  state.officialBrowserViewport = browser.viewport || desiredOfficialBrowserViewport();
  elements.officialBrowserStage.style.aspectRatio = `${state.officialBrowserViewport.width} / ${state.officialBrowserViewport.height}`;
  elements.officialBrowserLoading.hidden = false;
  elements.officialBrowserStatus.textContent = "隔离会话";
  if (!elements.officialBrowserDialog.open) elements.officialBrowserDialog.showModal();
  startOfficialBrowserCountdown();
  connectOfficialBrowserStream();
}

function closeOfficialBrowserDialogLegacy() {
  state.officialBrowserStream?.close();
  clearTimeout(state.officialBrowserFallbackTimer);
  clearInterval(state.officialBrowserCountdownTimer);
  state.officialBrowserStream = null;
  state.officialBrowserFallbackTimer = null;
  state.officialBrowserCountdownTimer = null;
  state.officialBrowserFrameLoading = false;
  state.officialBrowserFramePending = null;
  state.officialBrowserFrameDecoding = false;
  elements.officialBrowserKeyboardInput.value = "";
  elements.officialBrowserKeyboardInput.inputMode = "text";
  delete elements.officialBrowserFrame.dataset.ready;
  const context = elements.officialBrowserFrame.getContext("2d");
  context?.clearRect(0, 0, elements.officialBrowserFrame.width, elements.officialBrowserFrame.height);
  if (elements.officialBrowserDialog.open) elements.officialBrowserDialog.close();
}

function connectOfficialBrowserStream() {
  state.officialBrowserStream?.close();
  clearTimeout(state.officialBrowserFallbackTimer);
  const stream = new EventSource(`/api/providers/official/login/browser/stream?_=${Date.now()}`);
  state.officialBrowserStream = stream;
  elements.officialBrowserStatus.textContent = "正在连接服务器";
  stream.addEventListener("open", () => {
    if (state.officialBrowserStream !== stream) return;
    elements.officialBrowserStatus.textContent = "服务器实时连接";
  });
  stream.addEventListener("message", (event) => {
    if (state.officialBrowserStream !== stream) return;
    let payload;
    try {
      payload = JSON.parse(event.data);
    } catch {
      return;
    }
    if (payload?.type === "closed") {
      closeOfficialBrowserDialog();
      void loadOfficialAccount({ silent: true });
      return;
    }
    if (payload?.type !== "frame" || typeof payload.data !== "string") return;
    clearTimeout(state.officialBrowserFallbackTimer);
    state.officialBrowserFallbackTimer = null;
    queueOfficialBrowserFrame(payload);
  });
  stream.addEventListener("error", () => {
    if (state.officialBrowserStream !== stream || !elements.officialBrowserDialog.open) return;
    elements.officialBrowserStatus.textContent = "实时连接重连中";
    if (!state.officialBrowserFallbackTimer) {
      state.officialBrowserFallbackTimer = setTimeout(() => {
        state.officialBrowserFallbackTimer = null;
        void loadOfficialBrowserFrame();
      }, 1_000);
    }
  });
  state.officialBrowserFallbackTimer = setTimeout(() => {
    state.officialBrowserFallbackTimer = null;
    void loadOfficialBrowserFrame();
  }, 2_000);
}

function queueOfficialBrowserFrame(payload) {
  const width = Number(payload.width);
  const height = Number(payload.height);
  if (!Number.isFinite(width) || !Number.isFinite(height) || width <= 0 || height <= 0) return;
  state.officialBrowserFramePending = {
    data: payload.data,
    host: typeof payload.host === "string" ? payload.host : "auth.openai.com",
    width: Math.round(width),
    height: Math.round(height),
    token: ++state.officialBrowserFrameToken,
  };
  if (!state.officialBrowserFrameDecoding) decodeNextOfficialBrowserFrame();
}

function decodeNextOfficialBrowserFrame() {
  const frame = state.officialBrowserFramePending;
  if (!frame || !elements.officialBrowserDialog.open) {
    state.officialBrowserFrameDecoding = false;
    return;
  }
  state.officialBrowserFramePending = null;
  state.officialBrowserFrameDecoding = true;
  const image = new Image();
  image.addEventListener("load", () => {
    const newerFrameWaiting = state.officialBrowserFramePending?.token > frame.token;
    if (!newerFrameWaiting && elements.officialBrowserDialog.open) {
      state.officialBrowserViewport = { width: frame.width, height: frame.height };
      elements.officialBrowserStage.style.aspectRatio = `${frame.width} / ${frame.height}`;
      if (elements.officialBrowserFrame.width !== frame.width) elements.officialBrowserFrame.width = frame.width;
      if (elements.officialBrowserFrame.height !== frame.height) elements.officialBrowserFrame.height = frame.height;
      elements.officialBrowserFrame.getContext("2d")?.drawImage(image, 0, 0, frame.width, frame.height);
      elements.officialBrowserFrame.dataset.ready = "true";
      elements.officialBrowserHost.textContent = frame.host;
      elements.officialBrowserLoading.hidden = true;
      elements.officialBrowserStatus.textContent = "服务器实时连接";
    }
    state.officialBrowserFrameDecoding = false;
    if (state.officialBrowserFramePending) decodeNextOfficialBrowserFrame();
  }, { once: true });
  image.addEventListener("error", () => {
    state.officialBrowserFrameDecoding = false;
    if (state.officialBrowserFramePending) decodeNextOfficialBrowserFrame();
  }, { once: true });
  image.src = `data:image/jpeg;base64,${frame.data}`;
}

async function loadOfficialBrowserFrame({ immediate = false } = {}) {
  if (!elements.officialBrowserDialog.open || state.officialBrowserFrameLoading) return;
  state.officialBrowserFrameLoading = true;
  if (immediate) elements.officialBrowserRefreshButton.disabled = true;
  try {
    const response = await fetch(`/api/providers/official/login/browser/frame?_=${Date.now()}`, { cache: "no-store" });
    if (!response.ok) throw new Error((await response.json().catch(() => null))?.error || "服务器登录画面已关闭");
    const blob = await response.blob();
    const dataUrl = await new Promise((resolve, reject) => {
      const reader = new FileReader();
      reader.addEventListener("load", () => resolve(reader.result), { once: true });
      reader.addEventListener("error", () => reject(new Error("服务器登录画面解码失败")), { once: true });
      reader.readAsDataURL(blob);
    });
    const width = Number(response.headers.get("X-WFL-Browser-Width"));
    const height = Number(response.headers.get("X-WFL-Browser-Height"));
    if (Number.isFinite(width) && Number.isFinite(height) && width > 0 && height > 0) {
      queueOfficialBrowserFrame({
        type: "frame",
        data: String(dataUrl).replace(/^data:image\/jpeg;base64,/, ""),
        host: response.headers.get("X-WFL-Browser-Host") || "auth.openai.com",
        width,
        height,
      });
    }
  } catch (error) {
    elements.officialBrowserStatus.textContent = error.message;
    if (/已关闭|请先登录/.test(error.message)) {
      closeOfficialBrowserDialog();
      void loadOfficialAccount({ silent: true });
      return;
    }
  } finally {
    state.officialBrowserFrameLoading = false;
    elements.officialBrowserRefreshButton.disabled = false;
  }
}

function startOfficialBrowserCountdownLegacy() {
  clearInterval(state.officialBrowserCountdownTimer);
  const render = () => {
    const expiresAt = Number(state.officialAccount?.pendingLogin?.browser?.expiresAt || 0);
    const remaining = Math.max(0, expiresAt - Date.now());
    const minutes = Math.floor(remaining / 60_000);
    const seconds = Math.floor((remaining % 60_000) / 1_000);
    elements.officialBrowserCountdown.textContent = `${minutes}:${String(seconds).padStart(2, "0")}`;
    if (!remaining) {
      closeOfficialBrowserDialog();
      void loadOfficialAccount({ silent: true });
    }
  };
  render();
  state.officialBrowserCountdownTimer = setInterval(render, 1_000);
}

async function sendOfficialBrowserInput(payload) {
  state.officialBrowserInputQueue ||= Promise.resolve();
  state.officialBrowserInputPending ||= 0;
  const task = state.officialBrowserInputQueue.then(async () => {
    state.officialBrowserInputPending += 1;
    try {
      const response = await fetch(`${officialBrowserApiPrefix()}/input`, {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
          "X-Codex-Desktop-Action": officialBrowserAction("input"),
        },
        body: JSON.stringify(payload),
      });
      return await readApiJson(response, "服务器浏览器输入失败");
    } catch (error) {
      elements.officialBrowserStatus.textContent = error.message;
      return null;
    } finally {
      state.officialBrowserInputPending = Math.max(0, state.officialBrowserInputPending - 1);
    }
  });
  state.officialBrowserInputQueue = task.catch(() => {});
  return task;
}

async function handleOfficialBrowserClick(event) {
  const bounds = elements.officialBrowserFrame.getBoundingClientRect();
  if (!bounds.width || !bounds.height) return;
  const sourceRatio = state.officialBrowserViewport.width / state.officialBrowserViewport.height;
  const targetRatio = bounds.width / bounds.height;
  const contentWidth = targetRatio > sourceRatio ? bounds.height * sourceRatio : bounds.width;
  const contentHeight = targetRatio > sourceRatio ? bounds.height : bounds.width / sourceRatio;
  const offsetX = bounds.left + (bounds.width - contentWidth) / 2;
  const offsetY = bounds.top + (bounds.height - contentHeight) / 2;
  if (event.clientX < offsetX || event.clientX > offsetX + contentWidth || event.clientY < offsetY || event.clientY > offsetY + contentHeight) return;
  const result = await sendOfficialBrowserInput({
    type: "click",
    x: (event.clientX - offsetX) * state.officialBrowserViewport.width / contentWidth,
    y: (event.clientY - offsetY) * state.officialBrowserViewport.height / contentHeight,
    clickCount: event.detail === 2 ? 2 : 1,
  });
  if (result?.editable) {
    elements.officialBrowserKeyboardInput.inputMode = ["email", "numeric", "tel", "text"].includes(result.inputMode)
      ? result.inputMode
      : "text";
    elements.officialBrowserKeyboardInput.focus({ preventScroll: true });
  }
  else elements.officialBrowserFrame.focus({ preventScroll: true });
}

function handleOfficialBrowserWheel(event) {
  event.preventDefault();
  void sendOfficialBrowserInput({ type: "wheel", deltaX: event.deltaX, deltaY: event.deltaY });
}

function handleOfficialBrowserKeydown(event) {
  if (event.isComposing || event.key === "Process" || event.key === "Dead") return;
  const key = event.key === " " ? "Space" : event.key;
  const modifiers = [
    event.altKey ? "Alt" : null,
    event.ctrlKey ? "Control" : null,
    event.metaKey ? "Meta" : null,
    event.shiftKey ? "Shift" : null,
  ].filter(Boolean);
  const special = /^(?:Backspace|Tab|Enter|Escape|Delete|Insert|Home|End|PageUp|PageDown|ArrowUp|ArrowDown|ArrowLeft|ArrowRight|Space)$/.test(key);
  if (special || (key.length === 1 && modifiers.some((value) => ["Control", "Meta", "Alt"].includes(value)))) {
    event.preventDefault();
    void sendOfficialBrowserInput({ type: "key", key, modifiers });
    return;
  }
  if (event.key.length === 1) {
    event.preventDefault();
    void sendOfficialBrowserInput({ type: "text", text: event.key });
  }
}

function handleOfficialBrowserTextInput(event) {
  if (event?.isComposing) return;
  const text = elements.officialBrowserKeyboardInput.value;
  elements.officialBrowserKeyboardInput.value = "";
  if (text) void sendOfficialBrowserInput({ type: "text", text });
}

function handleOfficialBrowserPaste(event) {
  const text = event.clipboardData?.getData("text/plain") || "";
  if (!text) return;
  event.preventDefault();
  elements.officialBrowserKeyboardInput.value = "";
  void sendOfficialBrowserInput({ type: "text", text: text.slice(0, 2_048) });
}

function activeOfficialBrowserSession(runtime = state.officialBrowserRuntime) {
  if (runtime === "claude") {
    return state.claudeConfig?.runtime?.officialLogin?.browser
      || state.claudeConfig?.runtime?.officialLoginBrowser
      || null;
  }
  if (runtime === "claude-mcp") return state.claudeMcpOAuthBrowser || null;
  if (runtime === "codex-mcp") return state.codexMcpOAuthBrowser || null;
  if (runtime === "codex-app") return state.codexAppInstall.browser || null;
  return state.officialAccount?.pendingLogin?.browser || null;
}

function officialBrowserApiPrefix(runtime = state.officialBrowserRuntime) {
  if (runtime === "claude") return "/api/claude/official/login/browser";
  if (runtime === "claude-mcp") return "/api/claude/mcp/oauth/browser";
  if (runtime === "codex-mcp") return "/api/codex/mcp/oauth/browser";
  if (runtime === "codex-app") return "/api/codex/apps/install/browser";
  return "/api/providers/official/login/browser";
}

function officialBrowserAction(operation, runtime = state.officialBrowserRuntime) {
  if (runtime === "claude-mcp") return `claude-mcp-oauth-browser-${operation}`;
  if (runtime === "codex-mcp") return `codex-mcp-oauth-browser-${operation}`;
  if (runtime === "codex-app") return `codex-app-install-browser-${operation}`;
  return `${runtime === "claude" ? "claude-" : ""}official-login-browser-${operation}`;
}

async function refreshActiveOfficialLoginState(runtime = state.officialBrowserRuntime) {
  if (runtime === "claude") return loadClaudeConfig();
  if (runtime === "claude-mcp" || runtime === "codex-mcp") return null;
  if (runtime === "codex-app") {
    const response = await fetch(`/api/codex/apps/install/status?_=${Date.now()}`, { cache: "no-store" });
    const data = await readApiJson(response, "无法读取 Codex App 连接状态");
    state.codexAppInstall = {
      appId: typeof data.appId === "string" ? data.appId : null,
      browser: data.browser?.active ? data.browser : null,
      busy: false,
    };
    return state.codexAppInstall;
  }
  return loadOfficialAccount({ silent: true });
}

function openOfficialBrowserDialog(runtime = "codex") {
  const selectedRuntime = ["claude", "claude-mcp", "codex-mcp", "codex-app"].includes(runtime) ? runtime : "codex";
  const browser = activeOfficialBrowserSession(selectedRuntime);
  if (!browser?.active) return;
  state.officialBrowserRuntime = selectedRuntime;
  elements.officialBrowserDialog.dataset.runtime = selectedRuntime;
  state.officialBrowserViewport = browser.viewport || desiredOfficialBrowserViewport();
  elements.officialBrowserStage.style.aspectRatio = `${state.officialBrowserViewport.width} / ${state.officialBrowserViewport.height}`;
  elements.officialBrowserEyebrow.textContent = selectedRuntime === "codex-app"
    ? "Codex App · 服务器隔离授权"
    : ["claude-mcp", "codex-mcp"].includes(selectedRuntime)
    ? `${selectedRuntime === "claude-mcp" ? "Claude" : "Codex"} MCP 服务器 OAuth`
    : selectedRuntime === "claude" ? "Claude 服务器 OAuth" : "服务器 OAuth";
  elements.officialBrowserTitle.textContent = selectedRuntime === "codex-app"
    ? `${codexAppMetadata(state.codexAppInstall.appId).name || "Codex App"} · 连接`
    : ["claude-mcp", "codex-mcp"].includes(selectedRuntime)
    ? "MCP 授权"
    : selectedRuntime === "claude" ? "Claude 官方登录" : "Codex 官方登录";
  elements.officialBrowserHost.textContent = browser.host
    || (selectedRuntime === "claude" ? "claude.com" : selectedRuntime === "codex-app" ? "chatgpt.com" : "auth.openai.com");
  elements.officialBrowserFrame.setAttribute("aria-label", selectedRuntime === "codex-app"
    ? "Codex App 服务器连接授权"
    : ["claude-mcp", "codex-mcp"].includes(selectedRuntime)
    ? "MCP OAuth 授权" : selectedRuntime === "claude" ? "Claude 官方登录" : "OpenAI 官方登录");
  elements.officialBrowserClaudeCodeButton.hidden = selectedRuntime !== "claude";
  elements.officialBrowserClaudeCodeButton.disabled = false;
  elements.officialBrowserCompleteButton.hidden = selectedRuntime !== "codex-app";
  elements.officialBrowserCompleteButton.disabled = false;
  elements.officialBrowserCancelButton.textContent = selectedRuntime === "codex-app" ? "取消连接" : "取消登录";
  elements.officialBrowserRefreshButton.title = selectedRuntime === "claude" ? "重新打开授权页" : "重新连接";
  elements.officialBrowserRefreshButton.setAttribute(
    "aria-label",
    selectedRuntime === "claude" ? "重新打开 Claude 授权页" : "重新连接服务器登录窗口",
  );
  elements.officialBrowserLoading.hidden = false;
  elements.officialBrowserStatus.textContent = "正在连接服务器";
  elements.officialBrowserKeyboardTray.hidden = true;
  elements.officialBrowserClipboardTray.hidden = true;
  elements.officialBrowserKeyboardButton.setAttribute("aria-pressed", "false");
  elements.officialBrowserKeyboardButton.querySelector("span").textContent = "输入键盘";
  elements.officialBrowserClipboardButton.setAttribute("aria-pressed", "false");
  if (!elements.officialBrowserDialog.open) {
    state.officialBrowserPendingInputs = [];
    elements.officialBrowserDialog.showModal();
  }
  startOfficialBrowserCountdown();
  void connectOfficialBrowserVnc({ manual: true });
}

async function reopenClaudeOfficialAuthorizationPage({ silent = false } = {}) {
  if (state.officialBrowserRuntime !== "claude") return false;
  elements.officialBrowserRefreshButton.disabled = true;
  elements.officialBrowserStatus.textContent = "正在重新打开 Claude 授权页";
  try {
    const response = await fetch("/api/claude/official/login/browser/authorize", {
      method: "POST",
      headers: { "X-Codex-Desktop-Action": "claude-official-login-browser-authorize" },
    });
    await readApiJson(response, "无法重新打开 Claude 授权页");
    if (!silent) toast("已重新打开 Claude 授权页");
    state.officialBrowserRfb?.focus({ preventScroll: true });
    return true;
  } catch (error) {
    elements.officialBrowserStatus.textContent = error.message;
    if (!silent) toast(error.message, "error");
    throw error;
  } finally {
    elements.officialBrowserRefreshButton.disabled = false;
  }
}

function refreshOfficialBrowser() {
  if (state.officialBrowserRuntime === "claude") {
    void reopenClaudeOfficialAuthorizationPage();
    return;
  }
  void connectOfficialBrowserVnc({ manual: true });
}

function closeOfficialBrowserDialog() {
  clearTimeout(state.officialBrowserReconnectTimer);
  clearInterval(state.officialBrowserCountdownTimer);
  state.officialBrowserReconnectTimer = null;
  state.officialBrowserCountdownTimer = null;
  state.officialBrowserReconnectAttempts = 0;
  state.officialBrowserClipboardText = "";
  state.officialBrowserClipboardWritePending = false;
  state.officialBrowserPendingInputs = [];
  state.officialBrowserConnectGeneration += 1;
  const rfb = state.officialBrowserRfb;
  state.officialBrowserRfb = null;
  try {
    rfb?.disconnect();
  } catch {}
  elements.officialBrowserFrame.replaceChildren();
  delete elements.officialBrowserFrame.dataset.ready;
  elements.officialBrowserKeyboardInput.value = "";
  elements.officialBrowserClipboardInput.value = "";
  elements.officialBrowserKeyboardTray.hidden = true;
  elements.officialBrowserClipboardTray.hidden = true;
  elements.officialBrowserKeyboardButton.setAttribute("aria-pressed", "false");
  elements.officialBrowserKeyboardButton.querySelector("span").textContent = "输入键盘";
  elements.officialBrowserClaudeCodeButton.hidden = true;
  elements.officialBrowserClaudeCodeButton.disabled = false;
  elements.officialBrowserCompleteButton.hidden = true;
  elements.officialBrowserCompleteButton.disabled = false;
  elements.officialBrowserCancelButton.textContent = "取消登录";
  delete elements.officialBrowserDialog.dataset.runtime;
  if (elements.officialBrowserDialog.open) elements.officialBrowserDialog.close();
  state.officialBrowserRuntime = null;
}

async function connectOfficialBrowserVnc({ manual = false } = {}) {
  if (!elements.officialBrowserDialog.open) return;
  if (manual) state.officialBrowserReconnectAttempts = 0;
  clearTimeout(state.officialBrowserReconnectTimer);
  state.officialBrowserReconnectTimer = null;
  const generation = ++state.officialBrowserConnectGeneration;
  const previous = state.officialBrowserRfb;
  state.officialBrowserRfb = null;
  try {
    previous?.disconnect();
  } catch {}
  elements.officialBrowserFrame.replaceChildren();
  delete elements.officialBrowserFrame.dataset.ready;
  elements.officialBrowserLoading.hidden = false;
  elements.officialBrowserRefreshButton.disabled = true;
  elements.officialBrowserStatus.textContent = "正在连接服务器";
  try {
    const { default: RFB } = await import("/vendor/novnc-1.7.0/core/rfb.js?v=0.44.61-beta");
    if (generation !== state.officialBrowserConnectGeneration || !elements.officialBrowserDialog.open) return;
    const protocol = location.protocol === "https:" ? "wss:" : "ws:";
    const rfb = new RFB(
      elements.officialBrowserFrame,
      `${protocol}//${location.host}${officialBrowserApiPrefix()}/vnc`,
      { shared: true },
    );
    state.officialBrowserRfb = rfb;
    rfb.background = "#ffffff";
    rfb.scaleViewport = true;
    rfb.clipViewport = false;
    rfb.resizeSession = false;
    rfb.focusOnClick = true;
    rfb.compressionLevel = 2;
    rfb.qualityLevel = 7;
    rfb.addEventListener("connect", () => {
      if (state.officialBrowserRfb !== rfb || generation !== state.officialBrowserConnectGeneration) return;
      state.officialBrowserReconnectAttempts = 0;
      elements.officialBrowserFrame.dataset.ready = "true";
      elements.officialBrowserLoading.hidden = true;
      elements.officialBrowserRefreshButton.disabled = false;
      elements.officialBrowserStatus.textContent = "服务器实时连接";
      flushOfficialBrowserPendingInputs();
      rfb.focus({ preventScroll: true });
    });
    rfb.addEventListener("clipboard", (event) => handleOfficialBrowserRemoteClipboard(event.detail?.text || ""));
    rfb.addEventListener("securityfailure", () => {
      if (state.officialBrowserRfb === rfb) elements.officialBrowserStatus.textContent = "服务器浏览器验证失败";
    });
    rfb.addEventListener("disconnect", () => {
      if (state.officialBrowserRfb !== rfb || generation !== state.officialBrowserConnectGeneration) return;
      state.officialBrowserRfb = null;
      delete elements.officialBrowserFrame.dataset.ready;
      elements.officialBrowserLoading.hidden = false;
      elements.officialBrowserRefreshButton.disabled = false;
      scheduleOfficialBrowserReconnect();
    });
  } catch (error) {
    if (generation !== state.officialBrowserConnectGeneration) return;
    elements.officialBrowserRefreshButton.disabled = false;
    elements.officialBrowserStatus.textContent = error.message || "服务器浏览器连接失败";
    scheduleOfficialBrowserReconnect();
  }
}

function scheduleOfficialBrowserReconnect() {
  if (!elements.officialBrowserDialog.open || state.officialBrowserReconnectTimer) return;
  if (state.officialBrowserReconnectAttempts >= 5) {
    elements.officialBrowserStatus.textContent = "连接已断开";
    return;
  }
  state.officialBrowserReconnectAttempts += 1;
  elements.officialBrowserStatus.textContent = "正在重新连接";
  const delay = Math.min(3_000, 500 * state.officialBrowserReconnectAttempts);
  const runtime = state.officialBrowserRuntime;
  state.officialBrowserReconnectTimer = setTimeout(async () => {
    state.officialBrowserReconnectTimer = null;
    await refreshActiveOfficialLoginState(runtime).catch(() => {});
    if (elements.officialBrowserDialog.open) void connectOfficialBrowserVnc();
  }, delay);
}

function startOfficialBrowserCountdown() {
  clearInterval(state.officialBrowserCountdownTimer);
  const render = () => {
    const runtime = state.officialBrowserRuntime;
    const expiresAt = Number(activeOfficialBrowserSession(runtime)?.expiresAt || 0);
    const remaining = Math.max(0, expiresAt - Date.now());
    const minutes = Math.floor(remaining / 60_000);
    const seconds = Math.floor((remaining % 60_000) / 1_000);
    elements.officialBrowserCountdown.textContent = `${minutes}:${String(seconds).padStart(2, "0")}`;
    if (!remaining) {
      closeOfficialBrowserDialog();
      void refreshActiveOfficialLoginState(runtime).catch(() => {});
    }
  };
  render();
  state.officialBrowserCountdownTimer = setInterval(render, 1_000);
}

function toggleOfficialBrowserKeyboard() {
  const opening = elements.officialBrowserKeyboardTray.hidden;
  elements.officialBrowserKeyboardTray.hidden = !opening;
  elements.officialBrowserClipboardTray.hidden = true;
  elements.officialBrowserKeyboardButton.setAttribute("aria-pressed", String(opening));
  elements.officialBrowserKeyboardButton.querySelector("span").textContent = opening ? "关闭键盘" : "输入键盘";
  elements.officialBrowserClipboardButton.setAttribute("aria-pressed", "false");
  if (opening) {
    elements.officialBrowserKeyboardInput.value = "";
    elements.officialBrowserKeyboardInput.focus({ preventScroll: true });
  } else {
    state.officialBrowserRfb?.focus({ preventScroll: true });
  }
}

function toggleOfficialBrowserClipboard() {
  const opening = elements.officialBrowserClipboardTray.hidden;
  elements.officialBrowserClipboardTray.hidden = !opening;
  elements.officialBrowserKeyboardTray.hidden = true;
  elements.officialBrowserClipboardButton.setAttribute("aria-pressed", String(opening));
  elements.officialBrowserKeyboardButton.setAttribute("aria-pressed", "false");
  elements.officialBrowserKeyboardButton.querySelector("span").textContent = "输入键盘";
  if (opening && document.activeElement !== elements.officialBrowserClipboardInput) {
    elements.officialBrowserClipboardInput.value = state.officialBrowserClipboardText;
  }
}

function handleOfficialBrowserKeyboardBeforeInput(event) {
  if (event.inputType === "deleteContentBackward" && !elements.officialBrowserKeyboardInput.value) {
    event.preventDefault();
    sendOfficialBrowserKey(0xff08, "Backspace");
  } else if (event.inputType === "insertLineBreak") {
    event.preventDefault();
    sendOfficialBrowserKey(0xff0d, "Enter");
  }
}

function handleOfficialBrowserKeyboardInput(event) {
  if (event?.isComposing) return;
  const text = elements.officialBrowserKeyboardInput.value;
  elements.officialBrowserKeyboardInput.value = "";
  if (text) sendOfficialBrowserText(text);
}

function handleOfficialBrowserKeyboardKeydown(event) {
  if (event.isComposing || event.key === "Process" || event.key === "Dead") return;
  const keysyms = {
    Backspace: [0xff08, "Backspace"],
    Tab: [0xff09, "Tab"],
    Enter: [0xff0d, "Enter"],
    Escape: [0xff1b, "Escape"],
    Delete: [0xffff, "Delete"],
  };
  const key = keysyms[event.key];
  if (!key) return;
  event.preventDefault();
  sendOfficialBrowserKey(...key);
}

function handleOfficialBrowserKeyboardPaste(event) {
  const text = event.clipboardData?.getData("text/plain") || "";
  if (!text) return;
  event.preventDefault();
  pasteOfficialBrowserText(text);
}

function sendOfficialBrowserText(text) {
  const characters = [...String(text).replace(/\r\n?/g, "\n")].slice(0, 2_048);
  if (!characters.length) return;
  queueOfficialBrowserRfbInput({ type: "text", text: characters.join("") });
}

function dispatchOfficialBrowserRfbInput(input) {
  const rfb = state.officialBrowserRfb;
  if (!rfb || elements.officialBrowserFrame.dataset.ready !== "true") return false;
  try {
    if (input.type === "key") {
      rfb.sendKey(input.keysym, input.code);
      return true;
    }
    const characters = [...input.text];
    for (const character of characters) {
      if (character === "\n") {
        rfb.sendKey(0xff0d, "Enter");
        continue;
      }
      if (character === "\t") {
        rfb.sendKey(0xff09, "Tab");
        continue;
      }
      const codePoint = character.codePointAt(0);
      rfb.sendKey(codePoint > 0xff ? 0x01000000 | codePoint : codePoint);
    }
    return true;
  } catch {
    return false;
  }
}

function queueOfficialBrowserRfbInput(input) {
  if (dispatchOfficialBrowserRfbInput(input)) return;
  const queue = state.officialBrowserPendingInputs;
  if (queue.length >= 64) {
    queue.shift();
    toast("服务器浏览器输入队列已满，最早一项未发送", "warning");
  }
  queue.push(input);
  elements.officialBrowserStatus.textContent = "连接恢复后继续输入";
}

function flushOfficialBrowserPendingInputs() {
  while (state.officialBrowserPendingInputs.length) {
    const input = state.officialBrowserPendingInputs[0];
    if (!dispatchOfficialBrowserRfbInput(input)) return;
    state.officialBrowserPendingInputs.shift();
  }
}

function sendOfficialBrowserKey(keysym, code) {
  queueOfficialBrowserRfbInput({ type: "key", keysym, code });
}

function handleOfficialBrowserShortcut(event) {
  if (event.altKey && ["ArrowLeft", "ArrowRight"].includes(event.key)) {
    event.preventDefault();
    event.stopImmediatePropagation();
    elements.officialBrowserStatus.textContent = "已阻止浏览器历史导航";
    return;
  }
  if (!(event.ctrlKey || event.metaKey) || event.altKey) return;
  const key = event.key.toLowerCase();
  if (["h", "j", "l", "n", "p", "r", "t", "w"].includes(key)) {
    event.preventDefault();
    event.stopImmediatePropagation();
    elements.officialBrowserStatus.textContent = "已阻止浏览器窗口快捷键";
    return;
  }
  if (!["c", "v", "x"].includes(key)) return;
  event.preventDefault();
  event.stopImmediatePropagation();
  if (key === "v") {
    navigator.clipboard.readText()
      .then((text) => pasteOfficialBrowserText(text))
      .catch(() => {
        if (elements.officialBrowserClipboardTray.hidden) toggleOfficialBrowserClipboard();
        elements.officialBrowserClipboardInput.focus({ preventScroll: true });
      });
    return;
  }
  state.officialBrowserClipboardWritePending = true;
  void sendOfficialBrowserInput({ type: "key", key, modifiers: ["Control"] })
    .then(() => setTimeout(() => void captureOfficialBrowserClipboard(), 180));
  setTimeout(() => { state.officialBrowserClipboardWritePending = false; }, 5_000);
}

function handleOfficialBrowserCanvasPaste(event) {
  const text = event.clipboardData?.getData("text/plain") || "";
  if (!text) return;
  event.preventDefault();
  event.stopImmediatePropagation();
  pasteOfficialBrowserText(text);
}

function pasteOfficialBrowserText(text) {
  const value = String(text || "");
  if (!value || !state.officialBrowserRfb) return;
  sendOfficialBrowserText(value);
  if ([...value].length > 2_048) toast("粘贴内容已截取前 2048 个字符", "warning");
}

function handleOfficialBrowserRemoteClipboard(text) {
  const value = String(text || "").slice(0, 8_192);
  state.officialBrowserClipboardText = value;
  if (document.activeElement !== elements.officialBrowserClipboardInput) {
    elements.officialBrowserClipboardInput.value = value;
  }
  if (!state.officialBrowserClipboardWritePending || !value) return;
  state.officialBrowserClipboardWritePending = false;
  navigator.clipboard.writeText(value)
    .then(() => toast("已复制服务器剪贴板"))
    .catch(() => toast("服务器剪贴板已更新，请从剪贴板面板复制", "warning"));
}

async function captureOfficialBrowserClipboard() {
  if (!state.officialBrowserClipboardWritePending || !elements.officialBrowserDialog.open) return;
  try {
    const response = await fetch(`${officialBrowserApiPrefix()}/clipboard`, {
      method: "POST",
      headers: { "X-Codex-Desktop-Action": officialBrowserAction("clipboard") },
    });
    if (!response.ok) return;
    const payload = await response.json();
    if (payload.text) handleOfficialBrowserRemoteClipboard(payload.text);
  } catch {}
}

async function copyOfficialBrowserClipboard() {
  const text = elements.officialBrowserClipboardInput.value || state.officialBrowserClipboardText;
  if (!text) return;
  try {
    await navigator.clipboard.writeText(text);
    toast("已复制服务器剪贴板");
  } catch {
    elements.officialBrowserClipboardInput.focus({ preventScroll: true });
    elements.officialBrowserClipboardInput.select();
  }
}

async function pasteOfficialBrowserClipboardFromTray() {
  let text = elements.officialBrowserClipboardInput.value;
  if (!text) {
    try {
      text = await navigator.clipboard.readText();
      elements.officialBrowserClipboardInput.value = text;
    } catch {}
  }
  pasteOfficialBrowserText(text);
  state.officialBrowserRfb?.focus({ preventScroll: true });
}

async function logoutOfficialAccount() {
  if (!confirm("移除当前官方账号？如果还有其他已保存账号，将自动切换到最近使用的账号。")) return;
  state.officialAccountLoading = true;
  renderOfficialAccount();
  try {
    const response = await fetch("/api/providers/official/logout", {
      method: "POST",
      headers: {
        "Content-Type": "application/json",
        "X-Codex-Desktop-Action": "official-logout",
      },
      body: JSON.stringify({ confirmation: "退出官方登录" }),
    });
    state.officialAccount = await readApiJson(response, "无法退出官方登录");
    toast("当前官方账号已移除");
  } catch (error) {
    elements.officialAccountError.textContent = error.message;
  } finally {
    state.officialAccountLoading = false;
    renderOfficialAccount();
  }
}

async function switchOfficialAccount(id) {
  state.officialAccountLoading = true;
  elements.officialAccountError.textContent = "";
  renderOfficialAccount();
  try {
    const response = await fetch(`/api/providers/official/accounts/${encodeURIComponent(id)}/activate`, {
      method: "POST",
      headers: { "X-Codex-Desktop-Action": "official-account-switch" },
    });
    state.officialAccount = await readApiJson(response, "无法切换官方账号");
    toast(`已切换到 ${state.officialAccount.account?.email || "官方账号"}`);
  } catch (error) {
    elements.officialAccountError.textContent = error.message;
  } finally {
    state.officialAccountLoading = false;
    renderOfficialAccount();
  }
}

async function removeOfficialAccount(account) {
  if (!confirm(`移除已保存账号 ${account.email || ""}？`)) return;
  state.officialAccountLoading = true;
  elements.officialAccountError.textContent = "";
  renderOfficialAccount();
  try {
    const response = await fetch(`/api/providers/official/accounts/${encodeURIComponent(account.id)}`, {
      method: "DELETE",
      headers: { "X-Codex-Desktop-Action": "official-account-remove" },
    });
    state.officialAccount = await readApiJson(response, "无法移除官方账号");
    toast("已移除保存的官方账号");
  } catch (error) {
    elements.officialAccountError.textContent = error.message;
  } finally {
    state.officialAccountLoading = false;
    renderOfficialAccount();
  }
}

async function activateOfficialAccount() {
  const restore = prepareProviderSwitch();
  state.officialAccountLoading = true;
  renderOfficialAccount();
  try {
    const response = await fetch("/api/providers/official/activate", {
      method: "POST",
      headers: { "X-Codex-Desktop-Action": "official-activate" },
    });
    await readApiJson(response, "无法启用官方配置");
    state.activeProviderId = null;
    await loadProviderProfiles();
    elements.providerDialog.close();
    toast("已启用 Codex 官方配置");
  } catch (error) {
    restore();
    elements.officialAccountError.textContent = error.message;
  } finally {
    state.officialAccountLoading = false;
    renderOfficialAccount();
  }
}

async function copyOfficialLoginCode() {
  const code = state.officialAccount?.pendingLogin?.userCode;
  if (!code) return;
  try {
    await navigator.clipboard.writeText(code);
    toast("验证码已复制");
  } catch {
    toast("无法访问剪贴板，请手动输入验证码", "error");
  }
}

function scheduleOfficialLoginPolling() {
  stopOfficialLoginPolling();
  if ((!elements.providerDialog.open && !elements.officialBrowserDialog.open) || state.editingProviderId !== "default") return;
  const expiresAt = Number(state.officialAccount?.pendingLogin?.expiresAt || 0);
  if (expiresAt && expiresAt <= Date.now()) return;
  state.officialLoginPollTimer = setTimeout(() => loadOfficialAccount({ silent: true }), 2_500);
}

function stopOfficialLoginPolling() {
  clearTimeout(state.officialLoginPollTimer);
  state.officialLoginPollTimer = null;
}

async function prepareOfficialReset() {
  elements.officialAccountError.textContent = "";
  elements.officialPrepareResetButton.disabled = true;
  try {
    const response = await fetch("/api/providers/official/reset/prepare", {
      method: "POST",
      headers: { "X-Codex-Desktop-Action": "official-reset-prepare" },
    });
    const data = await readApiJson(response, "无法查询官方重置额度");
    state.officialResetChallenge = data;
    elements.officialResetConfirmationInput.value = "";
    elements.officialResetError.textContent = "";
    elements.officialResetDialogSummary.textContent = `官方账户有 ${data.availableCount} 次可用重置额度。本次操作会消耗其中一次，提交后不能撤销。`;
    updateOfficialResetConfirmation();
    elements.officialResetDialog.showModal();
    requestAnimationFrame(() => elements.officialResetConfirmationInput.focus());
  } catch (error) {
    elements.officialAccountError.textContent = error.message;
  } finally {
    renderOfficialAccount();
  }
}

async function executeOfficialReset(event) {
  event.preventDefault();
  const challenge = state.officialResetChallenge;
  if (!challenge || elements.officialResetConfirmationInput.value !== challenge.confirmationPhrase) return;
  elements.officialResetConfirmButton.disabled = true;
  elements.officialResetConfirmationInput.disabled = true;
  elements.officialResetError.textContent = "";
  try {
    const response = await fetch("/api/providers/official/reset/execute", {
      method: "POST",
      headers: {
        "Content-Type": "application/json",
        "X-Codex-Desktop-Action": "official-reset-execute",
      },
      body: JSON.stringify({
        nonce: challenge.nonce,
        confirmation: elements.officialResetConfirmationInput.value,
      }),
    });
    const data = await readApiJson(response, "无法确认官方额度重置");
    const messages = {
      reset: "官方速率限额已重置",
      nothingToReset: "当前没有符合条件的限额窗口",
      noCredit: "官方账户已没有可用重置额度",
      alreadyRedeemed: "本次重置请求已经处理",
      unknown: "官方服务返回了未知结果",
    };
    elements.officialResetDialog.close();
    toast(messages[data.outcome] || messages.unknown, data.outcome === "reset" ? "default" : "error");
    await loadOfficialAccount({ silent: true });
  } catch (error) {
    elements.officialResetError.textContent = error.message;
  } finally {
    elements.officialResetConfirmationInput.disabled = false;
    updateOfficialResetConfirmation();
  }
}

function updateOfficialResetConfirmation() {
  elements.officialResetConfirmButton.disabled = !state.officialResetChallenge
    || elements.officialResetConfirmationInput.disabled
    || elements.officialResetConfirmationInput.value !== state.officialResetChallenge.confirmationPhrase;
}

function closeOfficialResetDialog() {
  elements.officialResetDialog.close();
}

function clearOfficialResetChallenge() {
  state.officialResetChallenge = null;
  elements.officialResetConfirmationInput.value = "";
  elements.officialResetConfirmationInput.disabled = false;
  elements.officialResetError.textContent = "";
  updateOfficialResetConfirmation();
}

function officialPlanLabel(plan) {
  return ({
    free: "Free",
    go: "Go",
    plus: "Plus",
    pro: "Pro",
    prolite: "Pro Lite",
    team: "Team",
    self_serve_business_usage_based: "Business",
    business: "Business",
    enterprise_cbp_usage_based: "Enterprise",
    enterprise: "Enterprise",
    edu: "Education",
    unknown: "未知套餐",
  })[plan] || plan || "未知套餐";
}

function formatOptionalInteger(value) {
  return Number.isSafeInteger(value) ? value.toLocaleString(interfaceLocale()) : "--";
}

function formatWindowDuration(minutes) {
  if (!Number.isSafeInteger(minutes)) return "周期未知";
  if (minutes < 60) return `${minutes} 分钟`;
  if (minutes % 1_440 === 0) return `${minutes / 1_440} 天`;
  if (minutes % 60 === 0) return `${minutes / 60} 小时`;
  return `${Math.floor(minutes / 60)} 小时 ${minutes % 60} 分`;
}

function formatOfficialResetTime(timestamp) {
  if (!Number.isSafeInteger(timestamp)) return "重置时间未知";
  return `重置 ${new Date(timestamp * 1_000).toLocaleString(interfaceLocale(), {
    month: "2-digit",
    day: "2-digit",
    hour: "2-digit",
    minute: "2-digit",
    hour12: false,
  })}`;
}

function safeOfficialAuthUrl(value) {
  try {
    const url = new URL(value);
    const hostname = url.hostname.toLowerCase();
    const official = hostname === "openai.com"
      || hostname.endsWith(".openai.com")
      || hostname === "chatgpt.com"
      || hostname.endsWith(".chatgpt.com");
    return url.protocol === "https:" && official ? url.href : null;
  } catch {
    return null;
  }
}

function readToolboxList(key) {
  try {
    const value = JSON.parse(localStorage.getItem(key) || "[]");
    return Array.isArray(value)
      ? value.filter((entry) => typeof entry === "string" && entry).slice(0, 24)
      : [];
  } catch {
    return [];
  }
}

function readToolboxCategory() {
  const value = localStorage.getItem(TOOLBOX_CATEGORY_KEY);
  return Object.hasOwn(TOOLBOX_CATEGORY_LABELS, value) ? value : "all";
}

function persistToolboxList(key, entries) {
  try {
    localStorage.setItem(key, JSON.stringify(entries));
  } catch {
    // Local preference persistence is best effort.
  }
}

function setToolboxCategory(category) {
  const next = Object.hasOwn(TOOLBOX_CATEGORY_LABELS, category) ? category : "all";
  state.toolboxCategory = next;
  try {
    localStorage.setItem(TOOLBOX_CATEGORY_KEY, next);
  } catch {
    // Local preference persistence is best effort.
  }
  renderToolbox();
}

function markToolboxRecent(toolId) {
  if (!toolId) return;
  state.toolboxRecent = [toolId, ...state.toolboxRecent.filter((entry) => entry !== toolId)].slice(0, 24);
  persistToolboxList(TOOLBOX_RECENT_KEY, state.toolboxRecent);
  renderToolbox();
}

function toggleToolboxFavorite(toolId) {
  if (!toolId) return;
  if (state.toolboxFavorites.has(toolId)) state.toolboxFavorites.delete(toolId);
  else state.toolboxFavorites.add(toolId);
  persistToolboxList(TOOLBOX_FAVORITES_KEY, [...state.toolboxFavorites]);
  renderToolbox();
}

function renderToolbox() {
  if (!elements.toolboxToolGrid) return;
  const category = state.toolboxCategory;
  const query = elements.toolboxSearch.value.trim().toLocaleLowerCase(interfaceLocale());
  const recent = new Set(state.toolboxRecent);
  const cards = [...elements.toolboxToolGrid.querySelectorAll("[data-toolbox-tool-id]")];
  let visibleCount = 0;
  for (const card of cards) {
    const id = card.dataset.toolboxToolId || "";
    const cardCategory = card.dataset.toolboxCategory || "other";
    const searchText = (card.dataset.toolboxSearch || "").toLocaleLowerCase(interfaceLocale());
    const permissionMatches = card.dataset.toolboxAdmin !== "true" || isAccountAdmin();
    const categoryMatches = category === "all"
      || (category === "recent" && recent.has(id))
      || (category === "favorite" && state.toolboxFavorites.has(id))
      || category === cardCategory;
    const queryMatches = !query || searchText.includes(query);
    const visible = permissionMatches && categoryMatches && queryMatches;
    card.hidden = !visible;
    if (visible) visibleCount += 1;
    card.dataset.favorite = String(state.toolboxFavorites.has(id));
    const favoriteButton = card.querySelector("[data-toolbox-favorite]");
    if (favoriteButton) {
      const favorite = state.toolboxFavorites.has(id);
      favoriteButton.dataset.active = String(favorite);
      favoriteButton.setAttribute("aria-pressed", String(favorite));
      favoriteButton.title = `${favorite ? "取消收藏" : "收藏"}${card.querySelector("strong")?.textContent || "工具"}`;
    }
  }
  for (const tab of elements.toolboxCategoryTabs.querySelectorAll("[data-toolbox-category]")) {
    const selected = tab.dataset.toolboxCategory === category;
    tab.setAttribute("aria-selected", String(selected));
    tab.classList.toggle("active", selected);
  }
  const sectionTitle = query ? `搜索结果` : TOOLBOX_CATEGORY_LABELS[category];
  elements.toolboxSectionTitle.textContent = sectionTitle;
  elements.toolboxCount.textContent = `${visibleCount} 项`;
  elements.toolboxEmpty.hidden = visibleCount > 0;
  if (!visibleCount) {
    const hasFilter = Boolean(query) || category !== "all";
    elements.toolboxEmptyTitle.textContent = query
      ? "没有匹配的工具"
      : category === "favorite" ? "还没有收藏工具" : category === "recent" ? "还没有使用记录" : "这个分类暂时为空";
    elements.toolboxEmptyMessage.textContent = hasFilter
      ? "试试其他关键词或切换工具分类。"
      : "后续工具可以直接添加到工具注册表。";
  }
  const imageStudioButton = elements.toolboxOpenImageStudioButton;
  elements.toolboxOpenResourceButton.disabled = !state.currentProject;
  elements.toolboxOpenBrowserButton.disabled = !state.currentProject;
  if (imageStudioButton && elements.imageStudioButton) imageStudioButton.disabled = elements.imageStudioButton.disabled;
  refreshIcons();
}

function setToolboxView(view) {
  const showResources = view === "resources";
  elements.toolboxOverview.hidden = showResources;
  elements.toolboxResourceDetail.hidden = !showResources;
  if (showResources) renderMapWorkspaceMaps();
  else renderToolbox();
}

function openToolboxResourceExplorer() {
  closeMapWorkspace();
  openResourceExplorer();
}

function openToolboxBrowserPreview() {
  closeMapWorkspace();
  void openBrowserPreview();
}

function openToolboxImageStudio() {
  closeMapWorkspace();
  void openImageStudioDialog();
}

function openToolboxGameResources() {
  setToolboxView("resources");
}

function openToolboxMobileApp() {
  const page = window.open("/mobile-tool.html", "_blank", "noopener,noreferrer");
  if (!page) toast("浏览器阻止了移动 App 工作台窗口", "error");
}

function openToolboxServerFiles() {
  if (!isAccountAdmin()) {
    toast("当前账号没有管理员权限", "error");
    return;
  }
  const page = window.open("/server-files.html", "_blank", "noopener,noreferrer");
  if (!page) toast("浏览器阻止了服务器文件管理器窗口", "error");
}

function openProjectDialog() {
  elements.projectForm.reset();
  elements.projectFormError.textContent = "";
  renderProjectRootOptions({ preferDefault: true });
  updateTemplateSelection();
  updateProjectPathPreview();
  elements.projectDialog.showModal();
  requestAnimationFrame(() => elements.projectNameInput.focus());
}

function updateTemplateSelection() {
  elements.templateGrid.querySelectorAll(".template-option").forEach((label) => {
    label.classList.toggle("selected", label.querySelector("input").checked);
  });
}

function renderProjectRootOptions({ preferDefault = false } = {}) {
  const roots = Array.isArray(state.projectRoots) ? state.projectRoots : [];
  elements.projectRootInput.replaceChildren();
  for (const root of roots) {
    const option = new Option(`${root.label || "存储位置"} · ${root.path}`, root.id);
    elements.projectRootInput.append(option);
  }
  if (!roots.length) return;
  const preferred = preferDefault
    ? roots.find((root) => root.isDefault)
    : roots.find((root) => root.id === state.projectCreateRootId);
  const selected = preferred || roots.find((root) => root.isDefault) || roots[0];
  state.projectCreateRootId = selected.id;
  elements.projectRootInput.value = selected.id;
  elements.projectRootInput.disabled = roots.length < 2;
}

function selectedProjectRootPath() {
  const selected = state.projectRoots.find((root) => root.id === elements.projectRootInput.value)
    || state.projectRoots.find((root) => root.id === state.projectCreateRootId)
    || state.projectRoots.find((root) => root.isDefault)
    || state.projectRoots[0];
  return selected?.path || state.projectRoot;
}

function updateProjectPathPreview() {
  const name = elements.projectNameInput.value.trim() || "my-project";
  setDataContent(elements.projectPathPreview, `${selectedProjectRootPath().replace(/\/$/, "")}/${name}`);
}

async function openMapWorkspace(projectFile = null) {
  const project = state.currentProject;
  if (state.mapWorkspaceProjectPath !== project?.path) state.mapWorkspaceSelectedEntry = null;
  closeMobilePanels();
  setDataContent(elements.mapWorkspaceProjectName, project?.name || "未选择工程");
  setDataContent(
    elements.mapWorkspaceProjectMeta,
    project ? "正在连接项目目录" : "选择工程后可使用项目工具",
  );
  elements.mapWorkspaceProjectMeta.title = project?.path || "";
  renderMapAiToolsSetting();
  renderImageContextIsolationSetting();
  renderMapGameWorkModeSetting();
  state.mapManagedMapPath = "";
  state.mapManagedMapVersion = null;
  state.mapManagedAuthorizations = [];
  elements.mapManagedMapPath.value = "";
  elements.mapManagedMapState.textContent = "先输入 .tmj 路径并读取当前 SHA-256。";
  elements.mapManagedMapState.dataset.status = "";
  renderMapManagedAccess();
  elements.toolboxSearch.value = "";
  setToolboxView("overview");
  state.mapEditorRecentTabs = project ? loadMapEditorRecentTabs() : [];
  renderMapWorkspaceTabs();
  resetMapWorkspaceView();
  if (!elements.mapWorkspaceDialog.open) elements.mapWorkspaceDialog.showModal();
  const loads = [loadMapAiToolsSetting({ silent: true })];
  if (project) loads.push(loadMapWorkspaceProject(projectFile));
  await Promise.allSettled(loads);
}

async function openMapWorkspaceEditor() {
  const project = state.currentProject;
  if (!project || state.mapWorkspaceLoading || state.mapEditorOpeningPath) return;
  pruneClosedMapEditorBindings();
  const live = [...state.mapEditorGameBindings.entries()]
    .filter(([, binding]) => binding.projectPath === project.path && binding.editorWindow && !binding.editorWindow.closed)
    .sort((left, right) => (right[1].lastActiveAt || 0) - (left[1].lastActiveAt || 0));
  if (live[0]?.[1]?.editorWindow) {
    live[0][1].editorWindow.focus();
    closeMapWorkspace();
    return;
  }

  const recent = state.mapEditorRecentTabs
    .filter((entry) => entry.projectPath === project.path)
    .sort((left, right) => (right.lastOpenedAt || 0) - (left.lastOpenedAt || 0))[0];
  if (recent?.relativePath) {
    await openMapEditorEntry({
      kind: "map",
      path: recent.relativePath,
      name: recent.relativePath.split("/").at(-1),
    }, { source: "workspace" });
    return;
  }

  const client = state.mapWorkspaceClient;
  const session = state.mapWorkspaceProjectSession;
  if (!client || !session) {
    toast("地图项目还在连接，请稍候再试", "error");
    return;
  }
  try {
    const page = await client.search({ query: ".tmj", kinds: ["map"], limit: 1 });
    const entry = page.entries.find((candidate) => candidate.kind === "map" && /\.tmj$/iu.test(candidate.path));
    if (!entry) {
      toast("当前工程没有找到 .tmj 地图", "error");
      return;
    }
    await openMapEditorEntry(entry, { source: "workspace" });
  } catch (error) {
    toast(`无法查找地图：${error.message}`, "error");
  }
}

function openCharacterEditor() {
  const project = state.currentProject;
  if (!project) {
    toast("请先选择工程", "error");
    return;
  }
  const fragment = new URLSearchParams({
    project: project.path,
    ...(state.account?.id ? { account: state.account.id } : {}),
  });
  const projectFile = state.mapWorkspaceProjectSession?.projectFile;
  if (projectFile) fragment.set("projectFile", projectFile);
  const selected = state.mapWorkspaceSelectedEntry || state.resourcePreviewEntry;
  const selectedPath = selected?.relativePath || selected?.path || "";
  if (/\.character\.json$/iu.test(selectedPath)) fragment.set("path", selectedPath);
  else if (/\.(?:png|jpe?g|webp)$/iu.test(selectedPath)) fragment.set("source", selectedPath);
  const editorWindow = window.open(`/character-editor.html#${fragment}`, "_blank");
  if (!editorWindow) {
    toast("浏览器阻止了角色编辑器窗口", "error");
    return;
  }
  editorWindow.focus?.();
  closeMapWorkspace();
}

function closeMapWorkspace() {
  closeMapNewDialog({ force: true });
  closeWorldNewDialog({ force: true });
  closeTilesetNewDialog({ force: true });
  if (elements.mapWorkspaceDialog.open) elements.mapWorkspaceDialog.close();
  state.mapWorkspaceLoadId += 1;
  clearTimeout(state.mapWorkspaceSearchTimer);
  state.mapWorkspaceSearchTimer = null;
  state.mapWorkspaceSearchPendingQuery = null;
  const client = state.mapWorkspaceClient;
  state.mapWorkspaceClient = null;
  resetMapWorkspaceView();
  void client?.close().catch(() => {});
}

function resetMapWorkspaceView() {
  state.mapWorkspaceProjectSession = null;
  state.mapWorkspaceProjectPath = null;
  state.mapWorkspaceDirectories = new Map();
  state.mapWorkspaceExpanded = new Set();
  state.mapWorkspaceSearchResult = null;
  state.mapWorkspaceSelectedEntry = null;
  state.mapWorkspaceSearchPendingQuery = null;
  state.mapWorkspaceSearchLoading = false;
  state.mapWorkspaceLoading = false;
  elements.mapWorkspaceSearch.value = "";
  elements.mapWorkspaceState.textContent = "";
  elements.mapWorkspaceState.dataset.status = "";
  state.mapManagedMapPath = "";
  state.mapManagedMapVersion = null;
  if (elements.mapManagedMapPath) elements.mapManagedMapPath.value = "";
  if (elements.mapManagedMapState) {
    elements.mapManagedMapState.textContent = "先输入 .tmj 路径并读取当前 SHA-256。";
    elements.mapManagedMapState.dataset.status = "";
  }
  invalidateMapManagedAuthorizations();
  renderMapWorkspaceMaps();
}

async function loadMapWorkspaceProject(projectFile = null) {
  const project = state.currentProject;
  if (!project) return;
  const loadId = ++state.mapWorkspaceLoadId;
  state.mapWorkspaceLoading = true;
  state.mapWorkspaceProjectSession = null;
  state.mapWorkspaceProjectPath = project.path;
  state.mapWorkspaceDirectories = new Map();
  state.mapWorkspaceExpanded = new Set();
  state.mapWorkspaceSearchResult = null;
  state.mapWorkspaceSearchPendingQuery = null;
  state.mapWorkspaceSearchLoading = false;
  elements.mapWorkspaceSearch.value = "";
  elements.mapWorkspaceState.textContent = "正在读取项目资源";
  elements.mapWorkspaceState.dataset.status = "busy";
  renderMapWorkspaceMaps();
  const client = state.mapWorkspaceClient || new MapProjectWorkspaceClient();
  state.mapWorkspaceClient = client;
  try {
    const session = await client.open({ project: project.path, projectFile });
    if (
      loadId !== state.mapWorkspaceLoadId
      || state.currentProject?.path !== project.path
      || state.mapWorkspaceClient !== client
    ) return;
    state.mapWorkspaceProjectSession = session;
    const compatibility = session.manifest?.compatibilityVersion
      ? `Tiled ${session.manifest.compatibilityVersion}`
      : "Tiled JSON";
    const projectMeta = session.projectFile
      ? `${project.path} · ${session.projectFile} · ${compatibility}`
      : `${project.path} · 临时目录项目 · ${compatibility}`;
    setDataContent(
      elements.mapWorkspaceProjectMeta,
      projectMeta,
    );
    elements.mapWorkspaceProjectMeta.title = projectMeta;
    await loadMapWorkspaceDirectory("", { loadId, reset: true });
    await loadMapManagedAuthorizations({ silent: true });
    if (session.warnings.length) {
      elements.mapWorkspaceState.textContent = session.warnings.join("；");
      elements.mapWorkspaceState.dataset.status = "warning";
    }
  } catch (error) {
    if (loadId !== state.mapWorkspaceLoadId) return;
    state.mapWorkspaceProjectSession = null;
    elements.mapWorkspaceState.textContent = error.message;
    elements.mapWorkspaceState.dataset.status = "error";
  } finally {
    if (loadId === state.mapWorkspaceLoadId) {
      state.mapWorkspaceLoading = false;
      renderMapWorkspaceMaps();
    }
  }
}

async function refreshMapWorkspace() {
  if (state.mapWorkspaceLoading || state.mapWorkspaceSearchLoading) return;
  await loadMapWorkspaceProject(state.mapWorkspaceProjectSession?.projectFile || null);
}

async function loadMapWorkspaceDirectory(directory, { append = false, loadId = state.mapWorkspaceLoadId, reset = false } = {}) {
  const client = state.mapWorkspaceClient;
  const sessionId = state.mapWorkspaceProjectSession?.id;
  if (!client || !sessionId || loadId !== state.mapWorkspaceLoadId) return;
  let record = state.mapWorkspaceDirectories.get(directory);
  if (!record || reset) {
    record = { entries: [], nextCursor: null, loaded: false, loading: false, error: "" };
    state.mapWorkspaceDirectories.set(directory, record);
  }
  if (record.loading || (append && !record.nextCursor)) return;
  record.loading = true;
  record.error = "";
  renderMapWorkspaceMaps();
  try {
    const page = await client.tree({
      directory,
      cursor: append ? record.nextCursor : null,
      limit: 100,
    });
    if (
      loadId !== state.mapWorkspaceLoadId
      || state.mapWorkspaceProjectSession?.id !== sessionId
      || state.mapWorkspaceClient !== client
    ) return;
    const entries = append ? [...record.entries, ...page.entries] : [...page.entries];
    record.entries = [...new Map(entries.map((entry) => [entry.path, entry])).values()];
    record.nextCursor = page.nextCursor;
    record.loaded = true;
    if (!elements.mapWorkspaceState.dataset.status || elements.mapWorkspaceState.dataset.status === "busy") {
      elements.mapWorkspaceState.textContent = "";
      elements.mapWorkspaceState.dataset.status = "";
    }
  } catch (error) {
    if (loadId !== state.mapWorkspaceLoadId) return;
    record.error = error.message;
    elements.mapWorkspaceState.textContent = error.message;
    elements.mapWorkspaceState.dataset.status = "error";
  } finally {
    if (loadId === state.mapWorkspaceLoadId) {
      record.loading = false;
      renderMapWorkspaceMaps();
    }
  }
}

function scheduleMapWorkspaceSearch() {
  clearTimeout(state.mapWorkspaceSearchTimer);
  state.mapWorkspaceSearchTimer = null;
  const query = elements.mapWorkspaceSearch.value.trim();
  if (!query) {
    state.mapWorkspaceSearchPendingQuery = null;
    state.mapWorkspaceSearchResult = null;
    state.mapWorkspaceSearchLoading = false;
    elements.mapWorkspaceState.textContent = "";
    elements.mapWorkspaceState.dataset.status = "";
    renderMapWorkspaceMaps();
    return;
  }
  if (query.length < 2) {
    state.mapWorkspaceSearchPendingQuery = null;
    state.mapWorkspaceSearchResult = { query, entries: [], nextCursor: null, scanned: 0, truncated: false };
    elements.mapWorkspaceState.textContent = "请至少输入 2 个字符";
    elements.mapWorkspaceState.dataset.status = "";
    renderMapWorkspaceMaps();
    return;
  }
  state.mapWorkspaceSearchPendingQuery = query;
  state.mapWorkspaceSearchTimer = setTimeout(() => void searchMapWorkspace(query), 250);
}

async function searchMapWorkspace(query, { append = false } = {}) {
  const client = state.mapWorkspaceClient;
  const sessionId = state.mapWorkspaceProjectSession?.id;
  const loadId = state.mapWorkspaceLoadId;
  if (!client || !sessionId) return;
  if (elements.mapWorkspaceSearch.value.trim() !== query) return;
  if (state.mapWorkspaceSearchLoading) {
    if (!append) state.mapWorkspaceSearchPendingQuery = query;
    return;
  }
  if (state.mapWorkspaceSearchPendingQuery === query) state.mapWorkspaceSearchPendingQuery = null;
  const previous = append && state.mapWorkspaceSearchResult?.query === query
    ? state.mapWorkspaceSearchResult
    : null;
  state.mapWorkspaceSearchLoading = true;
  if (!previous) state.mapWorkspaceSearchResult = { query, entries: [], nextCursor: null, scanned: 0, truncated: false };
  elements.mapWorkspaceState.textContent = "正在搜索项目资源";
  elements.mapWorkspaceState.dataset.status = "busy";
  renderMapWorkspaceMaps();
  try {
    const page = await client.search({ query, cursor: previous?.nextCursor || null, limit: 100 });
    if (
      loadId !== state.mapWorkspaceLoadId
      || state.mapWorkspaceProjectSession?.id !== sessionId
      || elements.mapWorkspaceSearch.value.trim() !== query
    ) return;
    const entries = previous ? [...previous.entries, ...page.entries] : [...page.entries];
    state.mapWorkspaceSearchResult = {
      ...page,
      entries: [...new Map(entries.map((entry) => [entry.path, entry])).values()],
    };
    elements.mapWorkspaceState.textContent = page.truncated
      ? `已检查 ${page.scanned.toLocaleString(interfaceLocale())} 项，达到搜索上限`
      : "";
    elements.mapWorkspaceState.dataset.status = page.truncated ? "warning" : "";
  } catch (error) {
    if (loadId !== state.mapWorkspaceLoadId) return;
    elements.mapWorkspaceState.textContent = error.message;
    elements.mapWorkspaceState.dataset.status = "error";
  } finally {
    if (loadId === state.mapWorkspaceLoadId) {
      state.mapWorkspaceSearchLoading = false;
      renderMapWorkspaceMaps();
      const pendingQuery = state.mapWorkspaceSearchPendingQuery;
      if (
        pendingQuery
        && pendingQuery !== query
        && elements.mapWorkspaceSearch.value.trim() === pendingQuery
      ) {
        state.mapWorkspaceSearchPendingQuery = null;
        void searchMapWorkspace(pendingQuery);
      }
    }
  }
}

function renderMapWorkspaceMaps() {
  renderMapWorkspaceTabs();
  const fragment = document.createDocumentFragment();
  let entryCount = 0;
  const search = state.mapWorkspaceSearchResult;
  if (search) {
    for (const entry of search.entries.filter(mapWorkspaceEntryMatchesFilter)) {
      appendMapWorkspaceEntry(fragment, entry, 0);
      entryCount += 1;
    }
    if (search.nextCursor) {
      appendMapWorkspaceLoadMore(fragment, () => void searchMapWorkspace(search.query, { append: true }), 0);
    }
  } else {
    entryCount = appendMapWorkspaceDirectory(fragment, "", 0);
  }
  elements.mapWorkspaceMapCount.textContent = `${entryCount} 项`;
  if (!entryCount && !state.mapWorkspaceLoading && !state.mapWorkspaceSearchLoading) {
    const empty = document.createElement("div");
    empty.className = "map-workspace-empty";
    empty.innerHTML = search
      ? '<i data-lucide="search-x"></i><span>没有匹配的项目资源</span>'
      : '<i data-lucide="folder-open"></i><span>项目目录中没有可显示的资源</span>';
    fragment.append(empty);
  }
  if (state.mapWorkspaceLoading || state.mapWorkspaceSearchLoading) {
    const loading = document.createElement("div");
    loading.className = "map-workspace-loading map-workspace-inline-state";
    loading.innerHTML = '<i data-lucide="loader-circle"></i><span>正在读取项目资源</span>';
    fragment.append(loading);
  }
  elements.mapWorkspaceMapList.replaceChildren(fragment);
  elements.mapWorkspaceRefreshButton.disabled = state.mapWorkspaceLoading
    || state.mapWorkspaceSearchLoading
    || Boolean(state.mapEditorOpeningPath);
  elements.mapWorkspaceOpenEditorButton.disabled = state.mapWorkspaceLoading
    || state.mapWorkspaceSearchLoading
    || Boolean(state.mapEditorOpeningPath)
    || !state.mapWorkspaceProjectSession;
  elements.mapWorkspaceOpenCharacterButton.disabled = state.mapWorkspaceLoading
    || state.mapWorkspaceSearchLoading
    || Boolean(state.mapEditorOpeningPath)
    || !state.mapWorkspaceProjectSession;
  elements.mapWorkspaceNewButton.disabled = state.mapWorkspaceLoading
    || state.mapWorkspaceSearchLoading
    || state.mapNewBusy
    || state.worldNewBusy
    || state.tilesetNewBusy
    || Boolean(state.mapEditorOpeningPath)
    || !state.mapWorkspaceProjectSession?.writable;
  elements.mapWorkspaceNewWorldButton.disabled = elements.mapWorkspaceNewButton.disabled || state.worldNewBusy;
  elements.mapWorkspaceNewTilesetButton.disabled = elements.mapWorkspaceNewButton.disabled || state.tilesetNewBusy;
  elements.mapWorkspaceSearch.disabled = state.mapWorkspaceLoading || !state.mapWorkspaceProjectSession;
  elements.toolboxOpenGameResourcesButton.disabled = state.mapWorkspaceLoading || !state.mapWorkspaceProjectSession;
  elements.mapWorkspaceKindFilter.value = mapWorkspaceKindFilterValue();
  renderMapWorkspaceActionState();
  renderMapWorkspaceSelectionState();
  renderToolbox();
  refreshIcons();
}

function mapWorkspaceKindFilterValue() {
  return ["all", "map", "world", "tileset", "character", "image"].includes(state.mapWorkspaceKindFilter)
    ? state.mapWorkspaceKindFilter
    : "all";
}

function mapWorkspaceEntryMatchesFilter(entry) {
  const filter = mapWorkspaceKindFilterValue();
  return filter === "all"
    || entry?.kind === "directory"
    || entry?.kind === "project"
    || entry?.kind === filter;
}

function updateMapWorkspaceKindFilter() {
  state.mapWorkspaceKindFilter = mapWorkspaceKindFilterValueFromElement();
  localStorage.setItem("codexDesktop.mapWorkspaceKindFilter", state.mapWorkspaceKindFilter);
  renderMapWorkspaceMaps();
}

function mapWorkspaceKindFilterValueFromElement() {
  const value = elements.mapWorkspaceKindFilter.value;
  return ["all", "map", "world", "tileset", "character", "image"].includes(value) ? value : "all";
}

function renderMapWorkspaceActionState() {
  const session = state.mapWorkspaceProjectSession;
  let status = "尚未连接工程资源";
  let reason = "请先选择工程并连接项目资源";
  if (state.mapWorkspaceLoading || state.mapWorkspaceSearchLoading) {
    status = "正在读取工程资源…";
    reason = "工程资源正在读取";
  } else if (elements.mapWorkspaceState.dataset.status === "error") {
    status = "工程资源连接失败 · 可点击刷新重试";
    reason = "工程资源连接失败，请刷新重试";
  } else if (session) {
    status = session.writable ? "已连接 · 可写工程" : "已连接 · 只读工程";
    reason = session.writable ? "当前工程已连接" : "当前工程是只读的";
  }
  setDataContent(elements.mapWorkspaceActionState, status);
  elements.mapWorkspaceActionState.dataset.status = session?.writable ? "writable" : "readonly";
  for (const button of [
    elements.mapWorkspaceOpenEditorButton,
    elements.mapWorkspaceOpenCharacterButton,
    elements.mapWorkspaceNewButton,
    elements.mapWorkspaceNewWorldButton,
    elements.mapWorkspaceNewTilesetButton,
    elements.mapWorkspaceRefreshButton,
  ]) {
    button.setAttribute("aria-describedby", "mapWorkspaceActionState");
    if (button.disabled) button.title = `暂不可用：${reason}`;
  }
}

function renderMapWorkspaceSelectionState() {
  const selected = state.mapWorkspaceSelectedEntry;
  const text = selected
    ? `已选择 ${selected.kind === "character" ? "角色清单" : "图片"} · ${selected.path}`
    : "未选择角色资源；可从资源管理器预览打开角色动作";
  setDataContent(elements.mapWorkspaceSelectionState, text);
  elements.mapWorkspaceSelectionState.title = selected?.path || "";
  elements.mapWorkspaceOpenCharacterButton.title = selected
    ? `使用 ${selected.path} 打开角色动作编辑器`
    : "打开当前工程的角色动作编辑器";
}

function appendMapWorkspaceDirectory(fragment, directory, depth) {
  const record = state.mapWorkspaceDirectories.get(directory);
  if (!record) return 0;
  let count = 0;
  for (const entry of record.entries) {
    if (!mapWorkspaceEntryMatchesFilter(entry)) continue;
    appendMapWorkspaceEntry(fragment, entry, depth);
    count += 1;
    if (entry.kind === "directory" && state.mapWorkspaceExpanded.has(entry.path)) {
      count += appendMapWorkspaceDirectory(fragment, entry.path, depth + 1);
    }
  }
  if (record.nextCursor) {
    appendMapWorkspaceLoadMore(
      fragment,
      () => void loadMapWorkspaceDirectory(directory, { append: true }),
      depth,
    );
  }
  if (record.loading && directory) {
    const loading = document.createElement("div");
    loading.className = "map-workspace-tree-state";
    loading.style.setProperty("--map-tree-depth", String(depth));
    loading.innerHTML = '<i data-lucide="loader-circle"></i><span>正在读取</span>';
    fragment.append(loading);
  }
  return count;
}

function appendMapWorkspaceEntry(fragment, entry, depth) {
  const actionable = ["directory", "map", "world", "tileset", "project", "character", "image"].includes(entry.kind);
  const row = document.createElement(actionable ? "button" : "div");
  if (actionable) row.type = "button";
  row.className = `map-workspace-resource-row${["map", "world", "tileset"].includes(entry.kind) ? " map-workspace-map-row" : ""}`;
  row.dataset.kind = entry.kind;
  row.dataset.opening = String(state.mapEditorOpeningPath === entry.path);
  row.dataset.selected = String(state.mapWorkspaceSelectedEntry?.path === entry.path);
  if (["character", "image"].includes(entry.kind)) {
    row.setAttribute("aria-selected", String(state.mapWorkspaceSelectedEntry?.path === entry.path));
  }
  row.style.setProperty("--map-tree-depth", String(depth));
  row.setAttribute("role", "treeitem");
  row.setAttribute("aria-level", String(depth + 1));
  if (entry.kind === "directory") row.setAttribute("aria-expanded", String(state.mapWorkspaceExpanded.has(entry.path)));
  row.innerHTML = '<span class="map-workspace-tree-toggle"></span><span class="map-workspace-map-icon"><i></i></span><span class="map-workspace-map-copy"><strong></strong><span></span></span><i class="map-workspace-map-open"></i>';
  const expanded = entry.kind === "directory" && state.mapWorkspaceExpanded.has(entry.path);
  const toggle = row.querySelector(".map-workspace-tree-toggle");
  if (entry.kind === "directory") toggle.innerHTML = `<i data-lucide="${expanded ? "chevron-down" : "chevron-right"}"></i>`;
  row.querySelector(".map-workspace-map-icon i").setAttribute("data-lucide", mapWorkspaceResourceIcon(entry.kind));
  setDataContent(row.querySelector("strong"), entry.name);
  setDataContent(row.querySelector(".map-workspace-map-copy span"), entry.path);
  const actionIcon = row.querySelector(".map-workspace-map-open");
  if (["map", "world", "tileset"].includes(entry.kind)) actionIcon.setAttribute("data-lucide", "arrow-up-right");
  else if (entry.kind === "project") {
    row.dataset.active = String(state.mapWorkspaceProjectSession?.projectFile === entry.path);
    actionIcon.setAttribute(
      "data-lucide",
      state.mapWorkspaceProjectSession?.projectFile === entry.path ? "circle-check" : "folder-input",
    );
  }
  if (actionable) {
    row.disabled = Boolean(state.mapEditorOpeningPath) || state.mapWorkspaceLoading;
    if (entry.kind === "directory") {
      row.title = `${expanded ? "收起" : "展开"} ${entry.path}`;
      row.addEventListener("click", () => void toggleMapWorkspaceDirectory(entry.path));
    } else if (entry.kind === "map") {
      row.title = `打开 ${entry.path}`;
      row.addEventListener("click", () => void openMapEditorEntry(entry, { source: "workspace" }));
    } else if (entry.kind === "world") {
      row.title = `打开 ${entry.path}`;
      row.addEventListener("click", () => void openWorldEditorEntry(entry));
    } else if (entry.kind === "tileset") {
      row.title = `打开 ${entry.path}`;
      row.addEventListener("click", () => void openTilesetEditorEntry(entry));
    } else if (["character", "image"].includes(entry.kind)) {
      row.title = `选择 ${entry.path}`;
      row.addEventListener("click", () => selectMapWorkspaceResource(entry));
    } else {
      const active = state.mapWorkspaceProjectSession?.projectFile === entry.path;
      row.disabled = row.disabled || active;
      row.title = active ? "当前 Tiled 项目" : `使用 ${entry.path}`;
      row.addEventListener("click", () => void loadMapWorkspaceProject(entry.path));
    }
    row.setAttribute("aria-label", row.title);
  }
  fragment.append(row);
}

function selectMapWorkspaceResource(entry) {
  if (!entry || !["character", "image"].includes(entry.kind)) return;
  state.mapWorkspaceSelectedEntry = Object.freeze({ ...entry });
  renderMapWorkspaceMaps();
}

async function toggleMapWorkspaceDirectory(directory) {
  if (state.mapWorkspaceExpanded.has(directory)) {
    state.mapWorkspaceExpanded.delete(directory);
    renderMapWorkspaceMaps();
    return;
  }
  state.mapWorkspaceExpanded.add(directory);
  renderMapWorkspaceMaps();
  if (!state.mapWorkspaceDirectories.get(directory)?.loaded) {
    await loadMapWorkspaceDirectory(directory);
  }
}

function appendMapWorkspaceLoadMore(fragment, onClick, depth) {
  const button = document.createElement("button");
  button.type = "button";
  button.className = "map-workspace-load-more";
  button.style.setProperty("--map-tree-depth", String(depth));
  button.innerHTML = '<i data-lucide="list-plus"></i><span>加载更多</span>';
  button.disabled = state.mapWorkspaceLoading || state.mapWorkspaceSearchLoading;
  button.addEventListener("click", onClick);
  fragment.append(button);
}

function mapWorkspaceResourceIcon(kind) {
  return ({
    directory: "folder",
    map: "map",
    world: "globe-2",
    tileset: "grid-3x3",
    project: "folder-cog",
    template: "copy",
    image: "image",
    audio: "audio-lines",
    html: "file-code-2",
    stylesheet: "braces",
    script: "file-code",
    automapping: "wand-sparkles",
    other: "file",
  })[kind] || "file";
}

function renderMapWorkspaceTabs() {
  const projectPath = state.currentProject?.path;
  const fragment = document.createDocumentFragment();
  if (!projectPath) {
    elements.mapWorkspaceTabsCount.textContent = "0";
    elements.mapWorkspaceTabs.replaceChildren();
    return;
  }
  pruneClosedMapEditorBindings();
  const live = [...state.mapEditorGameBindings.entries()]
    .filter(([, binding]) => binding.projectPath === projectPath && binding.relativePath)
    .sort((left, right) => (right[1].lastActiveAt || 0) - (left[1].lastActiveAt || 0));
  const livePaths = new Set(live.map(([, binding]) => binding.relativePath));
  const recent = state.mapEditorRecentTabs
    .filter((entry) => entry.projectPath === projectPath && !livePaths.has(entry.relativePath))
    .slice(0, 12);
  for (const [editorInstanceId, binding] of live) {
    fragment.append(createMapWorkspaceTab({
      editorInstanceId,
      relativePath: binding.relativePath,
      dirty: binding.dirty === true,
      open: true,
      onActivate: () => {
        if (binding.editorWindow && !binding.editorWindow.closed) {
          binding.editorWindow.focus();
          binding.lastActiveAt = Date.now();
          closeMapWorkspace();
        }
      },
      onClose: () => requestMapEditorTabClose(editorInstanceId),
    }));
  }
  for (const entry of recent) {
    fragment.append(createMapWorkspaceTab({
      relativePath: entry.relativePath,
      dirty: false,
      open: false,
      onActivate: () => void openMapEditorEntry({
        kind: "map",
        path: entry.relativePath,
        name: entry.relativePath.split("/").at(-1),
      }, { source: "workspace" }),
      onClose: () => forgetMapEditorRecentTab(projectPath, entry.relativePath),
    }));
  }
  const count = live.length + recent.length;
  if (!count) {
    const empty = document.createElement("span");
    empty.className = "map-workspace-tabs-empty";
    empty.textContent = "暂无地图标签";
    fragment.append(empty);
  }
  elements.mapWorkspaceTabsCount.textContent = String(count);
  elements.mapWorkspaceTabs.replaceChildren(fragment);
  refreshIcons();
  renderMapGameWorkModeSetting();
}

function createMapWorkspaceTab({ relativePath, dirty, open, onActivate, onClose, editorInstanceId = "" }) {
  const row = document.createElement("div");
  row.className = "map-workspace-tab";
  row.dataset.open = String(open);
  row.dataset.dirty = String(dirty);
  if (editorInstanceId) row.dataset.editorInstanceId = editorInstanceId;
  row.innerHTML = '<span class="map-workspace-tab-state"></span><button class="map-workspace-tab-main" type="button" role="tab"></button><button class="map-workspace-tab-close" type="button" aria-label="关闭地图标签"><i data-lucide="x"></i></button>';
  const name = relativePath.split("/").at(-1) || relativePath;
  const activate = row.querySelector(".map-workspace-tab-main");
  activate.textContent = name;
  activate.title = relativePath;
  activate.setAttribute("aria-selected", String(open));
  activate.addEventListener("click", onActivate);
  const close = row.querySelector(".map-workspace-tab-close");
  close.title = open ? `关闭 ${name}` : `移除 ${name}`;
  close.setAttribute("aria-label", close.title);
  close.addEventListener("click", onClose);
  return row;
}

function loadMapEditorRecentTabs() {
  try {
    const value = JSON.parse(localStorage.getItem(accountStorageKey(MAP_EDITOR_RECENT_KEY)) || "[]");
    if (!Array.isArray(value)) return [];
    return value.filter((entry) => (
      entry
      && typeof entry.projectPath === "string"
      && entry.projectPath.startsWith("/")
      && typeof entry.relativePath === "string"
      && entry.relativePath.toLowerCase().endsWith(".tmj")
      && Number.isFinite(Number(entry.lastOpenedAt))
    )).slice(0, 50);
  } catch {
    return [];
  }
}

function rememberMapEditorTab(projectPath, relativePath) {
  const next = [
    { projectPath, relativePath, lastOpenedAt: Date.now() },
    ...state.mapEditorRecentTabs.filter((entry) => (
      entry.projectPath !== projectPath || entry.relativePath !== relativePath
    )),
  ].slice(0, 50);
  state.mapEditorRecentTabs = next;
  persistMapEditorRecentTabs();
  renderMapWorkspaceTabs();
}

function ensureMapEditorRecentTab(projectPath, relativePath) {
  if (state.mapEditorRecentTabs.some((entry) => (
    entry.projectPath === projectPath && entry.relativePath === relativePath
  ))) return;
  rememberMapEditorTab(projectPath, relativePath);
}

function forgetMapEditorRecentTab(projectPath, relativePath) {
  state.mapEditorRecentTabs = state.mapEditorRecentTabs.filter((entry) => (
    entry.projectPath !== projectPath || entry.relativePath !== relativePath
  ));
  persistMapEditorRecentTabs();
  renderMapWorkspaceTabs();
}

function persistMapEditorRecentTabs() {
  try {
    localStorage.setItem(accountStorageKey(MAP_EDITOR_RECENT_KEY), JSON.stringify(state.mapEditorRecentTabs));
  } catch {
    // The live window registry remains authoritative when storage is unavailable.
  }
}

function pruneClosedMapEditorBindings() {
  let changed = false;
  for (const [editorInstanceId, binding] of state.mapEditorGameBindings) {
    if (!binding.editorWindow?.closed) continue;
    state.mapEditorGameBindings.delete(editorInstanceId);
    changed = true;
  }
  if (changed) broadcastMapEditorTabSnapshot();
}

function requestMapEditorTabClose(editorInstanceId) {
  const binding = state.mapEditorGameBindings.get(editorInstanceId);
  if (!binding) return;
  try {
    state.gameWorkModeChannel?.postMessage(createMapEditorTabSignal("close-command", {
      hostWindowId: CLIENT_WINDOW_ID,
      editorInstanceId: CLIENT_WINDOW_ID,
      targetEditorInstanceId: editorInstanceId,
    }));
    binding.editorWindow?.focus();
  } catch {
    binding.editorWindow?.close();
  }
}

function openWorldNewDialog() {
  const session = state.mapWorkspaceProjectSession;
  if (!session || !state.mapWorkspaceClient) {
    toast("地图项目工作区尚未连接", "error");
    return;
  }
  if (!session.writable) {
    toast("当前地图项目是只读的", "error");
    return;
  }
  state.worldNewBusy = false;
  elements.worldNewForm.reset();
  elements.worldNewName.value = "game-world";
  elements.worldNewDirectory.value = defaultWorldNewDirectory(session);
  elements.worldNewError.textContent = "";
  updateWorldNewForm();
  elements.worldNewDialog.showModal();
  requestAnimationFrame(() => elements.worldNewName.focus());
}

function closeWorldNewDialog({ force = false } = {}) {
  if (state.worldNewBusy && !force) return;
  if (elements.worldNewDialog.open) elements.worldNewDialog.close();
  elements.worldNewError.textContent = "";
}

function updateWorldNewForm() {
  elements.worldNewName.setCustomValidity("");
  elements.worldNewDirectory.setCustomValidity("");
  try {
    elements.worldNewPathPreview.textContent = worldNewRelativePath(
      elements.worldNewName.value,
      elements.worldNewDirectory.value,
    );
  } catch (error) {
    elements.worldNewName.setCustomValidity(error.message);
    elements.worldNewPathPreview.textContent = "World 路径待修正";
  }
  renderWorldNewForm();
}

function renderWorldNewForm() {
  elements.worldNewForm.setAttribute("aria-busy", String(state.worldNewBusy));
  for (const control of elements.worldNewForm.querySelectorAll("input, button")) {
    control.disabled = state.worldNewBusy;
  }
  elements.worldNewSubmitButton.querySelector("span").textContent = state.worldNewBusy ? "正在创建" : "创建并打开";
  renderMapWorkspaceMaps();
}

async function submitWorldNewForm(event) {
  event.preventDefault();
  if (state.worldNewBusy) return;
  updateWorldNewForm();
  if (!elements.worldNewForm.reportValidity()) return;
  const editorWindow = window.open("/world-editor.html#pending", "_blank");
  if (!editorWindow) {
    elements.worldNewError.textContent = "浏览器阻止了 World 编辑器窗口";
    return;
  }
  const client = state.mapWorkspaceClient;
  const sessionId = state.mapWorkspaceProjectSession?.id;
  state.worldNewBusy = true;
  elements.worldNewError.textContent = "";
  renderWorldNewForm();
  try {
    if (!client || !sessionId) throw new Error("地图项目工作区连接已经关闭");
    const created = await client.createWorld({
      relativePath: worldNewRelativePath(elements.worldNewName.value, elements.worldNewDirectory.value),
      maps: [],
      patterns: [],
      onlyShowAdjacentMaps: elements.worldNewAdjacent.checked,
    });
    if (state.mapWorkspaceClient !== client || state.mapWorkspaceProjectSession?.id !== sessionId) {
      throw new Error("地图项目工作区在创建过程中发生变化");
    }
    await refreshMapWorkspaceCreatedPath(created, "world");
    if (elements.worldNewDialog.open) elements.worldNewDialog.close();
    await openWorldEditorEntry({
      kind: "world",
      path: created.relativePath,
      name: created.relativePath.split("/").at(-1),
      size: created.size,
      modifiedAt: created.modifiedAt,
    }, { editorWindow });
  } catch (error) {
    if (!editorWindow.closed) editorWindow.close();
    elements.worldNewError.textContent = error.message;
    toast(error.message, "error");
  } finally {
    state.worldNewBusy = false;
    renderWorldNewForm();
  }
}

function defaultWorldNewDirectory(session) {
  return session.resourceRoots.find((root) => root && /(^|\/)worlds?$/iu.test(root))
    || session.resourceRoots.find((root) => root && /(^|\/)maps?$/iu.test(root))
    || session.resourceRoots.find(Boolean)
    || "maps";
}

function worldNewRelativePath(nameValue, directoryValue) {
  const name = String(nameValue || "").trim();
  if (!name || name.startsWith(".") || name.includes("/") || name.includes("\\") || /[\u0000-\u001f\u007f]/u.test(name)) {
    throw new Error("World 名称不能包含路径分隔符、隐藏前缀或控制字符");
  }
  const filename = /\.world$/iu.test(name) ? name : `${name}.world`;
  const directory = String(directoryValue || "").trim().replace(/\/$/u, "");
  const candidate = directory ? `${directory}/${filename}` : filename;
  if (candidate.length > 4096) throw new Error("World 路径过长");
  return normalizeMapNewResourcePath(candidate, ".world", "World 路径");
}

function openMapNewDialog() {
  const session = state.mapWorkspaceProjectSession;
  if (!session || !state.mapWorkspaceClient) {
    toast("地图项目工作区尚未连接", "error");
    return;
  }
  if (!session.writable) {
    toast("当前地图项目是只读的", "error");
    return;
  }
  state.mapNewBusy = false;
  state.mapNewTilesetLoadId += 1;
  elements.mapNewForm.reset();
  elements.mapNewName.value = "new-map";
  elements.mapNewDirectory.value = defaultMapNewDirectory(session);
  elements.mapNewError.textContent = "";
  elements.mapNewTilesetOptions.replaceChildren();
  updateMapNewForm();
  elements.mapNewDialog.showModal();
  void loadMapNewTilesetOptions(session.id, state.mapNewTilesetLoadId);
  requestAnimationFrame(() => elements.mapNewName.focus());
}

function closeMapNewDialog({ force = false } = {}) {
  if (state.mapNewBusy && !force) return;
  state.mapNewTilesetLoadId += 1;
  if (elements.mapNewDialog.open) elements.mapNewDialog.close();
  elements.mapNewError.textContent = "";
}

function updateMapNewForm() {
  const orientation = elements.mapNewOrientation.value;
  const infinite = elements.mapNewInfinite.checked;
  const staggered = orientation === "staggered" || orientation === "hexagonal";
  elements.mapNewSizeGrid.dataset.infinite = String(infinite);
  for (const field of elements.mapNewSizeGrid.querySelectorAll(".map-new-fixed-field")) field.hidden = infinite;
  elements.mapNewWidth.required = !infinite;
  elements.mapNewHeight.required = !infinite;
  elements.mapNewStaggerFields.hidden = !staggered;
  elements.mapNewHexField.hidden = orientation !== "hexagonal";
  elements.mapNewObliqueFields.hidden = orientation !== "oblique";
  elements.mapNewBackgroundColor.disabled = state.mapNewBusy || !elements.mapNewBackgroundEnabled.checked;
  const hexMaximum = elements.mapNewStaggerAxis.value === "x"
    ? Number(elements.mapNewTileWidth.value)
    : Number(elements.mapNewTileHeight.value);
  elements.mapNewHexSideLength.max = String(Number.isSafeInteger(hexMaximum) && hexMaximum > 0 ? hexMaximum : 1_000_000);
  setMapNewPathValidity();
  renderMapNewForm();
}

function renderMapNewForm() {
  elements.mapNewForm.setAttribute("aria-busy", String(state.mapNewBusy));
  for (const control of elements.mapNewForm.querySelectorAll("input, select, button")) {
    if (control === elements.mapNewBackgroundColor) continue;
    control.disabled = state.mapNewBusy;
  }
  elements.mapNewBackgroundColor.disabled = state.mapNewBusy || !elements.mapNewBackgroundEnabled.checked;
  elements.mapNewSubmitButton.dataset.busy = String(state.mapNewBusy);
  elements.mapNewSubmitButton.querySelector("span").textContent = state.mapNewBusy ? "正在创建" : "创建并打开";
  renderMapWorkspaceMaps();
}

function setMapNewPathValidity() {
  for (const input of [elements.mapNewName, elements.mapNewDirectory, elements.mapNewTileset]) {
    input.setCustomValidity("");
  }
  let relativePath = null;
  try {
    relativePath = mapNewRelativePath(elements.mapNewName.value, elements.mapNewDirectory.value);
    elements.mapNewPathPreview.textContent = relativePath;
  } catch (error) {
    elements.mapNewName.setCustomValidity(error.message);
    elements.mapNewPathPreview.textContent = "地图路径待修正";
  }
  const tileset = elements.mapNewTileset.value.trim();
  try {
    const normalizedTileset = tileset ? normalizeMapNewResourcePath(tileset, ".tsj", "外部瓦片集") : null;
    elements.mapNewReferencePreview.textContent = normalizedTileset && relativePath
      ? mapNewRelativeReference(relativePath, normalizedTileset)
      : "无外部瓦片集";
  } catch (error) {
    elements.mapNewTileset.setCustomValidity(error.message);
    elements.mapNewReferencePreview.textContent = "瓦片集路径待修正";
  }
}

async function loadMapNewTilesetOptions(sessionId, loadId) {
  const client = state.mapWorkspaceClient;
  if (!client) return;
  try {
    const page = await client.search({ query: ".tsj", kinds: ["tileset"], limit: 100 });
    if (
      loadId !== state.mapNewTilesetLoadId
      || !elements.mapNewDialog.open
      || state.mapWorkspaceProjectSession?.id !== sessionId
    ) return;
    const fragment = document.createDocumentFragment();
    for (const entry of page.entries) {
      const option = document.createElement("option");
      option.value = entry.path;
      fragment.append(option);
    }
    elements.mapNewTilesetOptions.replaceChildren(fragment);
  } catch {
    // The field remains manually editable when the optional suggestions fail.
  }
}

async function submitMapNewForm(event) {
  event.preventDefault();
  if (state.mapNewBusy) return;
  updateMapNewForm();
  if (!elements.mapNewForm.reportValidity()) return;
  let payload;
  try {
    payload = mapNewPayload();
  } catch (error) {
    elements.mapNewError.textContent = error.message;
    return;
  }
  const editorWindow = window.open("/map-editor.html#pending", "_blank");
  if (!editorWindow) {
    elements.mapNewError.textContent = "浏览器阻止了地图编辑器窗口";
    return;
  }
  const client = state.mapWorkspaceClient;
  const sessionId = state.mapWorkspaceProjectSession?.id;
  state.mapNewBusy = true;
  elements.mapNewError.textContent = "";
  renderMapNewForm();
  try {
    if (!client || !sessionId) throw new Error("地图项目工作区连接已经关闭");
    const created = await client.createMap(payload);
    if (state.mapWorkspaceClient !== client || state.mapWorkspaceProjectSession?.id !== sessionId) {
      throw new Error("地图项目工作区在创建过程中发生变化");
    }
    await refreshMapWorkspaceCreatedPath(created);
    if (elements.mapNewDialog.open) elements.mapNewDialog.close();
    await openMapEditorEntry({
      kind: "map",
      path: created.relativePath,
      name: created.relativePath.split("/").at(-1),
      size: created.size,
      modifiedAt: created.modifiedAt,
    }, { source: "workspace", editorWindow });
  } catch (error) {
    if (!editorWindow.closed) editorWindow.close();
    elements.mapNewError.textContent = error.message;
    toast(error.message, "error");
  } finally {
    state.mapNewBusy = false;
    renderMapNewForm();
  }
}

function mapNewPayload() {
  const relativePath = mapNewRelativePath(elements.mapNewName.value, elements.mapNewDirectory.value);
  const orientation = elements.mapNewOrientation.value;
  const infinite = elements.mapNewInfinite.checked;
  const tileset = elements.mapNewTileset.value.trim();
  return {
    relativePath,
    orientation,
    infinite,
    ...(!infinite ? {
      width: Number(elements.mapNewWidth.value),
      height: Number(elements.mapNewHeight.value),
    } : {}),
    tilewidth: Number(elements.mapNewTileWidth.value),
    tileheight: Number(elements.mapNewTileHeight.value),
    renderorder: elements.mapNewRenderOrder.value,
    initialLayerName: elements.mapNewInitialLayer.value.trim(),
    tilesets: tileset ? [normalizeMapNewResourcePath(tileset, ".tsj", "外部瓦片集")] : [],
    targetVersion: elements.mapNewTargetVersion.value,
    ...(elements.mapNewBackgroundEnabled.checked ? { backgroundcolor: elements.mapNewBackgroundColor.value } : {}),
    ...(["staggered", "hexagonal"].includes(orientation) ? {
      staggeraxis: elements.mapNewStaggerAxis.value,
      staggerindex: elements.mapNewStaggerIndex.value,
    } : {}),
    ...(orientation === "hexagonal" ? { hexsidelength: Number(elements.mapNewHexSideLength.value) } : {}),
    ...(orientation === "oblique" ? {
      skewx: Number(elements.mapNewSkewX.value),
      skewy: Number(elements.mapNewSkewY.value),
    } : {}),
  };
}

async function refreshMapWorkspaceCreatedPath(created, kind = "map") {
  state.mapWorkspaceSearchResult = null;
  elements.mapWorkspaceSearch.value = "";
  const parent = created.relativePath.split("/").slice(0, -1);
  const directories = [""];
  for (let index = 1; index <= parent.length; index += 1) {
    directories.push(parent.slice(0, index).join("/"));
  }
  for (const directory of directories) {
    if (directory) state.mapWorkspaceExpanded.add(directory);
    await loadMapWorkspaceDirectory(directory, { reset: true });
  }
  const parentPath = parent.join("/");
  const record = state.mapWorkspaceDirectories.get(parentPath);
  if (record && !record.entries.some((entry) => entry.path === created.relativePath)) {
    record.entries.push(Object.freeze({
      path: created.relativePath,
      name: created.relativePath.split("/").at(-1),
      kind,
      size: created.size,
      modifiedAt: created.modifiedAt,
    }));
    record.entries.sort((left, right) => left.name.localeCompare(right.name, interfaceLocale(), { numeric: true }));
  }
  renderMapWorkspaceMaps();
}

function openTilesetNewDialog() {
  const session = state.mapWorkspaceProjectSession;
  if (!session || !state.mapWorkspaceClient) {
    toast("地图项目工作区尚未连接", "error");
    return;
  }
  if (!session.writable) {
    toast("当前地图项目是只读的", "error");
    return;
  }
  state.tilesetNewImageLoadId += 1;
  state.tilesetNewImages = [];
  state.tilesetNewSelectedImages = new Set();
  elements.tilesetNewForm.reset();
  elements.tilesetNewName.value = "terrain";
  elements.tilesetNewDirectory.value = defaultTilesetNewDirectory(session);
  elements.tilesetNewDisplayName.value = "Terrain";
  elements.tilesetNewError.textContent = "";
  elements.tilesetNewImageSearch.value = "";
  updateTilesetNewForm();
  elements.tilesetNewDialog.showModal();
  const loadId = state.tilesetNewImageLoadId;
  void loadTilesetNewImages(session.id, loadId);
  requestAnimationFrame(() => elements.tilesetNewName.focus());
}

function closeTilesetNewDialog({ force = false } = {}) {
  if (state.tilesetNewBusy && !force) return;
  state.tilesetNewImageLoadId += 1;
  if (elements.tilesetNewDialog.open) elements.tilesetNewDialog.close();
  elements.tilesetNewError.textContent = "";
}

function updateTilesetNewForm() {
  const atlas = elements.tilesetNewKind.value === "atlas";
  elements.tilesetNewAtlasFields.hidden = !atlas;
  for (const field of [elements.tilesetNewTileWidth, elements.tilesetNewTileHeight, elements.tilesetNewMargin, elements.tilesetNewSpacing]) {
    field.required = atlas;
  }
  elements.tilesetNewImagesLegend.textContent = atlas ? "选择一张工程图片" : "选择一张或多张工程图片";
  elements.tilesetNewImageList.setAttribute("aria-multiselectable", String(!atlas));
  if (atlas && state.tilesetNewSelectedImages.size > 1) {
    state.tilesetNewSelectedImages = new Set([...state.tilesetNewSelectedImages].slice(-1));
  }
  elements.tilesetNewTransparentColor.disabled = state.tilesetNewBusy
    || !atlas
    || !elements.tilesetNewTransparentEnabled.checked;
  for (const input of [elements.tilesetNewName, elements.tilesetNewDirectory]) input.setCustomValidity("");
  try {
    elements.tilesetNewPathPreview.textContent = tilesetNewRelativePath(
      elements.tilesetNewName.value,
      elements.tilesetNewDirectory.value,
    );
  } catch (error) {
    elements.tilesetNewName.setCustomValidity(error.message);
    elements.tilesetNewPathPreview.textContent = "瓦片集路径待修正";
  }
  renderTilesetNewForm();
}

function renderTilesetNewForm() {
  elements.tilesetNewForm.setAttribute("aria-busy", String(state.tilesetNewBusy));
  for (const control of elements.tilesetNewForm.querySelectorAll("input, select, button")) {
    if (control === elements.tilesetNewTransparentColor) continue;
    control.disabled = state.tilesetNewBusy;
  }
  elements.tilesetNewTransparentColor.disabled = state.tilesetNewBusy
    || elements.tilesetNewKind.value !== "atlas"
    || !elements.tilesetNewTransparentEnabled.checked;
  elements.tilesetNewSubmitButton.dataset.busy = String(state.tilesetNewBusy);
  elements.tilesetNewSubmitButton.querySelector("span").textContent = state.tilesetNewBusy ? "正在创建" : "创建并打开";
  renderTilesetNewImages();
  renderMapWorkspaceMaps();
}

async function loadTilesetNewImages(sessionId, loadId) {
  const client = state.mapWorkspaceClient;
  if (!client) return;
  elements.tilesetNewImageState.textContent = "正在读取工程图片";
  elements.tilesetNewImageState.dataset.status = "busy";
  try {
    const results = await Promise.all(["png", "webp", "jpg", "jpeg"].map((query) => (
      client.search({ query, kinds: ["image"], limit: 100 }).catch(() => ({ entries: [] }))
    )));
    if (
      loadId !== state.tilesetNewImageLoadId
      || !elements.tilesetNewDialog.open
      || state.mapWorkspaceProjectSession?.id !== sessionId
    ) return;
    const images = new Map();
    for (const page of results) for (const entry of page.entries) images.set(entry.path, entry);
    state.tilesetNewImages = [...images.values()].sort((left, right) => (
      left.path.localeCompare(right.path, interfaceLocale(), { numeric: true })
    ));
    elements.tilesetNewImageState.textContent = state.tilesetNewImages.length
      ? `找到 ${state.tilesetNewImages.length} 张图片`
      : "当前工程没有可用的 PNG、JPEG 或 WebP";
    elements.tilesetNewImageState.dataset.status = state.tilesetNewImages.length ? "ready" : "warning";
    renderTilesetNewImages();
  } catch (error) {
    if (loadId !== state.tilesetNewImageLoadId) return;
    elements.tilesetNewImageState.textContent = error.message;
    elements.tilesetNewImageState.dataset.status = "error";
  }
}

function renderTilesetNewImages() {
  const query = elements.tilesetNewImageSearch.value.trim().toLocaleLowerCase(interfaceLocale());
  const fragment = document.createDocumentFragment();
  let visible = 0;
  for (const entry of state.tilesetNewImages) {
    if (query && !entry.path.toLocaleLowerCase(interfaceLocale()).includes(query)) continue;
    visible += 1;
    const row = document.createElement("label");
    row.className = "tileset-new-image-row";
    row.dataset.imagePath = entry.path;
    row.setAttribute("role", "option");
    row.setAttribute("aria-selected", String(state.tilesetNewSelectedImages.has(entry.path)));
    row.dataset.disabled = String(state.tilesetNewBusy);
    row.innerHTML = '<input class="tileset-new-image-choice" type="checkbox" /><i data-lucide="image"></i><span><strong></strong><small></small></span>';
    const choice = row.querySelector(".tileset-new-image-choice");
    choice.type = elements.tilesetNewKind.value === "atlas" ? "radio" : "checkbox";
    choice.name = "tilesetImages";
    choice.checked = state.tilesetNewSelectedImages.has(entry.path);
    choice.disabled = state.tilesetNewBusy;
    choice.addEventListener("input", (event) => {
      event.stopPropagation();
      setTilesetNewImage(entry.path, choice.checked);
    });
    setDataContent(row.querySelector("strong"), entry.name);
    setDataContent(row.querySelector("small"), entry.path);
    fragment.append(row);
  }
  if (!visible && state.tilesetNewImages.length) {
    const empty = document.createElement("p");
    empty.className = "tileset-new-image-empty";
    empty.textContent = "没有匹配的工程图片";
    fragment.append(empty);
  }
  elements.tilesetNewImageList.replaceChildren(fragment);
  elements.tilesetNewImageList.dataset.selectedCount = String(state.tilesetNewSelectedImages.size);
  refreshIcons();
}

function setTilesetNewImage(imagePath, selected) {
  const next = new Set(state.tilesetNewSelectedImages);
  if (elements.tilesetNewKind.value === "atlas") {
    next.clear();
    if (selected) next.add(imagePath);
  } else if (selected) next.add(imagePath);
  else next.delete(imagePath);
  state.tilesetNewSelectedImages = next;
  elements.tilesetNewError.textContent = "";
  renderTilesetNewImages();
}

async function submitTilesetNewForm(event) {
  event.preventDefault();
  if (state.tilesetNewBusy) return;
  updateTilesetNewForm();
  if (!elements.tilesetNewForm.reportValidity()) return;
  let payload;
  try {
    payload = tilesetNewPayload();
  } catch (error) {
    elements.tilesetNewError.textContent = error.message;
    return;
  }
  const editorWindow = window.open("/tileset-editor.html#pending", "_blank");
  if (!editorWindow) {
    elements.tilesetNewError.textContent = "浏览器阻止了瓦片集编辑器窗口";
    return;
  }
  const client = state.mapWorkspaceClient;
  const sessionId = state.mapWorkspaceProjectSession?.id;
  state.tilesetNewBusy = true;
  elements.tilesetNewError.textContent = "";
  renderTilesetNewForm();
  try {
    if (!client || !sessionId) throw new Error("地图项目工作区连接已经关闭");
    const created = await client.createTileset(payload);
    if (state.mapWorkspaceClient !== client || state.mapWorkspaceProjectSession?.id !== sessionId) {
      throw new Error("地图项目工作区在创建过程中发生变化");
    }
    await refreshMapWorkspaceCreatedPath(created, "tileset");
    if (elements.tilesetNewDialog.open) elements.tilesetNewDialog.close();
    await openTilesetEditorEntry({
      kind: "tileset",
      path: created.relativePath,
      name: created.relativePath.split("/").at(-1),
      size: created.size,
      modifiedAt: created.modifiedAt,
    }, { editorWindow });
  } catch (error) {
    if (!editorWindow.closed) editorWindow.close();
    elements.tilesetNewError.textContent = error.message;
    toast(error.message, "error");
  } finally {
    state.tilesetNewBusy = false;
    renderTilesetNewForm();
  }
}

function tilesetNewPayload() {
  const relativePath = tilesetNewRelativePath(elements.tilesetNewName.value, elements.tilesetNewDirectory.value);
  const kind = elements.tilesetNewKind.value;
  const images = [...state.tilesetNewSelectedImages];
  if (kind === "atlas" && images.length !== 1) throw new Error("单图 Atlas 必须选择一张工程图片");
  if (kind === "collection" && !images.length) throw new Error("图片集合至少选择一张工程图片");
  return {
    relativePath,
    kind,
    name: elements.tilesetNewDisplayName.value.trim(),
    targetVersion: elements.tilesetNewTargetVersion.value,
    ...(kind === "atlas" ? {
      image: images[0],
      tilewidth: Number(elements.tilesetNewTileWidth.value),
      tileheight: Number(elements.tilesetNewTileHeight.value),
      margin: Number(elements.tilesetNewMargin.value),
      spacing: Number(elements.tilesetNewSpacing.value),
      ...(elements.tilesetNewTransparentEnabled.checked
        ? { transparentcolor: elements.tilesetNewTransparentColor.value }
        : {}),
    } : { images }),
  };
}

function defaultTilesetNewDirectory(session) {
  return session.resourceRoots.find((root) => root && /(^|\/)tilesets?$/iu.test(root))
    || session.resourceRoots.find(Boolean)
    || "tilesets";
}

function tilesetNewRelativePath(nameValue, directoryValue) {
  const name = String(nameValue || "").trim();
  if (!name || name.startsWith(".") || name.includes("/") || name.includes("\\") || /[\u0000-\u001f\u007f]/u.test(name)) {
    throw new Error("瓦片集名称不能包含路径分隔符或控制字符");
  }
  const basename = name.toLowerCase().endsWith(".tsj") ? name : `${name}.tsj`;
  const directory = String(directoryValue || "").trim().replace(/^\/+|\/+$/gu, "");
  return normalizeMapNewResourcePath(directory ? `${directory}/${basename}` : basename, ".tsj", "瓦片集路径");
}

function defaultMapNewDirectory(session) {
  return session.resourceRoots.find((root) => root && /(^|\/)maps?$/iu.test(root))
    || session.resourceRoots.find(Boolean)
    || "maps";
}

function mapNewRelativePath(nameValue, directoryValue) {
  const name = String(nameValue || "").trim();
  if (!name || name.startsWith(".") || name.includes("/") || name.includes("\\") || /[\u0000-\u001f\u007f]/u.test(name)) {
    throw new Error("地图名称不能包含路径分隔符、隐藏前缀或控制字符");
  }
  const filename = /\.tmj$/iu.test(name) ? name : `${name}.tmj`;
  const directory = String(directoryValue || "").trim().replace(/\/$/u, "");
  const candidate = directory ? `${directory}/${filename}` : filename;
  if (candidate.length > 4096) throw new Error("地图路径过长");
  return normalizeMapNewResourcePath(candidate, ".tmj", "地图路径");
}

function normalizeMapNewResourcePath(value, extension, label) {
  const normalized = String(value || "").trim();
  if (!normalized || normalized.startsWith("/") || normalized.includes("\\") || /^[a-z][a-z0-9+.-]*:/iu.test(normalized)) {
    throw new Error(`${label}必须使用工程相对路径`);
  }
  const segments = normalized.split("/");
  if (segments.some((segment) => !segment || segment === "." || segment === ".." || segment.startsWith("."))) {
    throw new Error(`${label}路径无效`);
  }
  if (!segments.at(-1).toLowerCase().endsWith(extension)) throw new Error(`${label}必须使用 ${extension} 扩展名`);
  return segments.join("/");
}

function mapNewRelativeReference(mapPath, targetPath) {
  const from = mapPath.split("/").slice(0, -1);
  const target = targetPath.split("/");
  let common = 0;
  while (common < from.length && common < target.length && from[common] === target[common]) common += 1;
  return `${"../".repeat(from.length - common)}${target.slice(common).join("/")}`;
}

async function loadMapAiToolsSetting({ silent = false } = {}) {
  const requestAccountId = state.account?.id || null;
  if (!requestAccountId) return false;
  if (state.mapAiToolsRequest && state.mapAiToolsRequestAccountId === requestAccountId) {
    return state.mapAiToolsRequest;
  }
  state.mapAiToolsMessage = silent ? "" : "正在读取";
  state.mapAiToolsMessageStatus = "busy";
  const request = (async () => {
    const response = await fetchWithTimeout("/api/account/map-ai", { cache: "no-store" }, 12_000);
    const data = await response.json();
    if (!response.ok) throw new Error(data.error || "无法读取地图 AI 开关");
    if (state.account?.id !== requestAccountId) return false;
    state.mapAiToolsEnabled = data?.mapAiToolsEnabled === true;
    state.mapAiToolsLoaded = true;
    state.mapAiToolsMessage = state.mapAiToolsEnabled ? "已开启" : "已关闭";
    state.mapAiToolsMessageStatus = "ready";
    return state.mapAiToolsEnabled;
  })();
  state.mapAiToolsRequest = request;
  state.mapAiToolsRequestAccountId = requestAccountId;
  renderMapAiToolsSetting();
  try {
    return await request;
  } catch (error) {
    if (state.account?.id !== requestAccountId) return false;
    state.mapAiToolsEnabled = false;
    state.mapAiToolsLoaded = true;
    state.mapAiToolsMessage = error.message;
    state.mapAiToolsMessageStatus = "error";
    if (!silent) toast(error.message, "error");
    return false;
  } finally {
    if (state.mapAiToolsRequest === request) {
      state.mapAiToolsRequest = null;
      state.mapAiToolsRequestAccountId = null;
      renderMapAiToolsSetting();
    }
  }
}

async function saveMapAiToolsSetting() {
  if (state.mapAiToolsSaving || state.mapAiToolsRequest) return;
  const requestAccountId = state.account?.id || null;
  if (!requestAccountId) return;
  const enabled = elements.mapAiToolsToggle.checked;
  state.mapAiToolsSaving = true;
  state.mapAiToolsMessage = "正在保存";
  state.mapAiToolsMessageStatus = "busy";
  renderMapAiToolsSetting();
  try {
    const response = await fetch("/api/account/map-ai", {
      method: "PUT",
      headers: {
        "Content-Type": "application/json",
        "X-Codex-Desktop-Action": "map-ai-setting",
      },
      body: JSON.stringify({ enabled }),
    });
    const data = await response.json();
    if (!response.ok) throw new Error(data.error || "无法保存地图 AI 开关");
    if (state.account?.id !== requestAccountId) return;
    state.mapAiToolsEnabled = data?.mapAiToolsEnabled === true;
    state.mapAiToolsLoaded = true;
    const revoked = Number(data?.revokedLeases) || 0;
    state.mapAiToolsMessage = state.mapAiToolsEnabled
      ? "已开启"
      : revoked > 0 ? `已关闭 · 撤销 ${revoked} 个授权` : "已关闭";
    state.mapAiToolsMessageStatus = "ready";
    toast(state.mapAiToolsEnabled ? "地图 AI 工具已开启" : "地图 AI 工具已关闭");
  } catch (error) {
    if (state.account?.id !== requestAccountId) return;
    state.mapAiToolsMessage = error.message;
    state.mapAiToolsMessageStatus = "error";
    toast(error.message, "error");
  } finally {
    if (state.account?.id === requestAccountId) {
      state.mapAiToolsSaving = false;
      renderMapAiToolsSetting();
    }
  }
}

function renderMapAiToolsSetting() {
  const busy = Boolean(state.mapAiToolsRequest) || state.mapAiToolsSaving;
  elements.mapAiToolsToggle.checked = state.mapAiToolsEnabled;
  elements.mapAiToolsToggle.disabled = busy;
  elements.mapAiToolsState.textContent = busy
    ? state.mapAiToolsSaving ? "保存中" : "读取中"
    : state.mapAiToolsMessage || (state.mapAiToolsEnabled ? "已开启" : "默认关闭");
  elements.mapAiToolsState.dataset.enabled = String(state.mapAiToolsEnabled);
  elements.mapAiToolsState.dataset.status = state.mapAiToolsMessageStatus;
  renderMapManagedAccess();
}

const MAP_MANAGED_POLICY_LABELS = Object.freeze({
  ask_each: "每条询问",
  ai_review: "AI 审查",
  full_authorization: "完全授权",
});

function setMapManagedMessage(message, status = "ready") {
  elements.mapManagedState.textContent = message || "";
  elements.mapManagedState.dataset.status = message ? status : "";
}

function managedProjectThread() {
  return currentCodexMapThread(state.currentProject);
}

function mapManagedContextSnapshot() {
  return {
    accountId: state.account?.id || null,
    projectPath: state.currentProject?.path || null,
    // Project-wide managed authorization is intentionally independent of the
    // current conversation. The active Thread remains the AI entry point,
    // never the grant boundary.
    threadId: null,
  };
}

function sameMapManagedContext(left, right) {
  return Boolean(left && right)
    && left.accountId === right.accountId
    && left.projectPath === right.projectPath
    && left.threadId === right.threadId;
}

function mapManagedContextIsCurrent(context) {
  return sameMapManagedContext(context, mapManagedContextSnapshot());
}

function invalidateMapManagedAuthorizations() {
  state.mapManagedRequestVersion += 1;
  state.mapManagedRequestAccountId = null;
  state.mapManagedLoading = false;
  state.mapManagedLoadingContext = null;
  state.mapManagedLoadedContext = null;
  state.mapManagedAuthorizations = [];
  renderMapManagedAccess();
}

function reloadMapManagedAuthorizationsForCurrentContext() {
  if (!elements.mapWorkspaceDialog?.open) return;
  if (state.mapWorkspaceProjectPath !== state.currentProject?.path) return;
  void loadMapManagedAuthorizations({ silent: true });
}

async function fingerprintForManagedProject(projectValue) {
  if (!globalThis.crypto?.subtle || typeof projectValue !== "string") return null;
  const digest = await crypto.subtle.digest("SHA-256", new TextEncoder().encode(projectValue));
  return [...new Uint8Array(digest)].map((value) => value.toString(16).padStart(2, "0")).join("");
}

function normalizeManagedMapPath(value) {
  const raw = String(value || "").trim().replaceAll("\\", "/");
  if (!raw || raw.startsWith("/") || raw.split("/").includes("..") || !/\.tmj$/iu.test(raw)) {
    throw new Error("地图必须是工程相对路径并以 .tmj 结尾");
  }
  const normalized = raw.split("/").filter(Boolean).join("/");
  if (!normalized || normalized === "." || normalized.startsWith("../")) throw new Error("地图相对路径无效");
  return normalized;
}

function parseMainManagedProtectedTargets(value, mapPath) {
  return String(value || "").split(",").map((entry) => entry.trim()).filter(Boolean).map((entry) => {
    const separator = entry.indexOf(":");
    const kind = separator < 0 ? "file" : entry.slice(0, separator).trim().toLowerCase();
    const target = separator < 0 ? entry : entry.slice(separator + 1).trim();
    if (kind === "file") return { kind, path: target };
    if (kind === "semantic") return { kind, mapPath, role: target };
    if (kind === "layer") {
      const layerId = Number(target);
      if (!Number.isSafeInteger(layerId) || layerId <= 0) throw new Error(`保护图层必须是正整数：${target}`);
      return { kind, mapPath, layerId };
    }
    if (kind === "object") {
      const [layerId, objectId] = target.split("/").map(Number);
      if (![layerId, objectId].every((id) => Number.isSafeInteger(id) && id > 0)) throw new Error(`保护对象格式应为 object:图层ID/对象ID：${target}`);
      return { kind, mapPath, layerId, objectId };
    }
    throw new Error(`不支持的保护目标类型：${kind}`);
  });
}

async function inspectMapManagedPath() {
  if (!state.currentProject || !state.mapWorkspaceClient) {
    setMapManagedMessage("地图项目工作区尚未连接，请先刷新地图工作区", "error");
    return;
  }
  let mapPath;
  try { mapPath = normalizeManagedMapPath(elements.mapManagedMapPath.value); } catch (error) {
    state.mapManagedMapVersion = null;
    elements.mapManagedMapState.textContent = error.message;
    elements.mapManagedMapState.dataset.status = "error";
    renderMapManagedAccess();
    return;
  }
  state.mapManagedInspecting = true;
  state.mapManagedMapPath = mapPath;
  elements.mapManagedMapState.textContent = "正在读取地图版本…";
  elements.mapManagedMapState.dataset.status = "busy";
  renderMapManagedAccess();
  try {
    const source = await state.mapWorkspaceClient.readResourceVersion(mapPath, "map");
    if (!source.version || !/^[a-f0-9]{64}$/iu.test(source.version)) throw new Error("服务器未返回可用于授权的地图 SHA-256");
    state.mapManagedMapVersion = source.version.toLowerCase();
    elements.mapManagedMapState.textContent = `基础版本 ${state.mapManagedMapVersion.slice(0, 8)}…${state.mapManagedMapVersion.slice(-8)}；只读检查不会进入对话上下文`;
    elements.mapManagedMapState.dataset.status = "ready";
    await loadMapManagedAuthorizations({ silent: true });
  } catch (error) {
    state.mapManagedMapVersion = null;
    elements.mapManagedMapState.textContent = `读取失败：${error.message}`;
    elements.mapManagedMapState.dataset.status = "error";
  } finally {
    state.mapManagedInspecting = false;
    renderMapManagedAccess();
  }
}

async function loadMapManagedAuthorizations({ silent = false } = {}) {
  const context = mapManagedContextSnapshot();
  if (!context.accountId || !context.projectPath) return;
  if (state.mapManagedLoading) {
    if (sameMapManagedContext(state.mapManagedLoadingContext, context)) return;
    invalidateMapManagedAuthorizations();
  }
  const requestVersion = ++state.mapManagedRequestVersion;
  state.mapManagedRequestAccountId = context.accountId;
  state.mapManagedLoading = true;
  state.mapManagedLoadingContext = context;
  renderMapManagedAccess();
  try {
    const query = new URLSearchParams({ limit: "100" });
    const response = await fetch(`/api/map-ai/managed-authorizations?${query}`, { cache: "no-store" });
    const data = await readApiJson(response, "无法读取地图 AI 托管授权");
    if (requestVersion !== state.mapManagedRequestVersion || !mapManagedContextIsCurrent(context)) return;
    const fingerprint = await fingerprintForManagedProject(context.projectPath);
    if (!fingerprint) throw new Error("当前浏览器不支持工程指纹校验，暂不显示托管授权");
    if (requestVersion !== state.mapManagedRequestVersion || !mapManagedContextIsCurrent(context)) return;
    state.mapManagedAuthorizations = Array.isArray(data?.authorizations)
      ? data.authorizations.filter((authorization) => (
        (!fingerprint || authorization.projectFingerprint === fingerprint)
        && (authorization.projectWide === true || !state.mapManagedMapPath || authorization.mapPaths?.includes(state.mapManagedMapPath))
      ))
      : [];
    state.mapManagedLoadedContext = context;
    if (!silent) setMapManagedMessage(`已读取 ${state.mapManagedAuthorizations.length} 个托管授权`, "ready");
  } catch (error) {
    if (requestVersion !== state.mapManagedRequestVersion || !mapManagedContextIsCurrent(context)) return;
    state.mapManagedAuthorizations = [];
    state.mapManagedLoadedContext = null;
    if (!silent) setMapManagedMessage(`读取失败：${error.message}`, "error");
  } finally {
    if (requestVersion !== state.mapManagedRequestVersion) return;
    if (!mapManagedContextIsCurrent(context)) {
      invalidateMapManagedAuthorizations();
      return;
    }
    state.mapManagedLoading = false;
    state.mapManagedLoadingContext = null;
    renderMapManagedAccess();
  }
}

function managedMainAllowedOps() {
  const operations = ["inspect_project", "get_map_context", "read_map_region", "validate_map", "request_map_preview", "list_map_revisions"];
  if (elements.mapManagedAllowPropose.checked) operations.push("propose_tiled_patch");
  if (elements.mapManagedAllowApply.checked) operations.push("apply_tiled_patch", "restore_map_revision");
  return operations;
}

async function createMapManagedAuthorization() {
  if (state.mapManagedCreating) return;
  if (!state.mapAiToolsEnabled) { setMapManagedMessage("请先开启“允许 AI 使用游戏工具”账号开关", "error"); return; }
  if (!state.currentProject?.path) { setMapManagedMessage("请先选择一个工程", "error"); return; }
  if (!elements.mapManagedConfirm.checked) { setMapManagedMessage("请先确认当前工程协作范围", "error"); return; }
  state.mapManagedCreating = true;
  renderMapManagedAccess();
  setMapManagedMessage("正在创建托管授权…", "busy");
  try {
    const response = await fetch("/api/map-ai/managed-authorizations", {
      method: "POST", cache: "no-store",
      headers: { "Content-Type": "application/json", "X-Codex-Desktop-Action": "map-ai-managed-authorization-create" },
      // Legacy mapVersion: state.mapManagedMapVersion and userConfirmed: true
      // remain documented for stored map-scoped grants; the project-scoped
      // request below intentionally omits manual versions and budgets.
      body: JSON.stringify({
        project: state.currentProject.path,
        projectWide: true,
        scopeKind: "project",
        mode: elements.mapManagedMode?.value === "apply" ? "apply" : "suggest",
        confirmed: true,
        clientOperationId: crypto.randomUUID(),
      }),
    });
    const data = await readApiJson(response, "无法创建地图 AI 托管授权");
    elements.mapManagedConfirm.checked = false;
    await loadMapManagedAuthorizations({ silent: true });
    const mode = elements.mapManagedMode?.value === "apply" ? "apply" : "suggest";
    setMapManagedMessage(data.created
      ? (mode === "apply" ? "整个工程自动应用授权已创建；安全规则和版本校验仍然生效" : "整个工程建议授权已创建；AI 只提交可审阅方案")
      : "已有相同范围的托管授权", "ready");
  } catch (error) {
    setMapManagedMessage(`创建失败：${error.message}`, "error");
  } finally {
    state.mapManagedCreating = false;
    renderMapManagedAccess();
  }
}

async function revokeMapManagedAuthorization(authorization) {
  if (!authorization?.id || !state.account?.id) return;
  const message = `撤销${MAP_MANAGED_POLICY_LABELS[authorization.approvalPolicy] || "当前"}授权？撤销后不能创建新托管任务，已运行任务会停止后续批次。地图文件不会被删除或回滚。`;
  if (!window.confirm(message)) return;
  try {
    const response = await fetch(`/api/map-ai/managed-authorizations/${encodeURIComponent(authorization.id)}`, {
      method: "DELETE", cache: "no-store",
      headers: { "Content-Type": "application/json", "X-Codex-Desktop-Action": "map-ai-managed-authorization-revoke" },
      body: JSON.stringify({ reason: "用户在主界面地图工作区中撤销" }),
    });
    await readApiJson(response, "无法撤销地图 AI 托管授权");
    await loadMapManagedAuthorizations({ silent: true });
    setMapManagedMessage("托管授权已撤销", "ready");
  } catch (error) {
    setMapManagedMessage(`撤销失败：${error.message}`, "error");
  }
}

function mapManagedTransferCandidates() {
  const currentThreadId = managedProjectThread();
  return state.threads.filter((thread) => thread?.id && thread.cwd === state.currentProject?.path && thread.id !== currentThreadId);
}

function openMapManagedTransfer(authorization) {
  if (!authorization?.id || state.mapManagedCreating) return;
  const candidates = mapManagedTransferCandidates();
  if (!candidates.length) {
    setMapManagedMessage("当前工程没有可转交的其他 Codex 对话；请先刷新对话列表", "error");
    return;
  }
  state.pendingMapManagedTransfer = authorization;
  elements.mapManagedTransferTarget.replaceChildren(...candidates.map((thread) => {
    const option = document.createElement("option");
    option.value = thread.id;
    option.textContent = `${conversationDisplayTitle(thread)}${thread.status?.type === "active" ? " · 运行中" : ""}`;
    option.title = conversationDisplayText(thread.preview);
    return option;
  }));
  elements.mapManagedTransferDetail.textContent = `当前授权属于 Thread ${authorization.threadId?.slice(0, 12) || "--"}…。转交后旧 Thread 不能再创建或继续执行此授权的任务；地图文件和批准策略保持不变。目标 Thread 必须属于同一工程。`;
  elements.mapManagedTransferState.textContent = "转交会留下审计记录，并取消旧 Thread 尚未完成的托管任务。";
  elements.mapManagedTransferState.dataset.status = "ready";
  elements.confirmMapManagedTransferButton.disabled = false;
  if (!elements.mapManagedTransferDialog.open) elements.mapManagedTransferDialog.showModal();
}

function cancelMapManagedTransfer() {
  state.pendingMapManagedTransfer = null;
  elements.mapManagedTransferDialog.close();
}

async function confirmMapManagedTransfer() {
  const authorization = state.pendingMapManagedTransfer;
  const targetThreadId = elements.mapManagedTransferTarget.value;
  if (!authorization?.id || !targetThreadId) return;
  elements.confirmMapManagedTransferButton.disabled = true;
  elements.mapManagedTransferState.textContent = "正在转交；旧 Thread 任务会先停止…";
  elements.mapManagedTransferState.dataset.status = "busy";
  try {
    const response = await fetch(`/api/map-ai/managed-authorizations/${encodeURIComponent(authorization.id)}/transfer`, {
      method: "POST", cache: "no-store",
      headers: { "Content-Type": "application/json", "X-Codex-Desktop-Action": "map-ai-managed-authorization-transfer" },
      body: JSON.stringify({
        targetThreadId,
        expectedThreadId: authorization.threadId,
        reason: "用户在主界面地图工作区中显式转交托管授权",
      }),
    });
    await readApiJson(response, "无法转交地图 AI 托管授权");
    const targetThread = state.threads.find((thread) => (
      thread?.id === targetThreadId
      && thread.cwd === state.currentProject?.path
    ));
    const projectPath = state.currentProject?.path;
    elements.mapManagedTransferDialog.close();
    if (targetThread) await selectThread(targetThread);
    const switched = Boolean(
      targetThread
      && state.activeThread?.id === targetThreadId
      && state.currentProject?.path === projectPath
    );
    if (switched) await loadMapManagedAuthorizations({ silent: true });
    else {
      // The old Thread must never continue to display a grant that now
      // belongs to another Thread. The user can switch manually once a
      // blocked running turn or stale Thread list has settled.
      state.mapManagedAuthorizations = [];
      renderMapManagedAccess();
    }
    setMapManagedMessage(
      switched
        ? "托管授权已转交，并已切换到目标 Thread；旧 Thread 任务已停止，新 Thread 可在授权范围内继续"
        : targetThread
          ? "托管授权已转交；当前回合暂时无法切换，请稍后手动切换到目标 Thread。旧 Thread 任务已停止"
          : "托管授权已转交；请刷新对话列表后手动切换到目标 Thread。旧 Thread 任务已停止",
      "ready",
    );
  } catch (error) {
    elements.mapManagedTransferState.textContent = Number(error.status) === 409
      ? "转交冲突：授权已被其他操作更新，请刷新列表后重新确认"
      : `转交失败：${error.message}`;
    elements.mapManagedTransferState.dataset.status = "error";
    elements.confirmMapManagedTransferButton.disabled = false;
    if (Number(error.status) === 409) await loadMapManagedAuthorizations({ silent: true });
  } finally {
    if (!elements.mapManagedTransferDialog.open) state.pendingMapManagedTransfer = null;
  }
}

function renderMapManagedAccess() {
  if (!elements.mapManagedList) return;
  const context = mapManagedContextSnapshot();
  const threadId = managedProjectThread();
  const loadedForCurrentContext = sameMapManagedContext(state.mapManagedLoadedContext, context);
  const loadingForCurrentContext = state.mapManagedLoading
    && sameMapManagedContext(state.mapManagedLoadingContext, context);
  elements.mapManagedRefreshButton.disabled = loadingForCurrentContext || !context.projectPath;
  elements.mapManagedInspectButton.disabled = true;
  elements.mapManagedCreateButton.disabled = state.mapManagedCreating || !state.mapAiToolsEnabled || !context.projectPath;
  const visibleAuthorizations = !loadedForCurrentContext
    ? []
    : state.mapManagedMapPath
    ? state.mapManagedAuthorizations.filter((authorization) => authorization.mapPaths?.includes(state.mapManagedMapPath))
    : state.mapManagedAuthorizations;
  const fragment = document.createDocumentFragment();
  if (loadingForCurrentContext && !visibleAuthorizations.length) {
    const loading = document.createElement("p"); loading.textContent = "正在读取托管授权…"; fragment.append(loading);
  } else if (!visibleAuthorizations.length) {
    const empty = document.createElement("p"); empty.textContent = context.projectPath ? "当前工程还没有 AI 协作授权" : "请先选择一个工程"; fragment.append(empty);
  }
  for (const authorization of visibleAuthorizations) {
    const item = document.createElement("article"); item.className = "map-managed-item";
    const header = document.createElement("header");
    const title = document.createElement("strong"); title.textContent = MAP_MANAGED_POLICY_LABELS[authorization.approvalPolicy] || authorization.approvalPolicy || "未知策略";
    const status = document.createElement("small");
    const currentVersion = authorization.projectWide ? null : authorization.mapVersions?.[state.mapManagedMapPath];
    status.textContent = authorization.revokedAt ? "已撤销" : Number(authorization.expiresAt) <= Date.now() ? "已过期" : currentVersion && state.mapManagedMapVersion && currentVersion !== state.mapManagedMapVersion ? "地图版本已变化" : "有效";
    header.append(title, status);
    const detail = document.createElement("p"); detail.textContent = `${authorization.projectWide ? "整个工程（地图、World、瓦片集、角色和资源）" : authorization.mapPaths?.join("、") || "地图"} · ${authorization.projectWide ? (authorization.allowedOps?.includes("apply_tiled_resource_patch") ? "自动应用" : "建议模式") : Array.isArray(authorization.allowedOps) ? authorization.allowedOps.join("、") : "--"} · 到期 ${new Date(authorization.expiresAt).toLocaleString(interfaceLocale())}`;
    const actions = document.createElement("div"); actions.className = "map-managed-item-actions";
    const transfer = document.createElement("button"); transfer.type = "button"; transfer.className = "secondary-button"; transfer.textContent = "转交"; transfer.disabled = authorization.projectWide === true || Boolean(authorization.revokedAt) || Number(authorization.expiresAt) <= Date.now(); transfer.addEventListener("click", () => openMapManagedTransfer(authorization));
    const revoke = document.createElement("button"); revoke.type = "button"; revoke.className = "secondary-button is-danger"; revoke.textContent = "撤销"; revoke.disabled = Boolean(authorization.revokedAt) || Number(authorization.expiresAt) <= Date.now(); revoke.addEventListener("click", () => void revokeMapManagedAuthorization(authorization));
    actions.append(transfer, revoke); item.append(header, detail, actions); fragment.append(item);
  }
  elements.mapManagedList.replaceChildren(fragment);
}

function toggleMapGameWorkMode() {
  const enable = elements.mapGameWorkModeToggle.checked === true;
  const bindings = currentMapGameWorkModeBindings();
  const targets = enable ? bindings.slice(0, 1) : bindings;
  if (!targets.length || !state.gameWorkModeChannel) {
    state.mapGameWorkModeMessage = "请先从当前 Codex 对话打开一张地图";
    renderMapGameWorkModeSetting();
    return;
  }
  let sent = 0;
  for (const [, binding] of targets) {
    try {
      state.gameWorkModeChannel.postMessage(createGameWorkModeCommand({
        action: enable ? "enable" : "disable",
        hostWindowId: CLIENT_WINDOW_ID,
        editorInstanceId: binding.editorInstanceId,
        sessionId: binding.sessionId,
        threadId: binding.threadId,
        projectPath: binding.projectPath,
      }));
      sent += 1;
    } catch {
      // Another eligible editor may still accept the same explicit command.
    }
  }
  if (!sent) {
    state.mapGameWorkModeMessage = "无法连接地图窗口";
    renderMapGameWorkModeSetting();
    return;
  }
  state.mapGameWorkModePendingAction = enable ? "enable" : "disable";
  state.mapGameWorkModeMessage = enable ? "正在开启" : "正在关闭";
  clearTimeout(state.mapGameWorkModeCommandTimer);
  state.mapGameWorkModeCommandTimer = setTimeout(() => {
    state.mapGameWorkModeCommandTimer = null;
    state.mapGameWorkModePendingAction = null;
    state.mapGameWorkModeMessage = "地图窗口未响应";
    renderMapGameWorkModeSetting();
  }, 3_000);
  renderMapGameWorkModeSetting();
}

function currentMapGameWorkModeBindings() {
  const project = state.currentProject;
  const threadId = currentCodexMapThread(project);
  if (!project || !threadId) return [];
  return [...state.mapEditorGameBindings.entries()]
    .filter(([, binding]) => (
      binding.projectPath === project.path
      && binding.threadId === threadId
      && binding.sessionId
      && binding.editorWindow
      && !binding.editorWindow.closed
    ))
    .map(([editorInstanceId, binding]) => [editorInstanceId, { ...binding, editorInstanceId }])
    .sort((left, right) => (
      Number(right[1].focused === true) - Number(left[1].focused === true)
      || (right[1].lastActiveAt || 0) - (left[1].lastActiveAt || 0)
    ));
}

function activeMapGameWorkModeBindingCount() {
  const eligible = currentMapGameWorkModeBindings();
  if (!eligible.length) return 0;
  const keys = new Set(eligible.map(([, binding]) => `${binding.sessionId}\u001f${binding.editorInstanceId}`));
  let active = 0;
  for (const lease of state.gameWorkModeLeases.values()) {
    if (keys.has(`${lease.sessionId}\u001f${lease.editorInstanceId}`) && Number(lease.expiresAt) > Date.now()) active += 1;
  }
  return active;
}

function reconcileMapGameWorkModeCommand() {
  const pending = state.mapGameWorkModePendingAction;
  if (!pending) return;
  const enabled = activeMapGameWorkModeBindingCount() > 0;
  if ((pending === "enable" && !enabled) || (pending === "disable" && enabled)) return;
  clearTimeout(state.mapGameWorkModeCommandTimer);
  state.mapGameWorkModeCommandTimer = null;
  state.mapGameWorkModePendingAction = null;
  state.mapGameWorkModeMessage = enabled ? "已开启" : "已关闭";
}

function renderMapGameWorkModeSetting() {
  const bindings = currentMapGameWorkModeBindings();
  const activeCount = activeMapGameWorkModeBindingCount();
  const pending = state.mapGameWorkModePendingAction;
  const enabled = activeCount > 0;
  elements.mapGameWorkModeToggle.checked = pending ? pending === "enable" : enabled;
  elements.mapGameWorkModeToggle.disabled = !bindings.length || Boolean(pending) || !state.gameWorkModeChannel;
  elements.mapGameWorkModeState.textContent = !bindings.length
    ? "未连接"
    : pending
      ? pending === "enable" ? "开启中" : "关闭中"
      : state.mapGameWorkModeMessage || (enabled ? "已开启" : "已关闭");
  elements.mapGameWorkModeState.dataset.enabled = String(enabled);
  elements.mapGameWorkModeState.dataset.status = bindings.length && state.mapGameWorkModeMessage === "地图窗口未响应"
    ? "error"
    : "ready";
  const target = bindings[0]?.[1];
  elements.mapGameWorkModeDetail.textContent = target
    ? `当前对话 · ${target.relativePath}；普通对话仍可直接读取图片。`
    : "从当前 Codex 对话打开地图后可用；普通对话仍可直接读取图片。";
}

async function openBrowserPreview(entryPath = null) {
  if (!state.currentProject) return;
  if (elements.resourceDialog.open) {
    if (!confirmDiscardResourceChanges()) return;
    await exitResourceFullscreen();
    elements.resourceDialog.close();
    clearResourcePreview();
  }
  if (!elements.browserDialog.open) elements.browserDialog.showModal();
  setDataContent(elements.browserProjectName, state.currentProject.name);
  await loadBrowserPreviewEntries(entryPath);
}

function openMapEditorWindow() {
  return openMapEditorEntry(state.resourcePreviewEntry, { source: "resource" });
}

async function closeToolboxEditorSession({ endpoint, sessionId, action, editorInstanceId }) {
  if (!endpoint || !sessionId || !action || !editorInstanceId) return;
  await fetch(`${endpoint}/${encodeURIComponent(sessionId)}`, {
    method: "DELETE",
    cache: "no-store",
    keepalive: true,
    headers: {
      "X-Codex-Desktop-Action": action,
      "X-Codex-Desktop-Editor-Instance": editorInstanceId,
    },
  }).catch(() => {});
}

async function openTilesetEditorEntry(entry, { editorWindow: suppliedEditorWindow = null } = {}) {
  const project = state.currentProject;
  const workspaceEntry = entry?.kind === "tileset"
    && typeof entry.path === "string"
    && /\.tsj$/iu.test(entry.path);
  if (!project || !workspaceEntry || !state.mapWorkspaceClient) return;
  const key = `${project.path}\0${entry.path}`;
  const existing = state.tilesetEditorWindows.get(key);
  if (existing?.editorWindow && !existing.editorWindow.closed) {
    if (suppliedEditorWindow && !suppliedEditorWindow.closed) suppliedEditorWindow.close();
    existing.editorWindow.focus();
    closeMapWorkspace();
    return;
  }
  state.tilesetEditorWindows.delete(key);
  const editorWindow = suppliedEditorWindow || window.open("/tileset-editor.html#pending", "_blank");
  if (!editorWindow) {
    toast("浏览器阻止了瓦片集编辑器窗口", "error");
    return;
  }
  const editorInstanceId = typeof crypto.randomUUID === "function"
    ? crypto.randomUUID()
    : `tileset-editor-${Date.now()}-${Math.random().toString(16).slice(2)}`;
  const workspaceClient = state.mapWorkspaceClient;
  const workspaceSessionId = state.mapWorkspaceProjectSession?.id || null;
  const workspaceProjectFile = state.mapWorkspaceProjectSession?.projectFile || null;
  let openedSessionId = null;
  state.mapEditorOpeningPath = entry.path;
  renderMapWorkspaceMaps();
  try {
    const requestBody = workspaceClient.tilesetOpenPayload(entry.path, editorInstanceId);
    const response = await fetchWithTimeout("/api/map-tilesets/sessions", {
      method: "POST",
      headers: {
        "Content-Type": "application/json",
        "X-Codex-Desktop-Action": "map-tileset-session-open",
      },
      body: JSON.stringify(requestBody),
    }, 20_000);
    const data = await response.json().catch(() => ({}));
    if (!response.ok) throw new Error(data.error || "无法建立瓦片集会话");
    openedSessionId = data.session?.id || null;
    if (!openedSessionId) throw new Error("瓦片集会话响应无效");
    if (editorWindow.closed) {
      await closeToolboxEditorSession({
        endpoint: "/api/map-tilesets/sessions",
        sessionId: openedSessionId,
        action: "map-tileset-session-close",
        editorInstanceId,
      });
      openedSessionId = null;
      return;
    }
    if (
      state.currentProject?.path !== project.path
      || state.mapWorkspaceClient !== workspaceClient
      || state.mapWorkspaceProjectSession?.id !== workspaceSessionId
    ) {
      throw new Error("地图项目工作区在打开过程中发生变化，请重新打开");
    }
    state.tilesetEditorWindows.set(key, {
      editorWindow,
      editorInstanceId,
      sessionId: openedSessionId,
      projectPath: project.path,
      relativePath: entry.path,
    });
    const fragment = new URLSearchParams({
      session: openedSessionId,
      editor: editorInstanceId,
      project: project.path,
      ...(workspaceProjectFile ? { projectFile: workspaceProjectFile } : {}),
      ...(state.account?.id ? { account: state.account.id } : {}),
    });
    editorWindow.location.replace(`/tileset-editor.html#${fragment}`);
    openedSessionId = null;
    closeMapWorkspace();
    toast(`已打开 ${entry.path}`);
  } catch (error) {
    if (openedSessionId) {
      await closeToolboxEditorSession({
        endpoint: "/api/map-tilesets/sessions",
        sessionId: openedSessionId,
        action: "map-tileset-session-close",
        editorInstanceId,
      });
      openedSessionId = null;
    }
    state.tilesetEditorWindows.delete(key);
    if (!editorWindow.closed) editorWindow.close();
    toast(error.message, "error");
  } finally {
    state.mapEditorOpeningPath = null;
    renderMapWorkspaceMaps();
  }
}

async function openWorldEditorEntry(entry, { editorWindow: suppliedEditorWindow = null } = {}) {
  const project = state.currentProject;
  const workspaceEntry = entry?.kind === "world"
    && typeof entry.path === "string"
    && /\.world$/iu.test(entry.path);
  if (!project || !workspaceEntry || !state.mapWorkspaceClient) return;
  const key = `${project.path}\0${entry.path}`;
  const existing = state.worldEditorWindows.get(key);
  if (existing?.editorWindow && !existing.editorWindow.closed) {
    if (suppliedEditorWindow && !suppliedEditorWindow.closed) suppliedEditorWindow.close();
    existing.editorWindow.focus();
    closeMapWorkspace();
    return;
  }
  state.worldEditorWindows.delete(key);
  const editorWindow = suppliedEditorWindow || window.open("/world-editor.html#pending", "_blank");
  if (!editorWindow) {
    toast("浏览器阻止了 World 编辑器窗口", "error");
    return;
  }
  const editorInstanceId = typeof crypto.randomUUID === "function"
    ? crypto.randomUUID()
    : `world-editor-${Date.now()}-${Math.random().toString(16).slice(2)}`;
  const workspaceClient = state.mapWorkspaceClient;
  const workspaceSessionId = state.mapWorkspaceProjectSession?.id || null;
  const workspaceProjectFile = state.mapWorkspaceProjectSession?.projectFile || null;
  let openedSessionId = null;
  state.mapEditorOpeningPath = entry.path;
  renderMapWorkspaceMaps();
  try {
    const requestBody = workspaceClient.worldOpenPayload(entry.path, editorInstanceId);
    const response = await fetchWithTimeout("/api/map-worlds/sessions", {
      method: "POST",
      headers: {
        "Content-Type": "application/json",
        "X-Codex-Desktop-Action": "map-world-session-open",
      },
      body: JSON.stringify(requestBody),
    }, 20_000);
    const data = await response.json().catch(() => ({}));
    if (!response.ok) throw new Error(data.error || "无法建立 World 会话");
    openedSessionId = data.session?.id || null;
    if (!openedSessionId) throw new Error("World 会话响应无效");
    if (editorWindow.closed) {
      await closeToolboxEditorSession({
        endpoint: "/api/map-worlds/sessions",
        sessionId: openedSessionId,
        action: "map-world-session-close",
        editorInstanceId,
      });
      openedSessionId = null;
      return;
    }
    if (
      state.currentProject?.path !== project.path
      || state.mapWorkspaceClient !== workspaceClient
      || state.mapWorkspaceProjectSession?.id !== workspaceSessionId
    ) {
      throw new Error("地图项目工作区在打开过程中发生变化，请重新打开");
    }
    state.worldEditorWindows.set(key, {
      editorWindow,
      editorInstanceId,
      sessionId: openedSessionId,
      projectPath: project.path,
      relativePath: entry.path,
    });
    const fragment = new URLSearchParams({
      session: openedSessionId,
      editor: editorInstanceId,
      project: project.path,
      ...(workspaceProjectFile ? { projectFile: workspaceProjectFile } : {}),
      ...(state.account?.id ? { account: state.account.id } : {}),
    });
    editorWindow.location.replace(`/world-editor.html#${fragment}`);
    openedSessionId = null;
    closeMapWorkspace();
    toast(`已打开 ${entry.path}`);
  } catch (error) {
    if (openedSessionId) {
      await closeToolboxEditorSession({
        endpoint: "/api/map-worlds/sessions",
        sessionId: openedSessionId,
        action: "map-world-session-close",
        editorInstanceId,
      });
      openedSessionId = null;
    }
    state.worldEditorWindows.delete(key);
    if (!editorWindow.closed) editorWindow.close();
    toast(error.message, "error");
  } finally {
    state.mapEditorOpeningPath = null;
    renderMapWorkspaceMaps();
  }
}

async function openMapEditorEntry(entry, {
  source = "resource",
  editorWindow: suppliedEditorWindow = null,
  replacingEditorInstanceId = null,
  projectSessionId = null,
  projectFile = null,
} = {}) {
  const project = state.currentProject;
  const workspaceEntry = ["workspace", "editor"].includes(source)
    && entry?.kind === "map"
    && typeof entry.path === "string"
    && /\.tmj$/iu.test(entry.path);
  const resourceEntry = !["workspace", "editor"].includes(source)
    && entry?.type === "file"
    && typeof entry.path === "string"
    && typeof entry.relativePath === "string"
    && /\.tmj$/iu.test(entry.relativePath);
  if (!project || (!workspaceEntry && !resourceEntry)) return;
  const relativePath = workspaceEntry ? entry.path : entry.relativePath;
  const existing = [...state.mapEditorGameBindings.entries()].find(([, binding]) => (
    binding.projectPath === project.path
    && binding.relativePath === relativePath
    && binding.editorWindow
    && !binding.editorWindow.closed
  ));
  if (existing) {
    // A file switch is requested by the current editor window. Never close
    // that window when the target is already open elsewhere; focus the
    // existing editor and leave the unsaved source map available to the user.
    if (suppliedEditorWindow && !suppliedEditorWindow.closed && !replacingEditorInstanceId) {
      suppliedEditorWindow.close();
    }
    existing[1].editorWindow.focus();
    existing[1].lastActiveAt = Date.now();
    broadcastMapEditorTabSnapshot();
    if (source === "workspace") closeMapWorkspace();
    return;
  }
  const editorWindow = suppliedEditorWindow || window.open("/map-editor.html#pending", "_blank");
  if (!editorWindow) {
    toast("浏览器阻止了地图编辑器窗口", "error");
    return;
  }
  const editorInstanceId = typeof crypto.randomUUID === "function"
    ? crypto.randomUUID()
    : `map-editor-${Date.now()}-${Math.random().toString(16).slice(2)}`;
  const workspaceClient = source === "workspace" ? state.mapWorkspaceClient : null;
  const workspaceSessionId = source === "workspace" ? state.mapWorkspaceProjectSession?.id || null : null;
  const workspaceProjectFile = source === "workspace" ? state.mapWorkspaceProjectSession?.projectFile || null : null;
  let openedSessionId = null;
  state.mapEditorOpeningPath = relativePath;
  elements.resourceMapEditorButton.disabled = true;
  renderMapWorkspaceMaps();
  try {
    if (!state.mapAiToolsLoaded) await loadMapAiToolsSetting({ silent: true });
    const requestBody = source === "workspace"
      ? workspaceClient?.mapOpenPayload(relativePath, editorInstanceId)
      : projectSessionId
        ? { projectSessionId, project: project.path, path: relativePath, editorInstanceId }
        : { project: project.path, path: entry.path, editorInstanceId };
    if (!requestBody) throw new Error("地图项目工作区连接已经关闭");
    const response = await fetchWithTimeout("/api/maps/sessions", {
      method: "POST",
      headers: {
        "Content-Type": "application/json",
        "X-Codex-Desktop-Action": "map-session-open",
      },
      body: JSON.stringify(requestBody),
    }, 20_000);
    const data = await response.json();
    if (!response.ok) throw new Error(data.error || "无法建立地图会话");
    openedSessionId = data.session?.id || null;
    if (!openedSessionId) throw new Error("地图会话响应无效");
    if (editorWindow.closed) {
      await closeToolboxEditorSession({
        endpoint: "/api/maps/sessions",
        sessionId: openedSessionId,
        action: "map-session-close",
        editorInstanceId,
      });
      openedSessionId = null;
      return;
    }
    if (
      state.currentProject?.path !== project.path
      || (source === "workspace" && (
        state.mapWorkspaceClient !== workspaceClient
        || state.mapWorkspaceProjectSession?.id !== workspaceSessionId
      ))
    ) {
      throw new Error("地图项目工作区在打开过程中发生变化，请重新打开");
    }
    const threadId = currentCodexMapThread(project);
    for (const binding of state.mapEditorGameBindings.values()) {
      if (binding.projectPath === project.path) binding.focused = false;
    }
    if (replacingEditorInstanceId) state.mapEditorGameBindings.delete(replacingEditorInstanceId);
    state.mapEditorGameBindings.delete(editorInstanceId);
    const editorProjectFile = data.session.projectFile
      || projectFile
      || workspaceProjectFile;
    state.mapEditorGameBindings.set(editorInstanceId, {
      editorInstanceId,
      sessionId: openedSessionId,
      threadId,
      projectPath: project.path,
      projectFile: editorProjectFile,
      relativePath,
      editorWindow,
      dirty: false,
      focused: true,
      lastActiveAt: Date.now(),
    });
    rememberMapEditorTab(project.path, relativePath);
    broadcastMapEditorTabSnapshot();
    while (state.mapEditorGameBindings.size > 128) {
      state.mapEditorGameBindings.delete(state.mapEditorGameBindings.keys().next().value);
    }
    const fragment = new URLSearchParams({
      session: openedSessionId,
      editor: editorInstanceId,
      host: CLIENT_WINDOW_ID,
      project: project.path,
      ...(requestBody.projectSessionId
        ? { projectSession: requestBody.projectSessionId }
        : {}),
      ...(editorProjectFile
        ? { projectFile: editorProjectFile }
        : {}),
      ...(state.account?.id ? { account: state.account.id } : {}),
      ...(threadId ? { thread: threadId } : {}),
      ...(threadId && state.mapAiToolsEnabled ? { connect: "1" } : {}),
    });
    editorWindow.location.replace(`/map-editor.html#${fragment}`);
    openedSessionId = null;
    if (source === "workspace") closeMapWorkspace();
    toast(`已打开 ${relativePath}`);
  } catch (error) {
    if (openedSessionId) {
      await closeToolboxEditorSession({
        endpoint: "/api/maps/sessions",
        sessionId: openedSessionId,
        action: "map-session-close",
        editorInstanceId,
      });
      openedSessionId = null;
    }
    if (!replacingEditorInstanceId) state.mapEditorGameBindings.delete(editorInstanceId);
    if (!editorWindow.closed && !replacingEditorInstanceId) editorWindow.close();
    toast(error.message, "error");
  } finally {
    state.mapEditorOpeningPath = null;
    elements.resourceMapEditorButton.disabled = false;
    renderMapWorkspaceMaps();
  }
}

function currentCodexMapThread(project = state.currentProject) {
  if (state.runtime !== "codex" || !project || !state.activeThread?.id) return null;
  const threadProject = conversationProjectForThread(
    state.activeThread.id,
    state.activeThread.cwd || project.path,
  );
  return threadProject === project.path ? state.activeThread.id : null;
}

async function loadBrowserPreviewEntries(preferredEntry = null) {
  if (!state.currentProject) return;
  const projectPath = state.currentProject.path;
  const loadId = ++state.browserLoadId;
  state.browserLoading = true;
  state.browserEntries = [];
  state.browserEntry = null;
  state.browserUrl = null;
  elements.browserFrame.src = "about:blank";
  elements.browserEntryInput.disabled = true;
  elements.browserEntryOpenButton.disabled = true;
  elements.browserRefreshButton.disabled = true;
  elements.browserOpenButton.disabled = true;
  elements.browserCopyButton.disabled = true;
  elements.browserFullscreenButton.disabled = true;
  elements.browserEntryDetails.open = false;
  elements.browserEntryInput.value = "";
  elements.browserEntryInput.placeholder = "正在查找 HTML 入口";
  elements.browserEntryOptions.replaceChildren();
  updateBrowserEntryDetails(0);
  setBrowserEmptyState("正在查找网页入口", "自动打开最近生成的 HTML");
  try {
    const url = new URL("/api/preview/entries", location.origin);
    url.searchParams.set("project", projectPath);
    const response = await fetch(url, { cache: "no-store" });
    const data = await response.json();
    if (!response.ok) throw new Error(data.error || "无法查找 HTML 入口");
    if (state.browserLoadId !== loadId || state.currentProject?.path !== projectPath || !elements.browserDialog.open) return;
    state.browserEntries = data.entries || [];
    elements.browserEntryOptions.replaceChildren();
    for (const entry of state.browserEntries) {
      const option = dataOption(entry.path, entry.path);
      elements.browserEntryOptions.append(option);
    }
    elements.browserEntryInput.disabled = false;
    elements.browserEntryOpenButton.disabled = false;
    elements.browserEntryInput.placeholder = "输入 HTML 相对路径";
    updateBrowserEntryDetails(state.browserEntries.length);
    if (!state.browserEntries.length) {
      if (preferredEntry) {
        elements.browserEntryInput.value = preferredEntry;
        await startBrowserPreview(preferredEntry);
        return;
      }
      elements.browserEntryDetails.open = true;
      setBrowserEmptyState("没有自动发现网页", "请在“入口设置”中输入工程内的 HTML 路径");
      return;
    }
    const selected = preferredEntry || automaticBrowserEntry(state.browserEntries);
    elements.browserEntryInput.value = selected;
    await startBrowserPreview(selected);
  } catch (error) {
    if (state.browserLoadId === loadId && state.currentProject?.path === projectPath) {
      setBrowserEmptyState("无法打开浏览器预览", error.message);
      toast(error.message, "error");
    }
  } finally {
    if (state.browserLoadId === loadId) state.browserLoading = false;
  }
}

function automaticBrowserEntry(entries) {
  return [...entries].sort((left, right) => {
    const modified = (Number(right.modifiedAt) || 0) - (Number(left.modifiedAt) || 0);
    return modified || String(left.path || "").localeCompare(String(right.path || ""), "zh-CN", { numeric: true });
  })[0]?.path || null;
}

function updateBrowserEntryDetails(count) {
  const label = elements.browserEntryDetails.querySelector("summary span");
  if (!label) return;
  label.textContent = count > 1 ? `更换入口（${count}）` : "入口设置";
}

function openSpecifiedBrowserEntry(event) {
  event.preventDefault();
  const entryPath = normalizeBrowserEntryPath(elements.browserEntryInput.value);
  if (!entryPath) {
    toast("请输入当前工程内的 HTML 相对路径", "error");
    elements.browserEntryInput.focus();
    return;
  }
  elements.browserEntryInput.value = entryPath;
  startBrowserPreview(entryPath);
}

function normalizeBrowserEntryPath(value) {
  if (typeof value !== "string" || !value.trim() || value.length > 1024) return null;
  const normalized = value.trim().replaceAll("\\", "/").replace(/^\.\/+/, "");
  const parts = normalized.split("/");
  if (
    normalized.startsWith("/")
    || /^[A-Za-z]:\//.test(normalized)
    || parts.some((part) => !part || part === "." || part === "..")
    || !/\.html?$/i.test(normalized)
  ) return null;
  return parts.join("/");
}

async function startBrowserPreview(entryPath) {
  entryPath = normalizeBrowserEntryPath(entryPath);
  if (!state.currentProject || !entryPath) return;
  const projectPath = state.currentProject.path;
  state.browserEntry = entryPath;
  state.browserUrl = null;
  elements.browserEntryInput.value = entryPath;
  elements.browserRefreshButton.disabled = true;
  elements.browserOpenButton.disabled = true;
  elements.browserFullscreenButton.disabled = true;
  setBrowserEmptyState("正在启动预览", entryPath);
  try {
    const response = await fetch("/api/preview/session", {
      method: "POST",
      headers: {
        "Content-Type": "application/json",
        "X-Codex-Desktop-Action": "project-preview",
      },
      body: JSON.stringify({ project: projectPath, entry: entryPath }),
    });
    const data = await response.json();
    if (!response.ok) throw new Error(data.error || "无法启动预览");
    if (
      state.currentProject?.path !== projectPath
      || state.browserEntry !== entryPath
      || !elements.browserDialog.open
    ) return;
    state.browserUrl = data.url;
    setDataContent(elements.browserAddress, `${state.currentProject.name}/${data.entry}`);
    elements.browserAddress.title = elements.browserAddress.textContent;
    elements.browserFrame.src = data.url;
    elements.browserEmptyState.hidden = true;
    elements.browserRefreshButton.disabled = false;
    elements.browserOpenButton.disabled = false;
    elements.browserCopyButton.disabled = false;
    elements.browserFullscreenButton.disabled = false;
  } catch (error) {
    if (state.currentProject?.path === projectPath && state.browserEntry === entryPath) {
      elements.browserEntryDetails.open = true;
      setBrowserEmptyState("预览启动失败", error.message);
      toast(error.message, "error");
    }
  }
}

function setBrowserEmptyState(title, detail) {
  elements.browserEmptyState.querySelector("strong").textContent = title;
  elements.browserEmptyState.querySelector("span").textContent = detail;
  elements.browserEmptyState.hidden = false;
  setDataContent(elements.browserAddress, state.browserEntry || "尚未加载", Boolean(state.browserEntry));
}

function refreshBrowserPreview() {
  if (!state.browserUrl) return;
  const url = new URL(state.browserUrl, location.origin);
  url.searchParams.set("refresh", Date.now());
  elements.browserFrame.src = url.href;
  elements.browserRefreshButton.classList.add("refreshing");
  setTimeout(() => elements.browserRefreshButton.classList.remove("refreshing"), 500);
}

function openBrowserPreviewWindow() {
  if (!state.browserUrl) return;
  window.open(state.browserUrl, "_blank", "noopener,noreferrer");
}

function copyBrowserPreviewLink() {
  if (!state.browserUrl) return;
  const url = new URL(state.browserUrl, location.origin).href;
  void copyTextToClipboard(url, "临时预览链接已复制", "无法复制预览链接");
}

function copyBrowserPreviewPrompt() {
  void copyTextToClipboard(
    PROJECT_PREVIEW_COPY_PROMPT,
    "项目预览提示词已复制",
    "无法复制项目预览提示词",
  );
}

async function toggleBrowserFullscreen() {
  try {
    if (document.fullscreenElement === elements.browserStage) await document.exitFullscreen();
    else await elements.browserStage.requestFullscreen();
  } catch {
    toast("当前浏览器不允许全屏预览", "error");
  }
}

function stopBrowserPreview() {
  if (document.fullscreenElement === elements.browserStage) document.exitFullscreen().catch(() => {});
  elements.browserFrame.src = "about:blank";
  state.browserEntries = [];
  state.browserEntry = null;
  state.browserUrl = null;
  state.browserLoading = false;
  state.browserLoadId += 1;
  elements.browserEntryInput.value = "";
  elements.browserEntryInput.disabled = true;
  elements.browserEntryOpenButton.disabled = true;
  elements.browserCopyButton.disabled = true;
  elements.browserEntryDetails.open = false;
  elements.browserEntryOptions.replaceChildren();
}

function renderResourceDisplayControls() {
  const fullscreen = document.fullscreenElement === elements.resourceShell;
  elements.resourceLargeButton.disabled = fullscreen;
  elements.resourceLargeButton.setAttribute("aria-pressed", String(state.resourceLargeMode));
  elements.resourceLargeButton.title = state.resourceLargeMode ? "恢复默认大小" : "大屏显示";
  elements.resourceLargeButton.setAttribute("aria-label", elements.resourceLargeButton.title);
  elements.resourceLargeButton.innerHTML = `<i data-lucide="${state.resourceLargeMode ? "shrink" : "expand"}"></i>`;
  elements.resourceFullscreenButton.setAttribute("aria-pressed", String(fullscreen));
  elements.resourceFullscreenButton.title = fullscreen ? "退出全屏" : "全屏显示";
  elements.resourceFullscreenButton.setAttribute("aria-label", elements.resourceFullscreenButton.title);
  elements.resourceFullscreenButton.innerHTML = `<i data-lucide="${fullscreen ? "minimize-2" : "maximize-2"}"></i>`;
  refreshIcons();
}

function setResourceLargeMode(enabled, { persist = true } = {}) {
  state.resourceLargeMode = enabled === true;
  elements.resourceDialog.dataset.large = String(state.resourceLargeMode);
  if (persist) {
    localStorage.setItem("codexDesktop.resourceLargeMode", String(state.resourceLargeMode));
  }
  renderResourceDisplayControls();
  if (elements.resourceDialog.open) requestAnimationFrame(normalizeResourceSplitSizes);
}

function toggleResourceLargeMode() {
  if (document.fullscreenElement === elements.resourceShell) return;
  setResourceLargeMode(!state.resourceLargeMode);
}

async function exitResourceFullscreen() {
  if (document.fullscreenElement !== elements.resourceShell) return;
  try {
    await document.exitFullscreen();
  } catch {
    // Closing the dialog also causes browsers to release its fullscreen element.
  }
}

async function toggleResourceFullscreen() {
  try {
    if (document.fullscreenElement === elements.resourceShell) {
      await document.exitFullscreen();
    } else {
      await elements.resourceShell.requestFullscreen();
    }
  } catch {
    toast("当前浏览器不允许文件管理器全屏显示", "error");
  } finally {
    renderResourceDisplayControls();
    requestAnimationFrame(normalizeResourceSplitSizes);
  }
}

function openResourceExplorer() {
  if (!state.currentProject) return;
  closeMobilePanels();
  state.resourceTreeDirectories.clear();
  state.resourceTreeExpanded.clear();
  state.resourceTreeLoading.clear();
  state.resourceSelectedPaths.clear();
  state.resourceGitFiles.clear();
  elements.resourceSearch.value = "";
  elements.resourceSortInput.value = ["name", "modified", "size"].includes(state.resourceSort)
    ? state.resourceSort
    : "name";
  renderResourceSortControls();
  renderResourceSelectionState();
  elements.resourceCurrentDirectory.textContent = state.currentProject.name || "工程";
  elements.resourceCurrentDirectory.title = state.currentProject.path;
  setResourceLargeMode(state.resourceLargeMode, { persist: false });
  elements.resourceDialog.showModal();
  requestAnimationFrame(normalizeResourceSplitSizes);
  loadResourceDirectory(state.currentProject.path);
}

function resourceSplitBounds(config) {
  const rect = config.container().getBoundingClientRect();
  const size = config.axis === "x" ? rect.width : rect.height;
  if (size <= 0) return { min: 20, max: 80 };
  const min = Math.min(80, (config.leadingMin / size) * 100);
  const max = Math.max(min, Math.min(80, ((size - config.trailingMin - 10) / size) * 100));
  return { min, max };
}

function setResourceSplitSize(kind, value, { persist = false } = {}) {
  const config = RESOURCE_SPLIT_CONFIG[kind];
  const bounds = resourceSplitBounds(config);
  const fallback = Number.isFinite(value) ? value : config.fallback;
  const percent = Math.max(bounds.min, Math.min(bounds.max, fallback));
  config.container().style.setProperty(config.property, `${percent.toFixed(2)}%`);
  config.element().setAttribute("aria-valuenow", String(Math.round(percent)));
  if (persist) localStorage.setItem(config.storageKey, percent.toFixed(2));
  return percent;
}

function normalizeResourceSplitSizes() {
  for (const [kind, config] of Object.entries(RESOURCE_SPLIT_CONFIG)) {
    const current = Number(config.element().getAttribute("aria-valuenow"));
    setResourceSplitSize(kind, current);
  }
}

function setupResourceResizeControls() {
  setResourceLargeMode(state.resourceLargeMode, { persist: false });
  for (const [kind, config] of Object.entries(RESOURCE_SPLIT_CONFIG)) {
    const splitter = config.element();
    const stored = Number(localStorage.getItem(config.storageKey));
    setResourceSplitSize(kind, Number.isFinite(stored) && stored > 0 ? stored : config.fallback);
    let activePointerId = null;
    const updateFromPointer = (event) => {
      if (event.pointerId !== activePointerId) return;
      const rect = config.container().getBoundingClientRect();
      const size = config.axis === "x" ? rect.width : rect.height;
      if (size <= 0) return;
      const offset = config.axis === "x" ? event.clientX - rect.left : event.clientY - rect.top;
      setResourceSplitSize(kind, (offset / size) * 100);
    };
    const finishPointer = (event) => {
      if (event.pointerId !== activePointerId) return;
      if (event.type === "pointerup") updateFromPointer(event);
      activePointerId = null;
      splitter.dataset.dragging = "false";
      const value = Number(splitter.getAttribute("aria-valuenow"));
      setResourceSplitSize(kind, value, { persist: true });
      if (splitter.hasPointerCapture?.(event.pointerId)) splitter.releasePointerCapture(event.pointerId);
    };
    splitter.addEventListener("pointerdown", (event) => {
      if (!event.isPrimary || (event.pointerType === "mouse" && event.button !== 0)) return;
      event.preventDefault();
      activePointerId = event.pointerId;
      splitter.dataset.dragging = "true";
      splitter.setPointerCapture?.(event.pointerId);
      updateFromPointer(event);
    });
    splitter.addEventListener("pointermove", updateFromPointer);
    splitter.addEventListener("pointerup", finishPointer);
    splitter.addEventListener("pointercancel", finishPointer);
    splitter.addEventListener("keydown", (event) => {
      const decrement = config.axis === "x" ? event.key === "ArrowLeft" : event.key === "ArrowUp";
      const increment = config.axis === "x" ? event.key === "ArrowRight" : event.key === "ArrowDown";
      if (!decrement && !increment) return;
      event.preventDefault();
      const current = Number(splitter.getAttribute("aria-valuenow")) || config.fallback;
      setResourceSplitSize(kind, current + (increment ? 2 : -2), { persist: true });
    });
  }
}

async function loadResourceDirectory(directoryPath) {
  if (!state.currentProject) return;
  elements.resourceList.innerHTML = '<div class="list-loading">正在读取目录</div>';
  elements.resourceNewFolderButton.disabled = true;
  elements.resourceNewFileButton.disabled = true;
  elements.resourceUploadButton.disabled = true;
  elements.resourceDownloadDirectoryButton.disabled = true;
  try {
    const url = new URL("/api/files/list", location.origin);
    url.searchParams.set("project", state.currentProject.path);
    if (directoryPath) url.searchParams.set("path", directoryPath);
    const response = await fetch(url, { cache: "no-store" });
    const data = await response.json();
    if (!response.ok) throw new Error(data.error || "无法读取目录");
    state.resourceDirectory = data.directoryPath;
    state.resourceParentPath = data.parentPath;
    state.resourceEntries = data.entries || [];
    state.resourceWritable = data.writable === true;
    state.resourceExternalChanged = false;
    elements.resourceExternalNotice.hidden = true;
    renderResourceBreadcrumbs(data.directoryPath);
    elements.resourceUpButton.disabled = !data.parentPath;
    elements.resourceNewFolderButton.disabled = !state.resourceWritable;
    elements.resourceNewFileButton.disabled = !state.resourceWritable;
    elements.resourceUploadButton.disabled = !state.resourceWritable || state.resourceUploadBusy;
    elements.resourceDownloadDirectoryButton.disabled = false;
    elements.resourceSearch.value = "";
    state.resourceTreeDirectories.set(
      data.directoryPath,
      state.resourceEntries.filter((entry) => entry.type === "directory"),
    );
    expandResourceTreeAncestors(data.directoryPath);
    clearResourcePreview();
    renderResourceTree();
    renderResourceSortControls();
    renderResourceEntries(state.resourceEntries);
    void startResourceWatcher(data.directoryPath);
    void loadResourceGitStatus();
    return data;
  } catch (error) {
    state.resourceWritable = false;
    elements.resourceDownloadDirectoryButton.disabled = true;
    elements.resourceList.innerHTML = '<div class="list-empty">无法读取目录</div>';
    toast(error.message, "error");
    return null;
  }
}

function expandResourceTreeAncestors(directoryPath) {
  const root = String(state.currentProject?.path || "").replace(/\/+$/, "");
  const target = String(directoryPath || "");
  if (!root || (target !== root && !target.startsWith(`${root}/`))) return;
  state.resourceTreeExpanded.add(root);
  const relative = target === root ? "" : target.slice(root.length + 1);
  let current = root;
  for (const segment of relative.split("/").filter(Boolean)) {
    current = `${current}/${segment}`;
    state.resourceTreeExpanded.add(current);
  }
}

async function loadResourceTreeChildren(directoryPath) {
  if (
    !state.currentProject
    || state.resourceTreeDirectories.has(directoryPath)
    || state.resourceTreeLoading.has(directoryPath)
  ) return;
  state.resourceTreeLoading.add(directoryPath);
  renderResourceTree();
  try {
    const url = new URL("/api/files/list", location.origin);
    url.searchParams.set("project", state.currentProject.path);
    url.searchParams.set("path", directoryPath);
    const response = await fetch(url, { cache: "no-store" });
    const data = await response.json();
    if (!response.ok) throw new Error(data.error || "无法读取目录树");
    state.resourceTreeDirectories.set(
      directoryPath,
      (data.entries || []).filter((entry) => entry.type === "directory"),
    );
  } catch (error) {
    toast(error.message, "error");
  } finally {
    state.resourceTreeLoading.delete(directoryPath);
    renderResourceTree();
  }
}

function renderResourceTree() {
  const root = String(state.currentProject?.path || "").replace(/\/+$/, "");
  elements.resourceTree.replaceChildren();
  if (!root) return;
  let rendered = 0;
  const appendDirectory = (directoryPath, label, depth) => {
    if (rendered >= 500) return;
    rendered += 1;
    const row = document.createElement("div");
    row.className = "resource-tree-row";
    row.style.setProperty("--resource-tree-depth", String(depth));
    row.dataset.active = String(directoryPath === state.resourceDirectory);
    const expanded = state.resourceTreeExpanded.has(directoryPath);
    const loading = state.resourceTreeLoading.has(directoryPath);
    const children = state.resourceTreeDirectories.get(directoryPath);
    const toggle = document.createElement("button");
    toggle.type = "button";
    toggle.className = "resource-tree-toggle";
    toggle.title = expanded ? "收起文件夹" : "展开文件夹";
    toggle.setAttribute("aria-label", toggle.title);
    toggle.innerHTML = `<i data-lucide="${loading ? "loader-circle" : expanded ? "chevron-down" : "chevron-right"}"></i>`;
    if (loading) toggle.querySelector("i")?.classList.add("spin");
    toggle.addEventListener("click", () => {
      if (expanded) {
        state.resourceTreeExpanded.delete(directoryPath);
        renderResourceTree();
        return;
      }
      state.resourceTreeExpanded.add(directoryPath);
      renderResourceTree();
      void loadResourceTreeChildren(directoryPath);
    });
    const open = document.createElement("button");
    open.type = "button";
    open.className = "resource-tree-open";
    open.innerHTML = '<i data-lucide="folder"></i><span></span>';
    setDataContent(open.querySelector("span"), label);
    open.title = directoryPath;
    open.addEventListener("click", () => {
      if (confirmDiscardResourceChanges()) void loadResourceDirectory(directoryPath);
    });
    row.append(toggle, open);
    elements.resourceTree.append(row);
    if (expanded && Array.isArray(children)) {
      for (const child of children) appendDirectory(child.path, child.name, depth + 1);
    }
  };
  appendDirectory(root, state.currentProject?.name || "工程", 0);
  refreshIcons();
}

function renderResourceSortControls() {
  elements.resourceSortInput.value = ["name", "modified", "size"].includes(state.resourceSort)
    ? state.resourceSort
    : "name";
  const descending = state.resourceSortDirection === "desc";
  elements.resourceSortDirectionButton.innerHTML = `<i data-lucide="${descending ? "arrow-down-wide-narrow" : "arrow-up-narrow-wide"}"></i>`;
  elements.resourceSortDirectionButton.title = descending ? "当前降序，点击切换升序" : "当前升序，点击切换降序";
  elements.resourceSortDirectionButton.setAttribute("aria-label", elements.resourceSortDirectionButton.title);
  refreshIcons();
}

function sortedResourceEntries(entries) {
  const direction = state.resourceSortDirection === "desc" ? -1 : 1;
  const value = (entry) => state.resourceSort === "modified"
    ? Number(entry.modifiedAt) || 0
    : state.resourceSort === "size" ? Number(entry.size) || 0 : String(entry.name || "");
  return [...entries].sort((left, right) => {
    if (left.type === "directory" && right.type !== "directory") return -1;
    if (left.type !== "directory" && right.type === "directory") return 1;
    const leftValue = value(left);
    const rightValue = value(right);
    const comparison = typeof leftValue === "number"
      ? leftValue - rightValue
      : leftValue.localeCompare(rightValue, "zh-CN", { numeric: true });
    return comparison * direction;
  });
}

function renderResourceSelectionState() {
  const count = state.resourceSelectedPaths.size;
  elements.resourceSelectionState.textContent = count ? `已选 ${count}` : "未选择";
  elements.resourceDownloadSelectedButton.disabled = count === 0;
  elements.resourceDownloadSelectedButton.title = count ? `打包下载所选 ${count} 项` : "请先选择文件或文件夹";
}

async function loadResourceGitStatus() {
  const projectPath = state.currentProject?.path;
  if (!projectPath || state.resourceGitLoading) return;
  state.resourceGitLoading = true;
  try {
    const url = new URL("/api/git/status", location.origin);
    url.searchParams.set("project", projectPath);
    const response = await fetch(url, { cache: "no-store" });
    const data = await response.json();
    if (!response.ok) throw new Error(data.error || "Git 状态不可用");
    if (state.currentProject?.path !== projectPath) return;
    state.resourceGitFiles = new Map((data.files || []).map((file) => [file.path, file]));
    renderResourceEntries(state.resourceEntries);
  } catch {
    if (state.currentProject?.path === projectPath) state.resourceGitFiles.clear();
  } finally {
    state.resourceGitLoading = false;
  }
}

function resourceGitLabel(entry) {
  const relativePath = String(entry.relativePath || "").replaceAll("\\", "/");
  const changed = entry.type === "directory"
    ? [...state.resourceGitFiles.values()].filter((file) => file.path.startsWith(`${relativePath}/`))
    : [state.resourceGitFiles.get(relativePath)].filter(Boolean);
  if (!changed.length) return "";
  if (changed.some((file) => file.untracked)) return "Git ?";
  if (changed.some((file) => file.staged && file.unstaged)) return "Git MM";
  if (changed.some((file) => file.staged)) return "Git M+";
  return "Git M";
}

function renderResourceBreadcrumbs(directoryPath) {
  const projectPath = String(state.currentProject?.path || "").replace(/\/+$/, "");
  const relativePath = directoryPath === projectPath ? "" : directoryPath.slice(projectPath.length + 1);
  const segments = relativePath ? relativePath.split("/").filter(Boolean) : [];
  elements.resourcePath.replaceChildren();
  const paths = [{ label: state.currentProject?.name || "工程", path: projectPath }];
  let current = projectPath;
  for (const segment of segments) {
    current = `${current}/${segment}`;
    paths.push({ label: segment, path: current });
  }
  paths.forEach((entry, index) => {
    if (index) {
      const divider = document.createElement("span");
      divider.textContent = "/";
      divider.setAttribute("aria-hidden", "true");
      elements.resourcePath.append(divider);
    }
    const button = document.createElement("button");
    button.type = "button";
    button.textContent = entry.label;
    button.title = entry.path;
    button.disabled = index === paths.length - 1;
    button.addEventListener("click", () => {
      if (confirmDiscardResourceChanges()) loadResourceDirectory(entry.path);
    });
    elements.resourcePath.append(button);
  });
  const currentEntry = paths[paths.length - 1];
  elements.resourceCurrentDirectory.textContent = currentEntry?.label || state.currentProject?.name || "工程";
  elements.resourceCurrentDirectory.title = directoryPath;
  elements.resourcePath.title = directoryPath;
  requestAnimationFrame(() => {
    if (elements.resourcePath.title === directoryPath) {
      elements.resourcePath.scrollLeft = elements.resourcePath.scrollWidth;
    }
  });
}

async function startResourceWatcher(directoryPath) {
  if (
    !state.bridgeReady
    || !elements.resourceDialog.open
    || !state.currentProject
    || !directoryPath
  ) {
    return;
  }
  if (state.resourceWatchId && state.resourceWatchPath === directoryPath) return;
  await stopResourceWatcher();
  if (
    !state.bridgeReady
    || !elements.resourceDialog.open
    || state.resourceDirectory !== directoryPath
  ) {
    return;
  }
  const watchId = `resource-${createClientMessageId()}`;
  state.resourceWatchId = watchId;
  state.resourceWatchPath = directoryPath;
  try {
    await rpc("fs/watch", {
      watchId,
      project: state.currentProject.path,
      path: directoryPath,
    }, { timeoutMs: 20_000 });
  } catch (error) {
    if (state.resourceWatchId === watchId) {
      state.resourceWatchId = null;
      state.resourceWatchPath = null;
    }
    if (elements.resourceDialog.open && state.bridgeReady && !/不存在|断开/.test(error.message)) {
      console.warn(`Resource watch unavailable: ${error.message}`);
    }
  }
}

async function stopResourceWatcher() {
  const watchId = state.resourceWatchId;
  state.resourceWatchId = null;
  state.resourceWatchPath = null;
  if (!watchId || state.socket?.readyState !== WebSocket.OPEN) return;
  await rpc("fs/unwatch", { watchId }, { timeoutMs: 10_000 }).catch(() => {});
}

function handleResourceWatchChange(payload) {
  if (
    !elements.resourceDialog.open
    || payload?.watchId !== state.resourceWatchId
    || Date.now() <= state.resourceIgnoreWatchUntil
  ) {
    return;
  }
  state.resourceExternalChanged = true;
  elements.resourceExternalNotice.hidden = false;
  if (state.resourceEditorDirty) {
    elements.resourceEditState.hidden = false;
    elements.resourceEditState.dataset.status = "conflict";
    elements.resourceEditState.textContent = "外部已修改";
  }
}

async function openProjectResourceFile(relativePath, line = null) {
  const project = state.currentProject;
  const parsed = parseProjectFileReference(relativePath);
  if (!project || !parsed || parsed.relativePath !== relativePath) return;
  if (elements.browserDialog.open) elements.browserDialog.close();
  closeMobilePanels();
  elements.resourceSearch.value = "";
  if (!elements.resourceDialog.open) elements.resourceDialog.showModal();
  else if (!confirmDiscardResourceChanges()) return;
  const segments = relativePath.split("/");
  const directory = segments.length > 1
    ? `${project.path.replace(/\/+$/, "")}/${segments.slice(0, -1).join("/")}`
    : project.path;
  const data = await loadResourceDirectory(directory);
  if (!data || state.currentProject?.path !== project.path) return;
  const entry = data.entries.find((candidate) => candidate.type === "file" && candidate.relativePath === relativePath);
  if (!entry) {
    toast(`文件不存在：${relativePath}`, "error");
    return;
  }
  await previewResourceFile(entry);
  if (line && !elements.resourcePreviewText.hidden) {
    setDataContent(elements.resourcePreviewName, `${relativePath}:${line}`);
    requestAnimationFrame(() => {
      const targetLine = elements.resourcePreviewText.querySelector(`[data-line="${line}"]`);
      if (targetLine) targetLine.scrollIntoView({ block: "center" });
    });
  }
}

function handleResourceSearch() {
  clearTimeout(state.resourceSearchTimer);
  const query = elements.resourceSearch.value.trim();
  if (!query) {
    renderResourceEntries(state.resourceEntries);
    return;
  }
  if (query.length < 2) {
    const normalized = query.toLowerCase();
    renderResourceEntries(state.resourceEntries.filter((entry) => entry.name.toLowerCase().includes(normalized)));
    return;
  }
  state.resourceSearchTimer = setTimeout(() => searchProjectResources(query), 250);
}

async function searchProjectResources(query) {
  if (!state.currentProject || elements.resourceSearch.value.trim() !== query) return;
  elements.resourceList.innerHTML = '<div class="list-loading">正在搜索</div>';
  try {
    const url = new URL("/api/files/search", location.origin);
    url.searchParams.set("project", state.currentProject.path);
    url.searchParams.set("query", query);
    const response = await fetch(url, { cache: "no-store" });
    const data = await response.json();
    if (!response.ok) throw new Error(data.error || "搜索失败");
    if (elements.resourceSearch.value.trim() === query) renderResourceEntries(data.entries || [], true);
  } catch (error) {
    elements.resourceList.innerHTML = '<div class="list-empty">搜索失败</div>';
    toast(error.message, "error");
  }
}

function renderResourceEntries(entries, searchResults = false) {
  elements.resourceList.replaceChildren();
  if (!entries.length) {
    elements.resourceList.innerHTML = '<div class="list-empty">没有匹配文件</div>';
    return;
  }
  for (const entry of sortedResourceEntries(entries)) {
    const row = document.createElement("div");
    row.className = "resource-row";
    row.setAttribute("role", "button");
    row.tabIndex = entry.type === "other" ? -1 : 0;
    row.dataset.disabled = entry.type === "other" ? "true" : "false";
    row.dataset.selected = String(state.resourceSelectedPaths.has(entry.path));
    row.innerHTML = '<label class="resource-row-select" title="选择用于打包下载"><input type="checkbox" aria-label="选择文件" /></label><span class="resource-row-icon"><i></i></span><span class="resource-row-copy"><strong></strong><span></span></span><span class="resource-row-size"></span><button class="resource-row-action" type="button" title="文件操作" aria-label="打开文件操作"><i data-lucide="ellipsis"></i></button>';
    row.querySelector(".resource-row-icon i").setAttribute("data-lucide", resourceEntryIcon(entry));
    setDataContent(row.querySelector("strong"), entry.name);
    const mode = Number.isInteger(entry.mode) ? `0${entry.mode.toString(8).padStart(3, "0")}` : "权限未知";
    const modified = Number(entry.modifiedAt)
      ? new Date(entry.modifiedAt).toLocaleString(interfaceLocale(), { hour12: false })
      : "时间未知";
    const git = resourceGitLabel(entry);
    setDataContent(row.querySelector(".resource-row-copy span"), [
      searchResults ? entry.relativePath : entry.type === "directory" ? "文件夹" : entry.type === "file" ? "文件" : "其他",
      entry.type === "file" && /\.html?$/i.test(entry.name) ? "双击运行" : null,
      modified,
      mode,
      git,
      state.resourceWritable ? null : "只读",
    ].filter(Boolean).join(" · "), searchResults);
    row.querySelector(".resource-row-size").textContent = entry.size === null ? "" : formatBytes(entry.size);
    const selection = row.querySelector(".resource-row-select input");
    selection.checked = state.resourceSelectedPaths.has(entry.path);
    selection.setAttribute("aria-label", `选择 ${entry.name}`);
    selection.addEventListener("click", (event) => event.stopPropagation());
    selection.addEventListener("change", (event) => {
      event.stopPropagation();
      if (selection.checked) {
        if (state.resourceSelectedPaths.size >= 100) {
          selection.checked = false;
          toast("一次最多选择 100 项", "error");
          return;
        }
        state.resourceSelectedPaths.add(entry.path);
      } else {
        state.resourceSelectedPaths.delete(entry.path);
      }
      row.dataset.selected = String(selection.checked);
      renderResourceSelectionState();
    });
    const openEntry = () => {
      if (entry.type === "other") return;
      if (!confirmDiscardResourceChanges()) return;
      if (entry.type === "directory") loadResourceDirectory(entry.path);
      else previewResourceFile(entry);
    };
    row.addEventListener("click", openEntry);
    row.addEventListener("dblclick", (event) => {
      if (
        entry.type !== "file"
        || !/\.html?$/i.test(entry.name)
        || event.target.closest("button, input, label")
      ) return;
      event.preventDefault();
      openBrowserPreview(entry.relativePath);
    });
    row.addEventListener("keydown", (event) => {
      if (event.target !== row) return;
      if (!["Enter", " "].includes(event.key)) return;
      event.preventDefault();
      openEntry();
    });
    const actionButton = row.querySelector(".resource-row-action");
    actionButton.hidden = !state.resourceWritable || entry.type === "other";
    actionButton.setAttribute("aria-label", `管理 ${entry.name}`);
    actionButton.addEventListener("click", (event) => {
      event.stopPropagation();
      openResourceEntryAction(entry);
    });
    elements.resourceList.append(row);
  }
  renderResourceSelectionState();
  refreshIcons();
}

function openResourceCreateAction(action) {
  if (!state.currentProject || !state.resourceWritable || !state.resourceDirectory) return;
  state.resourceActionEntry = null;
  state.resourceActionMode = action;
  elements.resourceActionForm.reset();
  elements.resourceActionTypeField.hidden = true;
  elements.resourceActionTitle.textContent = action === "createDirectory" ? "新建文件夹" : "新建文件";
  elements.resourceActionError.textContent = "";
  renderResourceActionFields();
  elements.resourceActionDialog.showModal();
  requestAnimationFrame(() => elements.resourceActionName.focus());
}

function openResourceEntryAction(entry) {
  if (!state.currentProject || !state.resourceWritable || !entry || entry.type === "other") return;
  state.resourceActionEntry = entry;
  state.resourceActionMode = null;
  elements.resourceActionForm.reset();
  elements.resourceActionTypeField.hidden = false;
  elements.resourceActionType.value = "rename";
  elements.resourceActionName.value = entry.name;
  elements.resourceActionDestination.value = resourceDirectoryRelativePath(state.resourceDirectory);
  elements.resourceActionTitle.textContent = `管理 ${entry.name}`;
  elements.resourceActionError.textContent = "";
  renderResourceActionFields();
  elements.resourceActionDialog.showModal();
  requestAnimationFrame(() => elements.resourceActionName.focus());
}

function closeResourceActionDialog() {
  if (elements.resourceActionDialog.open) elements.resourceActionDialog.close();
  state.resourceActionEntry = null;
  state.resourceActionMode = null;
  elements.resourceActionError.textContent = "";
}

function currentResourceAction() {
  return state.resourceActionMode || elements.resourceActionType.value;
}

function renderResourceActionFields() {
  const action = currentResourceAction();
  const creates = action === "createDirectory" || action === "createFile";
  const deletes = action === "delete";
  elements.resourceActionNameField.hidden = deletes;
  elements.resourceActionDestinationField.hidden = !["copy", "move"].includes(action);
  elements.resourceActionName.required = !deletes;
  elements.resourceActionSubmitButton.classList.toggle("danger-confirm-button", deletes);
  elements.resourceActionSubmitButton.textContent = {
    createDirectory: "创建文件夹",
    createFile: "创建文件",
    rename: "重命名",
    copy: "复制",
    move: "移动",
    delete: "移到回收区",
  }[action] || "确认";
  if (creates) {
    elements.resourceActionNote.textContent = "将在当前文件夹创建，不会覆盖已有同名项目。";
  } else if (action === "delete") {
    elements.resourceActionNote.textContent = "项目会移入工程内的只读回收区，不会立即永久删除。";
  } else if (action === "rename") {
    elements.resourceActionNote.textContent = "重命名前会校验文件版本；外部已经修改时操作会被拒绝。";
  } else {
    elements.resourceActionNote.textContent = "目标文件夹使用工程相对路径；不会覆盖已有同名项目。";
  }
}

function resourceDirectoryRelativePath(directoryPath) {
  const root = String(state.currentProject?.path || "").replace(/\/+$/, "");
  const directory = String(directoryPath || "");
  if (!root || directory === root) return ".";
  return directory.startsWith(`${root}/`) ? directory.slice(root.length + 1) || "." : ".";
}

function resolveResourceDestinationInput(value) {
  const root = String(state.currentProject?.path || "").replace(/\/+$/, "");
  const normalized = String(value || "").trim().replaceAll("\\", "/").replace(/^\.\/+/, "");
  if (!root) throw new Error("当前工程不可用");
  if (!normalized || normalized === ".") return root;
  if (
    normalized.startsWith("/")
    || normalized.split("/").some((segment) => !segment || segment === "." || segment === "..")
  ) {
    throw new Error("目标文件夹必须是工程内的有效相对路径");
  }
  return `${root}/${normalized}`;
}

async function submitResourceAction(event) {
  event.preventDefault();
  if (!state.currentProject || !state.resourceWritable || !elements.resourceActionForm.reportValidity()) return;
  const action = currentResourceAction();
  const entry = state.resourceActionEntry;
  if (!state.resourceActionMode && !entry) return;
  if (action === "delete" && !confirm(`将“${entry.name}”移到工程回收区？`)) return;
  elements.resourceActionError.textContent = "";
  elements.resourceActionSubmitButton.disabled = true;
  try {
    const body = {
      project: state.currentProject.path,
      action,
    };
    if (action === "createDirectory" || action === "createFile") {
      body.parentPath = state.resourceDirectory;
      body.name = elements.resourceActionName.value;
    } else {
      body.path = entry.path;
      body.expectedVersion = entry.version;
      if (action !== "delete") body.name = elements.resourceActionName.value;
      if (action === "copy" || action === "move") {
        body.destinationPath = resolveResourceDestinationInput(elements.resourceActionDestination.value);
      }
    }
    const response = await fetch("/api/files/action", {
      method: "POST",
      headers: {
        "Content-Type": "application/json",
        "X-Codex-Desktop-Action": "resource-file-action",
      },
      body: JSON.stringify(body),
    });
    const data = await response.json().catch(() => ({}));
    if (!response.ok) throw Object.assign(new Error(data.error || "文件操作失败"), { status: response.status });
    state.resourceIgnoreWatchUntil = Date.now() + 1_500;
    const labels = {
      createDirectory: "文件夹已创建",
      createFile: "文件已创建",
      rename: "重命名完成",
      copy: "复制完成",
      move: "移动完成",
      delete: "已移到工程回收区",
    };
    if (["rename", "move", "delete"].includes(action) && entry?.path) {
      state.resourceSelectedPaths.delete(entry.path);
    }
    closeResourceActionDialog();
    await loadResourceDirectory(state.resourceDirectory);
    toast(labels[action] || "文件操作完成");
  } catch (error) {
    elements.resourceActionError.textContent = error.message;
  } finally {
    elements.resourceActionSubmitButton.disabled = false;
  }
}

async function uploadResourceFiles() {
  const files = [...(elements.resourceUploadInput.files || [])];
  elements.resourceUploadInput.value = "";
  if (!files.length || !state.currentProject || !state.resourceWritable || state.resourceUploadBusy) return;
  state.resourceUploadBusy = true;
  elements.resourceUploadButton.disabled = true;
  let uploaded = 0;
  const failures = [];
  try {
    for (const file of files) {
      if (file.size > 20 * 1024 * 1024) {
        failures.push(`${file.name}：超过 20 MiB`);
        continue;
      }
      const url = new URL("/api/files/upload", location.origin);
      url.searchParams.set("project", state.currentProject.path);
      url.searchParams.set("path", state.resourceDirectory);
      url.searchParams.set("name", file.name);
      try {
        const response = await fetch(url, {
          method: "POST",
          headers: {
            "Content-Type": "application/octet-stream",
            "X-Codex-Desktop-Action": "resource-file-upload",
          },
          body: file,
        });
        const data = await response.json().catch(() => ({}));
        if (!response.ok) throw new Error(data.error || `上传失败（HTTP ${response.status}）`);
        uploaded += 1;
      } catch (error) {
        failures.push(`${file.name}：${error.message}`);
      }
    }
    state.resourceIgnoreWatchUntil = Date.now() + 1_500;
    await loadResourceDirectory(state.resourceDirectory);
    if (uploaded) toast(`已上传 ${uploaded} 个文件`);
    if (failures.length) toast(failures.slice(0, 3).join("；"), "error");
  } finally {
    state.resourceUploadBusy = false;
    elements.resourceUploadButton.disabled = !state.resourceWritable;
  }
}

async function refreshResourceAfterExternalChange() {
  if (!state.currentProject || !confirmDiscardResourceChanges()) return;
  const previewRelativePath = state.resourcePreviewEntry?.relativePath || null;
  const directory = state.resourceDirectory;
  const data = await loadResourceDirectory(directory);
  if (!data || !previewRelativePath) return;
  const entry = data.entries.find((candidate) => candidate.relativePath === previewRelativePath);
  if (entry?.type === "file") await previewResourceFile(entry);
}

function resourceEntryIcon(entry) {
  if (entry.type === "directory") return "folder";
  if (/\.(?:avif|gif|jpe?g|png|webp)$/i.test(entry.name)) return "image";
  if (/\.(?:js|jsx|ts|tsx|css|html|json|md|mjs|cjs|py|rs|go|java|toml|ya?ml)$/i.test(entry.name)) return "file-code-2";
  return "file";
}

function toggleResourceMarkdownPreview() {
  if (state.resourceEditing || state.resourcePreviewData?.previewKind !== "markdown") return;
  state.resourceMarkdownRendered = !state.resourceMarkdownRendered;
  elements.resourcePreviewMarkdown.hidden = !state.resourceMarkdownRendered;
  elements.resourcePreviewText.hidden = state.resourceMarkdownRendered;
  elements.resourcePreviewModeButton.innerHTML = `<i data-lucide="${state.resourceMarkdownRendered ? "code-2" : "book-open-text"}"></i>`;
  elements.resourcePreviewModeButton.title = state.resourceMarkdownRendered ? "查看 Markdown 源码" : "查看格式化 Markdown";
  refreshIcons();
}

function renderResourceMarkdown(content) {
  elements.resourcePreviewMarkdown.replaceChildren();
  const lines = String(content || "").split(/\r?\n/);
  let paragraph = [];
  let list = null;
  let code = null;

  const flushParagraph = () => {
    if (!paragraph.length) return;
    const node = document.createElement("p");
    appendResourceMarkdownInline(node, paragraph.join(" "));
    elements.resourcePreviewMarkdown.append(node);
    paragraph = [];
  };
  const closeList = () => {
    list = null;
  };
  const closeCode = () => {
    if (!code) return;
    elements.resourcePreviewMarkdown.append(code.wrapper);
    code = null;
  };

  for (const line of lines) {
    const fence = /^```([\w+-]*)\s*$/.exec(line);
    if (fence) {
      flushParagraph();
      closeList();
      if (code) {
        closeCode();
      } else {
        const wrapper = document.createElement("pre");
        const codeNode = document.createElement("code");
        if (fence[1]) codeNode.dataset.language = fence[1];
        wrapper.append(codeNode);
        code = { wrapper, node: codeNode, lines: [] };
      }
      continue;
    }
    if (code) {
      code.lines.push(line);
      code.node.textContent = code.lines.join("\n");
      continue;
    }
    if (!line.trim()) {
      flushParagraph();
      closeList();
      continue;
    }
    const heading = /^(#{1,6})\s+(.+)$/.exec(line);
    if (heading) {
      flushParagraph();
      closeList();
      const node = document.createElement(`h${heading[1].length}`);
      appendResourceMarkdownInline(node, heading[2]);
      elements.resourcePreviewMarkdown.append(node);
      continue;
    }
    if (/^\s*(?:-{3,}|\*{3,}|_{3,})\s*$/.test(line)) {
      flushParagraph();
      closeList();
      elements.resourcePreviewMarkdown.append(document.createElement("hr"));
      continue;
    }
    const quote = /^>\s?(.*)$/.exec(line);
    if (quote) {
      flushParagraph();
      closeList();
      const node = document.createElement("blockquote");
      appendResourceMarkdownInline(node, quote[1]);
      elements.resourcePreviewMarkdown.append(node);
      continue;
    }
    const item = /^\s*(?:(-|\*|\+)|(\d+)\.)\s+(.+)$/.exec(line);
    if (item) {
      flushParagraph();
      const type = item[2] ? "ol" : "ul";
      if (!list || list.tagName.toLowerCase() !== type) {
        list = document.createElement(type);
        elements.resourcePreviewMarkdown.append(list);
      }
      const node = document.createElement("li");
      appendResourceMarkdownInline(node, item[3]);
      list.append(node);
      continue;
    }
    closeList();
    paragraph.push(line.trim());
  }
  flushParagraph();
  closeCode();
}

function appendResourceMarkdownInline(parent, text) {
  const pattern = /(`[^`\n]+`|\*\*[^*\n]+\*\*|\[[^\]\n]+\]\(https?:\/\/[^)\s]+\))/giu;
  let offset = 0;
  for (const match of String(text).matchAll(pattern)) {
    if (match.index > offset) parent.append(document.createTextNode(text.slice(offset, match.index)));
    const token = match[0];
    if (token.startsWith("`")) {
      const code = document.createElement("code");
      code.textContent = token.slice(1, -1);
      parent.append(code);
    } else if (token.startsWith("**")) {
      const strong = document.createElement("strong");
      strong.textContent = token.slice(2, -2);
      parent.append(strong);
    } else {
      const link = /^\[([^\]]+)\]\((https?:\/\/[^)]+)\)$/iu.exec(token);
      const anchor = document.createElement("a");
      anchor.textContent = link[1];
      anchor.href = link[2];
      anchor.target = "_blank";
      anchor.rel = "noopener noreferrer";
      parent.append(anchor);
    }
    offset = match.index + token.length;
  }
  if (offset < text.length) parent.append(document.createTextNode(text.slice(offset)));
}

async function previewResourceFile(entry) {
  clearResourcePreview();
  state.resourcePreviewEntry = entry;
  const isImage = entry.type === "file"
    && /\.(?:avif|gif|jpe?g|png|webp)$/iu.test(entry.name || "")
    && Boolean(entry.relativePath);
  setDataContent(elements.resourcePreviewName, entry.relativePath || entry.name);
  elements.resourceDownloadButton.hidden = entry.type !== "file";
  elements.resourceCopyPathButton.hidden = entry.type !== "file";
  elements.resourcePreviewBrowserButton.hidden = !/\.html?$/i.test(entry.name);
  elements.resourceMapEditorButton.hidden = !/\.tmj$/i.test(entry.name);
  elements.resourceImageStudioButton.hidden = !isImage;
  elements.resourceVisualReviewButton.hidden = !isImage;
  if (isImage) {
    elements.resourcePreviewImage.src = `/api/files/image?path=${encodeURIComponent(entry.path)}`;
    elements.resourcePreviewImage.hidden = false;
    return;
  }
  try {
    const url = new URL("/api/files/read", location.origin);
    url.searchParams.set("project", state.currentProject.path);
    url.searchParams.set("path", entry.path);
    const response = await fetch(url, { cache: "no-store" });
    const data = await response.json();
    if (!response.ok) throw new Error(data.error || "无法预览文件");
    state.resourcePreviewData = data;
    elements.resourcePreviewMeta.textContent = [
      formatBytes(data.size),
      Number(data.modifiedAt) ? new Date(data.modifiedAt).toLocaleString(interfaceLocale(), { hour12: false }) : null,
      Number.isInteger(data.mode) ? `0${data.mode.toString(8).padStart(3, "0")}` : null,
      Number.isInteger(data.uid) && Number.isInteger(data.gid) ? `${data.uid}:${data.gid}` : null,
      resourceGitLabel(entry),
      data.editable ? "可编辑" : "只读",
    ].filter(Boolean).join(" · ");
    elements.resourcePreviewText.dataset.kind = data.previewKind || "text";
    if (data.binary) {
      elements.resourcePreviewText.textContent = `二进制文件 · ${formatBytes(data.size)}\n\n此类型不在浏览器内展开，可使用右上角下载按钮查看。`;
      elements.resourcePreviewText.hidden = false;
    } else {
      renderResourceTextPreview(data.content || "");
      state.resourceMarkdownRendered = data.previewKind === "markdown";
      if (state.resourceMarkdownRendered) {
        renderResourceMarkdown(data.content || "");
        elements.resourcePreviewMarkdown.hidden = false;
        elements.resourcePreviewText.hidden = true;
        elements.resourcePreviewModeButton.hidden = false;
        elements.resourcePreviewModeButton.innerHTML = '<i data-lucide="code-2"></i>';
        elements.resourcePreviewModeButton.title = "查看 Markdown 源码";
      } else {
        elements.resourcePreviewText.hidden = false;
      }
    }
    elements.resourceReloadButton.hidden = false;
    elements.resourceLoadMoreButton.hidden = !Number.isSafeInteger(data.nextOffset);
    elements.resourceEditState.hidden = false;
    elements.resourceEditState.dataset.status = data.editable ? "saved" : "readonly";
    elements.resourceEditState.textContent = data.binary
      ? "二进制"
      : data.truncated
        ? `大文件 · 剩余 ${formatBytes(data.omittedBytes)}`
        : data.editable
          ? "可编辑"
          : "只读";
    elements.resourceEditButton.hidden = !data.editable;
    refreshIcons();
  } catch (error) {
    elements.resourcePreviewText.textContent = error.message;
    elements.resourcePreviewText.hidden = false;
  }
}

function clearResourcePreview() {
  state.resourceVisualReviewInstance?.close?.();
  state.resourceVisualReviewInstance = null;
  state.resourcePreviewEntry = null;
  state.resourcePreviewData = null;
  state.resourceEditing = false;
  state.resourceEditorDirty = false;
  state.resourceSaving = false;
  state.resourceMarkdownRendered = false;
  setDataContent(elements.resourcePreviewName, "未选择文件", false);
  elements.resourcePreviewMeta.textContent = "";
  elements.resourcePreviewText.textContent = "";
  elements.resourcePreviewText.hidden = true;
  elements.resourcePreviewText.removeAttribute("data-kind");
  elements.resourcePreviewMarkdown.replaceChildren();
  elements.resourcePreviewMarkdown.hidden = true;
  elements.resourceEditor.value = "";
  elements.resourceEditor.hidden = true;
  elements.resourceEditState.hidden = true;
  elements.resourceEditState.removeAttribute("data-status");
  elements.resourceReloadButton.hidden = true;
  elements.resourceDownloadButton.hidden = true;
  elements.resourceCopyPathButton.hidden = true;
  elements.resourceLoadMoreButton.hidden = true;
  elements.resourceLoadMoreButton.disabled = false;
  elements.resourcePreviewModeButton.hidden = true;
  elements.resourceEditButton.hidden = true;
  elements.resourceEditButton.innerHTML = '<i data-lucide="square-pen"></i>';
  elements.resourceEditButton.title = "编辑文件";
  elements.resourceEditButton.setAttribute("aria-label", "编辑文件");
  elements.resourceSaveButton.hidden = true;
  elements.resourceSaveButton.disabled = true;
  elements.resourcePreviewImage.removeAttribute("src");
  elements.resourcePreviewImage.hidden = true;
  elements.resourcePreviewBrowserButton.hidden = true;
  elements.resourceMapEditorButton.hidden = true;
  elements.resourceImageStudioButton.hidden = true;
  elements.resourceVisualReviewButton.hidden = true;
  elements.resourceVisualReviewButton.disabled = false;
}

async function closeResourceExplorer() {
  if (!confirmDiscardResourceChanges()) return;
  void stopResourceWatcher();
  if (elements.resourceActionDialog.open) closeResourceActionDialog();
  await exitResourceFullscreen();
  elements.resourceDialog.close();
  clearResourcePreview();
}

function confirmDiscardResourceChanges() {
  if (!state.resourceEditorDirty) return true;
  return confirm("当前文件有未保存修改，确定放弃吗？");
}

function toggleResourceEditor() {
  if (!state.resourcePreviewData?.editable || state.resourceSaving) return;
  if (state.resourceEditing) {
    if (!confirmDiscardResourceChanges()) return;
    state.resourceEditorDirty = false;
    setResourceEditing(false);
    return;
  }
  elements.resourceEditor.value = state.resourcePreviewData.content;
  setResourceEditing(true);
  requestAnimationFrame(() => elements.resourceEditor.focus());
}

function setResourceEditing(editing) {
  state.resourceEditing = editing;
  const showMarkdown = !editing
    && state.resourcePreviewData?.previewKind === "markdown"
    && state.resourceMarkdownRendered;
  elements.resourcePreviewText.hidden = editing || !state.resourcePreviewData || showMarkdown;
  elements.resourcePreviewMarkdown.hidden = !showMarkdown;
  elements.resourcePreviewModeButton.hidden = editing || state.resourcePreviewData?.previewKind !== "markdown";
  elements.resourceEditor.hidden = !editing;
  elements.resourceSaveButton.hidden = !editing;
  elements.resourceSaveButton.disabled = !state.resourceEditorDirty || state.resourceSaving;
  elements.resourceEditButton.innerHTML = `<i data-lucide="${editing ? "x" : "square-pen"}"></i>`;
  elements.resourceEditButton.title = editing ? "取消编辑" : "编辑文件";
  elements.resourceEditButton.setAttribute("aria-label", elements.resourceEditButton.title);
  elements.resourceEditState.dataset.status = editing ? state.resourceEditorDirty ? "dirty" : "saved" : "saved";
  elements.resourceEditState.textContent = editing ? state.resourceEditorDirty ? "未保存" : "已保存" : "可编辑";
  refreshIcons();
}

function setResourceEditorDirty(dirty) {
  if (!state.resourceEditing || state.resourceSaving) return;
  state.resourceEditorDirty = dirty;
  elements.resourceSaveButton.disabled = !dirty;
  elements.resourceEditState.dataset.status = dirty ? "dirty" : "saved";
  elements.resourceEditState.textContent = dirty ? "未保存" : "已保存";
}

function handleResourceEditorKeydown(event) {
  if ((event.ctrlKey || event.metaKey) && event.key.toLowerCase() === "s") {
    event.preventDefault();
    saveResourceFile();
    return;
  }
  if (event.key !== "Tab" || event.ctrlKey || event.metaKey || event.altKey) return;
  event.preventDefault();
  const start = elements.resourceEditor.selectionStart;
  const end = elements.resourceEditor.selectionEnd;
  elements.resourceEditor.setRangeText("  ", start, end, "end");
  setResourceEditorDirty(true);
}

async function reloadResourcePreview() {
  const entry = state.resourcePreviewEntry;
  if (!entry || !confirmDiscardResourceChanges()) return;
  await previewResourceFile(entry);
  toast("文件已重新加载");
}

function downloadResourceFile() {
  const entry = state.resourcePreviewEntry;
  if (!state.currentProject || !entry || entry.type !== "file") return;
  const url = new URL("/api/files/download", location.origin);
  url.searchParams.set("project", state.currentProject.path);
  url.searchParams.set("path", entry.path);
  const link = document.createElement("a");
  link.href = url.href;
  link.download = "";
  document.body.append(link);
  link.click();
  link.remove();
  toast(`正在下载 ${entry.name}`);
}

function downloadResourceDirectory() {
  if (!state.currentProject || !state.resourceDirectory) return;
  const url = new URL("/api/files/archive", location.origin);
  url.searchParams.set("project", state.currentProject.path);
  url.searchParams.set("path", state.resourceDirectory);
  const link = document.createElement("a");
  link.href = url.href;
  link.download = "";
  document.body.append(link);
  link.click();
  link.remove();
  toast("正在打包当前文件夹");
}

async function downloadSelectedResources() {
  const paths = [...state.resourceSelectedPaths];
  if (!state.currentProject || !paths.length) return;
  elements.resourceDownloadSelectedButton.disabled = true;
  try {
    const response = await fetch("/api/files/archive", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ project: state.currentProject.path, paths }),
    });
    if (!response.ok) {
      const data = await response.json().catch(() => ({}));
      throw new Error(data.error || "所选文件打包失败");
    }
    const blob = await response.blob();
    const objectUrl = URL.createObjectURL(blob);
    const link = document.createElement("a");
    link.href = objectUrl;
    link.download = `WFL-Codex-selection-${Date.now()}.tar.gz`;
    document.body.append(link);
    link.click();
    link.remove();
    setTimeout(() => URL.revokeObjectURL(objectUrl), 30_000);
    toast(`正在下载所选 ${paths.length} 项`);
  } catch (error) {
    toast(error.message, "error");
  } finally {
    renderResourceSelectionState();
  }
}

async function copyResourcePath() {
  const pathValue = state.resourcePreviewEntry?.relativePath;
  if (!pathValue) return;
  await copyText(pathValue);
  toast("已复制工程相对路径");
}

function renderResourceTextPreview(content) {
  const fragment = document.createDocumentFragment();
  const lines = String(content || "").split("\n");
  for (let index = 0; index < lines.length; index += 1) {
    const line = document.createElement("span");
    line.className = "resource-code-line";
    line.dataset.line = String(index + 1);
    line.textContent = lines[index] || " ";
    fragment.append(line);
  }
  elements.resourcePreviewText.replaceChildren(fragment);
}

async function loadMoreResourcePreview() {
  const entry = state.resourcePreviewEntry;
  const data = state.resourcePreviewData;
  const offset = Number(data?.nextOffset);
  if (
    !state.currentProject
    || !entry
    || !Number.isSafeInteger(offset)
    || offset < 0
    || state.resourceChunkLoading
  ) return;
  state.resourceChunkLoading = true;
  elements.resourceLoadMoreButton.disabled = true;
  elements.resourceLoadMoreButton.innerHTML = '<i class="spin" data-lucide="loader-circle"></i>';
  refreshIcons();
  try {
    const url = new URL("/api/files/read-chunk", location.origin);
    url.searchParams.set("project", state.currentProject.path);
    url.searchParams.set("path", entry.path);
    url.searchParams.set("offset", String(offset));
    const response = await fetch(url, { cache: "no-store" });
    const chunk = await response.json();
    if (!response.ok) throw new Error(chunk.error || "无法加载下一段文件");
    if (chunk.version !== data.version) throw new Error("文件已被其他任务修改，请重新加载后再继续读取");
    state.resourcePreviewData = {
      ...data,
      content: `${data.content || ""}${chunk.content || ""}`,
      nextOffset: chunk.eof ? null : chunk.nextOffset,
      omittedBytes: chunk.omittedBytes,
      truncated: !chunk.eof,
    };
    renderResourceTextPreview(state.resourcePreviewData.content);
    elements.resourceLoadMoreButton.hidden = chunk.eof;
    elements.resourceEditState.textContent = chunk.eof
      ? `大文件 · 已读取 ${formatBytes(chunk.size)}`
      : `大文件 · 剩余 ${formatBytes(chunk.omittedBytes)}`;
  } catch (error) {
    toast(error.message, "error");
  } finally {
    state.resourceChunkLoading = false;
    elements.resourceLoadMoreButton.disabled = false;
    elements.resourceLoadMoreButton.innerHTML = '<i data-lucide="list-plus"></i>';
    refreshIcons();
  }
}

async function saveResourceFile() {
  const entry = state.resourcePreviewEntry;
  const data = state.resourcePreviewData;
  if (!state.currentProject || !entry || !data?.editable || !state.resourceEditing || !state.resourceEditorDirty || state.resourceSaving) return;
  state.resourceSaving = true;
  elements.resourceSaveButton.disabled = true;
  elements.resourceEditState.dataset.status = "saving";
  elements.resourceEditState.textContent = "保存中";
  try {
    state.resourceIgnoreWatchUntil = Date.now() + 1_500;
    const url = new URL("/api/files/write", location.origin);
    url.searchParams.set("project", state.currentProject.path);
    url.searchParams.set("path", entry.path);
    const response = await fetch(url, {
      method: "PUT",
      headers: {
        "Content-Type": "text/plain; charset=utf-8",
        "X-Codex-Desktop-Action": "resource-file-save",
        "X-Codex-Desktop-File-Version": data.version,
      },
      body: elements.resourceEditor.value,
    });
    const updated = await response.json();
    if (!response.ok) throw Object.assign(new Error(updated.error || "保存文件失败"), { status: response.status });
    state.resourcePreviewData = {
      ...updated,
      binary: false,
      truncated: false,
      omittedBytes: 0,
      previewKind: data.previewKind || "text",
    };
    state.resourcePreviewEntry = { ...entry, size: updated.size, modifiedAt: updated.modifiedAt };
    renderResourceTextPreview(updated.content);
    if (state.resourcePreviewData.previewKind === "markdown") renderResourceMarkdown(updated.content);
    state.resourceEditorDirty = false;
    elements.resourceEditState.dataset.status = "saved";
    elements.resourceEditState.textContent = "已保存";
    toast(`已保存 ${updated.relativePath}`);
  } catch (error) {
    elements.resourceEditState.dataset.status = error.status === 409 ? "conflict" : "error";
    elements.resourceEditState.textContent = error.status === 409 ? "保存冲突" : "保存失败";
    toast(error.message, "error");
  } finally {
    state.resourceSaving = false;
    elements.resourceSaveButton.disabled = !state.resourceEditorDirty;
  }
}

function downloadCurrentProject() {
  if (!state.currentProject) return;
  const link = document.createElement("a");
  link.href = `/api/projects/download?project=${encodeURIComponent(state.currentProject.path)}`;
  link.download = "";
  document.body.append(link);
  link.click();
  link.remove();
  toast("正在打包工程");
}

async function submitProjectForm(event) {
  if (event.submitter?.value === "cancel") return;
  event.preventDefault();
  if (!elements.projectForm.reportValidity()) return;
  elements.projectSubmitButton.disabled = true;
  elements.projectFormError.textContent = "";
  try {
    const formData = new FormData(elements.projectForm);
    const response = await fetch("/api/projects", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({
        name: formData.get("name"),
        template: formData.get("template"),
        rootId: formData.get("rootId"),
        initializeGit: elements.initializeGitInput.checked,
      }),
    });
    const data = await response.json();
    if (!response.ok) throw new Error(data.error || "无法创建工程");
    elements.projectDialog.close();
    await loadProjects();
    await selectProject(state.projects.find((project) => project.path === data.project.path) || data.project);
    toast("工程已创建");
  } catch (error) {
    elements.projectFormError.textContent = error.message;
  } finally {
    elements.projectSubmitButton.disabled = false;
  }
}

function openProjectImportDialog() {
  elements.projectImportForm.reset();
  elements.projectImportError.textContent = "";
  elements.projectImportProgress.hidden = true;
  elements.projectImportProgress.firstElementChild.style.width = "0";
  elements.projectImportDialog.showModal();
}

function updateProjectImportName() {
  const file = elements.projectArchiveInput.files?.[0];
  if (!file || elements.projectImportNameInput.value.trim()) return;
  const base = file.name.replace(/\.tar\.gz$/i, "").replace(/[^A-Za-z0-9._-]+/g, "-").replace(/^[^A-Za-z0-9]+/, "");
  elements.projectImportNameInput.value = base.slice(0, 64) || "imported-project";
}

async function submitProjectImport(event) {
  if (event.submitter?.value === "cancel") return;
  event.preventDefault();
  if (!elements.projectImportForm.reportValidity()) return;
  const file = elements.projectArchiveInput.files?.[0];
  if (!file) return;
  if (file.size > 256 * 1024 * 1024) {
    elements.projectImportError.textContent = "工程压缩包不能超过 256 MB";
    return;
  }
  elements.projectImportSubmitButton.disabled = true;
  elements.projectImportError.textContent = "";
  elements.projectImportProgress.hidden = false;
  elements.projectImportProgress.firstElementChild.style.width = "0";
  try {
    const data = await uploadProjectArchive(file, elements.projectImportNameInput.value.trim(), (percent) => {
      elements.projectImportProgress.firstElementChild.style.width = `${percent}%`;
    });
    elements.projectImportDialog.close();
    await loadProjects();
    await selectProject(state.projects.find((project) => project.path === data.project.path) || data.project);
    toast("工程已导入");
  } catch (error) {
    elements.projectImportError.textContent = error.message;
  } finally {
    elements.projectImportSubmitButton.disabled = false;
  }
}

function uploadProjectArchive(file, name, onProgress) {
  return new Promise((resolve, reject) => {
    const request = new XMLHttpRequest();
    request.open("POST", `/api/projects/import?name=${encodeURIComponent(name)}`);
    request.setRequestHeader("Content-Type", "application/gzip");
    request.setRequestHeader("X-Codex-Desktop-Action", "project-import");
    request.responseType = "json";
    request.upload.addEventListener("progress", (event) => {
      if (event.lengthComputable) onProgress(Math.min(96, Math.round((event.loaded / event.total) * 96)));
    });
    request.addEventListener("load", () => {
      const data = request.response || {};
      if (request.status >= 200 && request.status < 300) {
        onProgress(100);
        resolve(data);
      } else {
        reject(new Error(data.error || "工程导入失败"));
      }
    });
    request.addEventListener("error", () => reject(new Error("工程上传连接失败")));
    request.addEventListener("abort", () => reject(new Error("工程上传已取消")));
    request.send(file);
  });
}

function renderContextWindowSetting() {
  const current = positiveTokenCount(state.config.model_context_window);
  const preserveValue = "__preserve__";
  const reportedWindow = positiveTokenCount(
    state.activeThread ? state.threadTokenUsage.get(state.activeThread.id)?.modelContextWindow : null,
  );
  elements.settingsContextWindow.replaceChildren(
    new Option("Codex 默认（自动）", ""),
    new Option("1M Token", "1000000"),
  );
  const hint = reportedWindow
    ? `当前对话实际上报 ${formatTokenCount(reportedWindow)} Token${current && current !== reportedWindow ? `（配置值 ${formatTokenCount(current)}）` : ""}；该设置只影响后续新建对话。`
    : "只影响后续新建对话；当前对话以 Codex 实际上报的窗口为准。";
  if (current && current !== 1_000_000) {
    const currentOption = new Option(
      `保留当前配置（${formatTokenCount(current)} Token）`,
      preserveValue,
    );
    currentOption.title = "当前配置不是界面预设；不修改此项时会继续保留。";
    elements.settingsContextWindow.add(currentOption);
    elements.settingsContextWindow.value = preserveValue;
    elements.settingsContextWindowHint.textContent = `${hint}当前配置为 ${formatTokenCount(current)} Token；选择其他选项后才会替换它。`;
    return;
  }
  elements.settingsContextWindow.value = current === 1_000_000 ? "1000000" : "";
  elements.settingsContextWindowHint.textContent = hint;
}

async function openSettings() {
  elements.settingsError.textContent = "";
  await loadMultiUserSettings();
  elements.compactModeInput.checked = state.ui.compact;
  elements.showToolOutputInput.checked = state.ui.showToolOutput;
  elements.expandFileChangesInput.checked = state.ui.expandFileChanges;
  elements.expandFileEditsInput.checked = state.ui.expandFileEdits;
  elements.showSystemStatusInput.checked = state.ui.showSystemStatus;
  elements.projectPanePersistentInput.checked = state.ui.projectPanePersistent;
  elements.threadPanePersistentInput.checked = state.ui.threadPanePersistent;
  elements.notifyTaskCompleteInput.checked = state.ui.notifyTaskComplete;
  elements.notifyApprovalInput.checked = state.ui.notifyApproval;
  elements.notifyQuestionInput.checked = state.ui.notifyQuestion;
  if (state.bridgeReady && state.currentProject) {
    try {
      await loadConfig();
    } catch (error) {
      elements.settingsError.textContent = error.message;
    }
  }
  elements.codexMemorySettingsSection.hidden = !canUseCodexMemory() || state.runtime !== "codex";
  if (!elements.codexMemorySettingsSection.hidden && state.bridgeReady) {
    await loadCodexMemories({ silent: true });
  } else {
    renderCodexMemorySettings();
  }
  elements.settingsModel.value = state.config.model || state.selectedModel || "";
  renderContextWindowSetting();
  populateSettingsEfforts(
    elements.settingsModel.value || state.selectedModel,
    state.config.model_reasoning_effort || state.selectedEffort,
  );
  elements.settingsApproval.value = normalizeApprovalPolicy(state.config.approval_policy);
  elements.settingsApprovalsReviewer.value = state.config.approvals_reviewer || "user";
  elements.settingsSandbox.value = state.config.sandbox_mode || "workspace-write";
  elements.settingsWebSearch.value = state.config.web_search || "disabled";
  renderCodexPolicySettings();
  elements.applySettingsToBranchButton.disabled = !state.activeThread || conversationBusy();
  elements.applySettingsToBranchButton.title = state.activeThread
    ? "保存权限并创建使用新沙箱的对话分支"
    : "请先打开一个对话";
  elements.settingsDialog.showModal();
}

async function loadCodexMemories({ silent = false } = {}) {
  if (!canUseCodexMemory() || state.runtime !== "codex" || !state.bridgeReady) {
    renderCodexMemorySettings();
    return null;
  }
  if (state.codexMemory.loading) return null;
  state.codexMemory.loading = true;
  state.codexMemory.error = "";
  renderCodexMemorySettings();
  try {
    const query = new URLSearchParams({ _: String(Date.now()) });
    if (state.activeThread?.id) query.set("threadId", state.activeThread.id);
    const response = await fetch(`/api/codex/memories?${query}`, { cache: "no-store" });
    const snapshot = await readApiJson(response, "无法读取 Codex Memories");
    state.codexMemory = {
      ...state.codexMemory,
      ...snapshot,
      preview: (Array.isArray(snapshot.files) ? snapshot.files : [])
        .some((entry) => entry.path === state.codexMemory.preview?.path)
        ? state.codexMemory.preview
        : null,
      loading: false,
      error: "",
    };
    renderCodexMemorySettings();
    return snapshot;
  } catch (error) {
    state.codexMemory.loading = false;
    state.codexMemory.error = error.message;
    renderCodexMemorySettings();
    if (!silent) toast(error.message, "error");
    return null;
  }
}

function renderCodexMemorySettings({ syncInputs = true } = {}) {
  const allowed = canUseCodexMemory() && state.runtime === "codex";
  elements.codexMemorySettingsSection.hidden = !allowed;
  if (!allowed) return;
  const snapshot = state.codexMemory;
  const configuration = snapshot.configuration || {};
  if (syncInputs) {
    elements.codexMemoryEnabledInput.checked = configuration.featureEnabled === true;
    elements.codexMemoryUseInput.checked = configuration.useMemories !== false;
    elements.codexMemoryGenerateInput.checked = configuration.generateMemories !== false;
    elements.codexMemoryExternalInput.checked = configuration.disableOnExternalContext === true;
  }
  const enabled = elements.codexMemoryEnabledInput.checked;
  const loading = snapshot.loading === true;
  elements.codexMemoryStatus.textContent = loading
    ? "正在同步"
    : snapshot.error ? "读取失败" : enabled ? "已启用" : "已关闭";
  elements.codexMemoryStatus.dataset.enabled = String(enabled && !snapshot.error);
  elements.codexMemoryUseInput.disabled = loading || !enabled;
  elements.codexMemoryGenerateInput.disabled = loading || !enabled;
  elements.codexMemoryExternalInput.disabled = loading || !enabled || !elements.codexMemoryGenerateInput.checked;
  elements.codexMemoryRefreshButton.disabled = loading;

  const thread = snapshot.thread?.id === state.activeThread?.id ? snapshot.thread : null;
  if (!state.activeThread) {
    elements.codexMemoryThreadState.textContent = "尚未打开对话";
  } else if (!enabled) {
    elements.codexMemoryThreadState.textContent = "全局 Memories 已关闭";
  } else if (thread?.effectiveMode === "disabled") {
    elements.codexMemoryThreadState.textContent = "此对话不会读取或贡献记忆";
  } else {
    elements.codexMemoryThreadState.textContent = thread?.source === "thread"
      ? "此对话已明确启用记忆"
      : "跟随全局设置";
  }
  const currentMode = thread?.configuredMode || "enabled";
  const nextMode = currentMode === "enabled" ? "disabled" : "enabled";
  elements.codexMemoryThreadToggleButton.dataset.nextMode = nextMode;
  elements.codexMemoryThreadToggleButton.disabled = loading || !enabled || !state.activeThread;
  elements.codexMemoryThreadToggleButton.querySelector("span").textContent = nextMode === "enabled"
    ? "启用此对话"
    : "停用此对话";

  const files = Array.isArray(snapshot.files) ? snapshot.files : [];
  elements.codexMemoryFileCount.textContent = `${files.length} 个`;
  elements.codexMemoryFileList.replaceChildren();
  if (!files.length) {
    const empty = document.createElement("span");
    empty.className = "codex-memory-empty";
    empty.textContent = loading ? "正在读取当前账号记忆" : "当前账号尚未生成记忆";
    elements.codexMemoryFileList.append(empty);
  } else {
    for (const file of files) {
      const button = document.createElement("button");
      button.type = "button";
      button.className = "codex-memory-file-button";
      const name = document.createElement("strong");
      name.textContent = file.path;
      const meta = document.createElement("span");
      meta.textContent = `${formatCodexMemorySize(file.size)} · ${formatCodexMemoryTime(file.updatedAt)}`;
      button.append(name, meta);
      button.addEventListener("click", () => previewCodexMemory(file.path));
      elements.codexMemoryFileList.append(button);
    }
  }
  const preview = snapshot.preview;
  elements.codexMemoryPreview.hidden = !preview;
  if (preview) {
    elements.codexMemoryPreviewName.textContent = preview.path;
    elements.codexMemoryPreviewNote.textContent = preview.redacted ? "已隐藏疑似凭据" : "只读预览";
    elements.codexMemoryPreviewContent.textContent = preview.content;
  } else {
    elements.codexMemoryPreviewContent.textContent = "";
  }
  elements.codexMemoryResetButton.disabled = loading || !files.length;
  if (snapshot.error) elements.settingsError.textContent = snapshot.error;
  refreshIcons();
}

async function saveCodexMemorySettingsFromForm() {
  if (elements.codexMemorySettingsSection.hidden) return null;
  const response = await fetch("/api/codex/memories/settings", {
    method: "PUT",
    headers: {
      "Content-Type": "application/json",
      "X-Codex-Desktop-Action": "codex-memory-settings-save",
    },
    body: JSON.stringify({
      settings: {
        featureEnabled: elements.codexMemoryEnabledInput.checked,
        useMemories: elements.codexMemoryUseInput.checked,
        generateMemories: elements.codexMemoryGenerateInput.checked,
        disableOnExternalContext: elements.codexMemoryExternalInput.checked,
      },
      threadId: state.activeThread?.id || null,
    }),
  });
  const snapshot = await readApiJson(response, "无法保存 Codex Memories 设置");
  state.codexMemory = { ...state.codexMemory, ...snapshot, loading: false, error: "" };
  renderCodexMemorySettings();
  return snapshot;
}

async function toggleCurrentThreadMemory() {
  if (!state.activeThread || state.codexMemory.loading) return;
  state.codexMemory.loading = true;
  renderCodexMemorySettings();
  try {
    const response = await fetch("/api/codex/memories/thread", {
      method: "PUT",
      headers: {
        "Content-Type": "application/json",
        "X-Codex-Desktop-Action": "codex-memory-thread-mode",
      },
      body: JSON.stringify({
        threadId: state.activeThread.id,
        mode: elements.codexMemoryThreadToggleButton.dataset.nextMode,
      }),
    });
    const result = await readApiJson(response, "无法更新当前对话的记忆模式");
    state.codexMemory.thread = {
      id: result.thread.threadId,
      configuredMode: result.thread.mode,
      effectiveMode: result.thread.mode,
      source: "thread",
      updatedAt: result.thread.updatedAt,
    };
    state.codexMemory.error = "";
    toast(result.thread.mode === "enabled" ? "当前对话已启用记忆" : "当前对话已停用记忆");
  } catch (error) {
    state.codexMemory.error = error.message;
    toast(error.message, "error");
  } finally {
    state.codexMemory.loading = false;
    renderCodexMemorySettings();
  }
}

async function previewCodexMemory(memoryPath) {
  if (state.codexMemory.loading) return;
  state.codexMemory.loading = true;
  renderCodexMemorySettings();
  try {
    const query = new URLSearchParams({ path: memoryPath, _: String(Date.now()) });
    const response = await fetch(`/api/codex/memories/file?${query}`, { cache: "no-store" });
    const result = await readApiJson(response, "无法读取记忆文件");
    state.codexMemory.preview = result.memory;
    state.codexMemory.error = "";
  } catch (error) {
    state.codexMemory.error = error.message;
    toast(error.message, "error");
  } finally {
    state.codexMemory.loading = false;
    renderCodexMemorySettings();
  }
}

function openCodexMemoryResetDialog() {
  elements.codexMemoryResetConfirmation.value = "";
  elements.codexMemoryResetError.textContent = "";
  elements.codexMemoryResetDialog.showModal();
  elements.codexMemoryResetConfirmation.focus();
}

function formatCodexMemoryTime(value) {
  const timestamp = Number(value);
  if (!Number.isFinite(timestamp) || timestamp <= 0) return "时间未知";
  return new Intl.DateTimeFormat(interfaceLocale(), {
    month: "2-digit",
    day: "2-digit",
    hour: "2-digit",
    minute: "2-digit",
  }).format(new Date(timestamp));
}

function formatCodexMemorySize(value) {
  const bytes = Number(value);
  if (!Number.isFinite(bytes) || bytes < 0) return "大小未知";
  if (bytes < 1_024) return `${Math.round(bytes)} B`;
  if (bytes < 1024 * 1024) {
    const kilobytes = bytes / 1_024;
    return `${kilobytes < 10 ? kilobytes.toFixed(1) : Math.round(kilobytes)} KB`;
  }
  return formatStorage(bytes);
}

async function resetCodexMemories(event) {
  if (event.submitter?.value === "cancel") return;
  event.preventDefault();
  const confirmation = elements.codexMemoryResetConfirmation.value.trim();
  if (confirmation !== "清除全部 Codex 记忆") {
    elements.codexMemoryResetError.textContent = "确认文字不匹配";
    return;
  }
  elements.codexMemoryResetConfirmButton.disabled = true;
  elements.codexMemoryResetError.textContent = "";
  try {
    const response = await fetch("/api/codex/memories/reset", {
      method: "POST",
      headers: {
        "Content-Type": "application/json",
        "X-Codex-Desktop-Action": "codex-memory-reset",
      },
      body: JSON.stringify({
        confirmation,
        threadId: state.activeThread?.id || null,
      }),
    });
    const snapshot = await readApiJson(response, "无法清除 Codex Memories");
    state.codexMemory = { ...state.codexMemory, ...snapshot, preview: null, loading: false, error: "" };
    elements.codexMemoryResetDialog.close();
    renderCodexMemorySettings();
    toast("当前账号的 Codex Memories 已清除");
  } catch (error) {
    elements.codexMemoryResetError.textContent = error.message;
  } finally {
    elements.codexMemoryResetConfirmButton.disabled = false;
  }
}

function renderCodexPolicySettings() {
  const requirements = state.codexPolicy.requirements;
  const profiles = state.codexPolicy.permissionProfiles;
  const managedProfiles = requirements?.allowedPermissionProfiles != null;
  const selectedProfile = state.config.default_permissions
    || requirements?.defaultPermissions
    || (managedProfiles ? profiles.find((profile) => profile.allowed)?.id : "")
    || "";
  const profileMode = managedProfiles || Boolean(state.config.default_permissions);

  elements.settingsPermissionProfileField.hidden = !profileMode && !profiles.length;
  elements.settingsPermissionProfile.replaceChildren();
  if (!managedProfiles) {
    elements.settingsPermissionProfile.append(dataOption(
      profileMode ? "切回传统批准与沙箱模式" : "传统批准与沙箱模式（当前）",
      "__legacy__",
    ));
  }
  if (!profiles.length) {
    elements.settingsPermissionProfile.append(dataOption("没有可用权限配置", ""));
  }
  for (const profile of profiles) {
    const option = dataOption(
      `${permissionProfileLabel(profile.id)}${profile.allowed ? "" : "（管理员已禁用）"}`,
      profile.id,
    );
    option.disabled = !profile.allowed;
    option.title = profile.description || (profile.allowed ? "可用" : "被管理员策略禁用");
    elements.settingsPermissionProfile.append(option);
  }
  if (
    selectedProfile
    && !profiles.some((profile) => profile.id === selectedProfile)
  ) {
    const option = dataOption(`${permissionProfileLabel(selectedProfile)}（当前值不可用）`, selectedProfile);
    option.disabled = true;
    elements.settingsPermissionProfile.append(option);
  }
  elements.settingsPermissionProfile.value = profileMode ? selectedProfile : "__legacy__";
  elements.settingsPermissionProfile.disabled = !profiles.some((profile) => profile.allowed);
  elements.settingsPermissionProfileState.textContent = managedProfiles
    ? "管理员已启用权限配置模式；旧的批准策略和沙箱选项不再决定最终权限。"
    : "权限配置会同时决定文件、命令和网络边界。";

  const approvalAllowed = requirements?.allowedApprovalPolicies;
  const reviewerAllowed = requirements?.allowedApprovalsReviewers;
  const sandboxAllowed = requirements?.allowedSandboxModes;
  const searchAllowed = requirements?.allowedWebSearchModes;
  applyManagedSelectOptions(
    elements.settingsApproval,
    profileMode ? [] : approvalAllowed,
    profileMode ? "权限配置模式已接管批准策略" : "被管理员策略禁用",
  );
  applyManagedSelectOptions(
    elements.settingsApprovalsReviewer,
    reviewerAllowed,
    "被管理员策略禁用",
  );
  applyManagedSelectOptions(
    elements.settingsSandbox,
    profileMode ? [] : sandboxAllowed,
    profileMode ? "权限配置模式已接管沙箱" : "被管理员策略禁用",
  );
  applyManagedSelectOptions(elements.settingsWebSearch, searchAllowed, "被管理员策略禁用");

  const summaries = [];
  if (state.codexPolicy.error) summaries.push(`协议状态：${state.codexPolicy.error}`);
  summaries.push(`账号边界：当前用户工程与独立 Unix 身份`);
  if (requirements) {
    summaries.push(`管理员策略：${managedProfiles ? "强制权限配置模式" : "限制可选批准与沙箱范围"}`);
  } else {
    summaries.push("管理员策略：未配置额外 requirements.toml 限制");
  }
  if (profileMode) {
    summaries.push(`用户选择：${permissionProfileLabel(selectedProfile)}`);
    const effective = profiles.find((profile) => profile.id === selectedProfile);
    summaries.push(`最终生效：${effective?.allowed ? permissionProfileLabel(selectedProfile) : "当前配置不可用，请重新选择"}`);
  } else {
    summaries.push(`用户选择：${approvalLabels[elements.settingsApproval.value] || elements.settingsApproval.value} · ${sandboxLabels[elements.settingsSandbox.value] || elements.settingsSandbox.value}`);
    summaries.push("最终生效：账号边界 ∩ 管理员策略 ∩ 当前选择");
  }
  summaries.push(`审批复核：${approvalsReviewerLabels[elements.settingsApprovalsReviewer.value] || elements.settingsApprovalsReviewer.value}`);
  elements.settingsPolicySummary.hidden = false;
  elements.settingsPolicySummary.replaceChildren(...summaries.map((text) => {
    const line = document.createElement("p");
    line.textContent = text;
    return line;
  }));
}

function applyManagedSelectOptions(select, allowed, disabledReason) {
  const constrained = Array.isArray(allowed);
  for (const option of select.options) {
    const optionAllowed = !constrained || allowed.includes(option.value);
    option.disabled = !optionAllowed;
    option.title = optionAllowed ? "" : disabledReason;
  }
  select.disabled = constrained && ![...select.options].some((option) => !option.disabled);
  if (constrained && select.selectedOptions[0]?.disabled) {
    const firstAllowed = [...select.options].find((option) => !option.disabled);
    if (firstAllowed) select.value = firstAllowed.value;
  }
}

function previewPermissionProfileSelection() {
  const profileMode = Boolean(elements.settingsPermissionProfile.value)
    && elements.settingsPermissionProfile.value !== "__legacy__";
  const requirements = state.codexPolicy.requirements;
  applyManagedSelectOptions(
    elements.settingsApproval,
    profileMode ? [] : requirements?.allowedApprovalPolicies,
    profileMode ? "权限配置模式已接管批准策略" : "被管理员策略禁用",
  );
  applyManagedSelectOptions(
    elements.settingsSandbox,
    profileMode ? [] : requirements?.allowedSandboxModes,
    profileMode ? "权限配置模式已接管沙箱" : "被管理员策略禁用",
  );
  elements.settingsPermissionProfileState.textContent = profileMode
    ? `${permissionProfileLabel(elements.settingsPermissionProfile.value)} 将成为后续任务的最终权限配置。`
    : "继续使用批准策略与沙箱的传统组合。";
}

function permissionProfileLabel(id) {
  return {
    ":read-only": "只读",
    ":workspace": "工作区写入",
    ":danger-full-access": "完全访问",
  }[id] || id || "未选择";
}

async function submitSettings(event) {
  if (event.submitter?.value === "cancel") return;
  event.preventDefault();
  const applyToBranch = event.submitter?.value === "apply-branch";
  if (applyToBranch && (!state.activeThread || conversationBusy())) {
    elements.settingsError.textContent = "当前对话正在运行或尚未打开，无法创建新分支";
    return;
  }
  elements.saveSettingsButton.disabled = true;
  elements.applySettingsToBranchButton.disabled = true;
  elements.settingsError.textContent = "";
  const wantsBrowserNotifications = elements.notifyTaskCompleteInput.checked
    || elements.notifyApprovalInput.checked
    || elements.notifyQuestionInput.checked;
  const notificationPermission = wantsBrowserNotifications
    && "Notification" in window
    && Notification.permission === "default"
    ? Notification.requestPermission()
    : Promise.resolve("Notification" in window ? Notification.permission : "unsupported");
  const previousModel = state.selectedModel;
  const values = {
    model: elements.settingsModel.value,
    model_reasoning_effort: elements.settingsEffort.value,
    approvals_reviewer: elements.settingsApprovalsReviewer.value,
    web_search: elements.settingsWebSearch.value,
  };
  const contextWindowSelection = elements.settingsContextWindow.value;
  if (contextWindowSelection !== "__preserve__") {
    const currentContextWindow = positiveTokenCount(state.config.model_context_window);
    const nextContextWindow = contextWindowSelection === ""
      ? null
      : Number(contextWindowSelection);
    if (nextContextWindow !== currentContextWindow) {
      values.model_context_window = nextContextWindow;
    }
  }
  const profileMode = !elements.settingsPermissionProfileField.hidden
    && Boolean(elements.settingsPermissionProfile.value)
    && elements.settingsPermissionProfile.value !== "__legacy__";
  if (values.approvals_reviewer === "auto_review") {
    const effectiveWorkspace = profileMode
      ? elements.settingsPermissionProfile.value === ":workspace"
      : elements.settingsSandbox.value === "workspace-write";
    if (!effectiveWorkspace) {
      elements.settingsError.textContent = "官方 --approve-for-me 必须使用“工作区写入”权限；请先选择该权限配置或沙箱。";
      elements.saveSettingsButton.disabled = false;
      elements.applySettingsToBranchButton.disabled = !state.activeThread || conversationBusy();
      return;
    }
  }
  if (profileMode) values.default_permissions = elements.settingsPermissionProfile.value;
  else {
    if (state.config.default_permissions) values.default_permissions = null;
    values.approval_policy = elements.settingsApproval.value;
    values.sandbox_mode = elements.settingsSandbox.value;
  }
  try {
    for (const [keyPath, value] of Object.entries(values)) {
      await rpc("config/value/write", {
        keyPath,
        value,
        mergeStrategy: "replace",
        _wflProjectCwd: state.currentProject.path,
      });
    }
    await saveCodexThreadLimitFromSettings();
    await saveCodexMemorySettingsFromForm();
    state.config = { ...state.config, ...values };
    state.selectedModel = values.model;
    rememberCodexModel(values.model);
    state.selectedEffort = values.model_reasoning_effort;
    if (state.selectedEffort !== "ultra") rememberSoloEffort(state.selectedEffort);
    state.ui.compact = elements.compactModeInput.checked;
    state.ui.showToolOutput = elements.showToolOutputInput.checked;
    state.ui.expandFileChanges = elements.expandFileChangesInput.checked;
    state.ui.expandFileEdits = elements.expandFileEditsInput.checked;
    state.ui.showSystemStatus = elements.showSystemStatusInput.checked;
    state.ui.projectPanePersistent = elements.projectPanePersistentInput.checked;
    state.ui.threadPanePersistent = elements.threadPanePersistentInput.checked;
    state.ui.notifyTaskComplete = elements.notifyTaskCompleteInput.checked;
    state.ui.notifyApproval = elements.notifyApprovalInput.checked;
    state.ui.notifyQuestion = elements.notifyQuestionInput.checked;
    localStorage.setItem("codexDesktop.compact", String(state.ui.compact));
    localStorage.setItem("codexDesktop.showToolOutput", String(state.ui.showToolOutput));
    localStorage.setItem("codexDesktop.expandFileChanges", String(state.ui.expandFileChanges));
    localStorage.setItem("codexDesktop.expandFileEdits", String(state.ui.expandFileEdits));
    localStorage.setItem("codexDesktop.showSystemStatus", String(state.ui.showSystemStatus));
    localStorage.setItem("codexDesktop.projectPanePersistent", String(state.ui.projectPanePersistent));
    localStorage.setItem("codexDesktop.threadPanePersistent", String(state.ui.threadPanePersistent));
    localStorage.setItem("codexDesktop.notifyTaskComplete", String(state.ui.notifyTaskComplete));
    localStorage.setItem("codexDesktop.notifyApproval", String(state.ui.notifyApproval));
    localStorage.setItem("codexDesktop.notifyQuestion", String(state.ui.notifyQuestion));
    const permission = await notificationPermission;
    if (wantsBrowserNotifications && permission !== "granted") {
      toast(permission === "denied" ? "浏览器已禁止通知，可在站点权限中重新开启" : "当前浏览器不支持系统通知", "warning");
    }
    applyUiPreferences();
    populateModelSelects();
    updatePolicyStatus();
    if (state.activeThread) {
      await updateThreadSettings({ modelChanged: previousModel !== state.selectedModel });
    }
    elements.settingsDialog.close();
    if (applyToBranch) await forkThread();
    else toast("默认设置已保存");
  } catch (error) {
    elements.settingsError.textContent = error.message;
  } finally {
    elements.saveSettingsButton.disabled = false;
    elements.applySettingsToBranchButton.disabled = !state.activeThread || conversationBusy();
  }
}

function applyUiPreferences() {
  elements.desktop.classList.toggle("compact-messages", state.ui.compact);
  elements.desktop.classList.remove("hide-tool-output");
  elements.desktop.classList.toggle("project-pane-persistent", state.ui.projectPanePersistent);
  elements.desktop.classList.toggle("thread-pane-persistent", state.ui.threadPanePersistent);
  elements.systemStatus.hidden = !state.ui.showSystemStatus;
  if (state.activeThread) renderMessages(true);
  closeMobilePanels();
  refreshIcons();
}

async function loadSystemStatus() {
  if (!state.ui.showSystemStatus || state.systemStatusRequestPending) return;
  state.systemStatusRequestPending = true;
  const controller = new AbortController();
  state.systemStatusController = controller;
  const timeout = setTimeout(() => controller.abort(), STATUS_REQUEST_TIMEOUT_MS);
  try {
    const response = await fetch(`/api/system/status?_=${Date.now()}`, {
      cache: "no-store",
      signal: controller.signal,
    });
    const data = await response.json();
    if (!response.ok) throw new Error(data.error || "无法读取服务状态");
    state.systemStatusHasData = true;
    elements.systemStatus.innerHTML = `<i data-lucide="${data.scope === "account" ? "hard-drive" : "activity"}"></i>`;
    if (data.scope === "account") {
      const storageStatus = document.createElement("span");
      storageStatus.className = "system-status-primary";
      storageStatus.textContent = `空间 ${formatStorage(data.storage.usedBytes)} / ${formatStorage(data.storage.totalBytes)}`;
      elements.systemStatus.append(storageStatus);
      elements.systemStatus.title = `个人空间 ${formatStorage(data.storage.usedBytes)} / ${formatStorage(data.storage.totalBytes)}\n${data.storage.quotaMode === "filesystem" ? "文件系统硬配额" : "应用配额"}`;
      refreshIcons();
      return;
    }
    const resourceMetrics = [
      ["cpu", "CPU", data.cpuPercent],
      ["memory", "内存", data.memory.percent],
      ["disk", "磁盘", data.disk.percent],
    ];
    const additionalDisks = (Array.isArray(data.disks) ? data.disks : [])
      .filter((disk) => disk && disk.primary !== true);
    for (const [index, disk] of additionalDisks.entries()) {
      resourceMetrics.push([
        `disk-storage-${index}`,
        disk.label || (disk.kind === "data" ? "数据盘" : "存储盘"),
        disk.percent,
      ]);
    }
    for (const [name, label, value] of resourceMetrics) {
      const metric = document.createElement("span");
      const disk = additionalDisks.find((_entry, index) => name === `disk-storage-${index}`);
      metric.className = `system-status-metric system-status-${name}`
        + (disk?.kind === "data" ? " system-status-data-disk" : disk ? " system-status-other-disk" : "");
      metric.dataset.label = label;
      metric.textContent = formatPercent(value);
      elements.systemStatus.append(metric);
    }
    elements.systemStatus.title = [
      `CPU ${formatPercent(data.cpuPercent)}`,
      `内存 ${formatBytes(data.memory.usedBytes)} / ${formatBytes(data.memory.totalBytes)}`,
      `磁盘 ${formatBytes(data.disk.usedBytes)} / ${formatBytes(data.disk.totalBytes)}`,
      ...additionalDisks.map((disk) => `${disk.label || "存储盘"} ${disk.mountPoint || ""} ${formatBytes(disk.usedBytes)} / ${formatBytes(disk.totalBytes)}`.trim()),
      `服务运行 ${formatDuration(data.uptimeSeconds)}`,
    ].join("\n");
    refreshIcons();
  } catch (error) {
    if (!state.systemStatusHasData && error.name !== "AbortError") {
      elements.systemStatus.innerHTML = '<i data-lucide="activity"></i><span class="system-status-primary">状态暂不可用</span>';
      refreshIcons();
    }
  } finally {
    clearTimeout(timeout);
    if (state.systemStatusController === controller) {
      state.systemStatusController = null;
      state.systemStatusRequestPending = false;
    }
  }
}

function cancelSystemStatusRequest() {
  state.systemStatusController?.abort();
  state.systemStatusController = null;
  state.systemStatusRequestPending = false;
}

function scheduleSystemStatusPoll(delay = document.visibilityState === "hidden"
  ? SYSTEM_STATUS_HIDDEN_POLL_MS
  : SYSTEM_STATUS_VISIBLE_POLL_MS) {
  clearTimeout(state.systemStatusTimer);
  state.systemStatusTimer = setTimeout(async () => {
    state.systemStatusTimer = null;
    await loadSystemStatus();
    scheduleSystemStatusPoll();
  }, delay);
}

async function loadTaskStatus({ force = false } = {}) {
  if (state.taskStatusRequestPending) {
    if (!force) return;
    cancelTaskStatusRequest();
  }
  const threadId = state.activeThread?.id || null;
  // Keep the Turn identity that this request was issued for. A terminal
  // response for an older Turn can otherwise arrive after a new Turn starts
  // and, because the server correctly reports canSend=true for the old Turn,
  // release the new Turn's composer fence.
  const requestedTurnId = state.activeTurnId || state.codexActiveTurnId || null;
  const selectionVersion = state.threadSelectionVersion;
  const authorityVersion = threadId ? (state.threadTaskAuthorityVersions.get(threadId) || 0) : 0;
  state.taskStatusRequestPending = true;
  const controller = new AbortController();
  state.taskStatusController = controller;
  const timeout = setTimeout(() => controller.abort(), STATUS_REQUEST_TIMEOUT_MS);
  try {
    const query = threadId
      ? new URLSearchParams({
        threadId,
        includeThreads: "1",
        ...(requestedTurnId ? { activeTurnId: requestedTurnId } : {}),
        _: String(Date.now()),
      })
      : new URLSearchParams({ scope: "threads", _: String(Date.now()) });
    const response = await fetch(`/api/task/status?${query}`, {
      cache: "no-store",
      signal: controller.signal,
    });
    const data = await response.json();
    if (!response.ok) throw new Error(data.error || "无法读取任务状态");
    if (
      state.taskStatusController !== controller
      || selectionVersion !== state.threadSelectionVersion
      || threadId !== (state.activeThread?.id || null)
      || !taskStatusResponseMatchesCurrentTurn(data, requestedTurnId)
      || (threadId && authorityVersion !== (state.threadTaskAuthorityVersions.get(threadId) || 0))
    ) return;
    state.taskStatusFailures = 0;
    rememberThreadTaskStatuses(data.tasks);
    if (threadId) renderTaskStatus(data);
    else {
      state.taskStatusSnapshot = null;
      refreshTaskStatusVisibility();
    }
  } catch (error) {
    if (
      error.name === "AbortError"
      || state.taskStatusController !== controller
      || selectionVersion !== state.threadSelectionVersion
      || threadId !== (state.activeThread?.id || null)
      || requestedTurnId !== (state.activeTurnId || state.codexActiveTurnId || null)
      || (threadId && authorityVersion !== (state.threadTaskAuthorityVersions.get(threadId) || 0))
    ) return;
    state.taskStatusFailures += 1;
    if (state.taskStatusFailures >= TASK_STATUS_FAILURE_THRESHOLD) {
      renderTaskStatus({
        status: "unavailable",
        phase: "unavailable",
        threadId: state.taskStatusSnapshot?.threadId || null,
      });
    }
  } finally {
    clearTimeout(timeout);
    if (state.taskStatusController === controller) {
      state.taskStatusController = null;
      state.taskStatusRequestPending = false;
      scheduleTaskStatusPoll(taskStatusPollDelay());
    }
  }
}

function taskStatusResponseMatchesCurrentTurn(snapshot, requestedTurnId) {
  const currentTurnId = state.activeTurnId || state.codexActiveTurnId || null;
  if (requestedTurnId === currentTurnId) return true;
  // A completion notification can clear the client pointer while a status
  // request issued just before that notification is still in flight. Accept
  // that response only when the server explicitly confirms the requested Turn
  // is terminal and can no longer block sending.
  return Boolean(
    requestedTurnId
    && !currentTurnId
    && TERMINAL_TASK_STATUSES.has(snapshot?.status)
    && snapshot.authoritative === true
    && snapshot.canSend === true
    && [snapshot.turnId, snapshot.staleTurnId, snapshot.activeTurnId].includes(requestedTurnId)
  );
}

function cancelTaskStatusRequest() {
  state.taskStatusController?.abort();
  state.taskStatusController = null;
  state.taskStatusRequestPending = false;
}

function synchronizeActiveConversation() {
  sendClientState();
  synchronizeApprovalView();
  void loadTaskStatus({ force: true });
}

function scheduleTaskStatusPoll(delay) {
  clearTimeout(state.taskStatusTimer);
  state.taskStatusTimer = setTimeout(loadTaskStatus, delay);
}

function taskStatusPollDelay() {
  if (document.visibilityState === "hidden") return STATUS_HIDDEN_POLL_MS;
  const active = state.imageTaskStatusSnapshot?.status === "running"
    || ACTIVE_TASK_STATUSES.has(state.taskStatusSnapshot?.status)
    || [...state.threadTaskStatuses.values()]
      .some((task) => ACTIVE_TASK_STATUSES.has(task.status));
  const baseDelay = active ? TASK_STATUS_ACTIVE_POLL_MS : TASK_STATUS_IDLE_POLL_MS;
  return Math.min(60_000, baseDelay * (2 ** Math.min(state.taskStatusFailures, 2)));
}

function rememberThreadTaskStatuses(tasks) {
  const next = new Map();
  for (const task of Array.isArray(tasks) ? tasks : []) {
    if (
      typeof task?.threadId !== "string"
      || !Object.hasOwn(taskStatusLabels, task.status)
      || task.status === "idle"
    ) continue;
    next.set(task.threadId, {
      status: task.status,
      phase: typeof task.phase === "string" ? task.phase : task.status,
      threadId: task.threadId,
      turnId: typeof task.turnId === "string" ? task.turnId : null,
      cwd: typeof task.cwd === "string" ? task.cwd : null,
      queuedAt: Number(task.queuedAt) || null,
      startedAt: Number(task.startedAt) || null,
      updatedAt: Number(task.updatedAt) || null,
      finishedAt: Number(task.finishedAt) || null,
    });
  }
  state.threadTaskStatusesReady = true;
  if (taskStatusMapsEqual(state.threadTaskStatuses, next)) {
    renderSidebarWorktrees();
    return;
  }
  state.threadTaskStatuses = next;
  renderProjects();
  renderThreads();
  renderSidebarWorktrees();
  queueTaskCenterRender();
}

function taskStatusMapsEqual(left, right) {
  if (left.size !== right.size) return false;
  for (const [threadId, task] of left) {
    const candidate = right.get(threadId);
    if (!candidate) return false;
    for (const field of ["status", "phase", "turnId", "cwd", "queuedAt", "startedAt", "updatedAt", "finishedAt"]) {
      if (task[field] !== candidate[field]) return false;
    }
  }
  return true;
}

function taskProjectPath(task) {
  if (task?.cwd) return task.cwd;
  const thread = state.threads.find((entry) => entry.id === task?.threadId)
    || conversationThreadById(task?.threadId, task?.cwd);
  return thread?.cwd || null;
}

function projectTaskStatus(projectPath) {
  const tasks = [...state.threadTaskStatuses.values()]
    .filter((task) => taskProjectPath(task) === projectPath);
  if (!tasks.length) return null;
  const rank = {
    uncertain: 8,
    waiting: 7,
    stopping: 6,
    running: 5,
    queued: 4,
    failed: 3,
    interrupted: 2,
    completed: 1,
  };
  tasks.sort((left, right) => (
    (rank[right.status] || 0) - (rank[left.status] || 0)
    || (right.updatedAt || 0) - (left.updatedAt || 0)
  ));
  const selected = tasks[0];
  const activeCount = tasks.filter((task) => ACTIVE_TASK_STATUSES.has(task.status)).length;
  const count = activeCount || tasks.filter((task) => task.status === selected.status).length;
  return {
    status: selected.status,
    count,
    title: tasks.slice(0, 6).map((task) => {
      const status = taskStatusLabels[task.status] || task.status;
      const phase = taskPhaseLabels[task.phase] || task.phase || "";
      return `${status}${phase ? ` · ${phase}` : ""}`;
    }).join("\n"),
  };
}

function renderTaskStatus(snapshot) {
  const status = Object.hasOwn(taskStatusLabels, snapshot?.status) ? snapshot.status : "unavailable";
  const previousStatus = visibleTaskStatusSnapshot()?.status;
  const nearBottom = elements.messageStage.scrollHeight - elements.messageStage.scrollTop - elements.messageStage.clientHeight < 140;
  state.taskStatusSnapshot = { ...snapshot, status };
  if (
    state.activeThread?.id === snapshot?.threadId
    && ACTIVE_TASK_STATUSES.has(status)
  ) {
    // A fresh active snapshot supersedes any weak terminal authority left by
    // a delayed idle/completed event. The current Turn is authoritative again.
    state.codexTerminalTaskAuthorities.delete(snapshot.threadId);
  }
  synchronizeTerminalTaskSnapshot(state.taskStatusSnapshot);
  if (
    state.imageTaskStatusSnapshot?.handoff
    && snapshot?.threadId === state.imageTaskStatusSnapshot.threadId
    && !["idle", "unavailable"].includes(status)
  ) {
    state.imageTaskStatusSnapshot = null;
  }
  const visible = refreshTaskStatusVisibility();
  // Runtime task status is informational and powers task controls. Official
  // Turn notifications alone own the chat lifecycle and composer gate.
  setTurnBusy(conversationBusy(), conversationBusyLabel());
  if (visible && ACTIVE_TASK_STATUSES.has(status) && (nearBottom || previousStatus !== status)) {
    requestAnimationFrame(scrollMessagesToBottom);
  }
}

const TERMINAL_TASK_STATUSES = new Set([
  "completed",
  "failed",
  "interrupted",
  "cancelled",
  "canceled",
  "idle",
]);

function taskAuthorityTimestamp(snapshot = {}) {
  for (const value of [
    snapshot.finishedAt,
    snapshot.completedAt,
    snapshot.updatedAt,
    snapshot.observedAt,
  ]) {
    const normalized = normalizeMessageTimestamp(value);
    if (normalized !== null) return normalized;
  }
  return Date.now();
}

function rememberCodexTerminalTaskAuthority(snapshot = {}, { source = "task-status" } = {}) {
  const threadId = typeof snapshot.threadId === "string" && snapshot.threadId
    ? snapshot.threadId
    : null;
  if (!threadId || !TERMINAL_TASK_STATUSES.has(snapshot.status)) return null;
  const explicitTurnId = typeof snapshot.turnId === "string" && snapshot.turnId
    ? snapshot.turnId
    : null;
  const staleTurnId = typeof snapshot.staleTurnId === "string" && snapshot.staleTurnId
    ? snapshot.staleTurnId
    : null;
  const authoritativeCanSend = snapshot.authoritative === true && snapshot.canSend === true;
  if (!authoritativeCanSend && !explicitTurnId && !staleTurnId) return null;
  const previous = state.codexTerminalTaskAuthorities.get(threadId);
  const capturedTurnIds = state.activeThread?.id === threadId
    ? localInProgressTurnIds()
    : [];
  const identifiedTurnIds = uniqueTurnIds([explicitTurnId, staleTurnId]);
  const authority = {
    threadId,
    status: taskStatusTerminalTurnStatus(snapshot.status),
    turnId: explicitTurnId,
    staleTurnId,
    canSend: authoritativeCanSend,
    source,
    observedAt: taskAuthorityTimestamp(snapshot),
    pointerAtObservation: state.activeThread?.id === threadId
      ? (state.activeTurnId || state.codexActiveTurnId || null)
      : null,
    capturedTurnIds: identifiedTurnIds.length
      ? identifiedTurnIds
      : uniqueTurnIds([
        ...(previous?.capturedTurnIds || []),
        ...(capturedTurnIds.length === 1 ? capturedTurnIds : []),
      ]),
    fencedTurnIds: uniqueTurnIds(previous?.fencedTurnIds || []),
  };
  state.codexTerminalTaskAuthorities.set(threadId, authority);
  return authority;
}

function terminalTaskAuthorityTurnIds(authority, turns = []) {
  if (!authority) return new Set();
  const candidates = (Array.isArray(turns) ? turns : [])
    .filter((turn) => (
      turn?.id
      && turnStatusType(turn) === "inProgress"
      && !state.codexTerminalTurnIds.has(turn.id)
    ));
  const ids = new Set(uniqueTurnIds([
    authority.turnId,
    authority.staleTurnId,
    ...(authority.capturedTurnIds || []),
    ...(authority.fencedTurnIds || []),
  ]));
  if (ids.size || candidates.length !== 1) return ids;
  const candidate = candidates[0];
  const startedAt = turnStartedTimestamp(candidate);
  // When the server omitted the Turn ID, only infer a single historical Turn
  // that was already present when the authoritative idle snapshot was read.
  // An explicitly newer Turn must remain sendable.
  if (startedAt === null || startedAt <= authority.observedAt + 2_000) ids.add(candidate.id);
  return ids;
}

function fenceCodexTurnsByTaskAuthority(threadId, turns) {
  const authority = state.codexTerminalTaskAuthorities.get(threadId);
  if (!authority) return turns;
  const targetIds = terminalTaskAuthorityTurnIds(authority, turns);
  if (!targetIds.size) return turns;
  let changed = false;
  const fenced = (Array.isArray(turns) ? turns : []).map((turn) => {
    if (!turn?.id || !targetIds.has(turn.id) || turnStatusType(turn) !== "inProgress") return turn;
    const status = authority.status || "completed";
    rememberCodexTerminalTurn(turn.id, status);
    changed = true;
    return { ...turn, status };
  });
  if (changed) {
    authority.fencedTurnIds = uniqueTurnIds([
      ...(authority.fencedTurnIds || []),
      ...targetIds,
    ]);
    state.codexTerminalTaskAuthorities.set(threadId, authority);
  }
  return fenced;
}

function taskStatusTerminalTurnStatus(status) {
  if (status === "failed") return "failed";
  if (["interrupted", "cancelled", "canceled"].includes(status)) return "interrupted";
  return "completed";
}

function synchronizeTerminalTaskSnapshot(snapshot) {
  if (
    !snapshot
    || !TERMINAL_TASK_STATUSES.has(snapshot.status)
    || snapshot.threadId !== state.activeThread?.id
  ) return false;

  const authority = rememberCodexTerminalTaskAuthority(snapshot);
  // TaskStatusTracker keeps the finished Turn ID in a terminal snapshot. It
  // is the only safe identity to use here: an old completion must never clear
  // a newer Turn that may already be running in the same conversation.
  const explicitTurnId = typeof snapshot.turnId === "string" && snapshot.turnId
    ? snapshot.turnId
    : null;
  const authoritativeCanSend = snapshot.authoritative === true && snapshot.canSend === true;
  const turnId = explicitTurnId
    || (typeof snapshot.staleTurnId === "string" && snapshot.staleTurnId ? snapshot.staleTurnId : null)
    || authority?.capturedTurnIds?.find((candidate) => (
      state.activeThread.turns?.some((turn) => turn?.id === candidate && turnStatusType(turn) === "inProgress")
    ))
    || (authoritativeCanSend && localInProgressTurnIds().length <= 1
      ? (state.activeTurnId || state.codexActiveTurnId || null)
      : null);

  const terminalStatus = taskStatusTerminalTurnStatus(snapshot.status);
  const localTurn = turnId
    ? state.activeThread.turns?.find((turn) => turn?.id === turnId) || null
    : null;
  const terminalTurnMatchedPointer = Boolean(
    authoritativeCanSend
    &&
    turnId
    && (state.activeTurnId === turnId || state.codexActiveTurnId === turnId)
  );
  let changed = false;
  if (localTurn && turnStatusType(localTurn) === "inProgress") {
    upsertTurn({ ...localTurn, status: terminalStatus });
    changed = true;
  }
  if (turnId) rememberCodexTerminalTurn(turnId, terminalStatus);

  for (const pointerName of ["activeTurnId", "codexActiveTurnId"]) {
    if (!turnId || state[pointerName] !== turnId) continue;
    state[pointerName] = null;
    changed = true;
  }
  if (changed || (authoritativeCanSend && !state.activeTurnId && !state.codexActiveTurnId)) {
    state.interruptRequestPending = false;
  }

  // A delivery-unknown turn may only exist in the recent history response.
  // Settle it when the matching client identity is present; otherwise leave
  // the request fenced until refreshRecentTurns can prove its identity.
  const pending = state.pendingTurnRequest;
  if (pending?.params?.threadId === snapshot.threadId) {
    const clientMatches = pending.params.clientUserMessageId
      && snapshot.clientSubmissionId
      && pending.params.clientUserMessageId === snapshot.clientSubmissionId;
    const turnMatches = localTurn && pendingTurnRequestMatchesTurn(
      pending,
      snapshot.threadId,
      localTurn,
      { turnId, turn: localTurn },
    );
    if (clientMatches || turnMatches || terminalTurnMatchedPointer) {
      commitPendingTurnRequest(pending);
      changed = true;
    }
  }

  clearStaleCodexTurnPointers(turnId);
  if (authority) {
    const fenced = fenceCodexTurnsByTaskAuthority(snapshot.threadId, state.activeThread.turns || []);
    if (fenced.some((turn, index) => turn !== state.activeThread.turns[index])) {
      replaceActiveConversationThread({ ...state.activeThread, turns: fenced });
      changed = true;
    }
  }
  if (changed) renderConversationUpdate();
  if (pending && state.pendingTurnRequest === pending && state.activeThread?.id === snapshot.threadId) {
    scheduleRecentTurnsRefresh(snapshot.threadId, 0);
  }
  return changed;
}

function invalidateThreadTaskAuthority(threadId) {
  if (!threadId) return;
  state.codexTerminalTaskAuthorities.delete(threadId);
  state.threadTaskAuthorityVersions.set(
    threadId,
    (state.threadTaskAuthorityVersions.get(threadId) || 0) + 1,
  );
}

function applyTaskAuthorityToActiveTurn(threadId, projectedTurnId = null) {
  if (!threadId || threadId !== state.activeThread?.id) return false;
  const projectedTurn = projectedTurnId
    ? state.activeThread.turns?.find((turn) => turn?.id === projectedTurnId)
    : null;
  const authority = state.codexTerminalTaskAuthorities.get(threadId);
  const unresolvedCandidates = authority?.canSend
    ? localInProgressTurnIds()
    : [];
  const projectionIsAmbiguous = Boolean(
    authority?.canSend
    && unresolvedCandidates.length > 1
    && !authority.turnId
    && !authority.staleTurnId
    && !(authority.fencedTurnIds || []).includes(projectedTurnId),
  );
  const nextTurnId = projectedTurn
    && turnStatusType(projectedTurn) === "inProgress"
    && !state.codexTerminalTurnIds.has(projectedTurn.id)
    && !projectionIsAmbiguous
    ? projectedTurn.id
    : null;
  const previousTurnId = state.activeTurnId;
  const previousCodexTurnId = state.codexActiveTurnId;
  state.activeTurnId = nextTurnId;
  state.codexActiveTurnId = nextTurnId;
  return previousTurnId !== state.activeTurnId || previousCodexTurnId !== state.codexActiveTurnId;
}

function refreshTaskStatusVisibility() {
  const existingSnapshot = visibleTaskStatusSnapshot();
  const agents = summarizeSubagents(state.activeThread);
  const snapshot = existingSnapshot || (
    agents.active > 0
    && state.activeThread?.id
    && state.activeTurnId
      ? {
          status: "running",
          phase: "collaboration",
          threadId: state.activeThread.id,
          turnId: state.activeTurnId,
          startedAt: collaborationTaskStartedAt(state.activeThread, agents),
          finishedAt: null,
        }
      : null
  );
  if (!snapshot) {
    elements.taskStatusBar.hidden = true;
    return false;
  }
  const status = Object.hasOwn(taskStatusLabels, snapshot.status) ? snapshot.status : "unavailable";
  const label = taskStatusLabels[status];
  const baseDetail = snapshot.detail
    || taskPhaseLabels[snapshot.phase]
    || (status === "unavailable" ? "正在自动重试" : "处理中");
  const activeAgents = ACTIVE_TASK_STATUSES.has(status) && state.activeTurnId
    ? agents.active
    : 0;
  const detailParts = [baseDetail];
  if (activeAgents > 0) detailParts.push(`${activeAgents} 个子代理运行中`);
  const detail = detailParts.join(" · ");
  const time = taskStatusTime(snapshot, status);
  elements.taskStatusBar.dataset.status = status;
  elements.taskStatusLabel.textContent = label;
  elements.taskStatusDetail.textContent = detail;
  elements.taskStatusTime.textContent = time;
  elements.taskStatusBar.title = `${label} · ${detail} · ${time}`;
  elements.taskStatusBar.hidden = false;
  return true;
}

function visibleTaskStatusSnapshot() {
  const image = state.imageTaskStatusSnapshot;
  if (image) {
    const sameConversation = image.threadId
      ? image.threadId === state.activeThread?.id
      : !state.activeThread && image.selectionVersion === state.threadSelectionVersion;
    if (sameConversation) return image;
  }
  const snapshot = state.taskStatusSnapshot;
  if (state.activeThread?.id && snapshot?.threadId === state.activeThread.id && snapshot.status !== "idle") {
    return snapshot;
  }
  return null;
}

function summarizeSubagents(thread) {
  const agents = state.threadSubagents.get(thread?.id);
  const values = agents ? [...agents.values()] : [];
  const active = values.filter((entry) => (
    ["pendingInit", "running"].includes(normalizeSubagentStatus(entry.status))
  ));
  const statuses = values.map((entry) => normalizeSubagentStatus(entry.status));
  const startedAt = active
    .map((entry) => nonnegativeGoalInteger(entry.startedAt))
    .filter(Boolean)
    .sort((left, right) => left - right)[0] || null;
  return {
    total: statuses.length,
    active: active.length,
    failed: statuses.filter((status) => ["errored", "notFound"].includes(status)).length,
    startedAt,
  };
}

function collaborationTaskStartedAt(thread, agents) {
  const activeTurn = (thread?.turns || []).find((turn) => turn.id === state.activeTurnId);
  return normalizeMessageTimestamp(
    activeTurn?.startedAt ?? activeTurn?.createdAt ?? activeTurn?._displayCreatedAt,
  ) || agents.startedAt || null;
}

function settleCompletedCollaborationTurn(turn) {
  if (!turn || typeof turn !== "object") return turn;
  const status = turnStatusType(turn);
  const agentStatus = terminalSubagentStatusForTurn(status);
  if (!agentStatus) return turn;
  const terminalItemStatus = agentStatus === "errored"
    ? "failed"
    : agentStatus === "interrupted" ? "interrupted" : "completed";
  let changed = false;
  const items = (turn.items || []).map((item) => {
    if (item?.type === "subAgentActivity") {
      const currentStatus = normalizeSubagentStatus(item.status, null);
      if (!["pendingInit", "running"].includes(currentStatus)) return item;
      changed = true;
      return {
        ...item,
        status: agentStatus,
        ...(agentStatus === "interrupted" ? { kind: "interrupted" } : {}),
      };
    }
    if (item?.type !== "collabAgentToolCall") return item;
    const currentItemStatus = normalizeSubagentStatus(item.status, null);
    const states = item.agentsStates && typeof item.agentsStates === "object" ? item.agentsStates : {};
    let itemChanged = ["pendingInit", "running"].includes(currentItemStatus);
    const agentsStates = Object.fromEntries(Object.entries(states).map(([agentId, agent]) => {
      if (!["pendingInit", "running"].includes(normalizeSubagentStatus(agent?.status))) return [agentId, agent];
      itemChanged = true;
      return [agentId, { ...agent, status: agentStatus }];
    }));
    if (!itemChanged) return item;
    changed = true;
    return {
      ...item,
      status: ["pendingInit", "running"].includes(currentItemStatus) ? terminalItemStatus : item.status,
      agentsStates,
    };
  });
  return changed ? { ...turn, items } : turn;
}

function inferredSubagentStatus(item) {
  const status = normalizeSubagentStatus(item?.status, null);
  if (status === "completed") return "completed";
  if (status === "errored") return "errored";
  if (status === "interrupted") return "interrupted";
  if (item?.tool === "closeAgent") return "shutdown";
  if (item?.tool === "wait" && status !== "running") return "completed";
  return "running";
}

function beginImageTaskStatus() {
  state.imageTaskStatusSnapshot = {
    status: "running",
    phase: "imageGeneration",
    detail: null,
    threadId: state.activeThread?.id || null,
    selectionVersion: state.threadSelectionVersion,
    startedAt: Date.now(),
    finishedAt: null,
    handoff: false,
  };
  refreshTaskStatusVisibility();
}

function updateImageTaskStatus(update) {
  if (!state.imageTaskStatusSnapshot) return;
  state.imageTaskStatusSnapshot = { ...state.imageTaskStatusSnapshot, ...update };
  refreshTaskStatusVisibility();
}

function bindImageTaskStatusToThread(threadId) {
  if (!state.imageTaskStatusSnapshot || state.imageTaskStatusSnapshot.threadId) return;
  updateImageTaskStatus({ threadId });
}

function finishImageTaskStatus(status) {
  if (!state.imageTaskStatusSnapshot) return;
  updateImageTaskStatus({
    status,
    phase: status,
    detail: status === "failed" ? "图片生成失败" : null,
    finishedAt: Date.now(),
    handoff: false,
  });
}

function clearImageTaskStatus(threadId = null) {
  if (!state.imageTaskStatusSnapshot) return;
  if (threadId && state.imageTaskStatusSnapshot.threadId !== threadId) return;
  state.imageTaskStatusSnapshot = null;
  refreshTaskStatusVisibility();
}

function taskStatusTime(snapshot, status) {
  if (status === "queued" && Number.isFinite(snapshot?.queuedAt)) {
    return `已排队 ${formatTaskDuration(Date.now() - snapshot.queuedAt)}`;
  }
  if (ACTIVE_TASK_STATUSES.has(status) && Number.isFinite(snapshot?.startedAt)) {
    return `已运行 ${formatTaskDuration(Date.now() - snapshot.startedAt)}`;
  }
  if (["completed", "failed", "interrupted"].includes(status) && Number.isFinite(snapshot?.finishedAt)) {
    const prefix = { completed: "完成于", failed: "失败于", interrupted: "终止于" }[status];
    const duration = Number.isFinite(snapshot?.startedAt)
      ? ` · 用时 ${formatTaskDuration(snapshot.finishedAt - snapshot.startedAt)}`
      : "";
    return `${prefix} ${formatTaskClock(snapshot.finishedAt)}${duration}`;
  }
  return status === "idle" ? "空闲" : "--";
}

function formatTaskDuration(milliseconds) {
  const seconds = Math.max(0, Math.floor((Number(milliseconds) || 0) / 1000));
  if (seconds < 60) return `${seconds} 秒`;
  const minutes = Math.floor(seconds / 60);
  if (minutes < 60) return `${minutes} 分 ${seconds % 60} 秒`;
  const hours = Math.floor(minutes / 60);
  return `${hours} 小时 ${minutes % 60} 分`;
}

function formatTaskClock(timestamp) {
  return new Date(timestamp).toLocaleTimeString(interfaceLocale(), {
    hour: "2-digit",
    minute: "2-digit",
    second: "2-digit",
    hour12: false,
  });
}

function addPolicyParams(params) {
  if (state.config.approvals_reviewer) {
    params.approvalsReviewer = state.config.approvals_reviewer;
  }
  if (state.config.default_permissions) {
    params.permissions = state.config.default_permissions;
    return params;
  }
  if (state.config.approval_policy) params.approvalPolicy = state.config.approval_policy;
  if (state.config.sandbox_mode) params.sandbox = state.config.sandbox_mode;
  return params;
}

function updatePolicyStatus() {
  const approval = normalizeApprovalPolicy(state.config.approval_policy);
  const sandbox = state.config.sandbox_mode || "workspace-write";
  elements.approvalStatus.innerHTML = '<i data-lucide="hand"></i>';
  elements.approvalStatus.append(document.createTextNode(` ${approvalLabels[approval] || approval}`));
  elements.sandboxStatus.innerHTML = '<i data-lucide="shield-check"></i>';
  elements.sandboxStatus.append(document.createTextNode(` ${sandboxLabels[sandbox] || sandbox}`));
  refreshIcons();
}

function normalizeApprovalPolicy(policy) {
  return typeof policy === "string" ? policy : "on-request";
}

function populateSettingsEfforts(modelName, preferred) {
  const model = state.models.find((entry) => entry.model === modelName) || state.models[0];
  const efforts = model?.supportedReasoningEfforts || [];
  const selected = efforts.some((entry) => entry.reasoningEffort === preferred)
    ? preferred
    : model?.defaultReasoningEffort || efforts[0]?.reasoningEffort || "medium";
  elements.settingsEffort.replaceChildren();
  for (const effort of efforts) {
    const value = effort.reasoningEffort;
    const option = new Option(effortLabels[value] || value, value);
    option.title = effort.description;
    elements.settingsEffort.add(option);
  }
  elements.settingsEffort.value = selected;
}

function compactPermissionProfile(profile) {
  if (!profile) return {};
  return Object.fromEntries(
    Object.entries(profile).filter(([, value]) => value !== null && value !== undefined),
  );
}

function rememberCodexTerminalTurn(turnId, status = "completed") {
  if (typeof turnId !== "string" || !turnId) return;
  const normalizedStatus = turnStatusType({ status }) === "inProgress"
    ? "completed"
    : (turnStatusType({ status }) || "completed");
  state.codexTerminalTurnIds.add(turnId);
  state.codexTerminalTurnStatuses.set(turnId, normalizedStatus);
  if (state.codexTerminalTurnIds.size > 256) {
    state.codexTerminalTurnIds = new Set([...state.codexTerminalTurnIds].slice(-128));
    state.codexTerminalTurnStatuses = new Map(
      [...state.codexTerminalTurnStatuses.entries()]
        .filter(([id]) => state.codexTerminalTurnIds.has(id)),
    );
  }
}

function codexTerminalTurnStatus(turnId) {
  return state.codexTerminalTurnStatuses.get(turnId) || "completed";
}

function fenceCodexTurn(turn) {
  if (!turn?.id) return turn;
  const status = turnStatusType(turn);
  if (status && status !== "inProgress") {
    rememberCodexTerminalTurn(turn.id, status);
    return turn;
  }
  if (!state.codexTerminalTurnIds.has(turn.id) || status !== "inProgress") {
    return turn;
  }
  return { ...turn, status: codexTerminalTurnStatus(turn.id) };
}

function fenceCodexTurns(turns, threadId = state.activeThread?.id) {
  const fenced = (Array.isArray(turns) ? turns : []).map(fenceCodexTurn);
  return fenceCodexTurnsByTaskAuthority(threadId, fenced);
}

function upsertTurn(turn) {
  if (!state.activeThread || !turn?.id) return turn || null;
  const activeThread = state.activeThread;
  const turns = [...(activeThread.turns || [])];
  const index = turns.findIndex((entry) => entry.id === turn.id);
  const incoming = index === -1 && !messageTimestamp(null, turn)
    ? { ...turn, _displayCreatedAt: Date.now() }
    : turn;
  const fencedIncoming = state.codexTerminalTurnIds.has(incoming.id)
    && turnStatusType(incoming) === "inProgress"
    ? { ...incoming, status: codexTerminalTurnStatus(incoming.id) }
    : incoming;
  const merged = fenceCodexTurn(mergeTurn(index === -1 ? null : turns[index], fencedIncoming));
  if (index === -1) turns.push(merged);
  else turns[index] = merged;
  replaceActiveConversationThread({
    ...activeThread,
    turns: orderTurnsChronologically(turns),
  });
  const stored = state.activeThread.turns.find((entry) => entry.id === merged.id) || merged;
  if (turnStatusType(stored) !== "inProgress") {
    rememberCodexTerminalTurn(stored.id, turnStatusType(stored));
  }
  settlePendingUserMessage(stored);
  settlePendingSteerMessages(stored);
  return stored;
}

function settlePendingUserMessage(turn, candidate) {
  const pending = state.pendingUserMessage;
  if (!pending) return;
  const items = candidate ? [candidate] : turn.items || [];
  if (items.some((item) => matchesPendingUserMessage(pending, turn.id, item))) {
    state.pendingUserMessage = null;
  }
}

function settlePendingSteerMessages(turn, candidate) {
  if (!state.pendingSteerMessages.length || !turn?.id) return;
  const items = candidate ? [candidate] : turn.items || [];
  state.pendingSteerMessages = state.pendingSteerMessages.filter((pending) =>
    pending.turnId !== turn.id
    || pending.threadId !== state.activeThread?.id
    || !items.some((item) => matchesPendingUserMessage(pending, turn.id, item)));
}

function finishPendingSteerForTurn(turnId) {
  if (!turnId) return;
  const request = state.pendingSteerRequest;
  if (request?.params.expectedTurnId === turnId) {
    const stillPending = state.pendingSteerMessages.some(
      (pending) => pending.clientId === request.pending.clientId,
    );
    if (stillPending) restorePendingSteerRequest(request);
    else {
      commitConversationImageContext(state.imageContextLedger, request.imageContextTransaction);
      rememberMapConversationImageDelivery(request.params.threadId, request.imageDelivery);
      state.pendingSteerRequest = null;
    }
  }
  state.pendingSteerMessages = state.pendingSteerMessages.filter(
    (pending) => pending.turnId !== turnId,
  );
}

function scheduleRecentTurnsRefresh(threadId, delayMs = 80, { allowFollowup = true } = {}) {
  if (!threadId) return;
  const previous = state.threadRecentRefreshTimers.get(threadId);
  if (previous) clearTimeout(previous);
  const inFlight = state.threadRecentRefreshInFlight.get(threadId);
  if (inFlight) {
    inFlight.dirty = true;
    return inFlight.promise;
  }
  const timer = setTimeout(() => {
    state.threadRecentRefreshTimers.delete(threadId);
    void refreshRecentTurns(threadId, { allowFollowup });
  }, Math.max(0, Number(delayMs) || 0));
  state.threadRecentRefreshTimers.set(threadId, timer);
}

async function refreshRecentTurns(threadId, { allowFollowup = true } = {}) {
  if (state.runtime !== "codex" || !threadId || state.activeThread?.id !== threadId) return;
  const existing = state.threadRecentRefreshInFlight.get(threadId);
  if (existing) {
    existing.dirty = true;
    return existing.promise;
  }
  const refreshVersion = (state.threadRecentRefreshVersions.get(threadId) || 0) + 1;
  state.threadRecentRefreshVersions.set(threadId, refreshVersion);
  const selectionVersion = state.threadSelectionVersion;
  const historyCursor = state.threadHistoryCursor;
  const entry = {
    dirty: false,
    allowFollowup,
    promise: null,
  };
  state.threadRecentRefreshInFlight.set(threadId, entry);
  const operation = (async () => {
    try {
      const result = await rpc("thread/turns/list", recoveryTurnsParams(threadId), {
        timeoutMs: THREAD_HISTORY_RPC_TIMEOUT_MS,
      });
      if (
        state.threadRecentRefreshVersions.get(threadId) !== refreshVersion
        || state.threadSelectionVersion !== selectionVersion
        || state.activeThread?.id !== threadId
        || state.threadHistoryCursor !== historyCursor
      ) return null;
      const recentTurns = normalizeTurnPage(result.data, "desc");
      const merged = mergeRecentTurnPage(
        state.activeThread.turns || [],
        recentTurns,
        historyCursor,
        result.nextCursor || null,
      );
      const previousProjectedTurnId = state.activeTurnId || state.codexActiveTurnId || null;
      replaceActiveConversationThread({
        ...state.activeThread,
        turns: fenceCodexTurns(merged.turns, threadId),
      });
      state.threadHistoryCursor = merged.nextCursor;
      reconcilePendingTurnRequestFromTurns(threadId, state.activeThread.turns || []);
      for (const turn of state.activeThread.turns || []) {
        settlePendingUserMessage(turn);
        settlePendingSteerMessages(turn);
        if (turnStatusType(turn) !== "inProgress") finishPendingSteerForTurn(turn.id);
      }
      const activeTurn = state.activeThread.turns?.find((turn) => turnStatusType(turn) === "inProgress");
      applyTaskAuthorityToActiveTurn(threadId, activeTurn?.id || null);
      const projectedTurnId = state.activeTurnId || state.codexActiveTurnId || null;
      if (!previousProjectedTurnId && projectedTurnId && !ACTIVE_TASK_STATUSES.has(state.taskStatusSnapshot?.status)) {
        // The history endpoint may briefly replay an old inProgress Turn after
        // the terminal event. Ask the authoritative task endpoint with this
        // exact ID so it can return staleTurnId and fence the replay instead of
        // leaving the composer locked until a full page reload.
        void loadTaskStatus({ force: true });
      }
      rebuildThreadSubagents(state.activeThread, { reset: true, persist: true });
      renderActiveThread({ preserveOptimistic: true });
      renderThreads();
      void hydrateThreadItemSummaries(threadId);
      return true;
    } catch (error) {
      if (
        state.threadRecentRefreshVersions.get(threadId) !== refreshVersion
        || state.threadSelectionVersion !== selectionVersion
        || state.activeThread?.id !== threadId
        || state.threadHistoryCursor !== historyCursor
      ) return null;
      console.error(`Unable to refresh recent turns for ${threadId}:`, error);
      return false;
    } finally {
      if (state.threadRecentRefreshInFlight.get(threadId) === entry) {
        state.threadRecentRefreshInFlight.delete(threadId);
        if (
          entry.dirty
          && entry.allowFollowup
          && state.runtime === "codex"
          && state.activeThread?.id === threadId
        ) {
          scheduleRecentTurnsRefresh(threadId, 80, { allowFollowup: false });
        }
      }
    }
  })();
  entry.promise = operation;
  return operation;
}

function createClientMessageId() {
  if (typeof crypto.randomUUID === "function") return crypto.randomUUID();
  return `web-${Date.now()}-${Math.random().toString(16).slice(2)}`;
}

async function beginDurableOperation(method, params) {
  const accountId = String(state.account?.id || "legacy");
  const payload = JSON.stringify([method, params]);
  let fingerprint;
  try {
    const digest = await crypto.subtle.digest("SHA-256", new TextEncoder().encode(payload));
    fingerprint = [...new Uint8Array(digest)]
      .map((value) => value.toString(16).padStart(2, "0"))
      .join("");
  } catch {
    fingerprint = transcriptNodeSignature(payload);
  }
  const storageKey = `${DURABLE_OPERATION_CACHE_PREFIX}:${encodeURIComponent(accountId)}`;
  const now = Date.now();
  let entries = [];
  try {
    const parsed = JSON.parse(localStorage.getItem(storageKey) || "[]");
    if (Array.isArray(parsed)) {
      entries = parsed.filter((entry) => (
        entry
        && typeof entry.fingerprint === "string"
        && typeof entry.clientOperationId === "string"
        && Number.isFinite(entry.createdAt)
        && now - entry.createdAt < DURABLE_OPERATION_CACHE_TTL_MS
      ));
    }
  } catch {
    entries = [];
  }
  let entry = entries.find((candidate) => candidate.fingerprint === fingerprint);
  if (!entry) {
    entry = {
      fingerprint,
      clientOperationId: createClientMessageId(),
      createdAt: now,
    };
    entries.unshift(entry);
  }
  try {
    localStorage.setItem(storageKey, JSON.stringify(entries.slice(0, DURABLE_OPERATION_CACHE_LIMIT)));
  } catch {
    // The in-flight request still has a stable ID for this page lifetime.
  }
  return { ...entry, storageKey };
}

function settleDurableOperation(operation, error = null) {
  if (!operation || error?.deliveryUnknown === true) return;
  try {
    const parsed = JSON.parse(localStorage.getItem(operation.storageKey) || "[]");
    if (!Array.isArray(parsed)) return;
    localStorage.setItem(
      operation.storageKey,
      JSON.stringify(parsed.filter((entry) => entry?.fingerprint !== operation.fingerprint)),
    );
  } catch {
    // A completed operation does not depend on cache cleanup.
  }
}

function codexTurnIdIsBusy(turnId) {
  if (!turnId) return false;
  if (state.codexTerminalTurnIds.has(turnId)) return false;
  const localTurn = state.activeThread?.turns?.find((turn) => turn?.id === turnId);
  if (localTurn && turnStatusType(localTurn) !== "inProgress") return false;
  const snapshot = state.taskStatusSnapshot;
  if (
    snapshot?.threadId === state.activeThread?.id
    && snapshot?.turnId === turnId
    && ["completed", "failed", "interrupted", "cancelled", "canceled", "idle"].includes(snapshot.status)
  ) return false;
  return true;
}

function codexLocalTurnIsBusy(turn) {
  return turnStatusType(turn) === "inProgress" && codexTurnIdIsBusy(turn?.id);
}

function clearStaleCodexTurnPointers(completedTurnId = null) {
  const pointerNames = ["activeTurnId", "codexActiveTurnId"];
  const localActiveIds = localInProgressTurnIds();
  const safeToClearUnknown = Boolean(
    completedTurnId
    && localActiveIds.length === 0
    && !state.pendingTurnRequest
    && !state.pendingSteerRequest
    && !state.turnPreparationPending
    && !state.turnStartRequestPending,
  );
  for (const name of pointerNames) {
    const turnId = state[name];
    if (!turnId) continue;
    if (completedTurnId && turnId === completedTurnId) {
      state[name] = null;
      continue;
    }
    if (state.codexTerminalTurnIds.has(turnId)) {
      state[name] = null;
      continue;
    }
    const localTurn = state.activeThread?.turns?.find((turn) => turn?.id === turnId);
    if (localTurn && turnStatusType(localTurn) !== "inProgress") state[name] = null;
    else if (safeToClearUnknown && !localTurn) state[name] = null;
  }
}

function conversationBusy() {
  if (state.runtime === "claude") {
    return Boolean(
      state.claudeTurnBusy
      || state.runtimeSwitchPending
      || state.promptSubmissionGuard
      || state.turnPreparationPending
      || state.threadSelectionPending
      || ["paused", "retryWaiting", "recoveryPending"].includes(state.activeClaudeSession?.status),
    );
  }
  const officialTurnBusy = (state.activeThread?.turns || [])
    .some((turn) => codexLocalTurnIsBusy(turn))
    || [state.activeTurnId, state.codexActiveTurnId].some((turnId) => codexTurnIdIsBusy(turnId));
  return Boolean(
    officialTurnBusy
    || state.runtimeSwitchPending
    || state.promptSubmissionGuard
    || state.queuedPromptAfterReconnect
    || state.pendingTurnRequest
    || state.pendingSteerRequest
    || state.steerRequestPending
    || state.interruptRequestPending
    || state.turnPreparationPending
    || state.imageGenerating
    || state.contextCompactionThreadId === state.activeThread?.id
    || state.threadSelectionPending
  );
}

function codexTaskAuthorityAllowsSend() {
  if (state.runtime !== "codex") return true;
  return codexRecoveryAllowsThread(state.activeThread?.id || null);
}

function turnStatusType(turn) {
  const status = turn?.status;
  return status && typeof status === "object" ? status.type : status;
}

function conversationBusyLabel() {
  if (state.runtimeSwitchPending) return "正在切换界面";
  if (state.runtime === "claude") {
    if (state.turnPreparationPending) return "正在准备 Claude 消息";
    if (state.claudeTurnBusy) {
      const startedAt = Number(state.activeClaudeSession?.startedAt);
      const elapsed = Number.isFinite(startedAt) && startedAt > 0
        ? ` · ${formatElapsedTime(Date.now() - startedAt)}`
        : "";
      return `Claude 正在处理${elapsed}`;
    }
    if (state.activeClaudeSession?.status === "paused") return "Claude 已暂停";
    if (state.activeClaudeSession?.status === "retryWaiting") return "等待连接恢复";
    if (state.activeClaudeSession?.status === "recoveryPending") return "等待恢复确认";
    return state.threadSelectionPending ? "正在切换" : "就绪";
  }
  if (state.contextCompactionThreadId === state.activeThread?.id) return "正在压缩上下文";
  if (state.interruptRequestPending) return "正在终止";
  if (state.queuedPromptAfterReconnect) return "等待连接恢复";
  if (state.pendingSteerRequest || state.steerRequestPending) return "正在确认追加指令";
  if (state.activeTurnId && codexTurnIdIsBusy(state.activeTurnId)) return "正在处理";
  if (state.codexActiveTurnId && codexTurnIdIsBusy(state.codexActiveTurnId)) return "正在处理";
  if (state.pendingTurnRequest) return "正在确认发送";
  if (state.imageGenerating) return "正在生成图片";
  if (state.turnPreparationPending) return "正在准备";
  if (state.threadSelectionPending) return "正在切换";
  if (state.activeThread?.id && codexThreadNeedsResume(state.activeThread.id)) return "发送时自动恢复对话";
  return "就绪";
}

function setTurnBusy(busy, label = busy ? "正在处理" : "就绪") {
  const canInterrupt = Boolean(state.activeTurnId);
  const claudeSession = state.runtime === "claude" ? state.activeClaudeSession : null;
  const claudePaused = claudeSession?.pause?.status === "paused";
  const claudeCanPause = Boolean(
    state.runtime === "claude"
    && claudeSession
    && (state.claudeTurnBusy || claudePaused),
  );
  const canQueueDuringReconnect = Boolean(
    state.runtime === "codex"
    && state.connectionPhase === "reconnecting"
    && state.conversationReady
  );
  const composerReady = Boolean(
    (state.bridgeReady || canQueueDuringReconnect)
    && state.initialDataReady
    && state.conversationReady
    && state.currentProject
    && codexTaskAuthorityAllowsSend()
  );
  const currentTaskStatus = state.taskStatusSnapshot?.threadId === state.activeThread?.id
    && state.taskStatusSnapshot?.turnId === state.activeTurnId
    ? state.taskStatusSnapshot.status
    : null;
  const canSteer = Boolean(
    state.runtime === "codex"
    && state.activeThread
    && state.activeTurnId
    && composerReady
    && !state.queuedPromptAfterReconnect
    && !state.pendingSteerRequest
    && !state.steerRequestPending
    && !state.interruptRequestPending
    && currentTaskStatus !== "stopping"
    && !state.uploading
    && !state.imageGenerating
    && !state.threadSelectionPending
  );
  const statusLabel = !busy && state.bridgeReady && !composerReady ? "正在同步" : label;
  elements.interruptButton.hidden = !canInterrupt;
  elements.stopTurnButton.hidden = !canInterrupt;
  elements.claudePauseButton.hidden = !claudeCanPause;
  elements.claudePauseButton.disabled = claudeSession?.pause?.status === "pausing";
  elements.claudePauseButton.title = claudePaused ? "继续 Claude 任务" : "暂停 Claude 任务";
  elements.claudePauseButton.setAttribute("aria-label", elements.claudePauseButton.title);
  elements.claudePauseButton.querySelector("i")?.setAttribute("data-lucide", claudePaused ? "play" : "pause");
  elements.interruptButton.disabled = canInterrupt && state.interruptRequestPending;
  elements.stopTurnButton.disabled = canInterrupt && state.interruptRequestPending;
  const sendDisabled = (busy && !canSteer) || !composerReady;
  if (elements.sendButton.disabled !== sendDisabled) {
    elements.sendButton.disabled = sendDisabled;
  }
  elements.sendButton.title = canSteer ? "追加到当前任务" : "发送";
  elements.sendButton.setAttribute("aria-label", canSteer ? "追加指令到当前任务" : "发送任务");
  elements.claudeCommandButton.disabled = state.runtime !== "claude" || busy || !composerReady;
  elements.providerQuickSelect.disabled = state.providerConfigurationRequired
    && !state.providers.length
    && !canEditProviderProfiles();
  updateProviderQuickChrome();
  elements.intelligenceMenuButton.disabled = busy || (state.runtime === "codex" && !state.models.length);
  if (busy) {
    closeIntelligenceMenu();
    closeClaudeCommandMenu();
  }
  renderTurnStatus({ busy, composerReady, label: statusLabel });
  updateThreadActionButtons(busy);
  renderContextStatus();
  renderClaudeSuggestion();
}

function renderTurnStatus({ busy, composerReady, label }) {
  const visualState = busy ? "busy" : composerReady ? "ready" : "waiting";
  if (
    elements.turnStatus.dataset.visualState === visualState
    && elements.turnStatus.dataset.label === label
  ) return;
  const dot = document.createElement("span");
  dot.className = "status-dot";
  if (visualState === "ready") dot.classList.add("ready");
  elements.turnStatus.replaceChildren(dot, document.createTextNode(` ${label}`));
  elements.turnStatus.dataset.visualState = visualState;
  elements.turnStatus.dataset.label = label;
}

function updateThreadActionButtons(busy = conversationBusy()) {
  const hasThread = state.runtime === "claude" ? Boolean(state.activeClaudeSession) : Boolean(state.activeThread);
  elements.conversationSearchButton.disabled = state.runtime !== "codex" || !hasThread || !state.bridgeReady;
  elements.conversationSearchButton.hidden = state.runtime !== "codex";
  elements.fileSearchButton.disabled = state.runtime !== "codex"
    || !state.currentProject
    || !state.bridgeReady
    || state.attachments.length >= 8;
  if (state.runtime === "claude") {
    elements.claudeRewindButton.hidden = false;
    elements.claudeRewindButton.disabled = !hasThread
      || busy
      || !state.activeClaudeSession?.rewindTargets?.length;
    elements.forkThreadButton.disabled = !hasThread || busy;
    elements.importThreadButton.disabled = true;
    elements.exportThreadButton.disabled = !hasThread;
    const restoring = elements.archivedThreadsToggle.checked;
    elements.archiveThreadButton.disabled = !hasThread || busy;
    elements.archiveThreadButton.title = restoring ? "恢复对话" : "归档对话";
    elements.archiveThreadButton.setAttribute("aria-label", elements.archiveThreadButton.title);
    elements.archiveThreadButton.innerHTML = `<i data-lucide="${restoring ? "archive-restore" : "archive"}"></i><span>${restoring ? "恢复" : "归档"}</span>`;
    elements.deleteThreadButton.disabled = !hasThread || busy;
    elements.copyThreadIdButton.disabled = !hasThread;
    elements.copyConversationButton.disabled = !hasThread;
    elements.pinThreadButton.disabled = !hasThread;
    const pinned = state.pinnedThreadIds.has(state.activeClaudeSession?.id);
    elements.pinThreadButton.classList.toggle("active", pinned);
    elements.pinThreadButton.title = pinned ? "取消置顶" : "置顶对话";
    elements.pinThreadButton.setAttribute("aria-label", elements.pinThreadButton.title);
    elements.pinThreadButton.querySelector("span").textContent = pinned ? "取消置顶" : "置顶";
    return;
  }
  elements.claudeRewindButton.hidden = true;
  elements.claudeRewindButton.disabled = true;
  const imported = state.activeThread?.imported === true;
  const worktree = state.activeThread?.worktree || null;
  elements.worktreeBranchButton.hidden = !worktree;
  elements.worktreeBranchButton.disabled = !worktree
    || busy
    || worktree.location !== "worktree"
    || Boolean(worktree.branch);
  elements.worktreeBranchButton.title = worktree?.branch
    ? `Worktree 已在分支 ${worktree.branch}`
    : "在 Worktree 创建正式 Git 分支";
  elements.worktreeBranchButton.setAttribute("aria-label", elements.worktreeBranchButton.title);
  elements.worktreeBranchButton.querySelector("span").textContent = worktree?.branch
    ? `Git 分支 · ${worktree.branch}`
    : "创建 Git 分支";
  const handoffTarget = worktree?.location === "local" ? "worktree" : "local";
  const handoffLabel = handoffTarget === "local" ? "交接到 Local" : "交接回 Worktree";
  elements.worktreeHandoffButton.hidden = !worktree;
  elements.worktreeHandoffButton.disabled = !worktree || busy;
  elements.worktreeHandoffButton.title = worktree
    ? `${handoffLabel} · 仅在目标侧未发生额外修改时执行`
    : "在 Local 与 Worktree 之间安全交接";
  elements.worktreeHandoffButton.setAttribute("aria-label", elements.worktreeHandoffButton.title);
  elements.worktreeHandoffButton.querySelector("span").textContent = handoffLabel;
  elements.worktreeSnapshotButton.hidden = !worktree;
  elements.worktreeSnapshotButton.disabled = !worktree || busy || worktree.location !== "worktree";
  elements.worktreeSnapshotButton.title = worktree?.snapshot
    ? `更新 Worktree 快照 · ${relativeTime(worktree.snapshot.createdAt / 1_000)}`
    : "保存 Worktree 恢复快照";
  elements.worktreeSnapshotButton.setAttribute("aria-label", elements.worktreeSnapshotButton.title);
  elements.pinThreadButton.hidden = true;
  const restoring = elements.archivedThreadsToggle.checked;
  elements.forkThreadButton.disabled = !hasThread || busy || Boolean(worktree);
  elements.forkThreadButton.title = worktree
    ? "Worktree 对话不能直接 fork，请先创建或切换到新的 Worktree"
    : imported ? "物化迁移记录并创建原生分支" : "分支对话";
  elements.forkThreadButton.setAttribute("aria-label", elements.forkThreadButton.title);
  elements.importThreadButton.disabled = busy || state.threadImporting || !state.bridgeReady || !state.currentProject;
  elements.exportThreadButton.disabled = !hasThread;
  elements.archiveThreadButton.disabled = !hasThread || busy;
  elements.deleteThreadButton.disabled = !hasThread || busy;
  elements.copyThreadIdButton.disabled = !hasThread;
  elements.copyConversationButton.disabled = !hasThread;
  elements.pinThreadButton.disabled = true;
  elements.pinThreadButton.classList.remove("active");
  elements.pinThreadButton.title = "Codex 0.147 使用持久分区顺序；请在对话列表中上移、下移或移动分区";
  elements.pinThreadButton.setAttribute("aria-label", elements.pinThreadButton.title);
  elements.pinThreadButton.querySelector("span").textContent = "分区排序";
  elements.archiveThreadButton.title = restoring ? "恢复对话" : "归档对话";
  elements.archiveThreadButton.setAttribute("aria-label", elements.archiveThreadButton.title);
  elements.archiveThreadButton.querySelector("span").textContent = restoring ? "恢复" : "归档";
}

function resizePrompt() {
  elements.promptInput.style.height = "auto";
  elements.promptInput.style.height = `${Math.min(elements.promptInput.scrollHeight, 180)}px`;
}

function scrollMessagesToBottom(immediate = false) {
  if (immediate) {
    const previousBehavior = elements.messageStage.style.scrollBehavior;
    elements.messageStage.style.scrollBehavior = "auto";
    elements.messageStage.scrollTop = elements.messageStage.scrollHeight;
    elements.messageStage.style.scrollBehavior = previousBehavior;
    return;
  }
  elements.messageStage.scrollTop = elements.messageStage.scrollHeight;
}

function restoreSidebarView() {
  openMobilePanels(state.sidebarView === "projects" ? "projects" : "threads", { persist: false });
}

function openMobilePanels(view, { persist = true } = {}) {
  const nextView = view === "projects" ? "projects" : "threads";
  state.sidebarView = nextView;
  if (persist) localStorage.setItem(SIDEBAR_VIEW_KEY, nextView);
  if (paneIsPersistent(nextView)) {
    closeMobilePanels();
    if (nextView === "projects") elements.projectSearch.focus();
    else elements.threadSearch.focus();
    return;
  }
  const workspace = document.querySelector(".workspace");
  workspace.classList.add("panels-open");
  workspace.classList.toggle("project-view", nextView === "projects");
  elements.panelsButton.setAttribute("aria-expanded", "true");
  elements.projectSwitcher.setAttribute("aria-expanded", String(nextView === "projects"));
}

function toggleMobilePanels(view) {
  if (paneIsPersistent(view)) {
    openMobilePanels(view);
    return;
  }
  const workspace = document.querySelector(".workspace");
  const sameView = workspace.classList.contains("panels-open")
    && workspace.classList.contains("project-view") === (view === "projects");
  if (sameView) closeMobilePanels();
  else openMobilePanels(view);
}

function closeMobilePanels() {
  document.querySelector(".workspace").classList.remove("panels-open", "project-view");
  elements.panelsButton.setAttribute("aria-expanded", "false");
  elements.projectSwitcher.setAttribute("aria-expanded", "false");
}

function paneIsPersistent(view) {
  if (!matchMedia(PERSISTENT_PANE_QUERY).matches) return false;
  return view === "projects" ? state.ui.projectPanePersistent : state.ui.threadPanePersistent;
}

function toggleThreadActionsMenu() {
  const expanded = !elements.chatActions.classList.contains("menu-open");
  elements.chatActions.classList.toggle("menu-open", expanded);
  elements.threadMoreButton.setAttribute("aria-expanded", String(expanded));
}

function closeThreadActionsMenu() {
  elements.chatActions.classList.remove("menu-open");
  elements.threadMoreButton.setAttribute("aria-expanded", "false");
}

function applyStoredTheme() {
  const saved = localStorage.getItem("codexDesktop.theme");
  const dark = saved === "dark" || (!saved && matchMedia("(prefers-color-scheme: dark)").matches);
  document.documentElement.dataset.theme = dark ? "dark" : "light";
}

function toggleTheme() {
  const dark = document.documentElement.dataset.theme !== "dark";
  document.documentElement.dataset.theme = dark ? "dark" : "light";
  localStorage.setItem("codexDesktop.theme", dark ? "dark" : "light");
}

async function toggleFullscreen() {
  try {
    if (!document.fullscreenElement) await document.documentElement.requestFullscreen();
    else await document.exitFullscreen();
  } catch (error) {
    toast(error.message, "error");
  }
}

function setConnection(status, text) {
  if (
    elements.connectionPill.dataset.status === status
    && elements.connectionText.textContent === text
  ) return;
  elements.connectionPill.dataset.status = status;
  elements.connectionText.textContent = text;
  elements.connectionPill.setAttribute("aria-label", text);
  elements.runtimeSwitcherButton.dataset.connectionStatus = status;
  updateRuntimeConnectionLabel();
  if (status === "reconnecting") {
    const turnBusy = conversationBusy();
    setTurnBusy(turnBusy, turnBusy ? conversationBusyLabel() : "正在重连");
  } else if (status !== "ready") {
    const turnBusy = conversationBusy();
    setTurnBusy(turnBusy, turnBusy ? conversationBusyLabel() : "离线");
  }
}

function updateRuntimeConnectionLabel() {
  const text = elements.connectionText.textContent || "正在连接";
  const runtime = state.runtime === "claude" ? "Claude Code" : "Codex";
  elements.runtimeSwitcherButton.title = `切换代码运行时 · ${text}`;
  elements.runtimeSwitcherButton.setAttribute("aria-label", `${runtime} ${text}，切换代码运行时`);
}

function statusText(status) {
  return {
    starting: "正在启动",
    ready: "Codex 已连接",
    reconnecting: "正在重连",
    error: "启动失败",
    offline: "连接断开",
  }[status] || status;
}

function approvalRequestTitle(method) {
  return {
    "item/commandExecution/requestApproval": "批准执行命令",
    "item/fileChange/requestApproval": "批准文件更改",
    "item/tool/requestUserInput": "Codex 需要你的选择",
    "item/permissions/requestApproval": "批准额外权限",
    "mcpServer/elicitation/request": "MCP 请求输入",
    "claude/permission": "Claude 请求权限",
    "claude/askUserQuestion": "Claude 需要你的选择",
    "claude/userDialog": "Claude 会话已暂停",
    "claude/elicitation": "Claude MCP 请求输入",
  }[method] || "Codex 请求批准";
}

function statusLabel(status) {
  if (typeof status === "object") return status?.type || "active";
  return {
    inProgress: "运行中",
    running: "运行中",
    completed: "完成",
    failed: "失败",
    declined: "已拒绝",
    pendingInit: "正在启动",
    interrupted: "已中断",
    errored: "错误",
    shutdown: "已关闭",
    notFound: "不可用",
  }[status] || status || "";
}

function sourceLabel(source) {
  if (typeof source === "string") return source;
  return source?.type || "Codex";
}

function relativeTime(timestampSeconds) {
  const seconds = Math.round(timestampSeconds - Date.now() / 1000);
  const formatter = new Intl.RelativeTimeFormat(interfaceLocale(), { numeric: "auto" });
  if (Math.abs(seconds) < 60) return formatter.format(seconds, "second");
  const minutes = Math.round(seconds / 60);
  if (Math.abs(minutes) < 60) return formatter.format(minutes, "minute");
  const hours = Math.round(minutes / 60);
  if (Math.abs(hours) < 24) return formatter.format(hours, "hour");
  const days = Math.round(hours / 24);
  return formatter.format(days, "day");
}

function formatPercent(value) {
  return `${Math.round(Number(value) || 0)}%`;
}

function formatBytes(value) {
  const bytes = Number(value) || 0;
  const units = ["B", "KB", "MB", "GB", "TB"];
  let amount = bytes;
  let unit = 0;
  while (amount >= 1024 && unit < units.length - 1) {
    amount /= 1024;
    unit += 1;
  }
  return `${amount >= 10 || unit === 0 ? Math.round(amount) : amount.toFixed(1)} ${units[unit]}`;
}

function formatDuration(seconds) {
  if (seconds < 60) return `${seconds} 秒`;
  if (seconds < 3600) return `${Math.floor(seconds / 60)} 分钟`;
  if (seconds < 86_400) return `${Math.floor(seconds / 3600)} 小时`;
  return `${Math.floor(seconds / 86_400)} 天`;
}

function pathBasename(value) {
  return value.replace(/\/+$/, "").split("/").pop() || value;
}

function loadStoredSet(key, account = state.account) {
  try {
    const values = JSON.parse(localStorage.getItem(accountStorageKey(key, account)) || "[]");
    return new Set(Array.isArray(values) ? values.filter((value) => typeof value === "string") : []);
  } catch {
    return new Set();
  }
}

function accountStorageKey(base, account = state.account) {
  const accountId = typeof account?.id === "string" && account.id.trim() ? account.id.trim() : "legacy";
  return `${base}:${encodeURIComponent(accountId)}`;
}

function persistPinnedThreadIds() {
  try {
    localStorage.setItem(
      accountStorageKey("codexDesktop.pinnedThreads"),
      JSON.stringify([...state.pinnedThreadIds]),
    );
  } catch {
    // The active UI remains authoritative when local storage is unavailable.
  }
}

function loadStoredThreadRecovery(account = state.account) {
  try {
    return parseThreadRecoveryRecord(localStorage.getItem(accountStorageKey(THREAD_RECOVERY_KEY, account)) || "");
  } catch {
    return null;
  }
}

function rememberActiveThread(thread, status = "remembered") {
  const recovery = createThreadRecoveryRecord({
    ...thread,
    cwd: thread?.cwd || state.currentProject?.path,
  });
  if (!recovery) return;
  state.threadRecovery = recovery;
  try {
    localStorage.setItem(accountStorageKey(THREAD_RECOVERY_KEY), JSON.stringify(recovery));
  } catch {
    // Recovery remains available in memory when browser storage is unavailable.
  }
  persistThreadRecovery(recovery, status);
}

function persistThreadRecovery(recovery, status) {
  const threadId = recovery?.id || recovery?.threadId;
  const cwd = recovery?.cwd;
  if (!threadId || !cwd) return;
  fetch("/api/recovery", {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ threadId, cwd, status }),
  }).catch(() => {});
}

function clearThreadRecovery() {
  state.threadRecovery = null;
  try {
    localStorage.removeItem(accountStorageKey(THREAD_RECOVERY_KEY));
  } catch {
    // Ignore browsers that disable local storage.
  }
}

function refreshIcons() {
  window.lucide?.createIcons({ attrs: { "aria-hidden": "true" } });
}

function activeDialogToastRegion() {
  const dialogs = [...document.querySelectorAll("dialog[open]")];
  const dialog = dialogs.at(-1);
  if (!dialog) return null;
  let region = [...dialog.children].find((child) => child.classList?.contains("dialog-toast-region"));
  if (!region) {
    region = document.createElement("div");
    region.className = "toast-region dialog-toast-region";
    region.setAttribute("aria-live", "polite");
    dialog.append(region);
  }
  return region;
}

function appendToast(region, message, type) {
  if (!region) return;
  const duplicate = [...region.children].find(
    (item) => item.dataset.message === message && item.dataset.type === type,
  );
  duplicate?.remove();
  while (region.childElementCount >= 3) region.firstElementChild?.remove();
  const item = document.createElement("div");
  item.className = `toast ${type}`;
  item.dataset.message = message;
  item.dataset.type = type;
  item.innerHTML = `<i data-lucide="${type === "error" ? "circle-alert" : "circle-check"}"></i><span></span>`;
  item.querySelector("span").textContent = message;
  region.append(item);
  setTimeout(() => item.remove(), 4_200);
}

function toast(message, type = "info") {
  const normalizedMessage = String(message || "").trim();
  if (!normalizedMessage) return;
  appendToast(elements.toastRegion, normalizedMessage, type);
  appendToast(activeDialogToastRegion(), normalizedMessage, type);
  refreshIcons();
}

function notifyBrowser(kind, title, body, tag) {
  const enabled = kind === "complete"
    ? state.ui.notifyTaskComplete
    : kind === "approval"
      ? state.ui.notifyApproval
      : state.ui.notifyQuestion;
  if (
    !enabled
    || document.visibilityState === "visible"
    || !("Notification" in window)
    || Notification.permission !== "granted"
  ) return;
  try {
    const notification = new Notification(title, {
      body: String(body || "").slice(0, 240),
      tag: String(tag || `wfl-${kind}`).slice(0, 120),
      renotify: false,
    });
    notification.addEventListener("click", () => {
      window.focus();
      notification.close();
    });
  } catch {}
}
